struct MetalLambertianNativeResources final {
    lambertian::native::Source source;
    lambertian::Request request{};
    lambertian::Result sentinel{};
    std::array<std::uint32_t,250> readback{};
    std::array<std::uint32_t,4> uniforms{};
    std::array<std::uint64_t,4> lengths{},allocations{};
    std::array<const void*,11> owners{};
    id<MTLDevice> device=nil;
    id<MTLBuffer> input=nil,result=nil,limits=nil,archive=nil;
    id<MTLLibrary> library=nil;id<MTLFunction> function=nil;
    id<MTLComputePipelineState> pipeline=nil;
    id<MTLCommandQueue> queue=nil;id<MTLCommandBuffer> command=nil;
    NSString* creationSource=nil;
    std::uint64_t nativeBytes=0;
    std::uint32_t recipe=lambertian::native::kSourceVersion;
    bool completed=false;
    ~MetalLambertianNativeResources(){
#if ! __has_feature(objc_arc)
        [input release];[result release];[limits release];[archive release];[library release];[function release];
        [pipeline release];[queue release];[command release];[device release];[creationSource release];
#endif
    }
};
