// The viewport is owned by another translation unit and may be torn down during
// process-static destruction. Keep the backend lock alive until the process is
// gone so a late renderer shutdown can never lock a destroyed std::mutex.
std::mutex& sokolMutex()
{
    static auto* mutex = new std::mutex();
    return *mutex;
}

std::uint64_t nextMetalRendererGeneration() noexcept
{
    static std::uint64_t generation = 0;
    return ++generation;
}
id<MTLDevice> gMetalDevice = nil;
std::string gSokolError;
std::string gSokolLastLog;
std::mutex& sokolLogMutex()
{
    static auto* mutex = new std::mutex();
    return *mutex;
}

void captureSokolLog (const char*, std::uint32_t logLevel, std::uint32_t logItem,
                      const char* message, std::uint32_t, const char*, void*)
{
    if (logLevel > 1)
        return;
    std::lock_guard<std::mutex> lock (sokolLogMutex());
    // Release builds of sokol_gfx pass no message text for named log items.
    // Keep the item number so a refused creation is still identifiable.
    gSokolLastLog = message != nullptr ? std::string (message)
                                       : "sokol_gfx log item " + std::to_string (logItem);
}

std::string lastSokolLog()
{
    std::lock_guard<std::mutex> lock (sokolLogMutex());
    return gSokolLastLog;
}

#if ARBIT_HAVE_VIEWPORT
bool resourceValid (sg_resource_state state);

void clearSokolLog()
{
    std::lock_guard<std::mutex> lock (sokolLogMutex());
    gSokolLastLog.clear();
}

// Called only for the viewport's selected scene-trace frame, after Sokol has
// submitted the stage being inspected. Keep the owned image alive at the call
// site; this readback never becomes a compositor input.
void traceSceneStage (const char* stage, std::uint64_t seqHint, int clipId,
                      std::uint64_t sourceImage, std::uint64_t sourceView,
                      sg_image image, sg_view view, int width, int height,
                      MTLPixelFormat format)
{
    const auto unavailable = [&] (const char* reason)
    {
        std::fprintf(stderr,
            "[viewport-scene-trace] %s clip=%d seqHint=%llu sourceImage=%llu sourceView=%llu image=%u view=%u read=unavailable reason=%s\n",
            stage, clipId, static_cast<unsigned long long>(seqHint),
            static_cast<unsigned long long>(sourceImage),
            static_cast<unsigned long long>(sourceView), image.id, view.id, reason);
    };
    if (width <= 0 || height <= 0 || !resourceValid(sg_query_image_state(image))
        || !resourceValid(sg_query_view_state(view)))
    { unavailable("stale image or view"); return; }
    const auto binding = sg_query_view_desc(view);
    const auto native = sg_mtl_query_image_info(image);
    if (binding.texture.image.id != image.id || native.active_slot < 0
        || native.active_slot >= SG_NUM_INFLIGHT_FRAMES)
    { unavailable("image/view binding or slot mismatch"); return; }
    id<MTLTexture> texture = (__bridge id<MTLTexture>) native.tex[native.active_slot];
    id<MTLCommandQueue> queue = (__bridge id<MTLCommandQueue>) sg_mtl_command_queue();
    if (texture == nil || queue == nil || texture.device != gMetalDevice
        || queue.device != gMetalDevice || texture.pixelFormat != format
        || texture.textureType != MTLTextureType2D || texture.sampleCount != 1
        || texture.width != static_cast<NSUInteger>(width)
        || texture.height != static_cast<NSUInteger>(height))
    { unavailable("Metal texture ownership, format, or extent mismatch"); return; }
    const size_t bytesPerPixel = format == MTLPixelFormatRGBA16Float ? 8u : 4u;
    const size_t tightRow = static_cast<size_t>(width) * bytesPerPixel;
    const size_t rowBytes = (tightRow + 255u) & ~size_t(255u);
    id<MTLBuffer> buffer = [gMetalDevice newBufferWithLength:rowBytes * height
                                                   options:MTLResourceStorageModeShared];
    id<MTLCommandBuffer> command = [queue commandBuffer];
    id<MTLBlitCommandEncoder> blit = buffer != nil && command != nil
        ? [command blitCommandEncoder] : nil;
    bool ok = blit != nil;
    if (ok)
    {
        [blit copyFromTexture:texture sourceSlice:0 sourceLevel:0
                  sourceOrigin:MTLOriginMake(0, 0, 0)
                    sourceSize:MTLSizeMake(width, height, 1)
                      toBuffer:buffer destinationOffset:0
         destinationBytesPerRow:rowBytes destinationBytesPerImage:rowBytes * height];
        [blit endEncoding];
        [command commit];
        [command waitUntilCompleted];
        ok = command.status == MTLCommandBufferStatusCompleted && buffer.contents != nullptr;
    }
    if (ok)
    {
        const auto* bytes = static_cast<const std::uint8_t*>(buffer.contents);
        const auto* corner = bytes;
        std::uint64_t hash = 14695981039346656037ull;
        size_t different = 0, nonblack = 0, bright = 0, alpha = 0;
        int minX = width, minY = height, maxX = -1, maxY = -1;
        const auto channel = [&] (const std::uint8_t* pixel, int component) -> float
        {
            if (format == MTLPixelFormatBGRA8Unorm)
                return pixel[component == 0 ? 2 : component == 2 ? 0 : component] / 255.0f;
            std::uint16_t half = 0;
            std::memcpy(&half, pixel + component * 2, sizeof(half));
            return hdrimage::halfToFloat(half);
        };
        const float cornerR = channel(corner, 0), cornerG = channel(corner, 1);
        const float cornerB = channel(corner, 2);
        for (int y = 0; y < height; ++y)
            for (int x = 0; x < width; ++x)
            {
                const auto* pixel = bytes + static_cast<size_t>(y) * rowBytes + x * bytesPerPixel;
                const float r = channel(pixel, 0), g = channel(pixel, 1), b = channel(pixel, 2);
                different += r != cornerR || g != cornerG || b != cornerB;
                nonblack += r > 0.0f || g > 0.0f || b > 0.0f;
                alpha += channel(pixel, 3) > 0.0f;
                if (r > 0.125f || g > 0.125f || b > 0.125f)
                {
                    ++bright;
                    minX = std::min(minX, x); minY = std::min(minY, y);
                    maxX = std::max(maxX, x); maxY = std::max(maxY, y);
                }
                for (size_t byte = 0; byte < bytesPerPixel; ++byte)
                { hash ^= pixel[byte]; hash *= 1099511628211ull; }
            }
        const auto* center = bytes + static_cast<size_t>(height / 2) * rowBytes
            + (width / 2) * bytesPerPixel;
        std::fprintf(stderr,
            "[viewport-scene-trace] %s clip=%d seqHint=%llu sourceImage=%llu sourceView=%llu image=%u view=%u metalTexture=%llx format=%s region=0,0,%d,%d hash=%016llx corner=%.4f,%.4f,%.4f center=%.4f,%.4f,%.4f different=%zu nonblack=%zu bright=%zu bounds=%d,%d,%d,%d alpha=%zu total=%zu\n",
            stage, clipId, static_cast<unsigned long long>(seqHint),
            static_cast<unsigned long long>(sourceImage),
            static_cast<unsigned long long>(sourceView), image.id, view.id,
            static_cast<unsigned long long>(reinterpret_cast<std::uintptr_t>((__bridge void*)texture)),
            format == MTLPixelFormatRGBA16Float ? "rgba16f" : "bgra8",
            width, height, static_cast<unsigned long long>(hash),
            cornerR, cornerG, cornerB,
            channel(center, 0), channel(center, 1), channel(center, 2),
            different, nonblack, bright,
            bright ? minX : 0, bright ? minY : 0,
            bright ? maxX - minX + 1 : 0, bright ? maxY - minY + 1 : 0,
            alpha, static_cast<size_t>(width) * height);
    }
    else unavailable("Metal blit readback failed");
#if !__has_feature(objc_arc)
    [buffer release];
#endif
}
#endif

bool ensureSokolMetal()
{
    if (sg_isvalid())
        return true;
    if (! gSokolError.empty())
        return false;

    gMetalDevice = MTLCreateSystemDefaultDevice();
    if (gMetalDevice == nil)
    {
        gSokolError = "Metal returned no default device";
        return false;
    }

    sg_desc desc = {};
    // The viewport, frame probe, and export can retain compositors concurrently
    // (18 shaders and pipelines each). The process-wide pools also serve native
    // scene programs; Sokol's 32-shader default fails during the second one.
    // Imported scenes need an image, view and sampler per texture role, so
    // every pool is sized explicitly (metal_resource_pools.h).
    desc.buffer_pool_size = arbitgpu::metalpools::kBufferPool;
    desc.image_pool_size = arbitgpu::metalpools::kImagePool;
    desc.sampler_pool_size = arbitgpu::metalpools::kSamplerPool;
    desc.shader_pool_size = arbitgpu::metalpools::kShaderPool;
    desc.pipeline_pool_size = arbitgpu::metalpools::kPipelinePool;
    desc.view_pool_size = arbitgpu::metalpools::kViewPool;
    desc.environment.metal.device = (__bridge const void*) gMetalDevice;
    // Sokol's default frame command buffer holds unretained references, so a
    // Metal object stays alive only as long as Sokol's frame-count release
    // queue or our own ARC owners say. Neither tracks GPU completion here:
    // frames bind native buffers (spectral diagnostics, raster capture rings)
    // into Sokol's encoders and release them on destroy, refusals leave the
    // frame command buffer open for another thread's sg_commit(), and
    // reclaimMetalIdPool() collects every pending release at once. Freeing an
    // object an unretained buffer still referenced panicked the kernel on
    // 15 Oct (IOGPUResource::free, AGXMetalG17P, during sg_commit). A retained
    // command buffer keeps every object it encodes alive until it completes.
    desc.metal.use_command_buffer_with_retained_references = true;
    desc.environment.defaults.color_format = SG_PIXELFORMAT_BGRA8;
    desc.environment.defaults.depth_format = SG_PIXELFORMAT_DEPTH_STENCIL;
    desc.environment.defaults.sample_count = 1;
    desc.logger.func = captureSokolLog;
    sg_setup (&desc);
    if (! sg_isvalid())
    {
        gSokolError = "sokol_gfx Metal initialization failed";
        return false;
    }
    return true;
}

int metalIdPoolFreeSlots() noexcept
{
    return sg_isvalid() ? std::max (_sg.mtl.idpool.free_queue_top, 0) : 0;
}

// Sokol returns a destroyed resource's Metal id slot to the free queue only in
// sg_commit(), three commits after sg_destroy_*(). A refusal that creates and
// destroys resources every frame without committing drains the queue. When no
// Sokol command buffer or pass is open, a fence committed on Sokol's queue
// proves every earlier command buffer has completed, so every pending release
// can be collected without advancing the frame index. Collection only drops
// the pool's reference: Sokol's command buffers retain what they encode
// (ensureSokolMetal), so a buffer still in flight keeps its objects alive even
// if the fence proves less than this assumes. Requires sokolMutex().
bool reclaimMetalIdPool()
{
    if (! sg_isvalid() || _sg.mtl.cmd_buffer != nil || _sg.cur_pass.in_pass)
        return false;
    if (_sg.mtl.idpool.release_queue_back == _sg.mtl.idpool.release_queue_front)
        return true;
    id<MTLCommandBuffer> fence = [_sg.mtl.cmd_queue commandBuffer];
    if (fence == nil)
        return false;
    [fence commit];
    [fence waitUntilCompleted];
    _sg_mtl_garbage_collect (std::numeric_limits<uint32_t>::max());
    return true;
}

// Requires sokolMutex(). A refusal between sg_end_pass() and sg_commit()
// leaves Sokol's frame command buffer open, and the next sg_commit() on any
// thread would submit its stale passes. Submit it here, before the refusing
// owner releases what those passes reference, and wait for it to finish.
void settleOpenSokolCommandBufferUnlocked()
{
    if (! sg_isvalid() || _sg.cur_pass.in_pass || _sg.mtl.cmd_buffer == nil)
        return;
    // Sokol keeps the autoreleased buffer without a retain. The refusing
    // caller's pool may already be drained, so hold it across the wait.
    id<MTLCommandBuffer> open = _sg.mtl.cmd_buffer;
#if ! __has_feature(objc_arc)
    [open retain];
#endif
    sg_commit();
    [open waitUntilCompleted];
#if ! __has_feature(objc_arc)
    [open release];
#endif
}

// Requires sokolMutex(). Refuses by name instead of letting Sokol run out of
// Metal id slots part way through a preparation.
bool ensureMetalIdHeadroom (int required, std::string& error)
{
    required = std::max (required, arbitgpu::metalpools::kMinimumFreeIds);
    if (metalIdPoolFreeSlots() >= required)
        return true;
    reclaimMetalIdPool();
    const auto available = metalIdPoolFreeSlots();
    if (available >= required)
        return true;
    error = "Metal resource id pool exhausted: " + std::to_string (available)
        + " free id slots, " + std::to_string (required) + " required";
    return false;
}

uint32_t fnv1a (const void* data, size_t size)
{
    const auto* bytes = static_cast<const uint8_t*> (data);
    uint32_t hash = 2166136261u;
    for (size_t i = 0; i < size; ++i)
    {
        hash ^= bytes[i];
        hash *= 16777619u;
    }
    return hash;
}

std::string deviceName (id<MTLDevice> device)
{
    if (device == nil || device.name == nil)
        return {};
    return std::string ([device.name UTF8String]);
}

void readBackSubmittedWork (id<MTLDevice> device, id<MTLBuffer> computeBuffer,
                            id<MTLTexture> renderTexture,
                            std::array<uint32_t, 4>& computed,
                            std::array<uint8_t, 4 * 4 * 4>& pixels)
{
    id<MTLCommandQueue> queue = (__bridge id<MTLCommandQueue>) sg_mtl_command_queue();
    id<MTLBuffer> textureReadback = [device newBufferWithLength:pixels.size()
                                                        options:MTLResourceStorageModeShared];
    id<MTLCommandBuffer> command = [queue commandBuffer];
    id<MTLBlitCommandEncoder> blit = [command blitCommandEncoder];
    if (computeBuffer.storageMode == MTLStorageModeManaged)
        [blit synchronizeResource:computeBuffer];
    if (renderTexture != nil && textureReadback != nil)
    {
        [blit copyFromTexture:renderTexture
                  sourceSlice:0
                  sourceLevel:0
                 sourceOrigin:MTLOriginMake (0, 0, 0)
                   sourceSize:MTLSizeMake (4, 4, 1)
                     toBuffer:textureReadback
            destinationOffset:0
       destinationBytesPerRow:16
     destinationBytesPerImage:pixels.size()];
    }
    [blit endEncoding];
    [command commit];
    [command waitUntilCompleted];

    if (computeBuffer != nil && computeBuffer.contents != nullptr)
        std::memcpy (computed.data(), computeBuffer.contents, sizeof (computed));
    if (textureReadback != nil && textureReadback.contents != nullptr)
        std::memcpy (pixels.data(), textureReadback.contents, pixels.size());

#if ! __has_feature(objc_arc)
    [textureReadback release];
#endif
}

bool resourceValid (sg_resource_state state)
{
    return state == SG_RESOURCESTATE_VALID;
}

bool compileMetalShaderStage (const char* source, const char* stage,
                              std::string& error, const char* entry = "_main",
                              std::array<id,2>* retainedOwners = nullptr)
{
    NSError* libraryError = nil;
    id<MTLLibrary> library = [gMetalDevice
        newLibraryWithSource:[NSString stringWithUTF8String:source]
        options:nil
        error:&libraryError];
    id<MTLFunction> function = [library newFunctionWithName:
        [NSString stringWithUTF8String:entry]];
    if(retainedOwners) *retainedOwners={library,function};
    if (library != nil && function != nil)
        return true;

    error = "Metal fixture " + std::string (stage) + " shader compilation failed";
    if (libraryError != nil && libraryError.localizedDescription != nil)
        error += ": " + std::string (libraryError.localizedDescription.UTF8String);
    else if (library != nil)
        error += ": entry point " + std::string (entry) + " was not found";
    return false;
}

struct FixtureUniforms
{
    float objectMatrix[16];
    float cameraRotation[4];
    float cameraTranslation[4];
    float projection[4];
    float baseColor[4];
    float materialParams[4];
    float timeMixEndColorAndTime[4];
    float emissive[4];
    float ambient[4];
    float lightRotations[16][4];
    float lightColors[16][4];
    float lightPositions[16][4];
    float lightCones[16][4];
    std::uint32_t lightKinds[16][4];
    std::uint32_t materialKind[4];
    diffractionmaterial::PhysicalDiffractionGpuParameters diffraction;
    float diffractionIncidentDirectionAndIntensity[4];
    std::uint32_t diffractionPathKindAndBounce[4];
    float diffractionFoilField[4][4];
    float diffractionOccupancyRectangles[5][4];
    std::uint32_t diffractionSpatialCounts[4];
    std::uint32_t diffractionEvaluationSchedule[4];
    float noteInstanceTransforms[visualnoteinstancing::kMaximumInstances][4];
    // Geometry Core and Block C remain independent instance domains. x selects
    // the Geometry Core matrix stream; y selects one Block C row for a geometry
    // draw, or UINT_MAX to use Metal's instance_id for an ordinary scene draw.
    // z selects the ordinary scene object; w is its note-instance count.
    std::uint32_t geometryInstanceControl[4];
    float noteAppearanceLow[4];
    float noteAppearanceHigh[4];
    float noteMeshScale[4];
    float imageOutput[4];
    float diffractionEnvironment[4];
    float rawIdentifiers[64][4];
    arbitgpu::NativeSceneMotionUniforms motion;
    float vertexTime[4];
    float vertexSpectrum[16][4];
    renderpasscomposite::GpuProgram passProgram;
    float surfaceCoating[4];
    float opaqueControl[4];
    arbitgpu::analyticsky::Uniforms sky {};
    float skyBackground[4];
    float glassControl[4], glassTransport[4];
    std::array<std::array<float,4>,64> glassReceivers {}, glassEmission {};
    float spectralQueryControl[4], spectralSampleControl[4], spectralSourceDirectionTrace[4];
    float spectralSourceRadiance[2][4];
    float previousNoteInstanceTransforms[visualnoteinstancing::kMaximumInstances][4];
