class MetalFixtureSceneResources final : public arbitgpu::NativeFixtureSceneResources
{
public:
    ~MetalFixtureSceneResources() override
    {
        if (hasResources())
        {
            std::lock_guard<std::mutex> lock (sokolMutex());
            destroyUnlocked();
        }
    }

    const std::string& backend() const noexcept override { return backend_; }

    bool hasResources() const noexcept
    {
        return vertexBuffer.id != 0 || previousVertexBuffer.id != 0 || indexBuffer.id != 0 || !textureImages.empty()
            || !textureViews.empty() || !samplers.empty() || shader.id != 0
            || diffractionResolveShader.id != 0 || roughReceiptShader.id != 0 || geometryInstanceBuffer.id != 0
            || environmentTexture.id!=0 || environmentView.id!=0 || !pipelines.empty();
    }

    void destroyUnlocked() noexcept
    {
        if (environmentView.id) sg_destroy_view(environmentView);
        if (environmentTexture.id) sg_destroy_image(environmentTexture);
        environmentView={}; environmentTexture={}; environmentResident.reset(); environmentBudget.reset();
        for (const auto pipeline : pipelines)
            if (pipeline.id != 0) sg_destroy_pipeline (pipeline);
        for (const auto pipeline : diffractionResolvePipelines)
            if (pipeline.id != 0) sg_destroy_pipeline (pipeline);
        for (const auto pipeline : mixedSurfacePipelines)
            if (pipeline.id != 0) sg_destroy_pipeline(pipeline);
        for (const auto pipeline : mixedGratingPipelines)
            if (pipeline.id != 0) sg_destroy_pipeline(pipeline);
        for (const auto pipeline : skyPipelines)
            if (pipeline.id != 0) sg_destroy_pipeline (pipeline);
        if (diffractionResolveShader.id != 0) sg_destroy_shader (diffractionResolveShader);
        if (shader.id != 0) sg_destroy_shader (shader);
        if (roughReceiptShader.id) sg_destroy_shader(roughReceiptShader);
        roughReceiptShader = {}; roughReceiptPipeline = {};
        for (const auto sampler : samplers)
            if (sampler.id != 0) sg_destroy_sampler (sampler);
        for (const auto view : textureViews)
            if (view.id != 0) sg_destroy_view (view);
        for (const auto image : textureImages)
            if (image.id != 0) sg_destroy_image (image);
        if (geometryInstanceBuffer.id != 0) sg_destroy_buffer (geometryInstanceBuffer);
        if (indexBuffer.id != 0) sg_destroy_buffer (indexBuffer);
        if (vertexBuffer.id != 0) sg_destroy_buffer (vertexBuffer);
        if (previousVertexBuffer.id != 0) sg_destroy_buffer (previousVertexBuffer);
        previousVertexBufferCharge.reset();
        previousVertexBuffer = {};
        previousScenePositions.reset();
        previousScenePositionBytes = 0;
        vertexBufferCharge.reset();
        vertexBuffer = {};
        indexBufferCharge.reset();
        indexBuffer = {};
        geometryInstanceBufferCharge.reset();
        geometryInstanceBuffer = {};
        textureCharges.clear();
        textureImages.clear();
        textureViews.clear();
        samplers.clear();
        shader = {};
        privateSurfaceCreation.reset();
        surfaceSourceCreation.reset();
        diffractionResolveShader = {};
        diffractionResolvePipelines = {};
        skyPipelines = {};
        mixedSurfacePipelines = {};
        mixedGratingPipelines = {};
        pipelines.clear();
    }

    std::string backend_ = "metal";
    std::shared_ptr<const HarmonicMIDI::grid::Visual3DScene> snapshot;
    std::shared_ptr<const arbitgpu::NativeFixtureSurfaceMaterialProgram> materialProgram;
    std::shared_ptr<const arbitgpu::NativeFixtureSurfaceMaterialProgram> materialProgramSource;
    std::unique_ptr<const MetalSurfaceSourceCreation> surfaceSourceCreation;
    mutable std::array<arbitgpu::surfacesource::Setup,arbitgpu::surfacesource::FrameAdmission::maximumAttempts> privateSurfaceFactoryJournal{};
    mutable std::size_t privateSurfaceFactoryAttempts=0;
    mutable std::shared_ptr<arbitgpu::surfacesource::FrameAdmission> privateSurfaceAdmission;
    mutable std::shared_ptr<const MetalPrivateSurfaceCreation> privateSurfaceCreation;
    arbitgpu::opaquevisibility::Prepared opaqueVisibility;
    arbitgpu::smoothglass::Prepared smoothGlass;
    std::shared_ptr<const arbitgpu::NativeFixtureSurfaceMaterialProgram> discreteGratingProgram;
    arbitgpu::diffractiontransportnative::Prepared spectralTransport;
    sg_image environmentTexture={};
    sg_view environmentView={};
    videohelper::environmentimage::ResidentPtr environmentResident;
    std::shared_ptr<arbitgpu::environmentimage::GpuBudget> environmentBudget;
    sg_buffer vertexBuffer = {};
    mutable sg_buffer previousVertexBuffer = {};
    // Set when previousVertexBuffer holds retained Geometry3D prior positions
    // rather than a skinned prior pose. The bytes are included in permanentBytes.
    mutable std::shared_ptr<const std::vector<HarmonicMIDI::grid::SceneVec3>> previousScenePositions;
    mutable std::uint64_t previousScenePositionBytes = 0;
    sg_buffer indexBuffer = {};
    sg_buffer geometryInstanceBuffer = {};
    // Charges follow the GPU objects beside them. destroyUnlocked releases each one
    // with its object. The HDR environment texture is charged through environmentBudget.
    arbitgpu::residency::ResidencyCharge vertexBufferCharge;
    arbitgpu::residency::ResidencyCharge indexBufferCharge;
    arbitgpu::residency::ResidencyCharge geometryInstanceBufferCharge;
    mutable arbitgpu::residency::ResidencyCharge previousVertexBufferCharge;
    // One charge per entry in textureImages, in the same order.
    std::vector<arbitgpu::residency::ResidencyCharge> textureCharges;
    bool instancedSharedGeometry = false;
    bool diagnosticInstanceIdentityColors = false;
    std::vector<videowire::geometry::InstanceAppearance> instanceAppearances;
    std::shared_ptr<const videohelper::geometry::AdmittedPlanValue> geometryAdmission;
    std::vector<sg_image> textureImages;
    std::vector<sg_view> textureViews;
    std::vector<sg_sampler> samplers;
    sg_shader shader = {};
    sg_shader diffractionResolveShader = {};
    sg_shader roughReceiptShader = {};
    sg_pipeline_desc roughReceiptPipeline = {};
    std::array<sg_pipeline, 2> diffractionResolvePipelines {};
    std::array<sg_pipeline, 2> skyPipelines {};
    std::array<sg_pipeline, 6> mixedSurfacePipelines {};
    std::array<sg_pipeline, 3> mixedGratingPipelines {};
    // Joint and composition mirror state of each deformed member, keyed by its first output
    // vertex. The compute dispatch writes it, and the draw combines it with objectMatrix.
    struct DeformedWinding final
    {
        bool jointsMixed = false;
        bool skinOrPointMirrored = false;
    };
    mutable std::unordered_map<std::uint32_t, DeformedWinding> deformedWindings;
    const DeformedWinding* deformedWindingFor (std::uint32_t firstVertex) const
    {
        const auto found = deformedWindings.find (firstVertex);
        return found == deformedWindings.end() ? nullptr : &found->second;
    }
    // Opaque/mask then blend, or diffraction, each with double-sided,
    // positive, and reflected winding.
    std::vector<sg_pipeline> pipelines;
    std::uint64_t rendererGeneration = 0;
    mutable std::uint64_t permanentBytes = 0;
};

// Mirror state of a deformed member from its palette and composition point. A joint or the
// point contributes the sign of det(upper 3x3). Mixed joint signs cannot share one front face,
// so the draw disables culling for them.
inline MetalFixtureSceneResources::DeformedWinding metalDeformedMemberWinding (
    const arbitgpu::NativeDeformationFrameData& data) noexcept
{
    const auto determinant = [] (const auto& m) noexcept {
        return m[0] * (m[5] * m[10] - m[9] * m[6]) - m[4] * (m[1] * m[10] - m[9] * m[2])
            + m[8] * (m[1] * m[6] - m[5] * m[2]);
    };
    const auto jointCount = std::min<std::size_t> (data.jointCount, data.jointPalette.size() / 16u);
    std::size_t mirroredJoints = 0;
    for (std::size_t joint = 0; joint < jointCount; ++joint)
        if (determinant (data.jointPalette.data() + joint * 16u) < 0.0f) ++mirroredJoints;
    const bool skinMirrored = jointCount != 0 && mirroredJoints == jointCount;
    const bool pointMirrored = data.compositionPost.control()[1] == 1.0f
        && determinant (data.compositionPost.point().data()) < 0.0f;
    MetalFixtureSceneResources::DeformedWinding winding;
    winding.jointsMixed = mirroredJoints != 0 && mirroredJoints != jointCount;
    winding.skinOrPointMirrored = skinMirrored != pointMirrored;
    return winding;
}

// Winding index for one draw (0 no culling, 1 counterclockwise front, 2 clockwise front) from
// its static index and the member's mirror state.
inline std::uint32_t metalDeformedDrawWinding (std::uint32_t staticWinding,
    const MetalFixtureSceneResources::DeformedWinding* deformed) noexcept
{
    if (deformed == nullptr) return staticWinding;
    if (deformed->jointsMixed) return 0u;
    if (staticWinding == 0u || !deformed->skinOrPointMirrored) return staticWinding;
    return staticWinding == 2u ? 1u : 2u;
}

class MetalFixtureSceneFrame;
static bool metalDirectGratingProgramMatches(
    const std::shared_ptr<const arbitgpu::NativeFixtureSurfaceMaterialProgram>& snapshot,
    const std::shared_ptr<const arbitgpu::NativeFixtureSurfaceMaterialProgram>& compiled)
{
    if(!snapshot||!compiled||snapshot->importedBaseColorTexture||compiled->importedBaseColorTexture
        ||snapshot->frameEndpoint||compiled->frameEndpoint||!snapshot->objectPrograms.empty()||!compiled->objectPrograms.empty())return false;
    const auto key=[](const auto& p){return std::tie(p.layoutVersion,p.backend,p.kind,p.object,p.bindingDigest,p.programIdentity,
        p.vertexProgram,p.baseColorSource,p.roughGlassScatteringVersion,p.diffractionPathCount,p.diffractionMaximumBounceDepth,
        p.diffractionLightingAdmission,p.diffractionPatternMask,p.diffractionMaskCoverage,p.diffractionProductDigest,
        p.diffractionFoilMaximumEvaluations,p.diffractionOccupancyRectangleCount,p.authoredScene,p.authoredMaterial,
        p.sceneRevision,p.structuralRevision,p.evaluationRevision,p.materialRevision);};
    if(key(*snapshot)!=key(*compiled)||std::memcmp(&snapshot->parameters,&compiled->parameters,sizeof(snapshot->parameters))
        ||std::memcmp(snapshot->timeMixEndColor.data(),compiled->timeMixEndColor.data(),sizeof(snapshot->timeMixEndColor))
        ||std::memcmp(snapshot->diffractionPaths.data(),compiled->diffractionPaths.data(),sizeof(snapshot->diffractionPaths))
        ||std::memcmp(snapshot->diffractionFoilField.data(),compiled->diffractionFoilField.data(),sizeof(snapshot->diffractionFoilField))
        ||std::memcmp(snapshot->diffractionOccupancyRectangles.data(),compiled->diffractionOccupancyRectangles.data(),sizeof(snapshot->diffractionOccupancyRectangles))
        ||snapshot->spectralReflectance.has_value()!=compiled->spectralReflectance.has_value())return false;
    return !snapshot->spectralReflectance||(snapshot->spectralReflectance->version==compiled->spectralReflectance->version
        &&std::memcmp(snapshot->spectralReflectance->coefficients.data(),compiled->spectralReflectance->coefficients.data(),
            sizeof(snapshot->spectralReflectance->coefficients))==0);
}
