// allocate_shared rebinds this allocator to the actual control-block type.
// Admit that exact requested size before operator new, including metadata.
// Pair allocation and deletion using the rebound type's alignment.
// Deallocation never touches the frame, so an escaped receipt can outlive it.
template<class T> struct MetalLrAllocator {
    using value_type=T;
    std::uint64_t* observed;
    std::uint64_t limit;
    MetalLrAllocator(std::uint64_t& bytes,std::uint64_t ceiling):observed(&bytes),limit(ceiling){}
    template<class U> MetalLrAllocator(const MetalLrAllocator<U>& other):observed(other.observed),limit(other.limit){}
    T* allocate(std::size_t count){
        std::uint64_t bytes=0,next=0;
        if(!renderpassoutput::detail::checkedMultiply(count,sizeof(T),bytes)
            ||!renderpassoutput::detail::checkedAdd(*observed,bytes,next)||next>limit)throw std::bad_alloc();
        T* memory;
        if constexpr(alignof(T)<=__STDCPP_DEFAULT_NEW_ALIGNMENT__)
            memory=static_cast<T*>(::operator new(std::size_t(bytes)));
        else memory=static_cast<T*>(::operator new(std::size_t(bytes),std::align_val_t(alignof(T))));
        *observed=next;return memory;
    }
    void deallocate(T* memory,std::size_t) noexcept {
        if constexpr(alignof(T)<=__STDCPP_DEFAULT_NEW_ALIGNMENT__)
            ::operator delete(const_cast<std::remove_const_t<T>*>(memory));
        else ::operator delete(const_cast<std::remove_const_t<T>*>(memory),std::align_val_t(alignof(T)));
    }
    template<class U> bool operator==(const MetalLrAllocator<U>& other) const noexcept
        {return observed==other.observed&&limit==other.limit;}
    template<class U> bool operator!=(const MetalLrAllocator<U>& other) const noexcept {return !(*this==other);}
};
