    id<MTLComputePipelineState> trace = nil, initializeKeys = nil, sort = nil, reduce = nil, resolve = nil;
    arbitgpu::glasscaustics::SubmissionIdentity identity;
    arbitgpu::MetalGlassCausticMetrics metrics;
    std::uint64_t bytes = 0, nativeReservation = 0, submission = 0;
    bool validated = false, gratingStagingCompleted = false;
    std::unique_ptr<MetalRasterCaptureManifest> rasterCaptureCandidate;
    std::shared_ptr<const MetalRasterCaptureManifest> rasterCapture;
    // One fixed receipt per manifest. Repeated diagnostics have no count cap;
    // each attempted scan is charged in its own units before reading content.
    MetalRasterCaptureAccounting rasterCaptureAccounting;
    // Residency charges for the objects above. A scratch handoff moves its charge
    // with the buffer, and each charge releases when its object is replaced or
    // when the state is destroyed.
    arbitgpu::residency::ResidencyCharge rasterDepthStencilCharge;
    std::array<arbitgpu::residency::ResidencyCharge,2> rasterImageCharges {};
    arbitgpu::residency::ResidencyCharge workBufferCharge, trianglesBufferCharge, pathsBufferCharge, depositsBufferCharge;
    arbitgpu::residency::ResidencyCharge accumulationBufferCharge, diagnosticBufferCharge, keysBufferCharge, queryTextureCharge;
    arbitgpu::residency::ResidencyCharge directionalInputCharge, directionalEchoCharge;
    arbitgpu::residency::ResidencyCharge cameraSpectralCharge, cameraResolvedCharge;
    arbitgpu::residency::ResidencyCharge cellInputCharge, cellEchoCharge, cellPointNativeCharge;
    arbitgpu::residency::ResidencyCharge cellBoundaryNativeCharge, cellLocatorNativeCharge, coverageNativeCharge;
    ~MetalCausticState() {
        if(rasterDepthStencilView.id)sg_destroy_view(rasterDepthStencilView);
        if(rasterDepthStencil.id)sg_destroy_image(rasterDepthStencil);
        for(auto p:rasterPipelines) if(p.id) sg_destroy_pipeline(p);
        for(auto v:rasterViews) if(v.id) sg_destroy_view(v);
        for(auto i:rasterImages) if(i.id) sg_destroy_image(i);
        if(rasterShader.id) sg_destroy_shader(rasterShader);
#if ! __has_feature(objc_arc)
        [query release];[work release];[triangles release];[paths release];[deposits release];
        [cohortStagingCommand release];
        [cameraSpectral release];[cameraResolved release];
        [cellInput release];[cellEcho release];[cellPointNative release];[cellBoundaryNative release];[cellLocatorNative release];
        [coverageNative release];
        [directionalInput release];[directionalEcho release];
        [accumulation release];[diagnostic release];[keys release];[trace release];[initializeKeys release];
        [sort release];[reduce release];[resolve release];[library release];
#endif
    }
};

// Supplementary work retains the original GPU point buffer until its own fence.
struct MetalGratingPointNativeInput {
    id<MTLBuffer> incidents=nil;
    arbitgpu::residency::ResidencyCharge incidentsCharge;
    std::vector<std::uint32_t> locators;
    std::shared_ptr<const arbitgpu::glasscaustics::GratingEntryCellBinding> sourceCells;
    const arbitgpu::glasscaustics::NativeReadback* incumbentPoint=nullptr;
    const arbitgpu::glasscaustics::NativeGratingCellTransportReadback* incumbentCells=nullptr;
    ~MetalGratingPointNativeInput() {
#if ! __has_feature(objc_arc)
        [incidents release];
#endif
    }
};

struct MetalSelectedRoughCamera final
{
    struct Selection { std::array<float,4> ray,position,normal; std::array<std::uint32_t,4> ids; std::array<std::int32_t,4> state; };
    struct Result { std::array<float,4> color,terminal,masked,tail; std::array<std::uint32_t,4> ids,work; };
    static_assert(sizeof(Selection)==80 && sizeof(Result)==96);
    using Work=arbitgpu::roughglasstiles::NativeTileReceipt::Work;
    // GPU records, retained completed CPU records, result upload and texture.
    // Receipt/readback storage is also charged by the shared tile admission.
    static constexpr std::uint64_t residentBytesPerPixel=2*(sizeof(Selection)+sizeof(Result)+sizeof(Work))+48*(SG_NUM_INFLIGHT_FRAMES+2);
    id<MTLLibrary> library=nil;
    id<MTLComputePipelineState> select=nil,transport=nil;
    id<MTLBuffer> uniforms=nil,selection=nil,result=nil,work=nil;
    // Charges follow the objects beside them. Buffers release through ARC and images
    // through sg_destroy_image in the destructor, so each charge releases with its object.
    arbitgpu::residency::ResidencyCharge uniformsCharge,selectionCharge,resultCharge,workCharge;
    id<MTLCommandBuffer> completedCommand=nil;
    id<MTLCommandQueue> queue=nil;
    std::shared_ptr<const arbitgpu::roughglasstiles::Schedule> schedule;
    arbitgpu::roughglasstiles::Tile completedTile {};
    std::vector<Selection> selections;
    std::vector<Result> results;
    std::vector<Work> nativeWork;
    std::vector<std::array<float,4>> upload;
    std::array<arbitgpu::NativeRawPassPixels,3> receipts;
    sg_image sharedImage {},resolvedImage {};
    arbitgpu::residency::ResidencyCharge sharedImageCharge,resolvedImageCharge;
    sg_view sharedView {},resolvedAttachment {},resolvedView {};
    sg_shader resolveShader {};
    sg_pipeline resolvePipeline {};
    std::uint64_t nativeReservation=0;
    bool completed=false;
    ~MetalSelectedRoughCamera() {
        if(resolvePipeline.id)sg_destroy_pipeline(resolvePipeline);
        if(resolveShader.id)sg_destroy_shader(resolveShader);
        if(sharedView.id)sg_destroy_view(sharedView);
        if(sharedImage.id)sg_destroy_image(sharedImage);
        if(resolvedAttachment.id)sg_destroy_view(resolvedAttachment);
        if(resolvedView.id)sg_destroy_view(resolvedView);
        if(resolvedImage.id)sg_destroy_image(resolvedImage);
#if ! __has_feature(objc_arc)
        [completedCommand release];[queue release];[uniforms release];[selection release];[result release];[work release];
        [select release];[transport release];[library release];
#endif
    }
};

