        }
    }

    const std::string& backend() const noexcept override { return backend_; }
    const arbitgpu::NativeFixtureSceneFrame& owner() const noexcept override { return *this; }
    const arbitgpu::glasscaustics::NativeDirectionalSourceUpload& upload() const noexcept override {
