    }
    const arbitgpu::glasscaustics::NativeDirectionalSourceUpload absentDirectionalUpload {};
    const arbitgpu::glasscaustics::NativeDirectionalSourceBinding& directSourceBinding() const noexcept override {return *this;}
    const MetalDirectGratingBatch* directBatch() const noexcept {
        return !caustic?nullptr:caustic->directCandidate?caustic->directCandidate
            :caustic->directBatches.empty()?nullptr:caustic->directBatches.back().get();
    }
    const std::shared_ptr<const arbitgpu::glasscaustics::GratingIncidentBinding>& directGratingBinding() const noexcept override {
        const auto* batch=directBatch();return batch?batch->binding:absentDirectBinding;
    }
    const arbitgpu::glasscaustics::NativeDirectGratingEndpointUpload& directEndpointUpload() const noexcept override {
        const auto* batch=directBatch();return batch?batch->upload:absentDirectUpload;
    }
    bool validateDirectProductionQuery(const arbitgpu::glasscaustics::SubmissionIdentity& expected,
        const arbitgpu::glasscaustics::NativeDirectGratingContributionReadback& supplied,std::string& error) const override {
        using namespace arbitgpu;using namespace glasscaustics;
        const auto refuse=[&](){error="Metal direct contribution lost its executed buffer, query, device or fence association";return false;};
        const auto* b=directBatch();
        if(metalDirectQueryLease!=this||!b||!caustic||!staticResources||!gMetalDevice||!sg_isvalid()
            ||!caustic->gratingStagingCompleted||caustic->validated||!privateCameraAttachments
            ||b->binding!=caustic->cameraBinding||rendererGeneration_!=staticResources->rendererGeneration
            ||!metalDirectGratingProgramMatches(b->binding->gratingOwner,staticResources->discreteGratingProgram)
            ||!caustic->cameraInputs||caustic->cameraInputs->timeSeconds!=float(b->binding->evaluationTime)
            ||b->binding->prepared.glass.sourceScene!=staticResources->snapshot
            ||b->binding->prepared.glass.sourceMaterial!=staticResources->materialProgram
            ||!b->dispatched||!b->command||b->command.status!=MTLCommandBufferStatusCompleted
            ||!b->queue||b->queue.device!=gMetalDevice||b->command.commandQueue!=b->queue
            ||b->queue!=(__bridge id<MTLCommandQueue>)sg_mtl_command_queue()
            ||!b->library||b->library.device!=gMetalDevice||!b->pipeline||b->pipeline.device!=gMetalDevice
            ||!(b->readback.submission==expected)||!(b->upload.submission==expected)
            ||expected.completedFence!=expected.submissionSerial||expected.rendererGeneration!=rendererGeneration_
            ||expected.queryGeneration!=caustic->identity.queryGeneration||expected.rasterGeneration!=caustic->identity.rasterGeneration
            ||caustic->identity.completedFence!=caustic->submission
            ||b->sourceInput!=caustic->directionalInput||!b->sourceInput||!b->sourceInput.contents
            ||b->sourceInput.device!=gMetalDevice||b->sourceInput.length!=sizeof(NativeDirectionalSourceInput)
            ||std::memcmp(b->sourceInput.contents,&upload().input,sizeof(upload().input))!=0
            ||b->query!=caustic->query||!b->query||b->query.device!=gMetalDevice
            ||b->query.width!=opaquevisibility::kTextureWidth||b->query.height!=b->binding->frame.query.height
            ||b->query.pixelFormat!=MTLPixelFormatRGBA32Float
            ||b->params.query!=caustic->params.query||b->params.source!=caustic->params.source
            ||b->params.query!=b->binding->frame.query.control||b->params.source!=b->binding->frame.sourceDirectionTrace
            ||std::memcmp(b->params.radiance.data(),b->binding->frame.sourceRadiance.data(),sizeof(b->params.radiance))!=0
            ||std::memcmp(b->params.radiance.data(),caustic->params.radiance,sizeof(b->params.radiance))!=0)
            return refuse();
        if(!arbitgpu::inspectMetalRasterCaptureUnlocked(*this,error))return false;
        const std::array<id<MTLBuffer>,4> buffers{b->input,b->result,b->witness,b->uniforms};
        const std::array<std::uint64_t,4> lengths{b->upload.inputs.size()*sizeof(NativeDirectGratingEndpointInput),
            b->packed.size()*sizeof(metalcaustic::DirectGratingResult),b->witnesses.size()*sizeof(metalcaustic::DirectGratingWitness),sizeof(b->params)};
        std::uint64_t alignment=0;
        for(unsigned i=0;i<buffers.size();++i) {
            const auto v=buffers[i];
            if(!v||!v.contents||v.device!=gMetalDevice||v.length!=lengths[i]||v.length>gMetalDevice.maxBufferLength)return refuse();
            const auto extra=std::max<std::uint64_t>(v.length,v.allocatedSize)-v.length;
            if(extra>renderpassoutput::kMaximumTotalBytes-alignment)return refuse();alignment+=extra;
        }
        if(std::memcmp(b->input.contents,b->upload.inputs.data(),lengths[0])!=0
            ||std::memcmp(b->result.contents,b->packed.data(),lengths[1])!=0
            ||std::memcmp(b->witness.contents,b->witnesses.data(),lengths[2])!=0
            ||std::memcmp(b->uniforms.contents,&b->params,sizeof(b->params))!=0
            ||b->packed.size()!=b->readback.samples.size()||b->params.control!=std::array<std::uint32_t,4>{
                std::uint32_t(b->upload.inputs.size()),std::uint32_t(b->binding->triangles.size()),1,0})return refuse();
        DirectGratingContributionBounds admitted;
        if(!calculateDirectGratingContributionBounds(*b->binding,b->upload.inputs.size(),b->upload.otherOwnedBytes,
            b->upload.otherWork,admitted,error)||admitted.bytes!=b->bounds.bytes||admitted.combinedWork!=b->bounds.combinedWork
            ||alignment!=b->alignedBytes)return refuse();
        for(std::size_t i=0;i<b->packed.size();++i) {
            const auto& r=b->packed[i];const auto decoded=metalcaustic::decodeDirectGrating(r);
            if(r.control!=std::array<std::uint32_t,4>{1,1,std::uint32_t(decoded.outcome),0}
                ||r.work[0]!=r.endpoint.value.work||r.work[1]!=r.shadow.value.work||r.work[2]!=8||r.work[3]
                ||r.endpoint.padding!=std::array<std::uint32_t,6>{}||r.shadow.padding!=std::array<std::uint32_t,6>{}
                ||r.barycentric[3]||std::memcmp(&r.input,&b->upload.inputs[i],sizeof(r.input))!=0
                ||!metalcaustic::sameDirectGratingSample(decoded,b->readback.samples[i]))return refuse();
        }
        if(caustic->directPrimitiveBytes>renderpassoutput::kMaximumTotalBytes-caustic->metrics.admittedBytes
            ||caustic->directWork>kMaximumQueryWork-b->binding->bounds.combinedWork
            ||caustic->adjunctWork>kMaximumQueryWork-b->binding->bounds.combinedWork-caustic->directWork)return refuse();
        std::uint64_t current=b->binding->frame.bounds.transientBytes;
        for(auto bytes:{b->binding->bounds.bytes,caustic->metrics.admittedBytes,caustic->directPrimitiveBytes,
            caustic->cameraPrimitiveBytes,caustic->cellPrimitiveBytes,caustic->coveragePrimitiveBytes}) {
            if(bytes>renderpassoutput::kMaximumTotalBytes-current)return refuse();current+=bytes;
        }
        // The decoded owner was populated from this completed result buffer.
        // Its packed bytes and native controls were checked above. Compare the
        // supplied batch here so direct shared validation has the same gate.
        if(!sameDirectGratingContributionReadback(supplied,b->readback)) {
            error="Metal direct contribution differs from its actual retained native output";return false;
        }
        error.clear();return true;
    }
    const std::shared_ptr<const arbitgpu::glasscaustics::GratingIncidentBinding> absentDirectBinding;
    const arbitgpu::glasscaustics::NativeDirectGratingEndpointUpload absentDirectUpload {};
    const MetalDirectGratingCohort* directCohortBatch() const noexcept {
        return !caustic?nullptr:caustic->cohortCandidate?caustic->cohortCandidate
            :caustic->directCohorts.empty()?nullptr:caustic->directCohorts.back().get();
