    const arbitgpu::glasscaustics::NativeDirectGratingIrradianceBinding* directSourceBatch(std::size_t i) const noexcept override {
        const auto* c=directCohortBatch();return c&&i<c->sources.size()?c->sources[i].get():nullptr;
