    bool validateDirectCohortTerminalResult(const arbitgpu::glasscaustics::NativeDirectGratingTerminalLease&,
        const arbitgpu::glasscaustics::DirectGratingTerminalOrderLedger&,std::string&) const override;
    bool beginDirectTerminalReceiverLease(const std::shared_ptr<const arbitgpu::glasscaustics::NativeDirectGratingTerminalResult>&,
        const arbitgpu::glasscaustics::SubmissionIdentity&,double,
        std::unique_ptr<arbitgpu::glasscaustics::NativeDirectGratingTerminalReceiverLease>&,
        arbitgpu::glasscaustics::DirectGratingTerminalReceiverNativeBudget&,std::string&) const override;
    bool reserveDirectTerminalReceiverLease(arbitgpu::glasscaustics::NativeDirectGratingTerminalReceiverLease&,
        const arbitgpu::glasscaustics::DirectGratingTerminalReceiverBounds&,
        const arbitgpu::glasscaustics::DirectGratingTerminalReceiverReadback&,std::string&) const override;
    bool dispatchDirectTerminalReceivers(arbitgpu::glasscaustics::NativeDirectGratingTerminalReceiverLease&,
        const std::vector<arbitgpu::glasscaustics::NativeDirectGratingTerminalReceiverInput>&,
        arbitgpu::glasscaustics::DirectGratingTerminalReceiverReadback&,std::string&) const override;
    bool finishDirectTerminalReceiverLease(arbitgpu::glasscaustics::NativeDirectGratingTerminalReceiverLease&,
        const arbitgpu::glasscaustics::DirectGratingTerminalReceiverReadback&,
        std::shared_ptr<const arbitgpu::glasscaustics::NativeDirectGratingTerminalReceiverResult>&,std::string&) const override;
    bool validateDirectTerminalReceiverResult(const arbitgpu::glasscaustics::NativeDirectGratingTerminalReceiverLease&,
        const arbitgpu::glasscaustics::DirectGratingTerminalReceiverReadback&,std::string&) const override;

    const arbitgpu::NativeFixtureSceneFrame& coverageOwner() const noexcept override {return *this;}
    bool beginCameraCellCoverageLease(const std::shared_ptr<const arbitgpu::glasscaustics::NativeDirectGratingTerminalReceiverResult>&,
        const arbitgpu::glasscaustics::SubmissionIdentity&,double,std::unique_ptr<arbitgpu::glasscaustics::NativeCameraCellCoverageLease>&,
        arbitgpu::glasscaustics::NativeCameraCellCoverageBudget&,std::string&) const override;
    bool reserveCameraCellCoverageLease(arbitgpu::glasscaustics::NativeCameraCellCoverageLease&,
        const arbitgpu::glasscaustics::CameraCellCoverageBounds&,const arbitgpu::glasscaustics::CameraCellCoverageReadback&,std::string&) const override;
    bool dispatchCameraCellCoverage(arbitgpu::glasscaustics::NativeCameraCellCoverageLease&,
