    std::uintptr_t depthTextureViewHandle() const noexcept override
    {
        return privateCameraAttachments?0:depthTextureView.id;
    }
    std::uintptr_t nativeResourceCacheIdentity() const noexcept override
    {
        return reinterpret_cast<std::uintptr_t> (staticResources.get());
    }
    arbitgpu::NativeTextureViewDescriptor colorTextureDescriptor() const noexcept override
    {
        if(privateCameraAttachments)return {};
        return { backend_, arbitgpu::NativeTextureViewKind::Texture2D,
                 linearColor ? arbitgpu::NativeTexturePixelFormat::Rgba16Float : arbitgpu::NativeTexturePixelFormat::Bgra8Unorm,
                 colorImage.id, colorTextureView.id,
                 width_, height_, 1, true,
                 reinterpret_cast<std::uintptr_t>((__bridge void*)gMetalDevice), rendererGeneration_,
                 linearColor ? colortransform::ColorSpace::LinearSRGB
                    : declaredSrgb ? colortransform::ColorSpace::SRGB : colortransform::ColorSpace::Unspecified,
                 linearColor ? colortransform::TransferFunction::Linear
                    : declaredSrgb ? colortransform::TransferFunction::SRGB : colortransform::TransferFunction::Unspecified };
    }
    arbitgpu::NativeTextureViewDescriptor depthTextureDescriptor() const noexcept override
    {
        if(privateCameraAttachments)return {};
        return { backend_, arbitgpu::NativeTextureViewKind::Texture2D,
                 arbitgpu::NativeTexturePixelFormat::R32Float, depthImage.id, depthTextureView.id,
                 width_, height_, 1, true,
                 reinterpret_cast<std::uintptr_t>((__bridge void*)gMetalDevice), rendererGeneration_ };
    }
    arbitgpu::NativeTextureViewDescriptor passTextureDescriptor(renderpassoutput::Output output) const noexcept override
    {
        if(privateCameraAttachments)return {};
        for (std::size_t i = 2; i < renderpasscomposite::kInputs.size(); ++i)
            if (renderpasscomposite::kInputs[i] == output)
                return { backend_, arbitgpu::NativeTextureViewKind::Texture2D, rawFormats[i - 2],
                    rawImages[i - 2].id, rawTextureViews[i - 2].id, width_, height_, 1, true,
                    reinterpret_cast<std::uintptr_t>((__bridge void*)gMetalDevice), rendererGeneration_ };
        return NativeFixtureSceneFrame::passTextureDescriptor(output);
    }

    bool hasResources() const noexcept
    {
        return colorImage.id != 0 || colorAttachmentView.id != 0
            || colorTextureView.id != 0 || depthImage.id != 0 || depthView.id != 0
            || depthTextureView.id != 0 || depthStencilImage.id != 0
            || depthStencilView.id != 0 || diffractionAccumulationImage.id != 0
            || opaqueImage.id != 0 || opaqueView.id != 0 || glassImage.id != 0 || glassView.id != 0
            || spectralQueryImage.id != 0 || spectralSampleImage.id != 0 || spectralDiagnostic != nil
            || roughReceiptImages[0].id != 0 || roughReceiptPipelines[0].id != 0 || caustic != nullptr || selectedRough != nullptr;
    }

    void destroyUnlocked() noexcept
    {
        settleOpenSokolCommandBufferUnlocked();
        selectedRough.reset();
        caustic.reset();
        if(roughTileDepthView.id) sg_destroy_view(roughTileDepthView);
        if(roughTileDepthImage.id) sg_destroy_image(roughTileDepthImage);
        roughTileDepthCharge.reset();
        roughTileDepthView={};roughTileDepthImage={};roughTileSchedule.reset();roughTilesComplete=false;
#if ! __has_feature(objc_arc)
        [spectralDiagnostic release];
#endif
        spectralDiagnostic = nil;
        spectralDiagnosticCharge.reset();
        for (const auto pipeline : roughReceiptPipelines)
            if (pipeline.id) sg_destroy_pipeline(pipeline);
        for (std::size_t i = 0; i < roughReceiptImages.size(); ++i) {
            if (roughReceiptTextureViews[i].id) sg_destroy_view(roughReceiptTextureViews[i]);
            if (roughReceiptAttachmentViews[i].id) sg_destroy_view(roughReceiptAttachmentViews[i]);
            if (roughReceiptImages[i].id) sg_destroy_image(roughReceiptImages[i]);
        }
        for (auto& charge : roughReceiptCharges) charge.reset();
        roughReceiptPipelines = {}; roughReceiptImages = {};
        roughReceiptTextureViews = {}; roughReceiptAttachmentViews = {};
        roughReceiptValidated = false; roughReceiptSubmission = 0; roughReceiptBytes = 0;
        roughReceiptProgram.reset(); roughReceiptInputs.reset();
        if (glassView.id) sg_destroy_view(glassView);
        if (spectralQueryView.id) sg_destroy_view(spectralQueryView);
        if (spectralSampleView.id) sg_destroy_view(spectralSampleView);
        if (spectralQueryImage.id) sg_destroy_image(spectralQueryImage);
        if (spectralSampleImage.id) sg_destroy_image(spectralSampleImage);
        spectralQueryView={}; spectralSampleView={}; spectralQueryImage={}; spectralSampleImage={};
        spectralQueryImageCharge.reset(); spectralSampleImageCharge.reset();
        if (glassImage.id) sg_destroy_image(glassImage);
        glassView={}; glassImage={};
        glassImageCharge.reset();
        if (opaqueView.id) sg_destroy_view(opaqueView);
        if (opaqueImage.id) sg_destroy_image(opaqueImage);
        opaqueView={}; opaqueImage={};
        opaqueImageCharge.reset();
        for (std::size_t i = 0; i < rawImages.size(); ++i)
        {
            if (rawTextureViews[i].id) sg_destroy_view(rawTextureViews[i]);
            if (rawAttachmentViews[i].id) sg_destroy_view(rawAttachmentViews[i]);
            if (rawImages[i].id) sg_destroy_image(rawImages[i]);
        }
        rawImages = {}; rawTextureViews = {}; rawAttachmentViews = {};
        for (auto& charge : rawImageCharges) charge.reset();
        if (depthTextureView.id != 0) sg_destroy_view (depthTextureView);
        if (depthView.id != 0) sg_destroy_view (depthView);
        if (depthImage.id != 0) sg_destroy_image (depthImage);
        depthImageCharge.reset();
        if (depthStencilView.id != 0) sg_destroy_view (depthStencilView);
        if (depthStencilImage.id != 0) sg_destroy_image (depthStencilImage);
        depthStencilImageCharge.reset();
        if (diffractionAccumulationTextureView.id != 0)
            sg_destroy_view (diffractionAccumulationTextureView);
        if (diffractionAccumulationAttachmentView.id != 0)
            sg_destroy_view (diffractionAccumulationAttachmentView);
        if (diffractionAccumulationImage.id != 0)
            sg_destroy_image (diffractionAccumulationImage);
        diffractionAccumulationImageCharge.reset();
        if (colorTextureView.id != 0) sg_destroy_view (colorTextureView);
        if (colorAttachmentView.id != 0) sg_destroy_view (colorAttachmentView);
        if (colorImage.id != 0) sg_destroy_image (colorImage);
        colorImageCharge.reset();
        colorImage = {};
        colorAttachmentView = {};
        colorTextureView = {};
        depthImage = {};
        depthView = {};
        depthTextureView = {};
        depthStencilImage = {};
        depthStencilView = {};
        diffractionAccumulationImage = {};
        diffractionAccumulationAttachmentView = {};
        diffractionAccumulationTextureView = {};
    }

    std::string backend_ = "metal";
    std::uint32_t width_ = 0;
    std::uint32_t height_ = 0;
    std::shared_ptr<const MetalFixtureSceneResources> staticResources;
    bool linearColor = false, privateCameraAttachments = false;
    bool declaredSrgb = false;
    std::shared_ptr<const videoopticalflow::PublishedNativeResult> opticalFieldOwner;
    std::shared_ptr<const videoopticalflow::NativeSourceFrame> opticalImageOwner;
    std::shared_ptr<const arbitgpu::NativeFixtureSceneFrame> materialFrameTexture;
    std::map<surfacematerialbinding::TextureSlotBinding::GraphFrameEndpoint,
        std::shared_ptr<const arbitgpu::NativeFixtureSceneFrame>> materialFrameTextures;
    std::uint64_t rendererGeneration_ = 0;
    std::shared_ptr<const arbitgpu::roughglasstiles::Schedule> roughTileSchedule;
    arbitgpu::roughglasstiles::Aggregate roughTileAggregate;
    bool roughTilesComplete = false;
    sg_image roughTileDepthImage {};
    arbitgpu::residency::ResidencyCharge roughTileDepthCharge;
    sg_view roughTileDepthView {};
    std::unique_ptr<MetalCausticState> caustic;
    std::unique_ptr<MetalSelectedRoughCamera> selectedRough;
    std::array<sg_image, 3> roughReceiptImages {};
    std::array<arbitgpu::residency::ResidencyCharge, 3> roughReceiptCharges {};
    std::array<sg_view, 3> roughReceiptTextureViews {}, roughReceiptAttachmentViews {};
    std::array<sg_pipeline, 3> roughReceiptPipelines {};
    std::uint64_t roughReceiptSubmission = 0, roughReceiptBytes = 0;
    bool roughReceiptValidated = false;
    std::shared_ptr<const arbitgpu::NativeFixtureSurfaceMaterialProgram> roughReceiptProgram;
    std::shared_ptr<const arbitgpu::NativeFixtureSceneRuntimeInputs> roughReceiptInputs;
    sg_image opaqueImage = {};
    sg_view opaqueView = {};
    id<MTLBuffer> spectralDiagnostic = nil;
    sg_image spectralQueryImage = {}, spectralSampleImage = {};
    sg_view spectralQueryView = {}, spectralSampleView = {};
    sg_image glassImage = {};
    sg_view glassView = {};
    sg_image colorImage = {};
    sg_view colorAttachmentView = {};
    sg_view colorTextureView = {};
    sg_image depthImage = {};
    sg_view depthView = {};
    sg_view depthTextureView = {};
    sg_image depthStencilImage = {};
    sg_view depthStencilView = {};
    sg_image diffractionAccumulationImage = {};
    sg_view diffractionAccumulationAttachmentView = {};
    sg_view diffractionAccumulationTextureView = {};
    // Per-frame targets are fixture-scene residency. Each charge releases with its
    // image in destroyUnlocked, and any charge left over releases with the frame.
    arbitgpu::residency::ResidencyCharge colorImageCharge, depthImageCharge, depthStencilImageCharge;
    arbitgpu::residency::ResidencyCharge diffractionAccumulationImageCharge, opaqueImageCharge, glassImageCharge;
    arbitgpu::residency::ResidencyCharge spectralQueryImageCharge, spectralSampleImageCharge, spectralDiagnosticCharge;
    std::array<arbitgpu::residency::ResidencyCharge, 6> rawImageCharges {};
    bool readRawPass(renderpassoutput::Output output, arbitgpu::NativeRawPassPixels& pixels,
                     std::string& error) const override
    {
        pixels = {};
        std::lock_guard<std::mutex> lock(sokolMutex());
        return readRawPassOwned(output, pixels, error);
    }
    // The renderer already holds the owning context/device mutex.
    bool readRawPassOwned(renderpassoutput::Output output, arbitgpu::NativeRawPassPixels& pixels,
                          std::string& error, bool spectralAccumulation = false) const
    {
        pixels = {};
        auto descriptor = passTextureDescriptor(output);
        if (spectralAccumulation) {
            descriptor.format = arbitgpu::NativeTexturePixelFormat::Rgba16Float;
            descriptor.imageHandle = diffractionAccumulationImage.id;
            descriptor.textureViewHandle = diffractionAccumulationTextureView.id;
        }
        if (!descriptor.complete() || !arbitgpu::rawPassFormatMatches(output, descriptor.format)
            || !arbitgpu::nativeFixtureDimensionsWithinBounds(width_, height_)
            || (!staticResources && output != renderpassoutput::Output::Color))
        { error = "Metal raw pass requires its live owner and supported attachment"; return false; }
        sg_image image {}; image.id = static_cast<std::uint32_t>(descriptor.imageHandle);
        return readTextureOwned(image, descriptor.format, pixels, error);
    }

    bool readRoughReceiptOwned(std::array<arbitgpu::NativeRawPassPixels, 3>& pixels,
                               std::string& error) const
    {
        if (!staticResources || !roughReceiptProgram || !roughReceiptInputs
            || roughReceiptSubmission == 0 || roughReceiptBytes != std::uint64_t(width_) * height_ * 48
            || rendererGeneration_ != staticResources->rendererGeneration
            || staticResources->snapshot != staticResources->smoothGlass.sourceScene
            || staticResources->materialProgram != staticResources->smoothGlass.sourceMaterial
            || roughReceiptProgram != staticResources->materialProgram
            || roughReceiptProgram->programIdentity != staticResources->smoothGlass.sourceMaterial->programIdentity
            || roughReceiptProgram->sceneRevision != staticResources->smoothGlass.sourceMaterial->sceneRevision)
        { error = "Metal rough glass receipt has stale scene, program or frame ownership"; return false; }
        if(selectedRough) {
            const auto& state=*selectedRough;
            if(!state.completed || state.completedCommand.status!=MTLCommandBufferStatusCompleted
                ||state.schedule!=roughTileSchedule || state.schedule->tiles().size()!=1
                ||!arbitgpu::roughglasstiles::sameTile(state.completedTile,state.schedule->tiles().front())) {
                error="Metal selected receipt requires its exact completed single-tile owner";return false;
            }
            pixels=state.receipts;return true;
        }
        for (std::size_t i = 0; i < pixels.size(); ++i)
            if (!readTextureOwned(roughReceiptImages[i], arbitgpu::NativeTexturePixelFormat::Rgba32Float,
                                  pixels[i], error)) return false;
        return true;
    }

    bool readTextureOwned(sg_image image, arbitgpu::NativeTexturePixelFormat format,
                          arbitgpu::NativeRawPassPixels& pixels, std::string& error) const
    {
        return readTextureRegionOwned(image,format,width_,height_,0,0,width_,height_,pixels,error);
    }

    bool readTextureRegionOwned(sg_image image,arbitgpu::NativeTexturePixelFormat format,
        std::uint32_t textureWidth,std::uint32_t textureHeight,std::uint32_t x,std::uint32_t y,
        std::uint32_t width,std::uint32_t height,arbitgpu::NativeRawPassPixels& pixels,std::string& error) const
    {
        pixels = {};
        if(!width||!height||x>textureWidth||width>textureWidth-x||y>textureHeight||height>textureHeight-y)
        {error="Metal owned tile readback region is out of bounds";return false;}
        if (!resourceValid(sg_query_image_state(image)))
        { error = "Metal owned readback image is unavailable"; return false; }
        const auto info = sg_mtl_query_image_info(image);
        if (info.active_slot < 0 || info.active_slot >= SG_NUM_INFLIGHT_FRAMES)
        { error = "Metal raw pass has no live texture slot"; return false; }
        id<MTLTexture> texture = (__bridge id<MTLTexture>) info.tex[info.active_slot];
        id<MTLCommandQueue> queue = (__bridge id<MTLCommandQueue>) sg_mtl_command_queue();
        MTLPixelFormat expectedFormat = MTLPixelFormatInvalid;
        using F = arbitgpu::NativeTexturePixelFormat;
        switch (format)
        {
            case F::Bgra8Unorm: expectedFormat = MTLPixelFormatBGRA8Unorm; break;
            case F::R32Float: expectedFormat = MTLPixelFormatR32Float; break;
            case F::Rgba16Float: expectedFormat = MTLPixelFormatRGBA16Float; break;
            case F::Rgba32Float: expectedFormat = MTLPixelFormatRGBA32Float; break;
            case F::Rg16Float: expectedFormat = MTLPixelFormatRG16Float; break;
            case F::R32Uint: expectedFormat = MTLPixelFormatR32Uint; break;
            case F::R8Unorm: expectedFormat = MTLPixelFormatR8Unorm; break;
            default: break;
        }
        if (texture == nil || queue == nil || texture.device != gMetalDevice
            || queue.device != gMetalDevice || expectedFormat == MTLPixelFormatInvalid
            || texture.pixelFormat != expectedFormat || texture.textureType != MTLTextureType2D
            || texture.width != textureWidth || texture.height != textureHeight || texture.sampleCount != 1)
        { error = "Metal raw pass texture ownership or extent mismatch"; return false; }
        const auto tightRow = static_cast<std::size_t>(width) * arbitgpu::rawPassChannels(format)
            * arbitgpu::rawPassScalarBytes(format);
        const auto rowBytes = (tightRow + 255u) & ~std::size_t(255u);
        id<MTLBuffer> buffer = [gMetalDevice newBufferWithLength:rowBytes * height
                                                       options:MTLResourceStorageModeShared];
        id<MTLCommandBuffer> command = [queue commandBuffer];
        id<MTLBlitCommandEncoder> blit = buffer != nil ? [command blitCommandEncoder] : nil;
        bool ok = buffer != nil && command != nil && blit != nil;
        if (ok)
        {
            [blit copyFromTexture:texture sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(x, y, 0)
                      sourceSize:MTLSizeMake(width, height, 1) toBuffer:buffer destinationOffset:0
             destinationBytesPerRow:rowBytes destinationBytesPerImage:rowBytes * height];
            [blit endEncoding];
            [command commit];
            [command waitUntilCompleted];
            ok = command.status == MTLCommandBufferStatusCompleted && buffer.contents != nullptr;
        }
        if (ok)
        {
            pixels = { format, width, height, std::vector<std::uint8_t>(tightRow * height) };
            const auto* source = static_cast<const std::uint8_t*>(buffer.contents);
            // Metal texture row zero is the top row. Strip only the blit padding.
            for (std::uint32_t row = 0; row < height; ++row)
                std::copy_n(source + row * rowBytes, tightRow, pixels.bytes.data() + row * tightRow);
            if (pixels.format == arbitgpu::NativeTexturePixelFormat::Bgra8Unorm)
            {
                for (std::size_t i = 0; i < pixels.bytes.size(); i += 4)
                    std::swap(pixels.bytes[i], pixels.bytes[i + 2]);
                pixels.format = arbitgpu::NativeTexturePixelFormat::Rgba8Unorm;
            }
        }
#if ! __has_feature(objc_arc)
        [buffer release];
#endif
        error = ok ? "" : "Metal raw pass readback failed";
        return ok;
    }

    std::array<sg_image, 6> rawImages {};
    std::array<sg_view, 6> rawTextureViews {}, rawAttachmentViews {};
    inline static constexpr std::array<arbitgpu::NativeTexturePixelFormat, 6> rawFormats {
        arbitgpu::NativeTexturePixelFormat::Rgba16Float, arbitgpu::NativeTexturePixelFormat::Rgba16Float,
        arbitgpu::NativeTexturePixelFormat::R8Unorm, arbitgpu::NativeTexturePixelFormat::R32Uint,
        arbitgpu::NativeTexturePixelFormat::R32Uint, arbitgpu::NativeTexturePixelFormat::Rg16Float };
};

