class MetalDeformationResources final : public arbitgpu::NativeDeformationResources
{
public:
    ~MetalDeformationResources() override
    {
        if (hasResources())
        {
            std::lock_guard<std::mutex> lock (sokolMutex());
            destroyUnlocked();
        }
    }

    const std::string& backend() const noexcept override { return backend_; }

    bool hasResources() const noexcept
    {
        return baseVertices.id != 0 || deformedVertices.id != 0
            || indexBuffer.id != 0 || jointIndices.id != 0
            || jointWeights.id != 0 || morphPositions.id != 0
            || morphNormals.id != 0 || jointPalette.id != 0
            || morphWeights.id != 0 || previousJointPalette.id != 0 || previousMorphWeights.id != 0
            || computeShader.id != 0
            || computePipeline.id != 0 || drawShader.id != 0
            || drawPipeline.id != 0;
    }

    void destroyUnlocked() noexcept
    {
        if (drawPipeline.id != 0) sg_destroy_pipeline (drawPipeline);
        if (drawShader.id != 0) sg_destroy_shader (drawShader);
        if (computePipeline.id != 0) sg_destroy_pipeline (computePipeline);
        if (computeShader.id != 0) sg_destroy_shader (computeShader);
        for (auto view : { previousDeformedVerticesView, previousMorphWeightsView, previousJointPaletteView,
                           morphWeightsView, jointPaletteView, morphNormalsView,
                           morphPositionsView, jointWeightsView, jointIndicesView,
                           deformedVerticesView, baseVerticesView })
            if (view.id != 0) sg_destroy_view (view);
        for (auto buffer : { previousMorphWeights, previousJointPalette, morphWeights, jointPalette, morphNormals, morphPositions,
                             jointWeights, jointIndices, indexBuffer,
                             deformedVertices, baseVertices })
            if (buffer.id != 0) sg_destroy_buffer (buffer);
        bufferCharges.clear();
        baseVertices = {}; baseVerticesView = {};
        deformedVertices = {}; deformedVerticesView = {};
        indexBuffer = {};
        jointIndices = {}; jointIndicesView = {};
        jointWeights = {}; jointWeightsView = {};
        morphPositions = {}; morphPositionsView = {};
        morphNormals = {}; morphNormalsView = {};
        jointPalette = {}; jointPaletteView = {};
        morphWeights = {}; morphWeightsView = {};
        previousJointPalette = {}; previousJointPaletteView = {};
        previousMorphWeights = {}; previousMorphWeightsView = {};
        previousDeformedVerticesView = {};
        computeShader = {}; computePipeline = {};
        drawShader = {}; drawPipeline = {};
    }

    std::string backend_ = "metal";
    std::shared_ptr<const arbitgpu::NativeDeformationScene> source;
    std::vector<std::shared_ptr<const MetalDeformationResources>> draws;
    std::shared_ptr<const MetalFixtureSceneResources> fixture;
    std::uint32_t vertexCount = 0;
    std::uint32_t indexCount = 0;
    std::uint32_t jointCount = 0;
    std::uint32_t morphTargetCount = 0;
    // One charge per storage buffer made by makeStorage, released with destroyUnlocked.
    std::vector<arbitgpu::residency::ResidencyCharge> bufferCharges;
    sg_buffer baseVertices = {}; sg_view baseVerticesView = {};
    sg_buffer deformedVertices = {}; sg_view deformedVerticesView = {};
    sg_buffer indexBuffer = {};
    sg_buffer jointIndices = {}; sg_view jointIndicesView = {};
    sg_buffer jointWeights = {}; sg_view jointWeightsView = {};
    sg_buffer morphPositions = {}; sg_view morphPositionsView = {};
    sg_buffer morphNormals = {}; sg_view morphNormalsView = {};
    sg_buffer jointPalette = {}; sg_view jointPaletteView = {};
    sg_buffer morphWeights = {}; sg_view morphWeightsView = {};
    sg_buffer previousJointPalette = {}; sg_view previousJointPaletteView = {};
    sg_buffer previousMorphWeights = {}; sg_view previousMorphWeightsView = {};
    sg_view previousDeformedVerticesView = {};
    sg_shader computeShader = {}; sg_pipeline computePipeline = {};
    sg_shader drawShader = {}; sg_pipeline drawPipeline = {};
    mutable std::mutex submissionMutex;
};

class DecodedMetalHdrFrame final : public arbitgpu::NativeFixtureSceneFrame
{
public:
    ~DecodedMetalHdrFrame() override
    {
        if (image.id == 0 && view.id == 0) return;
        std::lock_guard<std::mutex> lock(sokolMutex());
        if (!owner.expired()) destroyUnlocked();
    }

    const std::string& backend() const noexcept override { return api; }
    std::uint32_t width() const noexcept override { return frameWidth; }
    std::uint32_t height() const noexcept override { return frameHeight; }
    std::uintptr_t colorImageHandle() const noexcept override { return image.id; }
    std::uintptr_t colorTextureViewHandle() const noexcept override { return view.id; }
    arbitgpu::NativeTextureViewDescriptor colorTextureDescriptor() const noexcept override
    {
        if (owner.expired()) return {};
        auto descriptor = arbitgpu::NativeTextureViewDescriptor {
            api, arbitgpu::NativeTextureViewKind::Texture2D,
            format, image.id, view.id,
            frameWidth, frameHeight, 1, true, deviceIdentity, generation };
        descriptor.colorSpace = colorSpace;
        descriptor.transfer = transfer;
        descriptor.rowOrder = arbitgpu::NativeTextureRowOrder::TopFirst;
        return descriptor;
    }

    arbitgpu::NativeTextureViewDescriptor decodedLinearMaterialDescriptor() const noexcept override
    {
        const auto descriptor = colorTextureDescriptor();
        return arbitgpu::materialFrameIsLinear(descriptor) ? descriptor : arbitgpu::NativeTextureViewDescriptor{};
    }
    bool readColorFloatPixels(std::vector<float>& output) const override
    {
        output.clear();
        std::lock_guard<std::mutex> lock(sokolMutex());
        if (owner.expired() || !resourceValid(sg_query_image_state(image))) return false;
        const auto native = sg_mtl_query_image_info(image);
        if (native.active_slot < 0 || native.active_slot >= SG_NUM_INFLIGHT_FRAMES) return false;
        id<MTLTexture> texture = (__bridge id<MTLTexture>)native.tex[native.active_slot];
        id<MTLCommandQueue> queue = (__bridge id<MTLCommandQueue>)sg_mtl_command_queue();
        if (texture == nil || queue == nil || texture.device != gMetalDevice
            || texture.pixelFormat != (format == arbitgpu::NativeTexturePixelFormat::Rgba16Float
                ? MTLPixelFormatRGBA16Float : MTLPixelFormatRGBA32Float)
            || texture.width != frameWidth || texture.height != frameHeight) return false;
        const bool half = format == arbitgpu::NativeTexturePixelFormat::Rgba16Float;
        const NSUInteger tightRow = static_cast<NSUInteger>(frameWidth) * 4u * (half ? sizeof(std::uint16_t) : sizeof(float));
        const NSUInteger alignedRow = (tightRow + 255u) & ~NSUInteger(255u);
        const NSUInteger bytes = alignedRow * frameHeight;
        id<MTLBuffer> buffer = [gMetalDevice newBufferWithLength:bytes
                                                      options:MTLResourceStorageModeShared];
        id<MTLCommandBuffer> command = [queue commandBuffer];
        id<MTLBlitCommandEncoder> blit = command != nil ? [command blitCommandEncoder] : nil;
        if (buffer == nil || blit == nil)
        {
            if (blit != nil) [blit endEncoding];
#if !__has_feature(objc_arc)
            [buffer release];
#endif
            return false;
        }
        [blit copyFromTexture:texture sourceSlice:0 sourceLevel:0
                  sourceOrigin:MTLOriginMake(0, 0, 0)
                    sourceSize:MTLSizeMake(frameWidth, frameHeight, 1)
                      toBuffer:buffer destinationOffset:0
         destinationBytesPerRow:alignedRow destinationBytesPerImage:bytes];
        [blit endEncoding];
        [command commit];
        [command waitUntilCompleted];
        if (command.status == MTLCommandBufferStatusCompleted && buffer.contents != nullptr)
        {
            output.resize(static_cast<std::size_t>(frameWidth) * frameHeight * 4u);
            const auto* source = static_cast<const std::uint8_t*>(buffer.contents);
            for (std::uint32_t row = 0; row < frameHeight; ++row)
                if (!half)
                    std::memcpy(output.data() + static_cast<std::size_t>(row) * frameWidth * 4u,
                                source + static_cast<std::size_t>(row) * alignedRow, tightRow);
                else for (std::uint32_t component = 0; component < frameWidth * 4u; ++component)
                {
                    std::uint16_t value = 0;
                    std::memcpy(&value,source + static_cast<std::size_t>(row) * alignedRow
                        + component * sizeof(value),sizeof(value));
                    output[static_cast<std::size_t>(row) * frameWidth * 4u + component] = hdrimage::halfToFloat(value);
                }
        }
#if !__has_feature(objc_arc)
        [buffer release];
#endif
        return !output.empty();
    }

    void destroyUnlocked() noexcept
    {
        if (view.id != 0) sg_destroy_view(view);
        if (image.id != 0) sg_destroy_image(image);
        view = {}; image = {};
    }

    std::string api = "metal";
    std::weak_ptr<const void> owner;
    std::uintptr_t deviceIdentity = 0;
    std::uint64_t generation = 0;
    std::uint32_t frameWidth = 0, frameHeight = 0;
    arbitgpu::NativeTexturePixelFormat format = arbitgpu::NativeTexturePixelFormat::Rgba32Float;
    colortransform::ColorSpace colorSpace = colortransform::ColorSpace::Rec2020;
    colortransform::TransferFunction transfer = colortransform::TransferFunction::Unspecified;
    sg_image image = {};
    sg_view view = {};
};

