struct alignas(16) SdfGpuRecord
{
    std::uint32_t header[4];
    float parameters0[4];
    float parameters1[4];
};
static_assert (sizeof (SdfGpuRecord) == 48, "Metal SDF record layout changed");

struct alignas(16) SdfUniforms
{
    SdfGpuRecord records[arbitgpu::kNativeSdfMaximumRecords];
    float raymarch[4];
    std::uint32_t quality[4];
    std::uint32_t program[4];
};
static_assert (sizeof (SdfUniforms) == 3120, "Metal SDF uniform layout changed");

float sdfHalfToFloat (std::uint16_t value) noexcept
{
    const std::uint32_t sign = static_cast<std::uint32_t> (value & 0x8000u) << 16u;
    const std::uint32_t exponent = (value >> 10u) & 0x1fu;
    const std::uint32_t fraction = value & 0x03ffu;
    std::uint32_t bits = sign;
    if (exponent == 0)
    {
        if (fraction != 0)
        {
            std::uint32_t normalized = fraction;
            std::uint32_t shift = 0;
            while ((normalized & 0x0400u) == 0) { normalized <<= 1u; ++shift; }
            bits |= (113u - shift) << 23u;
            bits |= (normalized & 0x03ffu) << 13u;
        }
    }
    else if (exponent == 0x1fu)
    {
        bits |= 0x7f800000u | (fraction << 13u);
    }
    else
    {
        bits |= (exponent + 112u) << 23u;
        bits |= fraction << 13u;
    }
    float result = 0.0f;
    std::memcpy (&result, &bits, sizeof (result));
    return result;
}

class MetalSdfSceneFrame final : public arbitgpu::NativeSdfSceneFrame
{
public:
    ~MetalSdfSceneFrame() override
    {
        {
            std::lock_guard<std::mutex> lock (sokolMutex());
            if (deviceIdentity_ == reinterpret_cast<std::uintptr_t> ((__bridge void*) gMetalDevice))
            {
                for (auto view : textViews_) if (view.id != 0) sg_destroy_view (view);
                for (auto buffer : textBuffers_) if (buffer.id != 0) sg_destroy_buffer (buffer);
                if (primaryTextureView_.id != 0) sg_destroy_view (primaryTextureView_);
                if (primaryAttachmentView_.id != 0) sg_destroy_view (primaryAttachmentView_);
                if (primaryImage_.id != 0) sg_destroy_image (primaryImage_);
            }
        }
        if (outputBackend_ != nullptr && lifecycle_.value != 0)
            outputBackend_->releaseRenderPassOutputs (lifecycle_);
    }

    const std::string& backend() const noexcept override { return backend_; }
    std::uint32_t width() const noexcept override { return width_; }
    std::uint32_t height() const noexcept override { return height_; }
    std::uintptr_t colorImageHandle() const noexcept override { return colorImage.id; }
    std::uintptr_t colorTextureViewHandle() const noexcept override
    {
        return colorTextureView.id;
    }
    std::uintptr_t depthTextureViewHandle() const noexcept override
    {
        return depthTextureView.id;
    }
    std::uintptr_t normalTextureViewHandle() const noexcept override
    {
        return normalTextureView.id;
    }
    arbitgpu::NativeTextureViewDescriptor colorTextureDescriptor() const noexcept override
    {
        return { backend_, arbitgpu::NativeTextureViewKind::Texture2D,
                 arbitgpu::NativeTexturePixelFormat::Rgba16Float, colorImage.id, colorTextureView.id,
                 width_, height_, 1, true, deviceIdentity_, lifecycle_.value,
                 colortransform::ColorSpace::LinearSRGB, colortransform::TransferFunction::Linear,
                 arbitgpu::NativeTextureRowOrder::TopFirst };
    }
    arbitgpu::NativeTextureViewDescriptor depthTextureDescriptor() const noexcept override
    {
        return { backend_, arbitgpu::NativeTextureViewKind::Texture2D,
                 arbitgpu::NativeTexturePixelFormat::R32Float, depthImage.id, depthTextureView.id,
                 width_, height_, 1, true, deviceIdentity_, lifecycle_.value,
                 colortransform::ColorSpace::Unspecified, colortransform::TransferFunction::Unspecified,
                 arbitgpu::NativeTextureRowOrder::TopFirst };
    }
    arbitgpu::NativeTextureViewDescriptor normalTextureDescriptor() const noexcept override
    {
        return { backend_, arbitgpu::NativeTextureViewKind::Texture2D,
                 arbitgpu::NativeTexturePixelFormat::Rgba16Float, normalImage.id, normalTextureView.id,
                 width_, height_, 1, true, deviceIdentity_, lifecycle_.value,
                 colortransform::ColorSpace::Unspecified, colortransform::TransferFunction::Unspecified,
                 arbitgpu::NativeTextureRowOrder::TopFirst };
    }
    const arbitgpu::FrameMemoryAdmission& frameMemoryAdmission() const noexcept override
    {
        return frameMemory_;
    }
    const arbitgpu::NativeSdfResourceReceipt& sdfResourceReceipt() const noexcept override
    {
        return receipt_;
    }

    bool readColorPixels (std::vector<std::uint8_t>& output) const override
    {
        output.clear();
        std::vector<float> values;
        if (! readColorFloatPixels (values)) return false;
        output.resize (values.size());
        for (std::size_t index = 0; index < values.size(); ++index)
        {
            if (! std::isfinite (values[index]))
            {
                output.clear();
                return false;
            }
            output[index] = static_cast<std::uint8_t> (
                std::lround (std::clamp (values[index], 0.0f, 1.0f) * 255.0f));
        }
        return true;
    }

    bool readDepthFloatPixels (std::vector<float>& output) const override
    {
        output.clear();
        std::lock_guard<std::mutex> lock (sokolMutex());
        @autoreleasepool
        {
            if (depthImage.id == 0 || width_ == 0 || height_ == 0
                || deviceIdentity_ != reinterpret_cast<std::uintptr_t>((__bridge void*)gMetalDevice))
                return false;
            const auto native = sg_mtl_query_image_info (depthImage);
            if (native.active_slot < 0 || native.active_slot >= SG_NUM_INFLIGHT_FRAMES) return false;
            id<MTLTexture> texture = (__bridge id<MTLTexture>) native.tex[native.active_slot];
            id<MTLCommandQueue> queue = (__bridge id<MTLCommandQueue>) sg_mtl_command_queue();
            if (texture == nil || queue == nil) return false;
            const auto rowBytes = static_cast<NSUInteger> (width_) * sizeof (float);
            const auto alignedRowBytes = (rowBytes + 255u) & ~NSUInteger (255u);
            const auto bufferBytes = alignedRowBytes * static_cast<NSUInteger> (height_);
            id<MTLBuffer> readback = [gMetalDevice newBufferWithLength:bufferBytes
                                                               options:MTLResourceStorageModeShared];
            id<MTLCommandBuffer> command = [queue commandBuffer];
            id<MTLBlitCommandEncoder> blit = [command blitCommandEncoder];
            if (readback == nil || command == nil || blit == nil)
            {
                if (blit != nil) [blit endEncoding];
#if ! __has_feature(objc_arc)
                [readback release];
#endif
                return false;
            }
            [blit copyFromTexture:texture sourceSlice:0 sourceLevel:0
                     sourceOrigin:MTLOriginMake (0, 0, 0)
                       sourceSize:MTLSizeMake (width_, height_, 1)
                         toBuffer:readback destinationOffset:0
           destinationBytesPerRow:alignedRowBytes destinationBytesPerImage:bufferBytes];
            [blit endEncoding];
            [command commit];
            [command waitUntilCompleted];
            if (command.status == MTLCommandBufferStatusCompleted && readback.contents != nullptr)
            {
                output.resize (static_cast<std::size_t> (width_) * height_);
                const auto* source = static_cast<const std::uint8_t*> (readback.contents);
                for (std::uint32_t row = 0; row < height_; ++row)
                    std::memcpy (output.data() + static_cast<std::size_t> (row) * width_,
                        source + static_cast<std::size_t> (row) * alignedRowBytes, rowBytes);
            }
#if ! __has_feature(objc_arc)
            [readback release];
#endif
            return ! output.empty();
        }
    }

    bool readColorFloatPixels (std::vector<float>& output) const override
    {
        output.clear();
        std::lock_guard<std::mutex> lock (sokolMutex());
        @autoreleasepool
        {
            if (colorImage.id == 0 || width_ == 0 || height_ == 0
                || deviceIdentity_ != reinterpret_cast<std::uintptr_t> ((__bridge void*) gMetalDevice))
                return false;
            const auto native = sg_mtl_query_image_info (colorImage);
            if (native.active_slot < 0 || native.active_slot >= SG_NUM_INFLIGHT_FRAMES) return false;
            id<MTLTexture> texture = (__bridge id<MTLTexture>)
                native.tex[native.active_slot];
            id<MTLCommandQueue> queue = (__bridge id<MTLCommandQueue>)
                sg_mtl_command_queue();
            if (texture == nil || queue == nil)
                return false;
            const auto sourceRowBytes = static_cast<NSUInteger> (width_) * 8u;
            const auto alignedRowBytes = (sourceRowBytes + 255u) & ~NSUInteger (255u);
            const auto bufferBytes = alignedRowBytes * static_cast<NSUInteger> (height_);
            id<MTLBuffer> readback = [gMetalDevice newBufferWithLength:bufferBytes
                                                               options:MTLResourceStorageModeShared];
            id<MTLCommandBuffer> command = [queue commandBuffer];
            id<MTLBlitCommandEncoder> blit = [command blitCommandEncoder];
            if (readback == nil || command == nil || blit == nil)
            {
                if (blit != nil) [blit endEncoding];
#if ! __has_feature(objc_arc)
                [readback release];
#endif
                return false;
            }
            [blit copyFromTexture:texture
                      sourceSlice:0
                      sourceLevel:0
                     sourceOrigin:MTLOriginMake (0, 0, 0)
                       sourceSize:MTLSizeMake (width_, height_, 1)
                         toBuffer:readback
                destinationOffset:0
           destinationBytesPerRow:alignedRowBytes
         destinationBytesPerImage:bufferBytes];
            [blit endEncoding];
            [command commit];
            [command waitUntilCompleted];
            if (command.status != MTLCommandBufferStatusCompleted
                || readback.contents == nullptr)
            {
#if ! __has_feature(objc_arc)
                [readback release];
#endif
                return false;
            }
            output.resize (static_cast<std::size_t> (width_) * height_ * 4u);
            const auto* source = static_cast<const std::uint8_t*> (readback.contents);
            for (std::uint32_t row = 0; row < height_; ++row)
            {
                const auto* sourcePixels = reinterpret_cast<const std::uint16_t*> (
                    source + static_cast<std::size_t> (row) * alignedRowBytes);
                auto* destination = output.data()
                    + static_cast<std::size_t> (row) * width_ * 4u;
                for (std::uint32_t column = 0; column < width_; ++column)
                {
                    for (std::size_t channel = 0; channel < 4; ++channel)
                    {
                        destination[static_cast<std::size_t> (column) * 4u + channel]
                            = sdfHalfToFloat (sourcePixels[static_cast<std::size_t> (column) * 4u + channel]);
                    }
                }
            }
#if ! __has_feature(objc_arc)
            [readback release];
#endif
            return true;
        }
    }

    std::string backend_ = "metal";
    std::uint32_t width_ = 0;
    std::uint32_t height_ = 0;
    std::uintptr_t deviceIdentity_ = 0;
    sg_image colorImage = {};
    sg_view colorAttachmentView = {};
    sg_view colorTextureView = {};
    sg_image depthImage = {};
    sg_view depthAttachmentView = {};
    sg_view depthTextureView = {};
    sg_image normalImage = {};
    sg_view normalAttachmentView = {};
    sg_view normalTextureView = {};
    arbitgpu::RenderPassOutputBackend* outputBackend_ = nullptr;
    arbitgpu::RenderPassOutputLifecycleHandle lifecycle_ {};
    arbitgpu::FrameMemoryAdmission frameMemory_ {};
    arbitgpu::NativeSdfResourceReceipt receipt_ {};
    std::array<sg_buffer, 7> textBuffers_ {};
    std::array<sg_view, 7> textViews_ {};
    sg_image primaryImage_ {};
    sg_view primaryAttachmentView_ {}, primaryTextureView_ {};
    std::array<arbitgpu::residency::ResidencyCharge, 7> textBufferCharges {};
    arbitgpu::residency::ResidencyCharge primaryImageCharge;
};

const char* kSdfVertexShader = R"metal(
#include <metal_stdlib>
using namespace metal;
struct VertexOut { float4 position [[position]]; };
vertex VertexOut _main(uint vertexId [[vertex_id]]) {
    const float2 positions[3] = { float2(-1.0, -1.0),
                                  float2( 3.0, -1.0),
                                  float2(-1.0,  3.0) };
    VertexOut out;
    out.position = float4(positions[vertexId], 0.0, 1.0);
    return out;
}
)metal";

const char* kSdfFragmentShader = R"metal(
#include <metal_stdlib>
using namespace metal;
struct Record { uint4 header; float4 parameters0; float4 parameters1; };
struct Uniforms {
    Record records[64];
    float4 raymarch;
    uint4 quality;
    uint4 program;
};
struct VertexOut { float4 position [[position]]; };
struct TextIndexNode { float4 bounds; uint4 links; };
struct TextTables {
#ifdef SDF_TEXT_TABLES
    const device uint* indices;
    const device uint4* resources;
    const device uint4* contours;
    const device float4* segments;
    const device TextIndexNode* nodes;
    const device uint* segmentIndices;
    const device uint* roots;
#else
    uint unused;
#endif
};
#ifdef SDF_TEXT_TABLES
float textDistance(float3 point,uint recordIndex,float depth,TextTables t) {
    uint root=t.roots[t.indices[recordIndex]];
    uint end=t.nodes[root].links.z;
    float nearest=INFINITY;
    int winding=0;
    for(uint nodeIndex=root;nodeIndex<end;) {
        TextIndexNode node=t.nodes[nodeIndex];
        // The hierarchy boxes certify Y crossings. Nearest-edge arithmetic
        // has no native pruning certificate, so every leaf stays evaluated.
        bool crossing=node.bounds.y<=point.y&&node.bounds.w>point.y;
        if(node.links.y==0u) {++nodeIndex;continue;}
        for(uint i=0;i<node.links.y;++i) {
            float4 edge=t.segments[t.segmentIndices[node.links.x+i]];
            float2 direction=edge.zw-edge.xy,relative=point.xy-edge.xy;
            float fraction=clamp(dot(relative,direction)/dot(direction,direction),0.0,1.0);
            nearest=min(nearest,length(relative-direction*fraction));
            float side=direction.x*relative.y-direction.y*relative.x;
            if(crossing&&edge.y<=point.y&&edge.w>point.y&&side>0.0)++winding;
            if(crossing&&edge.y>point.y&&edge.w<=point.y&&side<0.0)--winding;
        }
        nodeIndex=node.links.z;
    }
    float d2=winding==0?nearest:-nearest;
    float2 d=float2(d2,abs(point.z)-depth*0.5);
    return length(max(d,float2(0.0)))+min(max(d.x,d.y),0.0);
}
#endif
float componentAt(float3 v, int axis) { return axis == 0 ? v.x : (axis == 1 ? v.y : v.z); }
float3 withComponent(float3 v, int axis, float x) {
    if (axis == 0) v.x=x; else if (axis == 1) v.y=x; else v.z=x; return v;
}
float3 rotateAxis(float3 v, float3 axis, float radians) {
    axis=normalize(axis); float c=cos(radians), s=sin(radians);
    return v*c+cross(axis,v)*s+axis*dot(axis,v)*(1.0-c);
}
float3 rotatePair(float3 v, int first, int second, float radians) {
    float a=componentAt(v,first), b=componentAt(v,second), c=cos(radians), s=sin(radians);
    v=withComponent(v,first,c*a-s*b); return withComponent(v,second,s*a+c*b);
}
float boxDistance(float3 p,float3 e) {
    float3 q=abs(p)-e; return length(max(q,float3(0.0)))+min(max(q.x,max(q.y,q.z)),0.0);
}
float primitiveDistance(uint op,float3 p,float4 a,float4 b) {
    if(op==2u)return boxDistance(p,a.xyz);
    if(op==3u)return boxDistance(p,a.xyz-float3(a.w))-a.w;
    if(op==4u)return dot(p,normalize(a.xyz))+a.w;
    if(op==5u)return length(float2(length(p.xz)-a.x,p.y))-a.y;
    if(op==6u){float3 r=p-a.xyz,s=float3(a.w,b.x,b.y)-a.xyz;float t=clamp(dot(r,s)/dot(s,s),0.0,1.0);return length(r-s*t)-b.z;}
    if(op==7u){float2 q=abs(float2(length(p.xz),p.y))-a.xy;return min(max(q.x,q.y),0.0)+length(max(q,float2(0.0)));}
    if(op==8u){float2 q=float2(length(p.xz),p.y),base=float2(a.x,-a.y),side=float2(a.x,-2.0*a.y);float2 cap=float2(q.x-min(q.x,q.y<0.0?a.x:0.0),abs(q.y)-a.y);float2 slope=q-base+side*clamp(dot(base-q,side)/dot(side,side),0.0,1.0);return(slope.x<0.0&&cap.y<0.0?-1.0:1.0)*sqrt(min(dot(cap,cap),dot(slope,slope)));}
    if(op==9u){float3 cell=p*a.x;return abs(dot(sin(cell),cos(cell.zxy)))/a.x-a.y;}
    return length(p)-a.x;
}
float smoothUnionDistance(float a,float b,float radius){float h=clamp(0.5+0.5*(b-a)/radius,0.0,1.0);return mix(b,a,h)-radius*h*(1.0-h);}
float3 childPoint(uint op,float3 p,float4 a,float4 b){
    if(op==16u)return p-a.xyz;
    if(op==17u)return rotateAxis(p,a.xyz,-a.w);
    if(op==18u)return p/a.xyz;
    if(op==19u)return p+a.xyz*0.5-a.xyz*floor((p+a.xyz*0.5)/a.xyz)-a.xyz*0.5;
    if(op==20u){int axis=int(a.x),first=(axis+1)%3,second=(axis+2)%3;float x=componentAt(p,first),y=componentAt(p,second),radius=length(float2(x,y)),sector=6.283185307179586/a.y;float shifted=atan2(y,x)-a.z+sector*0.5;float angle=shifted-sector*floor(shifted/sector)-sector*0.5;p=withComponent(p,first,radius*cos(angle));return withComponent(p,second,radius*sin(angle));}
    if(op==21u)return mix(p,abs(p),a.xyz);
    if(op==22u){int axis=int(a.x);return rotatePair(p,(axis+1)%3,(axis+2)%3,-a.y*componentAt(p,axis));}
    if(op==23u){int axis=int(a.x);return rotatePair(p,(axis+1)%3,axis,-a.y*componentAt(p,axis));}
    if(op==24u){int axis=int(a.x);float factor=1.0-a.y*componentAt(p,axis);p=withComponent(p,(axis+1)%3,componentAt(p,(axis+1)%3)*factor);return withComponent(p,(axis+2)%3,componentAt(p,(axis+2)%3)*factor);}
    if(op==26u)return p+float3(a.x*sin(a.w*p.y),a.y*sin(b.x*p.z),a.z*sin(b.y*p.x));
    return p;
}
float sceneDistanceWithMaterial(float3 point,thread int& contributor,constant Uniforms& u,TextTables t){
    int indices[32],stages[32],firstContributors[32];
    float3 points[32];float firstValues[32];
    int top=0;indices[0]=int(u.program.y);stages[0]=0;points[0]=point;
    float value=0.0;contributor=-1;
    for(int iteration=0;iteration<768;++iteration){
        int index=indices[top];Record record=u.records[index];
        uint op=record.header.x;float4 a=record.parameters0,b=record.parameters1;
        if(op<=9u
#ifdef SDF_TEXT_TABLES
            ||op==27u
#endif
        ){
#ifdef SDF_TEXT_TABLES
            value=op==27u?textDistance(points[top],uint(index),a.x,t)
                :primitiveDistance(op,points[top],a,b);
#else
            value=primitiveDistance(op,points[top],a,b);
#endif
            contributor=index;
            if(top==0)return value;--top;continue;
        }
        bool binary=op>=10u&&op<=15u;
        if(binary){
            if(stages[top]==0){
                stages[top]=1;++top;indices[top]=int(record.header.y);
                stages[top]=0;points[top]=points[top-1];continue;
            }
            if(stages[top]==1){
                firstContributors[top]=contributor;firstValues[top]=value;
                stages[top]=2;++top;indices[top]=int(record.header.z);
                stages[top]=0;points[top]=points[top-1];continue;
            }
            float first=firstValues[top],second=value;
            // Dominant smooth contributor; B owns a cut and A wins a tie.
            bool takeFirst=(op==10u||op==13u)?first<=second
                :first>=((op==12u||op==15u)?-second:second);
            if(takeFirst)contributor=firstContributors[top];
            if(op==10u)value=min(first,second);
            else if(op==11u)value=max(first,second);
            else if(op==12u)value=max(first,-second);
            else if(op==13u)value=smoothUnionDistance(first,second,a.x);
            else if(op==14u)value=-smoothUnionDistance(-first,-second,a.x);
            else value=-smoothUnionDistance(-first,second,a.x);
        }else if(stages[top]==0){
            stages[top]=1;++top;indices[top]=int(record.header.y);stages[top]=0;
            points[top]=childPoint(op,points[top-1],a,b);continue;
        }else{
            if(op==18u)value*=min(abs(a.x),min(abs(a.y),abs(a.z)));
            else if(op==25u){float3 q=points[top];value+=a.x*sin(a.y*q.x)*sin(a.y*q.y)*sin(a.y*q.z);}
        }
        if(top==0)return value;--top;
    }
    return u.raymarch.y;
}
float sceneDistance(float3 point,constant Uniforms& u,TextTables t){
    int contributor;return sceneDistanceWithMaterial(point,contributor,u,t);
}
float qualityScale(uint q){if(q==0u)return 4.0;if(q==1u)return 2.0;if(q==2u)return 1.0;return 0.5;}
float3 sceneNormal(float3 p,constant Uniforms& u,TextTables t){
    float e=max(u.raymarch.x*qualityScale(u.quality.y),0.000001);
    float3 gradient=float3(0.0);
    for(int sampleIndex=0;sampleIndex<6;++sampleIndex){
        int axis=sampleIndex/2;
        float sign=(sampleIndex%2)==0?1.0:-1.0;
        float3 offset=float3(0.0);offset[axis]=sign*e;
        gradient[axis]+=sign*sceneDistance(p+offset,u,t);
    }
    float squaredLength=dot(gradient,gradient);
    return squaredLength>0.0&&isfinite(squaredLength)?normalize(gradient):float3(0,0,1);
}
float sceneShadow(float3 origin,float3 direction,constant Uniforms& u,TextTables t){
    int limit=u.quality.z==0u?8:(u.quality.z==1u?16:(u.quality.z==2u?32:64));
    float travel=u.raymarch.x*4.0,visibility=1.0;
    for(int step=0;step<64;++step){
        if(step>=limit)break;
        float field=sceneDistance(origin+direction*travel,u,t);
        if(!isfinite(field)||field<u.raymarch.x)return 0.0;
        visibility=min(visibility,12.0*field/max(travel,u.raymarch.x));
        travel+=clamp(field,u.raymarch.x*2.0,0.25);
        if(travel>min(u.raymarch.y,8.0))break;
    }
    return clamp(visibility,0.0,1.0);
}
float sceneCurvature(float3 point,constant Uniforms& u,TextTables t){
    // Gradient/Hessian curvature uses one distance-call site, avoiding nested
    // normal stencils and their duplicated traversal stacks.
    float h=max(max(u.raymarch.x*qualityScale(u.quality.y)*4.0,0.002),length(point)*0.0001);
    const float3 offsets[19]={float3(0),
        float3(1,0,0),float3(-1,0,0),float3(0,1,0),float3(0,-1,0),float3(0,0,1),float3(0,0,-1),
        float3(1,1,0),float3(1,-1,0),float3(-1,1,0),float3(-1,-1,0),
        float3(1,0,1),float3(1,0,-1),float3(-1,0,1),float3(-1,0,-1),
        float3(0,1,1),float3(0,1,-1),float3(0,-1,1),float3(0,-1,-1)};
    float values[19];
    for(int i=0;i<19;++i)values[i]=sceneDistance(point+offsets[i]*h,u,t);
    float3 g=float3(values[1]-values[2],values[3]-values[4],values[5]-values[6])/(2.0*h);
    float3 diagonal=(float3(values[1]+values[2],values[3]+values[4],values[5]+values[6])-2.0*values[0])/(h*h);
    float3 crossTerms=float3(values[7]-values[8]-values[9]+values[10],
        values[11]-values[12]-values[13]+values[14],values[15]-values[16]-values[17]+values[18])/(4.0*h*h);
    float g2=dot(g,g);
    if(g2<=0.000000000001||!isfinite(g2))return 0.5;
    float directional=dot(g*g,diagonal)+2.0*dot(float3(g.x*g.y,g.x*g.z,g.y*g.z),crossTerms);
    float curvature=(g2*(diagonal.x+diagonal.y+diagonal.z)-directional)/(2.0*g2*sqrt(g2));
    if(!isfinite(curvature))return 0.5;
    curvature=clamp(curvature,-1.0/h,1.0/h);
    return 0.5+0.5*curvature/(1.0+abs(curvature));
}
float sceneAmbientVisibility(float3 point,float3 normal,constant Uniforms& u,TextTables t){
    int count=4+4*int(u.quality.y);
    float radius=min(u.raymarch.y,max(0.5,32.0*u.raymarch.x));
    float occlusion=0.0,total=0.0,weight=1.0;
    for(int i=0;i<16;++i){
        if(i>=count)break;
        float reach=radius*float(i+1)/float(count);
        float field=sceneDistance(point+normal*reach,u,t);
        if(!isfinite(field))return 0.0;
        occlusion+=weight*clamp(1.0-field/reach,0.0,1.0);
        total+=weight;weight*=0.75;
    }
    return clamp(1.0-occlusion/total,0.0,1.0);
}
bool traceSdf(float3 direction,thread float& travel,constant Uniforms& u,TextTables t){
    float3 origin=float3(0,0,3);travel=0.0;
    for(uint step=0u;step<512u;++step){
        if(step>=u.quality.x||travel>u.raymarch.y)break;
        float field=sceneDistance(origin+direction*travel,u,t);
        if(!isfinite(field))break;
        float threshold=max(u.raymarch.x*qualityScale(u.quality.w)*max(1.0,travel*0.05),0.000001);
        if(field<=threshold)return true;
        travel+=field;
    }
    return false;
}
float sceneEdgeDistance(float2 uv,constant Uniforms& u,TextTables t){
    const float2 axes[8]={float2(1,0),float2(-1,0),float2(0,1),float2(0,-1),
        float2(0.70710678,0.70710678),float2(-0.70710678,0.70710678),
        float2(0.70710678,-0.70710678),float2(-0.70710678,-0.70710678)};
    float distance=8.0;
    for(int i=0;i<8;++i){
        float low=0.0,high=8.0,travel;
        float2 axis=axes[i]*2.0/u.raymarch.w;
        if(traceSdf(normalize(float3(uv+axis*high,-1.8)),travel,u,t))continue;
        for(int j=0;j<4;++j){
            float middle=(low+high)*0.5;
            if(traceSdf(normalize(float3(uv+axis*middle,-1.8)),travel,u,t))low=middle;
            else high=middle;
        }
        distance=min(distance,high);
    }
    return distance/8.0;
}
float4 shadeSdf(float2 uv,float3 direction,bool hit,float travel,float3 point,
                float3 normal,constant Uniforms& u,TextTables t){
    if(!hit)return u.program.w!=0u?float4(0.5,0.5,0.5,1)
        :u.program.x>=3u?float4(0,0,0,1)
        :(u.program.x==1u?float4(1.0):float4(0.02745,0.03922,0.07059,1.0));
    if(u.program.x==1u)return float4(float3(clamp(travel/u.raymarch.y,0.0,1.0)),1.0);
    if(u.program.x==7u)return float4(float3(sceneEdgeDistance(uv,u,t)),1.0);
    if(u.program.x==3u){
        int contributor;sceneDistanceWithMaterial(point,contributor,u,t);
        uint code=contributor<0?0u:u.records[contributor].header.w;
        return float4(float3(code&255u,(code>>8u)&255u,(code>>16u)&255u)/255.0,1.0);
    }
    if(u.program.x==4u)return float4(float3(sceneCurvature(point,u,t)),1.0);
    if(u.program.x==2u)return float4(normal*0.5+0.5,1.0);
    if(u.program.x==5u)return float4(float3(sceneAmbientVisibility(point,normal,u,t)),1.0);
    float3 light=normalize(float3(-0.45,0.75,0.6));
    if(u.program.x==6u){
        float visibility=dot(normal,light)<=0.0?0.0:sceneShadow(point+normal*u.raymarch.x*4.0,light,u,t);
        return float4(float3(visibility),1.0);
    }
    float diffuse=max(dot(normal,light),0.0),shadow=sceneShadow(point+normal*u.raymarch.x*4.0,light,u,t);
    float rim=pow(1.0-max(dot(normal,-direction),0.0),3.0);
    return float4(float3(0.12,0.42,0.88)*(0.12+0.88*diffuse*shadow)+float3(0.18,0.35,0.65)*rim,1.0);
}
struct SdfOutputs { float4 color [[color(0)]]; float4 normal [[color(1)]]; };
fragment SdfOutputs _main(VertexOut in [[stage_in]],constant Uniforms& u [[buffer(0)]]
#ifdef SDF_TEXT_TABLES
    ,const device uint* indices [[buffer(8)]],const device uint4* resources [[buffer(9)]]
    ,const device uint4* contours [[buffer(10)]],const device float4* segments [[buffer(11)]]
    ,const device TextIndexNode* nodes [[buffer(12)]],const device uint* segmentIndices [[buffer(13)]]
    ,const device uint* roots [[buffer(14)]]
    ,texture2d<float,access::read> primary [[texture(0)]]
#endif
){
#ifdef SDF_TEXT_TABLES
    TextTables t={indices,resources,contours,segments,nodes,segmentIndices,roots};
#else
    TextTables t={0u};
#endif
    float2 extent=u.raymarch.zw,uv=(2.0*in.position.xy-extent)/extent.y;
    // Metal raster rows start at the top; positive scene Y points up.
    uv.y=-uv.y;
    float3 direction=normalize(float3(uv,-1.8));
#ifdef SDF_TEXT_TABLES
    float2 primaryResult=primary.read(uint2(in.position.xy)).xy;
    float travel=primaryResult.y;
    bool hit=primaryResult.x!=0.0;
#else
    float travel;
    bool hit=traceSdf(direction,travel,u,t);
#endif
    float3 point=float3(0,0,3)+direction*travel;
    float3 normal=hit?sceneNormal(point,u,t):float3(0.0);
    return { shadeSdf(uv,direction,hit,travel,point,normal,u,t),
             float4(normal,hit?1.0:0.0) };
}
fragment float _depth(VertexOut in [[stage_in]],constant Uniforms& u [[buffer(0)]]
#ifdef SDF_TEXT_TABLES
    ,const device uint* indices [[buffer(8)]],const device uint4* resources [[buffer(9)]]
    ,const device uint4* contours [[buffer(10)]],const device float4* segments [[buffer(11)]]
    ,const device TextIndexNode* nodes [[buffer(12)]],const device uint* segmentIndices [[buffer(13)]]
    ,const device uint* roots [[buffer(14)]]
    ,texture2d<float,access::read> primary [[texture(0)]]
#endif
){
#ifdef SDF_TEXT_TABLES
    TextTables t={indices,resources,contours,segments,nodes,segmentIndices,roots};
#else
    TextTables t={0u};
#endif
    float2 extent=u.raymarch.zw,uv=(2.0*in.position.xy-extent)/extent.y;
    uv.y=-uv.y;
#ifdef SDF_TEXT_TABLES
    float2 primaryResult=primary.read(uint2(in.position.xy)).xy;
    float travel=primaryResult.y;
    bool hit=primaryResult.x!=0.0;
#else
    float travel;
    bool hit=traceSdf(normalize(float3(uv,-1.8)),travel,u,t);
#endif
    return hit ? clamp(travel/u.raymarch.y,0.0,1.0) : 1.0;
}
#ifdef SDF_TEXT_TABLES
fragment float2 _primary(VertexOut in [[stage_in]],constant Uniforms& u [[buffer(0)]],
    const device uint* indices [[buffer(8)]],const device uint4* resources [[buffer(9)]],
    const device uint4* contours [[buffer(10)]],const device float4* segments [[buffer(11)]],
    const device TextIndexNode* nodes [[buffer(12)]],const device uint* segmentIndices [[buffer(13)]],
    const device uint* roots [[buffer(14)]]) {
    TextTables t={indices,resources,contours,segments,nodes,segmentIndices,roots};
    float2 extent=u.raymarch.zw,uv=(2.0*in.position.xy-extent)/extent.y;
    uv.y=-uv.y;
    float travel;
    bool hit=traceSdf(normalize(float3(uv,-1.8)),travel,u,t);
    return float2(hit?1.0:0.0,travel);
}
#endif
)metal";

std::shared_ptr<const arbitgpu::NativeSdfCompiledProgram> resolveSdfProgram (
    const arbitgpu::NativeSdfDrawRequest& request, std::string& error)
{
    if (request.compiledProgram != nullptr)
    {
        if (! videohelper::sdf::validateNativeSdfProgram (
                *request.compiledProgram, request.geometry, error, true))
            return {};
        return request.compiledProgram;
    }
    return videohelper::sdf::compileNativeSdfProgram (request.geometry, error, true);
}

