constant float pi = 3.14159265358979323846f;
constant float degreesToRadians = 0.01745329251994329577f;
constant uint materialDiffractionReflective = 1u;
constant int profileBinaryRectangular = 1;
constant int profileSinusoidal = 2;
constant int profileBlazedSawtooth = 3;
constant int coatingUncoated = 1;
constant int coatingIncoherentDielectric = 2;

float3 rotateQuaternion(float4 q, float3 value) {
    return value + 2.0f * cross(q.xyz, cross(q.xyz, value) + q.w * value);
}

float interfaceReflectance(float2 first, float2 second) {
    const float2 difference = first - second;
    const float2 sum = first + second;
    return clamp(dot(difference, difference) / dot(sum, sum), 0.0f, 1.0f);
}

float spectralReflectance(float wavelength, int coatingModel,
                          float substrateN, float substrateK,
                          constant Uniforms& u) {
    if (coatingModel == coatingUncoated)
        return interfaceReflectance(float2(1.0f, 0.0f),
                                    float2(substrateN, substrateK));
    if (coatingModel != coatingIncoherentDielectric)
        return -1.0f;
    const float2 layer = float2(u.diffractionCoating.y, u.diffractionCoating.z);
    const float r01 = interfaceReflectance(float2(1.0f, 0.0f), layer);
    const float r12 = interfaceReflectance(layer, float2(substrateN, substrateK));
    const float roundTrip = exp(-8.0f * pi * u.diffractionCoating.z
                                * u.diffractionCoating.x / wavelength);
    const float denominator = 1.0f - r01 * r12 * roundTrip;
    return clamp(r01 + (1.0f - r01) * (1.0f - r01)
                    * r12 * roundTrip / denominator, 0.0f, 1.0f);
}

float2 complexMultiply(float2 a, float2 b) {
    return float2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x);
}

float2 complexExponentialIntegral(float frequency, float begin, float end) {
    if (abs(frequency) < 1.0e-6f)
        return float2(end - begin, 0.0f);
    const float beginPhase = frequency * begin;
    const float endPhase = frequency * end;
    return float2((sin(endPhase) - sin(beginPhase)) / frequency,
                  -(cos(endPhase) - cos(beginPhase)) / frequency);
}

float besselJ(int order, float argument) {
    const int magnitude = order < 0 ? -order : order;
    const float halfArgument = 0.5f * argument;
    float term = 1.0f;
    for (int factor = 1; factor <= 8; ++factor)
        if (factor <= magnitude)
            term *= halfArgument / float(factor);
    float sum = term;
    for (int seriesIndex = 1; seriesIndex <= 24; ++seriesIndex) {
        term *= -(halfArgument * halfArgument)
              / (float(seriesIndex) * float(magnitude + seriesIndex));
        sum += term;
    }
    return sum;
}

float profileEfficiency(int profile, int signedOrder, float duty,
                        float phase, float2 terracePhase) {
    if (profile == profileBinaryRectangular) {
        if (signedOrder == 0) {
            const float2 amplitude = float2(1.0f - duty, 0.0f) + duty * terracePhase;
            return dot(amplitude, amplitude);
        }
        const float order = float(signedOrder);
        const float aperture = sin(pi * order * duty) / (pi * order);
        const float rotation = -pi * order * duty;
        const float2 amplitude = aperture * complexMultiply(
            terracePhase - float2(1.0f, 0.0f),
            float2(cos(rotation), sin(rotation)));
        return dot(amplitude, amplitude);
    }
    if (profile == profileSinusoidal) {
        const float amplitude = besselJ(signedOrder, 0.5f * phase);
        return amplitude * amplitude;
    }
    if (profile == profileBlazedSawtooth) {
        const float orderFrequency = -2.0f * pi * float(signedOrder);
        const float2 ramp = complexExponentialIntegral(
            phase / duty + orderFrequency, 0.0f, duty);
        const float2 land = complexExponentialIntegral(orderFrequency, duty, 1.0f);
        const float2 amplitude = ramp + land;
        return dot(amplitude, amplitude);
    }
    return 0.0f;
}

float diffractionOrderContribution(int primaryOrder,
                                   int secondaryOrder,
                                   bool crossedTwoDimensional,
                                   float wavelength,
                                   float3 incident,
                                   float3 outgoing,
                                   int profile,
                                   float duty,
                                   float sigma,
                                   float4 localGeometry,
                                   float4 localSecondaryGeometry,
                                   constant Uniforms& u) {
    const int firstOrder = int(round(u.diffractionMicrostructure.w));
    const int lastOrder = int(u.diffractionControl.x + 0.5f);
    const int primaryMagnitude = primaryOrder < 0 ? -primaryOrder : primaryOrder;
    const int secondaryMagnitude = secondaryOrder < 0 ? -secondaryOrder : secondaryOrder;
    if ((primaryOrder != 0
            && (primaryMagnitude < firstOrder || primaryMagnitude > lastOrder))
        || (crossedTwoDimensional && secondaryOrder != 0
            && (secondaryMagnitude < firstOrder || secondaryMagnitude > lastOrder)))
        return 0.0f;

    float2 expectedTangent = -incident.xy
        + float(primaryOrder) * wavelength / localGeometry.z
            * localGeometry.xy;
    if (crossedTwoDimensional)
        expectedTangent += float(secondaryOrder) * wavelength
            / localSecondaryGeometry.z
            * localSecondaryGeometry.xy;
    if (dot(expectedTangent, expectedTangent) >= 1.0f)
        return 0.0f;

    const float expectedOutgoingCosine = sqrt(max(
        0.0f, 1.0f - dot(expectedTangent, expectedTangent)));
    const float2 deviation = outgoing.xy - expectedTangent;
    const float gaussianNormalization = 1.0f / (2.0f * pi * sigma * sigma);
    const float lobe = gaussianNormalization
        * exp(-dot(deviation, deviation) / (2.0f * sigma * sigma));
    const float roughnessArgument = 2.0f * pi * u.diffractionRoughness.x
        * (incident.z + expectedOutgoingCosine) / wavelength;
    const float coherentFactor = exp(-(roughnessArgument * roughnessArgument));
    const float phase = 2.0f * pi * u.diffractionGeometry.w
        * (incident.z + expectedOutgoingCosine) / wavelength;
    const float2 terracePhase = float2(cos(phase), sin(phase));
    float efficiency = coherentFactor * profileEfficiency(
        profile, primaryOrder, duty, phase, terracePhase);
    if (crossedTwoDimensional)
        efficiency *= profileEfficiency(
            profile, secondaryOrder, duty, phase, terracePhase);
    efficiency *= expectedOutgoingCosine / incident.z;
    return efficiency * lobe;
}

int2 propagatingOneDimensionalOrders(float2 incidentTangent, float2 grooveDirection,
                                    float period, float wavelength, int lastOrder) {
    float grooveLength = length(grooveDirection);
    if (grooveLength <= 1.0e-8f || abs(period) <= 1.0e-8f || wavelength <= 0.0f)
        return int2(-lastOrder, lastOrder);
    float step = wavelength * grooveLength / period;
    if (abs(step) <= 1.0e-8f)
        return int2(-lastOrder, lastOrder);
    // A propagating order needs |m * step - projectedIncident| < 1.
    float projectedIncident = dot(incidentTangent, grooveDirection) / grooveLength;
    float lower = (projectedIncident - 1.0f) / step;
    float upper = (projectedIncident + 1.0f) / step;
    return int2(int(max(-float(lastOrder), floor(min(lower, upper)) - 1.0f)),
                int(min(float(lastOrder), ceil(max(lower, upper)) + 1.0f)));
}

// Integrate discrete reciprocal orders. The environment is affine on the unit
// sphere. A five-point angular rule follows the admitted roughness width.
float diffractionEnvironmentSample(float3 direction, float3 position, constant Uniforms& u) {
    bool hit = false;
    if (direction.y < -1.0e-6f && position.y > u.diffractionEnvironment.y) {
        float distance = (u.diffractionEnvironment.y - position.y) / direction.y;
        hit = distance > 0.0f && distance <= u.diffractionEnvironment.z;
    }
    float3 axis = u.diffractionIncidentDirectionAndIntensity.xyz;
    if (u.diffractionPathKindAndBounce.x == 3u)
        return hit ? 0.625f + 0.25f * axis.y : 0.0f;
    return hit ? 0.0f : 0.625f + 0.375f * dot(axis, direction);
}

float3 integrateDiffractionEnvironment(float3 outgoing, float3 tangent,
                                    float3 bitangent, float3 normal, VertexOut in, constant Uniforms& u) {
    float4 geometry;
    float4 secondaryGeometry;
    geometry = u.diffractionGeometry;
    secondaryGeometry = u.diffractionSecondaryGeometry;
    if (u.diffractionSpatialCounts.x > 0u) {
        float4 lower = mix(u.diffractionFoilField[0], u.diffractionFoilField[1], clamp(in.uv.x, 0.0f, 1.0f));
        float4 upper = mix(u.diffractionFoilField[2], u.diffractionFoilField[3], clamp(in.uv.x, 0.0f, 1.0f));
        float4 local = mix(lower, upper, clamp(in.uv.y, 0.0f, 1.0f));
        geometry.xyz = float3(normalize(local.xy), local.z);
    } else if (int(u.diffractionGrooveField.x + 0.5f) != 1) {
        float2 offset = in.uv - u.diffractionGrooveField.yz;
        float coordinate = int(u.diffractionGrooveField.x + 0.5f) == 2
            ? dot(offset, u.diffractionGrooveVariation.xy) : length(offset);
        geometry.z += coordinate * u.diffractionGrooveVariation.z;
        secondaryGeometry.z += coordinate * u.diffractionGrooveVariation.w;
        float angle = coordinate * u.diffractionGrooveField.w * degreesToRadians;
        float2x2 rotation = float2x2(float2(cos(angle), sin(angle)), float2(-sin(angle), cos(angle)));
        geometry.xy = rotation * geometry.xy;
        secondaryGeometry.xy = rotation * secondaryGeometry.xy;
    }
    bool crossed = int(secondaryGeometry.w + 0.5f) == 2;
    int firstOrder = int(round(u.diffractionMicrostructure.w));
    int lastOrder = int(u.diffractionControl.x + 0.5f);
    int profile = int(u.diffractionControl.y + 0.5f);
    float duty = u.diffractionMicrostructure.x;
    float sigma = max(2.0f * u.diffractionRoughness.y, 1.0e-4f);
    float3 xyz = float3(0.0f);
    float whiteY = 0.0f;
    for (int wavelengthIndex = 0; wavelengthIndex < 8; ++wavelengthIndex) {
        float4 spectral = u.diffractionSpectral[wavelengthIndex];
        float4 spectralZ = u.diffractionSpectralZ[wavelengthIndex];
        float wavelength = spectral.x;
        float radiance = 0.0f;
        float totalEfficiency = 0.0f;
        int firstPrimary = -lastOrder;
        int lastPrimary = lastOrder;
        if (!crossed) {
            int2 range = propagatingOneDimensionalOrders(
                outgoing.xy, geometry.xy, geometry.z, wavelength, lastOrder);
            firstPrimary = range.x;
            lastPrimary = range.y;
        }
        for (int primary = firstPrimary; primary <= lastPrimary; ++primary) {
            if (primary != 0 && abs(primary) < firstOrder) continue;
            int secondaryLimit = crossed ? lastOrder : 0;
            for (int secondary = -secondaryLimit; secondary <= secondaryLimit; ++secondary) {
                if (secondary != 0 && abs(secondary) < firstOrder) continue;
                float2 xy = -outgoing.xy + float(primary) * wavelength / geometry.z * geometry.xy;
                if (crossed)
                    xy += float(secondary) * wavelength / secondaryGeometry.z * secondaryGeometry.xy;
                if (dot(xy, xy) >= 1.0f) continue;
                float z = sqrt(max(0.0f, 1.0f - dot(xy, xy)));
                float phase = 2.0f * pi * geometry.w * (outgoing.z + z) / wavelength;
                float2 terrace = float2(cos(phase), sin(phase));
                float efficiency = profileEfficiency(profile, primary, duty, phase, terrace);
                if (crossed) efficiency *= profileEfficiency(profile, secondary, duty, phase, terrace);
                if (primary != 0 || secondary != 0) efficiency *= z / outgoing.z;
                float height = 2.0f * pi * u.diffractionRoughness.x * (outgoing.z + z) / wavelength;
                efficiency *= exp(-height * height);
                float3 direction = xy.x * tangent + xy.y * bitangent + z * normal;
                float3 side = normalize(cross(abs(direction.y) < 0.9f
                    ? float3(0.0f, 1.0f, 0.0f) : float3(1.0f, 0.0f, 0.0f), direction));
                float3 up = cross(direction, side);
                float lighting = 0.5f * diffractionEnvironmentSample(direction, in.worldPosition, u);
                lighting += 0.125f * diffractionEnvironmentSample(normalize(direction + sigma * side), in.worldPosition, u);
                lighting += 0.125f * diffractionEnvironmentSample(normalize(direction - sigma * side), in.worldPosition, u);
                lighting += 0.125f * diffractionEnvironmentSample(normalize(direction + sigma * up), in.worldPosition, u);
                lighting += 0.125f * diffractionEnvironmentSample(normalize(direction - sigma * up), in.worldPosition, u);
                radiance += efficiency * lighting;
                totalEfficiency += efficiency;
            }
        }
        float reflectance = spectralReflectance(wavelength, int(u.diffractionControl.w + 0.5f),
            u.diffractionMicrostructure.y, u.diffractionMicrostructure.z, u);
        float energy = u.diffractionIncidentDirectionAndIntensity.w * spectral.y
            * reflectance * spectralZ.y * radiance / max(1.0f, totalEfficiency);
        xyz += energy * float3(spectral.z, spectral.w, spectralZ.x);
        whiteY += spectralZ.y * spectral.w;
    }
    xyz /= max(whiteY, 1.0e-8f);
    return float3(3.2406f * xyz.x - 1.5372f * xyz.y - 0.4986f * xyz.z,
                -0.9689f * xyz.x + 1.8758f * xyz.y + 0.0415f * xyz.z,
                0.0557f * xyz.x - 0.2040f * xyz.y + 1.0570f * xyz.z);
}

float3 evaluateDiffraction(VertexOut in, constant Uniforms& u) {
    const float3 normal = normalize(in.worldNormal);
    const float3 dpdx = dfdx(in.worldPosition);
    const float3 dpdy = dfdy(in.worldPosition);
    const float2 duvdx = dfdx(in.uv);
    const float2 duvdy = dfdy(in.uv);
    const float determinant = duvdx.x * duvdy.y - duvdx.y * duvdy.x;
    if (abs(determinant) <= 1.0e-8f)
        return float3(0.0f);
    float3 tangent = normalize((dpdx * duvdy.y - dpdy * duvdx.y) / determinant);
    tangent = normalize(tangent - normal * dot(normal, tangent));
    float3 bitangent = normalize(cross(normal, tangent));
    if (dot(bitangent, (-dpdx * duvdy.x + dpdy * duvdx.x) / determinant) < 0.0f)
        bitangent = -bitangent;

    const float3 toLightWorld = normalize(rotateQuaternion(
        u.lightRotations[0], float3(0.0f, 0.0f, 1.0f)));
    const float3 toViewWorld = normalize(u.cameraTranslation.xyz - in.worldPosition);
    float3 incident = u.diffractionIncidentDirectionAndIntensity.xyz;
    const float3 outgoing = float3(dot(toViewWorld, tangent),
                                  dot(toViewWorld, bitangent),
                                  dot(toViewWorld, normal));
    if (outgoing.z <= 0.0f)
        return float3(0.0f);
    if (u.diffractionEnvironment.x == 2.0f && u.diffractionPathKindAndBounce.x != 1u)
        return integrateDiffractionEnvironment(outgoing, tangent, bitangent, normal, in, u);
    if (u.diffractionEnvironment.x == 2.0f) {
        if (u.ambient.w == 0.0f) return float3(0.0f);
        incident = float3(dot(toLightWorld, tangent), dot(toLightWorld, bitangent), dot(toLightWorld, normal));
    }
    if (incident.z <= 1.0e-6f) return float3(0.0f);

    const float duty = u.diffractionMicrostructure.x;
    const float substrateN = u.diffractionMicrostructure.y;
    const float substrateK = u.diffractionMicrostructure.z;
    const int profile = int(u.diffractionControl.y + 0.5f);
    const int coatingModel = int(u.diffractionControl.w + 0.5f);
    const int firstOrder = int(round(u.diffractionMicrostructure.w));
    const int lastOrder = int(u.diffractionControl.x + 0.5f);
    const bool crossedTwoDimensional
        = int(u.diffractionSecondaryGeometry.w + 0.5f) == 2;
    const float sigma = 2.0f * u.diffractionRoughness.y;
    float4 localGeometry = u.diffractionGeometry;
    float4 localSecondaryGeometry = u.diffractionSecondaryGeometry;
    if (u.diffractionSpatialCounts.x > 0u) {
        const float4 lower = mix(u.diffractionFoilField[0], u.diffractionFoilField[1], clamp(in.uv.x, 0.0f, 1.0f));
        const float4 upper = mix(u.diffractionFoilField[2], u.diffractionFoilField[3], clamp(in.uv.x, 0.0f, 1.0f));
        const float4 local = mix(lower, upper, clamp(in.uv.y, 0.0f, 1.0f));
        localGeometry.xyz = float3(normalize(local.xy), local.z);
    }
    const int fieldMode = int(u.diffractionGrooveField.x + 0.5f);
    if (u.diffractionSpatialCounts.x == 0u && fieldMode != 1) {
        const float2 offset = in.uv - u.diffractionGrooveField.yz;
        const float coordinate = fieldMode == 2
            ? dot(offset, u.diffractionGrooveVariation.xy) : length(offset);
        localGeometry.z += coordinate * u.diffractionGrooveVariation.z;
        localSecondaryGeometry.z += coordinate * u.diffractionGrooveVariation.w;
        const float angle = coordinate * u.diffractionGrooveField.w * degreesToRadians;
        const float2x2 rotation = float2x2(
            float2(cos(angle), sin(angle)), float2(-sin(angle), cos(angle)));
        localGeometry.xy = rotation * localGeometry.xy;
        localSecondaryGeometry.xy = rotation * localSecondaryGeometry.xy;
    }

    float3 xyz = float3(0.0f);
    float referenceWhiteY = 0.0f;

    for (int wavelengthIndex = 0; wavelengthIndex < 8; ++wavelengthIndex) {
        const float4 spectral = u.diffractionSpectral[wavelengthIndex];
        const float4 spectralZ = u.diffractionSpectralZ[wavelengthIndex];
        const float wavelength = spectral.x;
        const float quadrature = spectralZ.y;
        const float reflectance = spectralReflectance(
            wavelength, coatingModel, substrateN, substrateK, u);
        float wavelengthRadiance = diffractionOrderContribution(
            0, 0, crossedTwoDimensional, wavelength,
            incident, outgoing, profile, duty, sigma,
                        localGeometry, localSecondaryGeometry, u);
        if (crossedTwoDimensional) {
            for (int primaryOrder = -lastOrder; primaryOrder <= -firstOrder; ++primaryOrder) {
                for (int secondaryOrder = -lastOrder; secondaryOrder <= -firstOrder; ++secondaryOrder)
                    wavelengthRadiance += diffractionOrderContribution(
                        primaryOrder, secondaryOrder, true, wavelength,
                        incident, outgoing, profile, duty, sigma,
                        localGeometry, localSecondaryGeometry, u);
                for (int secondaryOrder = firstOrder; secondaryOrder <= lastOrder; ++secondaryOrder)
                    wavelengthRadiance += diffractionOrderContribution(
                        primaryOrder, secondaryOrder, true, wavelength,
                        incident, outgoing, profile, duty, sigma,
                        localGeometry, localSecondaryGeometry, u);
            }
            for (int primaryOrder = firstOrder; primaryOrder <= lastOrder; ++primaryOrder) {
                for (int secondaryOrder = -lastOrder; secondaryOrder <= -firstOrder; ++secondaryOrder)
                    wavelengthRadiance += diffractionOrderContribution(
                        primaryOrder, secondaryOrder, true, wavelength,
                        incident, outgoing, profile, duty, sigma,
                        localGeometry, localSecondaryGeometry, u);
                for (int secondaryOrder = firstOrder; secondaryOrder <= lastOrder; ++secondaryOrder)
                    wavelengthRadiance += diffractionOrderContribution(
                        primaryOrder, secondaryOrder, true, wavelength,
                        incident, outgoing, profile, duty, sigma,
                        localGeometry, localSecondaryGeometry, u);
            }
            for (int primaryOrder = -lastOrder; primaryOrder <= -firstOrder; ++primaryOrder)
                wavelengthRadiance += diffractionOrderContribution(
                    primaryOrder, 0, true, wavelength,
                    incident, outgoing, profile, duty, sigma,
                        localGeometry, localSecondaryGeometry, u);
            for (int primaryOrder = firstOrder; primaryOrder <= lastOrder; ++primaryOrder)
                wavelengthRadiance += diffractionOrderContribution(
                    primaryOrder, 0, true, wavelength,
                    incident, outgoing, profile, duty, sigma,
                        localGeometry, localSecondaryGeometry, u);
            for (int secondaryOrder = -lastOrder; secondaryOrder <= -firstOrder; ++secondaryOrder)
                wavelengthRadiance += diffractionOrderContribution(
                    0, secondaryOrder, true, wavelength,
                    incident, outgoing, profile, duty, sigma,
                        localGeometry, localSecondaryGeometry, u);
            for (int secondaryOrder = firstOrder; secondaryOrder <= lastOrder; ++secondaryOrder)
                wavelengthRadiance += diffractionOrderContribution(
                    0, secondaryOrder, true, wavelength,
                    incident, outgoing, profile, duty, sigma,
                        localGeometry, localSecondaryGeometry, u);
        } else {
            int2 range = propagatingOneDimensionalOrders(
                incident.xy, localGeometry.xy, localGeometry.z, wavelength, lastOrder);
            for (int primaryOrder = range.x; primaryOrder <= min(-firstOrder, range.y); ++primaryOrder)
                wavelengthRadiance += diffractionOrderContribution(
                    primaryOrder, 0, false, wavelength,
                    incident, outgoing, profile, duty, sigma,
                        localGeometry, localSecondaryGeometry, u);
            for (int primaryOrder = max(firstOrder, range.x); primaryOrder <= range.y; ++primaryOrder)
                wavelengthRadiance += diffractionOrderContribution(
                    primaryOrder, 0, false, wavelength,
                    incident, outgoing, profile, duty, sigma,
                        localGeometry, localSecondaryGeometry, u);
        }
        const float pathTransport = u.diffractionPathKindAndBounce.x == 3u
            ? 1.0f / float(1u + u.diffractionPathKindAndBounce.y) : 1.0f;
        float energy = u.diffractionIncidentDirectionAndIntensity.w
                           * spectral.y * pathTransport * quadrature * reflectance
                           * wavelengthRadiance * incident.z;
        if (u.diffractionEnvironment.x == 2.0f) energy *= u.lightColors[0].w;
        xyz += energy * float3(spectral.z, spectral.w, spectralZ.x);
        referenceWhiteY += quadrature * spectral.w;
    }
    xyz /= max(referenceWhiteY, 1.0e-8f);
    return float3(3.2406f * xyz.x - 1.5372f * xyz.y - 0.4986f * xyz.z,
                  -0.9689f * xyz.x + 1.8758f * xyz.y + 0.0415f * xyz.z,
                  0.0557f * xyz.x - 0.2040f * xyz.y + 1.0570f * xyz.z);
}

struct FragmentOut {
    float4 color [[color(0)]];
    float linearDepth [[color(1)]];
    float4 rawNormal [[color(2)]];
    float4 rawEmission [[color(3)]];
    float rawMask [[color(4)]];
    uint rawMaterialId [[color(5)]];
    uint rawObjectId [[color(6)]];
    float2 rawMotion [[color(7)]];
};
float4 compositePass(FragmentOut value, constant Uniforms& u) {
    const int count = int(u.passProgramControl.x);
    if (count == 0) return value.color;
    float4 values[8];
    for (int i = 0; i < 8; ++i) {
        if (i >= count) break;
        const float4 p = u.passModes[i];
        const int mode = int(p.x);
        const float depth = clamp((value.linearDepth - p.y) / (p.z - p.y), 0.0f, 1.0f);
        float3 fog = u.passColors[i].rgb;
        if (u.passTransforms[i].y > 0.5f)
            fog = select(pow((fog + 0.055f) / 1.055f, float3(2.4f)), fog / 12.92f,
                fog <= float3(0.04045f));
        const uint identity = uint(u.passReferences[i].x) | (uint(u.passReferences[i].y) << 16u);
        float4 result = float4(value.color.rgb, value.rawMask);
        if (mode == 1) result = float4(mix(value.color.rgb, fog, depth * p.w), value.rawMask);
        const float inspectionAlpha = u.passTransforms[i].w > 0.5f ? 1.0f : value.rawMask;
        if (mode == 2) result = float4(float3(u.passTransforms[i].w > 1.5f ? 1.0f - depth : depth), inspectionAlpha);
        if (mode == 3) result = float4(value.rawNormal.xyz * 0.5f + 0.5f, inspectionAlpha);
        if (mode == 4) result = float4(value.rawEmission.rgb, value.rawMask);
        if (mode >= 5 && mode <= 7) {
            float matte = value.rawMask;
            if (mode == 6) matte *= value.rawMaterialId == identity ? 1.0f : 0.0f;
            if (mode == 7) matte *= value.rawObjectId == identity ? 1.0f : 0.0f;
            result = float4(float3(matte), 1.0f);
        }
        if (mode == 8) result = float4(clamp(float2(0.5f) + value.rawMotion / u.motionViewport.xy
            * (1.0f + 63.0f * p.w), 0.0f, 1.0f), 0.5f, value.rawMask);
        if (mode == 9 || mode == 10) {
            const float4 a = values[int(u.passReferences[i].z) - 1];
            const float4 b = values[int(u.passReferences[i].w) - 1];
            result = mode == 9 ? mix(a, b, p.w)
                : float4(a.rgb + b.rgb * p.w, max(a.a, b.a));
        }
        result.rgb *= exp2(u.passTransforms[i].x);
        values[i] = result;
    }
    const int selected = int(u.passProgramControl.y);
    float4 result = values[selected];
    const int transform = int(u.passTransforms[selected].z);
    if (transform > 0 && u.passProgramControl.z < 0.5f) {
        float3 rgb = max(result.rgb, float3(0.0f));
        if (transform == 2) rgb /= float3(1.0f) + rgb;
        result.rgb = select(1.055f * pow(rgb, float3(1.0f / 2.4f)) - 0.055f, rgb * 12.92f,
            rgb <= float3(0.0031308f));
    }
    return u.passProgramControl.z > 0.5f ? result : clamp(result, 0.0f, 1.0f);
}
// Direct base GGX contract: shared/BaseSurfaceReflection.h. Ambient and coat
// retain their existing independent approximations. No radiance/output clamp.
float3 baseSurfaceUnit(float3 value) {
    float lengthSquared = dot(value, value);
    return lengthSquared > 1.0e-12f ? value * rsqrt(lengthSquared) : float3(0.0f);
}
float3 baseSurfaceDirect(float3 base, float metallic, float roughness,
                     float dielectric, float transmission,
                     float3 normal, float3 toLight, float3 toView) {
    float3 n = baseSurfaceUnit(normal);
    float3 l = baseSurfaceUnit(toLight);
    float3 v = baseSurfaceUnit(toView);
    float nl = clamp(dot(n, l), 0.0f, 1.0f);
    float nv = clamp(dot(n, v), 0.0f, 1.0f);
    if (nl <= 0.0f || nv <= 0.0f) return float3(0.0f);
    float3 h = baseSurfaceUnit(l + v);
    float nh = clamp(dot(n, h), 0.0f, 1.0f);
    float vh = clamp(dot(v, h), 0.0f, 1.0f);
    float alpha = max(roughness * roughness, 0.0025f);
    float a2 = alpha * alpha;
    float denominator = (1.0f - nh * nh) + a2 * nh * nh;
    float distribution = a2 / (3.14159265358979323846f * denominator * denominator);
    float visibility = 1.0f / ((nl + sqrt(a2 + (1.0f - a2) * nl * nl))
                            * (nv + sqrt(a2 + (1.0f - a2) * nv * nv)));
    float3 f0 = mix(float3(dielectric), base, metallic);
    float3 fresnel = f0 + (1.0f - f0) * pow(1.0f - vh, 5.0f);
    float3 diffuse = (1.0f - fresnel) * (1.0f - metallic) * base
                  * (1.0f - transmission) / 3.14159265358979323846f;
    return (distribution * visibility * fresnel + diffuse) * nl;
}
fragment FragmentOut _main(VertexOut in [[stage_in]],
                           uint primitive [[primitive_id]],
                           texture2d<float> baseTexture [[texture(0)]],
                           texture2d<float> metallicRoughnessTexture [[texture(1)]],
                           texture2d<float> normalTexture [[texture(2)]],
                           texture2d<float> occlusionTexture [[texture(3)]],
                           texture2d<float> emissiveTexture [[texture(4)]],
                           texture2d<float> opaqueTexture [[texture(5)]],
                           texture2d<float> glassTexture [[texture(6)]],
                           texture2d<float> environmentTexture [[texture(7)]],
                           texture2d<float> spectralQueryTexture [[texture(8)]],
                           texture2d<float> spectralSampleTexture [[texture(9)]],
                           sampler baseSampler [[sampler(0)]],
                           sampler metallicRoughnessSampler [[sampler(1)]],
                           sampler normalSampler [[sampler(2)]],
                           sampler occlusionSampler [[sampler(3)]],
                           sampler emissiveSampler [[sampler(4)]],
                           constant Uniforms& u [[buffer(0)]],
                           device atomic_uint* spectralDiagnostic [[buffer(1)]]) {
    FragmentOut out;
    if (u.skyBackground.x>0.5f) {
        float3 radiance=u.sky[0].w>1.5f ? environmentImageRadiance(in.worldPosition,u.sky[0],u.sky[1],environmentTexture)
            : analyticSkyRadiance(in.worldPosition,u.sky[0],u.sky[1],u.sky[2],u.sky[3],u.sky[4]);
        out.color=float4(radiance,1.0f);
        out.linearDepth=1.0f; out.rawNormal=float4(0.0f); out.rawEmission=float4(0.0f);
        out.rawMask=0.0f; out.rawMaterialId=0u; out.rawObjectId=0u; out.rawMotion=float2(0.0f);
        out.color=compositePass(out,u);
        return out;
    }
    out.linearDepth = in.linearDepth;
    out.rawNormal = float4(normalize(in.worldNormal), 1.0f);
    out.rawEmission = float4(0.0f);
    out.rawMask = 1.0f;
    out.rawMaterialId = uint(in.rawIdentifiers.x) | (uint(in.rawIdentifiers.y) << 16u);
    out.rawObjectId = uint(in.rawIdentifiers.z) | (uint(in.rawIdentifiers.w) << 16u);
    out.rawMotion = clamp((in.motionCurrentClip.xy / in.motionCurrentClip.w
        - in.motionPreviousClip.xy / in.motionPreviousClip.w) * 0.5f * u.motionViewport.xy,
        float2(-65504.0f), float2(65504.0f));
    if (u.materialKind.x == materialDiffractionReflective)
    {
        const float coverage = u.diffractionSpatialCounts.y == 0u
            ? 1.0f : as_type<float>(u.diffractionPathKindAndBounce.w);
        float occupancy = u.diffractionSpatialCounts.y == 0u ? 1.0f : 0.0f;
        for (uint i = 0u; i < u.diffractionSpatialCounts.y; ++i) {
            const float4 r = u.diffractionOccupancyRectangles[i];
            occupancy = max(occupancy, in.uv.x >= r.x && in.uv.y >= r.y
                && in.uv.x <= r.z && in.uv.y <= r.w ? 1.0f : 0.0f);
        }
        if (u.diffractionSpatialCounts.x > 0u) {
            const float4 lower = mix(u.diffractionFoilField[0], u.diffractionFoilField[1], clamp(in.uv.x, 0.0f, 1.0f));
            const float4 upper = mix(u.diffractionFoilField[2], u.diffractionFoilField[3], clamp(in.uv.x, 0.0f, 1.0f));
            occupancy *= mix(lower.w, upper.w, clamp(in.uv.y, 0.0f, 1.0f));
        }
        const uint evaluationIndex = u.diffractionEvaluationSchedule.w
            * (u.diffractionEvaluationSchedule.x * u.diffractionEvaluationSchedule.y)
            + uint(in.position.y) * u.diffractionEvaluationSchedule.x
            + uint(in.position.x);
        const bool firstPath = u.diffractionEvaluationSchedule.w == 0u;
        const float3 diffraction = u.spectralSampleControl.w == 1.0f
            ? spectralTransport(in, primitive, true, u, spectralQueryTexture, spectralSampleTexture, spectralDiagnostic)
            : (u.diffractionSpatialCounts.x == 0u
                || evaluationIndex < u.diffractionEvaluationSchedule.z)
            ? max(evaluateDiffraction(in, u), float3(0.0f))
            : firstPath ? in.litBase : float3(0.0f);
        if (u.spectralSampleControl.w == 1.0f && (!all(isfinite(diffraction))
            || any(abs(diffraction) > float3(65504.0f))))
            atomic_store_explicit(spectralDiagnostic, 1u, memory_order_relaxed);
        const float scatterWeight = clamp(coverage * occupancy, 0.0f, 1.0f);
        out.color = float4((firstPath ? in.litBase * (1.0f - scatterWeight)
            : float3(0.0f)) + diffraction * scatterWeight, 1.0f);
