fragment float4 _resolve(float4 position [[position]],
                         texture2d<float> accumulation [[texture(0)]],
                         texture2d<float> linearDepth [[texture(1)]],
                         texture2d<float> rawNormal [[texture(2)]],
                         texture2d<float> rawEmission [[texture(3)]],
                         texture2d<float> rawMask [[texture(4)]],
                         texture2d<uint> rawMaterialId [[texture(5)]],
                         texture2d<uint> rawObjectId [[texture(6)]],
                         texture2d<float> rawMotion [[texture(7)]],
                         constant Uniforms& u [[buffer(0)]]) {
    const uint2 pixel = uint2(position.xy);
    FragmentOut value;
    value.rawMask = rawMask.read(pixel).r;
    if (value.rawMask <= 0.0f) discard_fragment();
    const float4 summed = accumulation.read(pixel);
    if (!all(isfinite(summed))) return summed;
    value.color = float4(summed.rgb, u.materialKind.y & 16u ? summed.a : 1.0f);
    value.linearDepth = linearDepth.read(pixel).r;
    value.rawNormal = rawNormal.read(pixel);
    value.rawEmission = rawEmission.read(pixel);
    value.rawMaterialId = rawMaterialId.read(pixel).r;
    value.rawObjectId = rawObjectId.read(pixel).r;
    value.rawMotion = rawMotion.read(pixel).rg;
    const uint imageOutput = uint(u.imageOutput.x);
    if (imageOutput != 0u) {
        float3 image = float3(0.0f);
        if (imageOutput == 1u) image = float3(value.linearDepth);
        if (imageOutput == 2u) image = value.rawNormal.xyz * 0.5f + 0.5f;
        if (imageOutput == 3u) image = float3(clamp(float2(0.5f)
            + value.rawMotion / u.motionViewport.xy, 0.0f, 1.0f), 0.5f);
        if (imageOutput == 4u) image = value.rawEmission.rgb;
        if (imageOutput == 5u) image = float3(1.0f);
        if (imageOutput == 6u || imageOutput == 7u) {
            uint hash = (imageOutput == 6u ? value.rawMaterialId : value.rawObjectId) * 0x9e3779b9u;
            hash ^= hash >> 16u;
            image = float3(32u + (hash & 191u), 32u + ((hash >> 8u) & 191u),
                           32u + ((hash >> 16u) & 191u)) / 255.0f;
        }
        return float4(image, value.rawMask);
    }
    return compositePass(value, u);
}
)metal";


