bool spectralHitValid(SpectralQueryClosestHit hit,float minimum,float maximum) {
    return hit.status == 0 || (hit.status == 1 && hit.objectId != 0u && hit.materialId != 0u
        && isfinite(hit.distance) && hit.distance >= minimum && hit.distance <= maximum
        && all(isfinite(hit.position)) && all(isfinite(hit.outwardNormal))
        && abs(dot(hit.outwardNormal,hit.outwardNormal)-1.0f) < 1.0e-4f);
