    float coverage=u.diffractionSpatialCounts.y==0u ? 1.0f : as_type<float>(u.diffractionPathKindAndBounce.w);
    float occupancy=u.diffractionSpatialCounts.y==0u ? 1.0f : 0.0f;
    for (uint i=0; i<u.diffractionSpatialCounts.y; ++i) {
