    if (!spectralHitValid(source,minimum,maximum)) return spectralFailure(diagnostic);
    float sourceCosine=source.status==0 ? max(dot(normal,light),0.0f) : 0.0f;
    float3 outgoing=grating ? spectralLocal(normalize(u.cameraTranslation.xyz-in.worldPosition),tangent,bitangent,normal) : float3(0.0f);
    float bands[8];
    for (int b=0;b<8;++b) {
        float li=u.spectralSourceRadiance[b/4][b%4];
        float rho=grating ? 1.0f : spectralSample(own,4+b/4,table)[b%4];
        bands[b]=li*sourceCosine*(grating ? spectralGratingBsdf(b,spectralLocal(light,tangent,bitangent,normal),outgoing,in.uv,u,diagnostic) : rho/pi);
    }
    int first=grating?0:receivers,count=grating?receivers:gratings;
    for (int i=first;i<first+count;++i) {
        float4 sample=spectralSample(i,0,table),ids=spectralSample(i,2,table),metadata=spectralSample(i,3,table);
        float3 sampleNormal=spectralSample(i,1,table).xyz;
        float3 delta=sample.xyz-in.worldPosition;
        float squared=dot(delta,delta),distance=sqrt(squared);
        if (!isfinite(distance) || distance<=2.0f*minimum || distance+minimum>maximum
            || !all(isfinite(sampleNormal)) || !isfinite(sample.w) || sample.w<=0.0f) return spectralFailure(diagnostic);
        float3 direction=delta/distance;
        SpectralQueryClosestHit forward=spectralQuerySceneClosestHit(in.worldPosition,direction,minimum,distance+minimum,u.spectralQueryControl,query);
        SpectralQueryClosestHit backward=spectralQuerySceneClosestHit(sample.xyz,-direction,minimum,distance+minimum,u.spectralQueryControl,query);
        SpectralQueryClosestHit illumination=spectralQuerySceneClosestHit(sample.xyz,light,minimum,maximum,u.spectralQueryControl,query);
        if (!spectralHitValid(forward,minimum,distance+minimum) || !spectralHitValid(backward,minimum,distance+minimum)
            || !spectralHitValid(illumination,minimum,maximum)) return spectralFailure(diagnostic);
        bool complete=true;
        bool visible=spectralEndpoint(forward,distance,ids,metadata,sampleNormal,complete);
        if (!complete || backward.status!=1) return spectralFailure(diagnostic);
        if (backward.distance>=distance-minimum) {
            if (backward.objectId!=object || backward.materialId!=material
                || backward.instanceId!=in.spectralInstance || backward.triangleId!=triangle
                || abs(backward.distance-distance)>minimum
                || dot(backward.outwardNormal,normal)<1.0f-1.0e-5f) return spectralFailure(diagnostic);
        } else visible=false;
        float ownCosine=max(dot(normal,direction),0.0f),sampleCosine=max(dot(sampleNormal,-direction),0.0f);
        float sampleLight=illumination.status==0 ? max(dot(sampleNormal,light),0.0f) : 0.0f;
        if (!visible || ownCosine==0.0f || sampleCosine==0.0f || sampleLight==0.0f) continue;
        float weight=sample.w*sampleCosine*ownCosine/squared;
        float4 st=spectralSample(i,6,table),sb=spectralSample(i,7,table);
        for (int b=0;b<8;++b) {
            float li=u.spectralSourceRadiance[b/4][b%4];
            float rho=spectralSample(grating?i:own,4+b/4,table)[b%4];
            float bsdf=grating ? spectralGratingBsdf(b,spectralLocal(direction,tangent,bitangent,normal),outgoing,in.uv,u,diagnostic)
                : spectralGratingBsdf(b,spectralLocal(light,st.xyz,sb.xyz,sampleNormal),
                    spectralLocal(-direction,st.xyz,sb.xyz,sampleNormal),float2(st.w,sb.w),u,diagnostic)*spectralScatterWeight(float2(st.w,sb.w),u);
            bands[b]+=li*sampleLight*rho/pi*weight*bsdf;
        }
    }
    float3 xyz=float3(0.0f);float whiteY=0.0f;
    for(int b=0;b<8;++b) {
        float4 spectral=u.diffractionSpectral[b],z=u.diffractionSpectralZ[b];
        if (!isfinite(bands[b]) || bands[b]<0.0f) return spectralFailure(diagnostic);
        xyz+=bands[b]*z.y*float3(spectral.z,spectral.w,z.x);whiteY+=z.y*spectral.w;
    }
    xyz/=max(whiteY,1.0e-8f);
    float3 rgb=float3(3.2406f*xyz.x-1.5372f*xyz.y-.4986f*xyz.z,
        -.9689f*xyz.x+1.8758f*xyz.y+.0415f*xyz.z,.0557f*xyz.x-.2040f*xyz.y+1.0570f*xyz.z);
    return all(isfinite(rgb)) ? max(rgb,float3(0.0f)) : spectralFailure(diagnostic);
}

)metal";
}
std::string metalSpectralTransportShader() { return metalSpectralTransportShaderRecipe<std::string>(); }

template<class String> auto restrictedSurfaceSourceRecipe()
{
    auto vertex=arbitgpu::fixtureNullVertexModifierRecipe<String>(kFixtureVertexShader);
    String fragment(kFixtureFragmentShader);
    auto modules=arbitgpu::opaquevisibility::metalShaderRecipe<String>()+arbitgpu::analyticsky::shaderRecipe<String>(true)
        +arbitgpu::environmentimage::shaderRecipe<String>(true)+arbitgpu::smoothglass::queryShaderRecipe<String>(true)
        +arbitgpu::smoothglass::transportShaderRecipe<String>(true,true,false)+metalSpectralTransportShaderRecipe<String>();
    const auto offset=fragment.find("fragment FragmentOut _main");
    if(offset==String::npos) throw std::length_error("Surface source fragment insertion marker missing");
    fragment.insert(offset,modules);
    return std::make_pair(vertex,fragment);
}

[[maybe_unused]] const char* kDeformationComputeShader = R"metal(
#include <metal_stdlib>
using namespace metal;
struct SceneVertex {
    packed_float3 position;
    packed_float3 normal;
    packed_float4 tangent;
    packed_float2 uv;
    packed_float4 color;
};
struct Params {
    uint vertexCount;
    uint jointCount;
    uint morphTargetCount;
    uint outputOffset;
};
struct CompositionPost {
    float4 control;
    float4x4 point;
    float4x4 normal;
};
kernel void _main(const device SceneVertex* source [[buffer(8)]],
                  device SceneVertex* destination [[buffer(9)]],
                  const device uint* jointIndices [[buffer(10)]],
                  const device float* jointWeights [[buffer(11)]],
                  const device float* morphPositions [[buffer(12)]],
                  const device float* morphNormals [[buffer(13)]],
                  const device float4x4* jointPalette [[buffer(14)]],
                  const device float* morphWeights [[buffer(15)]],
                  constant Params& params [[buffer(0)]],
                  constant CompositionPost& post [[buffer(1)]],
                  uint vertexIndex [[thread_position_in_grid]]) {
    if (vertexIndex >= params.vertexCount) return;
    const SceneVertex input = source[vertexIndex];
    float3 position = float3(input.position);
    float3 normal = float3(input.normal);
    for (uint target = 0; target < params.morphTargetCount; ++target) {
        const uint scalar = (target * params.vertexCount + vertexIndex) * 3u;
        const float weight = morphWeights[target];
        position += weight * float3(morphPositions[scalar],
                                    morphPositions[scalar + 1u],
                                    morphPositions[scalar + 2u]);
        normal += weight * float3(morphNormals[scalar],
                                  morphNormals[scalar + 1u],
                                  morphNormals[scalar + 2u]);
    }
    SceneVertex output = input;
    if (post.control.y == 1.0f) {
        float3 tangent = float4(input.tangent).xyz;
        float handedness = input.tangent.w;
        if (params.jointCount > 0u) {
            float3x3 skinLinear = float3x3(0.0f);
            float3 skinnedPosition = float3(0.0f);
            for (uint component = 0; component < 4u; ++component) {
                const uint influence = vertexIndex * 4u + component;
                const float weight = jointWeights[influence];
                const uint joint = jointIndices[influence];
                if (weight == 0.0f) continue;
                const float4x4 palette = jointPalette[joint];
                skinnedPosition += weight * (palette * float4(position, 1.0f)).xyz;
                skinLinear += weight * float3x3(palette[0].xyz,palette[1].xyz,palette[2].xyz);
            }
            position = skinnedPosition;
            const float3 cofactor0 = cross(skinLinear[1],skinLinear[2]);
            const float3 cofactor1 = cross(skinLinear[2],skinLinear[0]);
            const float3 cofactor2 = cross(skinLinear[0],skinLinear[1]);
            const float skinDeterminant = dot(skinLinear[0],cofactor0);
            normal = (cofactor0*normal.x+cofactor1*normal.y+cofactor2*normal.z)/skinDeterminant;
            tangent = skinLinear * tangent;
            handedness *= skinDeterminant < 0.0f ? -1.0f : 1.0f;
        }
        position = (post.point * float4(position,1.0f)).xyz;
        normal = (post.normal * float4(normal,0.0f)).xyz;
        tangent = (post.point * float4(tangent,0.0f)).xyz;
        const float tangentLength = length(tangent);
        tangent = tangentLength > 1.0e-8f ? tangent/tangentLength : float3(1.0f,0.0f,0.0f);
        output.tangent = packed_float4(float4(tangent,handedness * post.normal[3].w));
        const float normalLength = length(normal);
        normal = normalLength > 1.0e-8f ? normal/normalLength : float3(0.0f,0.0f,1.0f);
    }
    else {
        if (params.jointCount > 0u) {
            float3 skinnedPosition = float3(0.0f);
            float3 skinnedNormal = float3(0.0f);
            for (uint component = 0; component < 4u; ++component) {
                const uint influence = vertexIndex * 4u + component;
                const float weight = jointWeights[influence];
                const uint joint = jointIndices[influence];
                if (weight == 0.0f) continue;
                const float4x4 palette = jointPalette[joint];
                skinnedPosition += weight * (palette * float4(position, 1.0f)).xyz;
                skinnedNormal += weight * (palette * float4(normal, 0.0f)).xyz;
            }
            position = skinnedPosition;
            normal = skinnedNormal;
        }
    }
    output.position = packed_float3(position);
    output.normal = packed_float3(post.control.y == 1.0f ? normal : normalize(normal));
    output.uv = input.uv;
    destination[vertexIndex + params.outputOffset] = output;
}
)metal";

[[maybe_unused]] const char* kDeformationVertexShader = R"metal(
#include <metal_stdlib>
using namespace metal;
struct SceneVertex {
    packed_float3 position;
    packed_float3 normal;
    packed_float2 uv;
};
struct Uniforms {
    float4 objectRotation;
    float4 objectTranslation;
    float4 objectScale;
    float4 cameraRotation;
    float4 cameraTranslation;
    float4 projection;
    float4 baseColor;
    float4 emissive;
    float4 ambient;
    float4 lightRotation;
    float4 lightColorIntensity;
};
struct VertexOut {
    float4 position [[position]];
    float3 color [[user(locn0)]];
};
float3 rotateQuaternion(float4 q, float3 value) {
    return value + 2.0f * cross(q.xyz, cross(q.xyz, value) + q.w * value);
}
vertex VertexOut _main(const device SceneVertex* vertices [[buffer(8)]],
                       constant Uniforms& u [[buffer(0)]],
                       uint vertex [[vertex_id]]) {
    const SceneVertex input = vertices[vertex];
    const float3 worldPosition = rotateQuaternion(
        u.objectRotation, float3(input.position) * u.objectScale.xyz)
        + u.objectTranslation.xyz;
    const float3 worldNormal = normalize(rotateQuaternion(
        u.objectRotation, float3(input.normal) / u.objectScale.xyz));
    const float4 inverseCamera = float4(-u.cameraRotation.xyz, u.cameraRotation.w);
    const float3 cameraPosition = rotateQuaternion(
        inverseCamera, worldPosition - u.cameraTranslation.xyz);
    const float distance = -cameraPosition.z;
    VertexOut out;
    out.position = float4(cameraPosition.x / (u.projection.x * u.projection.y),
                          cameraPosition.y / u.projection.x,
                          distance * u.projection.w / (u.projection.w - u.projection.z)
                              - u.projection.z * u.projection.w
                                  / (u.projection.w - u.projection.z),
                          distance);
    const float3 toLight = rotateQuaternion(u.lightRotation, float3(0.0f, 0.0f, 1.0f));
    const float diffuse = max(dot(worldNormal, normalize(toLight)), 0.0f);
    const float3 lighting = u.ambient.xyz
        + u.lightColorIntensity.xyz * u.lightColorIntensity.w * diffuse;
    out.color = u.baseColor.xyz * lighting + u.emissive.xyz;
    return out;
}
)metal";

[[maybe_unused]] const char* kDeformationFragmentShader = R"metal(
#include <metal_stdlib>
using namespace metal;
struct VertexOut {
    float4 position [[position]];
    float3 color [[user(locn0)]];
};
fragment float4 _main(VertexOut input [[stage_in]]) {
    return float4(input.color, 1.0f);
}
)metal";

void storeVec3 (float (&destination)[4],
                const HarmonicMIDI::grid::SceneVec3& source,
                float fourth = 0.0f) noexcept
{
    destination[0] = source.x;
    destination[1] = source.y;
    destination[2] = source.z;
    destination[3] = fourth;
}

void storeQuaternion (float (&destination)[4],
                      const HarmonicMIDI::grid::SceneQuaternion& source) noexcept
{
    destination[0] = source.x;
    destination[1] = source.y;
    destination[2] = source.z;
    destination[3] = source.w;
}

std::array<float, 16> metalFixtureTransformMatrix (
    const HarmonicMIDI::grid::SceneTransform3D& transform) noexcept
{
    const auto x = transform.rotation.x, y = transform.rotation.y;
    const auto z = transform.rotation.z, w = transform.rotation.w;
    const auto sx = transform.scale.x, sy = transform.scale.y, sz = transform.scale.z;
    return {
        (1.0f - 2.0f * (y * y + z * z)) * sx,
        (2.0f * (x * y + w * z)) * sx,
        (2.0f * (x * z - w * y)) * sx, 0.0f,
        (2.0f * (x * y - w * z)) * sy,
        (1.0f - 2.0f * (x * x + z * z)) * sy,
        (2.0f * (y * z + w * x)) * sy, 0.0f,
        (2.0f * (x * z + w * y)) * sz,
        (2.0f * (y * z - w * x)) * sz,
        (1.0f - 2.0f * (x * x + y * y)) * sz, 0.0f,
        transform.translation.x, transform.translation.y, transform.translation.z, 1.0f
    };
}

std::array<float, 16> multiplyMetalFixtureMatrices (
    const std::array<float, 16>& left, const std::array<float, 16>& right) noexcept
{
    std::array<float, 16> result {};
    for (std::size_t column = 0; column < 4; ++column)
        for (std::size_t row = 0; row < 4; ++row)
            for (std::size_t inner = 0; inner < 4; ++inner)
                result[column * 4 + row] += left[inner * 4 + row]
                    * right[column * 4 + inner];
    return result;
}

std::array<float, 16> metalFixtureWorldMatrix (
    const HarmonicMIDI::grid::Visual3DScene& scene,
    const HarmonicMIDI::grid::SceneObjectRecord& object) noexcept
{
    auto result = metalFixtureTransformMatrix (object.transform);
    auto parent = object.parent;
    for (std::size_t depth = 0; parent.isValid() && depth < scene.objectCount; ++depth)
    {
        const auto* parentObject = HarmonicMIDI::grid::visual3d_detail::findById (
            scene.objects, scene.objectCount, parent);
        if (parentObject == nullptr) break;
        result = multiplyMetalFixtureMatrices (
            metalFixtureTransformMatrix (parentObject->transform), result);
        parent = parentObject->parent;
    }
    return result;
}

float metalFixtureDeterminant3x3 (const std::array<float, 16>& matrix) noexcept
{
    return matrix[0] * (matrix[5] * matrix[10] - matrix[9] * matrix[6])
         - matrix[4] * (matrix[1] * matrix[10] - matrix[9] * matrix[2])
         + matrix[8] * (matrix[1] * matrix[6] - matrix[5] * matrix[2]);
}

