namespace
{
sg_pixel_format sokolPixelFormat (renderpassoutput::PixelFormat format) noexcept
{
    using renderpassoutput::PixelFormat;
    switch (format)
    {
        case PixelFormat::R8Unorm: return SG_PIXELFORMAT_R8;
        case PixelFormat::RG16Float: return SG_PIXELFORMAT_RG16F;
        case PixelFormat::RGBA16Float: return SG_PIXELFORMAT_RGBA16F;
        case PixelFormat::R32Float: return SG_PIXELFORMAT_R32F;
        case PixelFormat::R32Uint: return SG_PIXELFORMAT_R32UI;
        case PixelFormat::Invalid: break;
    }
    return SG_PIXELFORMAT_NONE;
}

RenderPassOutputCapabilities metalRenderPassOutputCapabilitiesUnlocked()
{
    RenderPassOutputCapabilities result;
    if (! ensureSokolMetal())
    {
        result.error = gSokolError;
        return result;
    }
    if (sg_query_backend() != SG_BACKEND_METAL_MACOS)
    {
        result.error = "sokol_gfx did not select the macOS Metal backend";
        return result;
    }

    const auto nativeLimits = sg_query_limits();
    if (nativeLimits.max_color_attachments <= 0 || nativeLimits.max_image_size_2d <= 0)
    {
        result.error = "Metal reported no render-pass output attachment capacity";
        return result;
    }

    const auto maximumDimension = static_cast<std::uint32_t> (
        std::min (nativeLimits.max_image_size_2d,
                  static_cast<int> (renderpassoutput::kMaximumWidth)));
    result.limits.attachments = std::min (
        static_cast<std::size_t> (nativeLimits.max_color_attachments),
        renderpassoutput::kMaximumAttachments);
    result.limits.width = maximumDimension;
    result.limits.height = std::min (
        maximumDimension, renderpassoutput::kMaximumHeight);
    result.limits.pixels = std::min (
        static_cast<std::uint64_t> (result.limits.width) * result.limits.height,
        renderpassoutput::kMaximumPixels);
    result.limits.totalBytes = renderpassoutput::kMaximumTotalBytes;

    for (const auto output : renderpassoutput::kOutputs)
    {
        const auto requirements = renderpassoutput::requirements (output);
        const auto format = sokolPixelFormat (requirements.format);
        if (format == SG_PIXELFORMAT_NONE)
            continue;
        const auto formatInfo = sg_query_pixelformat (format);
        const auto exactBytes = renderpassoutput::bytesPerPixel (requirements.format);
        result.supportedOutputs[static_cast<std::size_t> (output)] =
            formatInfo.render && formatInfo.sample
            && formatInfo.bytes_per_pixel == exactBytes;
    }

    result.available = std::any_of (
        result.supportedOutputs.begin(), result.supportedOutputs.end(),
        [] (bool supported) { return supported; });
    if (! result.available)
        result.error = "Metal supports none of the exact render-pass output formats";
    return result;
}

struct MetalRenderPassOutputAttachment
{
    renderpassoutput::Output output = renderpassoutput::Output::Count;
    sg_image image = {};
    sg_view attachmentView = {};
    sg_view textureView = {};
};

struct MetalRenderPassOutputAllocation
{
    std::vector<MetalRenderPassOutputAttachment> attachments;
    // One charge per attachment image, in attachment order.
    std::vector<arbitgpu::residency::ResidencyCharge> imageCharges;
};

void destroyRenderPassOutputAllocationUnlocked (
    MetalRenderPassOutputAllocation& allocation) noexcept
{
    for (auto found = allocation.attachments.rbegin();
         found != allocation.attachments.rend(); ++found)
    {
        if (found->textureView.id != 0)
            sg_destroy_view (found->textureView);
        if (found->attachmentView.id != 0)
            sg_destroy_view (found->attachmentView);
        if (found->image.id != 0)
            sg_destroy_image (found->image);
        *found = {};
    }
    allocation.attachments.clear();
    allocation.imageCharges.clear();
}

class MetalRenderPassOutputBackend final : public RenderPassOutputBackend
{
public:
    RenderPassOutputCapabilities renderPassOutputCapabilities() const override
    {
        std::lock_guard<std::mutex> lock (sokolMutex());
        @autoreleasepool
        {
            return metalRenderPassOutputCapabilitiesUnlocked();
        }
    }

    RenderPassOutputAdmission admitRenderPassOutputs (
        const renderpassoutput::AdmittedOutputs& outputs) override
    {
        RenderPassOutputAdmission result;
        std::lock_guard<std::mutex> lock (sokolMutex());
        @autoreleasepool
        {
            const auto capabilities = metalRenderPassOutputCapabilitiesUnlocked();
            if (! capabilities.available)
            {
                result.error = capabilities.error;
                return result;
            }
            if (outputs.attachments().empty())
            {
                result.error = "Metal render-pass output admission requires an attachment";
                return result;
            }
            if (! admitRenderPassOutputFrameMemory (
                    outputs, capabilities.limits.totalBytes,
                    result.frameMemory, result.error))
                return result;

            const auto extent = outputs.extent();
            const auto pixels = static_cast<std::uint64_t> (extent.width) * extent.height;
            if (outputs.attachments().size() > capabilities.limits.attachments
                || extent.width > capabilities.limits.width
                || extent.height > capabilities.limits.height
                || pixels > capabilities.limits.pixels
                || outputs.totalByteCount() > capabilities.limits.totalBytes)
            {
                result.error = "Metal render-pass output request exceeds backend limits";
                return result;
            }

            MetalRenderPassOutputAllocation allocation;
            allocation.attachments.reserve (outputs.attachments().size());
            allocation.imageCharges.reserve (outputs.attachments().size());
            result.resources.reserve (outputs.attachments().size());
            for (const auto& attachment : outputs.attachments())
            {
                if (! capabilities.supports (attachment.output))
                {
                    result.error = "Metal does not support render-pass output ";
                    result.error += renderpassoutput::token (attachment.output);
                    destroyRenderPassOutputAllocationUnlocked (allocation);
                    result.resources.clear();
                    return result;
                }

                const auto format = sokolPixelFormat (attachment.format);
                MetalRenderPassOutputAttachment owned;
                owned.output = attachment.output;

                sg_image_desc imageDesc = {};
                imageDesc.usage.color_attachment = true;
                imageDesc.width = static_cast<int> (attachment.extent.width);
                imageDesc.height = static_cast<int> (attachment.extent.height);
                imageDesc.pixel_format = format;
                imageDesc.sample_count = 1;
                imageDesc.label = "arbit-metal-render-pass-output";
                owned.image = sg_make_image (&imageDesc);
                bool valid = owned.image.id != 0
                    && resourceValid (sg_query_image_state (owned.image));
                if (valid)
                    allocation.imageCharges.emplace_back (
                        arbitgpu::residency::BackingClass::renderPassOutput,
                        arbitgpu::residency::nominalTextureBytes (
                            attachment.extent.width, attachment.extent.height, 1, 1,
                            renderpassoutput::bytesPerPixel (attachment.format), 1));

                if (valid)
                {
                    sg_view_desc attachmentViewDesc = {};
                    attachmentViewDesc.color_attachment.image = owned.image;
                    owned.attachmentView = sg_make_view (&attachmentViewDesc);
                    valid = owned.attachmentView.id != 0
                        && resourceValid (sg_query_view_state (owned.attachmentView));
                }

                if (valid)
                {
                    sg_view_desc textureViewDesc = {};
                    textureViewDesc.texture.image = owned.image;
                    owned.textureView = sg_make_view (&textureViewDesc);
                    valid = owned.textureView.id != 0
                        && resourceValid (sg_query_view_state (owned.textureView));
                }

                allocation.attachments.push_back (owned);
                if (! valid)
                {
                    result.error = "Metal failed to allocate render-pass output ";
                    result.error += renderpassoutput::token (attachment.output);
                    destroyRenderPassOutputAllocationUnlocked (allocation);
                    result.resources.clear();
                    return result;
                }

                result.resources.push_back ({ attachment.output,
                                              owned.image.id,
                                              owned.attachmentView.id,
                                              owned.textureView.id });
            }

            RenderPassOutputLifecycleHandle lifecycle;
            do
            {
                lifecycle = { nextLifecycle_++ };
            }
            while (! lifecycle || allocations_.find (lifecycle.value) != allocations_.end());
            allocations_.emplace (lifecycle.value, std::move (allocation));
            result.lifecycle = lifecycle;
            return result;
        }
    }

    RenderPassColorAovExecution executeColorAovClear (
        RenderPassOutputLifecycleHandle lifecycle,
        const RenderPassColorAovClear& clear) override
    {
        RenderPassColorAovExecution result;
        std::lock_guard<std::mutex> lock (sokolMutex());
        @autoreleasepool
        {
            if (! lifecycle)
            {
                result.error = "Metal Color AOV execution requires a lifecycle";
                return result;
            }
            if (! std::all_of (clear.linearRgba.begin(), clear.linearRgba.end(),
                               [] (float value) { return std::isfinite (value); }))
            {
                result.error = "Metal Color AOV clear values must be finite";
                return result;
            }

            const auto allocation = allocations_.find (lifecycle.value);
            if (allocation == allocations_.end())
            {
                result.error = "Metal Color AOV execution rejected a stale lifecycle";
                return result;
            }
            const auto color = std::find_if (
                allocation->second.attachments.begin(), allocation->second.attachments.end(),
                [] (const MetalRenderPassOutputAttachment& attachment)
                {
                    return attachment.output == renderpassoutput::Output::Color;
                });
            if (color == allocation->second.attachments.end()
                || color->attachmentView.id == 0
                || ! resourceValid (sg_query_view_state (color->attachmentView)))
            {
                result.error = "Metal Color AOV execution requires an admitted Color attachment";
                return result;
            }

            sg_pass pass = {};
            pass.attachments.colors[0] = color->attachmentView;
            pass.action.colors[0].load_action = SG_LOADACTION_CLEAR;
            pass.action.colors[0].store_action = SG_STOREACTION_STORE;
            pass.action.colors[0].clear_value = {
                clear.linearRgba[0], clear.linearRgba[1],
                clear.linearRgba[2], clear.linearRgba[3] };
            pass.label = "arbit-metal-color-aov-clear-pass";
            sg_begin_pass (&pass);
            sg_end_pass();
            sg_commit();

            do
            {
                result.submission = nextSubmission_++;
            }
            while (result.submission == 0);
            result.submitted = true;
            return result;
        }
    }

    RenderPassMotionAovExecution executeMotionAovClear (
        RenderPassOutputLifecycleHandle lifecycle,
        const RenderPassMotionAovClear& clear) override
    {
        RenderPassMotionAovExecution result;
        std::lock_guard<std::mutex> lock (sokolMutex());
        @autoreleasepool
        {
            if (! lifecycle)
            {
                result.error = "Metal Motion AOV execution requires a lifecycle";
                return result;
            }
            if (! std::all_of (clear.pixelDisplacement.begin(), clear.pixelDisplacement.end(),
                               [] (float value) { return std::isfinite (value); }))
            {
                result.error = "Metal Motion AOV clear values must be finite";
                return result;
            }

            const auto allocation = allocations_.find (lifecycle.value);
            if (allocation == allocations_.end())
            {
                result.error = "Metal Motion AOV execution rejected a stale lifecycle";
                return result;
            }
            const auto motion = std::find_if (
                allocation->second.attachments.begin(), allocation->second.attachments.end(),
                [] (const MetalRenderPassOutputAttachment& attachment)
                {
                    return attachment.output == renderpassoutput::Output::Motion;
                });
            if (motion == allocation->second.attachments.end()
                || motion->attachmentView.id == 0
                || ! resourceValid (sg_query_view_state (motion->attachmentView)))
            {
                result.error = "Metal Motion AOV execution requires an admitted Motion attachment";
                return result;
            }

            sg_pass pass = {};
            pass.attachments.colors[0] = motion->attachmentView;
            pass.action.colors[0].load_action = SG_LOADACTION_CLEAR;
            pass.action.colors[0].store_action = SG_STOREACTION_STORE;
            pass.action.colors[0].clear_value = {
                clear.pixelDisplacement[0], clear.pixelDisplacement[1], 0.0f, 0.0f };
            pass.label = "arbit-metal-motion-aov-clear-pass";
            sg_begin_pass (&pass);
            sg_end_pass();
            sg_commit();

            do
            {
                result.submission = nextSubmission_++;
            }
            while (result.submission == 0);
            result.submitted = true;
            return result;
        }
    }

    RenderPassSceneAovExecution executeSceneAov (
        RenderPassOutputLifecycleHandle,
        const sceneaov::Payload&) override
    {
        RenderPassSceneAovExecution result;
        result.error = "native Metal scene AOV execution is not compiled in";
        return result;
    }

    void releaseRenderPassOutputs (
        RenderPassOutputLifecycleHandle lifecycle) noexcept override
    {
        if (! lifecycle)
            return;
        std::lock_guard<std::mutex> lock (sokolMutex());
        @autoreleasepool
        {
            const auto found = allocations_.find (lifecycle.value);
            if (found == allocations_.end())
                return;
            destroyRenderPassOutputAllocationUnlocked (found->second);
            allocations_.erase (found);
        }
    }

private:
    std::uint64_t nextLifecycle_ = 1;
    std::uint64_t nextSubmission_ = 1;
    std::unordered_map<std::uint64_t, MetalRenderPassOutputAllocation> allocations_;
};

static constexpr const char* kOpticalFlowKernel = R"METAL(
#include <metal_stdlib>
using namespace metal;

inline float flowLuma(half4 rgba)
{
    return dot(float3(rgba.rgb), float3(0.2126, 0.7152, 0.0722));
}

// Bounded integer search only: 81 candidates with a 3x3 luminance patch.
// Confidence requires <=0.05 linear-luma RMS and a unique runner-up margin.
inline int2 matchFlowPatch(texture2d<half, access::read> first,
                           texture2d<half, access::read> second,
                           int2 pixel, int2 extent, thread bool& confident)
{
    float bestScore = INFINITY;
    float runnerUp = INFINITY;
    int2 best = int2(0);
    int bestMagnitude = 0;
    for (int dy = -4; dy <= 4; ++dy)
    {
        for (int dx = -4; dx <= 4; ++dx)
        {
            float score = 0.0;
            for (int py = -1; py <= 1; ++py)
            {
                for (int px = -1; px <= 1; ++px)
                {
                    const int2 a = clamp(pixel + int2(px, py), int2(0), extent - 1);
                    const int2 b = clamp(pixel + int2(px + dx, py + dy), int2(0), extent - 1);
                    const float difference = flowLuma(first.read(uint2(a)))
                                           - flowLuma(second.read(uint2(b)));
                    score += difference * difference;
                }
            }
            const int magnitude = dx * dx + dy * dy;
            const bool betterTie = score == bestScore
                && (magnitude < bestMagnitude
                    || (magnitude == bestMagnitude
                        && (dy < best.y || (dy == best.y && dx < best.x))));
            if (score < bestScore || betterTie)
            {
                runnerUp = bestScore;
                bestScore = score;
                best = int2(dx, dy);
                bestMagnitude = magnitude;
            }
            else
            {
                runnerUp = min(runnerUp, score);
            }
        }
    }
    confident = isfinite(bestScore) && bestScore <= 9.0 * 0.0025
        && runnerUp > bestScore * 1.1 + 0.000001;
    return best;
}

kernel void boundedBlockFlow(texture2d<half, access::read> first [[texture(0)]],
                             texture2d<half, access::read> second [[texture(1)]],
                             texture2d<half, access::write> output [[texture(2)]],
                             uint2 gid [[thread_position_in_grid]])
{
    const int2 extent = int2(output.get_width(), output.get_height());
    if (any(gid >= uint2(extent))) return;
    bool forwardConfidence = false;
    const int2 forward = matchFlowPatch(first, second, int2(gid), extent, forwardConfidence);
    const int2 destination = int2(gid) + forward;
    int2 flow = int2(0);
    if (forwardConfidence && all(destination >= int2(0)) && all(destination < extent))
    {
        // Both directions must pass confidence and return to the exact First pixel.
        // At most 162 candidates total; no pyramid or large-motion claim.
        bool reverseConfidence = false;
        const int2 reverse = matchFlowPatch(second, first, destination, extent, reverseConfidence);
        if (reverseConfidence && all(reverse == -forward)) flow = forward;
    }
    // Finite zero is the invalid-match fallback, not a validity-mask API.
    output.write(half4(half(flow.x), half(flow.y), half(0.0), half(0.0)), gid);
}

kernel void opticalMotionView(texture2d<half, access::read> field [[texture(0)]],
                              texture2d<half, access::write> image [[texture(1)]],
                              constant float& displayRangePixels [[buffer(0)]],
                              uint2 pixel [[thread_position_in_grid]])
{
    if (pixel.x >= image.get_width() || pixel.y >= image.get_height()) return;
    const float2 displacement = float2(field.read(pixel).rg);
    const float2 extent = float2(image.get_width(), image.get_height());
    const float2 denominator = displayRangePixels > 0.0 ? float2(displayRangePixels) : extent;
    const float2 direction = clamp(float2(0.5) + displacement / denominator, 0.0, 1.0);
    image.write(half4(half(direction.x), half(direction.y), half(0.5), half(1.0)), pixel);
}

struct OpticalBlurParams { uint samples; float scale; };
kernel void opticalMotionBlur(texture2d<half, access::sample> image [[texture(0)]],
                              texture2d<half, access::read> field [[texture(1)]],
                              texture2d<half, access::write> output [[texture(2)]],
                              constant OpticalBlurParams& params [[buffer(0)]],
                              uint2 pixel [[thread_position_in_grid]])
{
    if (pixel.x >= output.get_width() || pixel.y >= output.get_height()) return;
    constexpr sampler nearestSampler(coord::normalized, address::clamp_to_edge, filter::nearest);
    const float2 extent = float2(output.get_width(), output.get_height());
    const float2 motion = float2(field.read(pixel).rg) * params.scale;
    float4 sum = float4(0.0);
    for (uint i = 0; i < 64; ++i)
    {
        if (i >= params.samples) break;
        const float position = params.samples == 1 ? 0.0
            : float(i) / float(params.samples - 1) - 0.5;
        const float2 uv = clamp((float2(pixel) + 0.5 + motion * position) / extent,
                                float2(0.0), float2(1.0));
        sum += float4(image.sample(nearestSampler, uv));
    }
    const float4 linearColor = sum / float(params.samples);
    const float3 low = 12.92 * linearColor.rgb;
    const float3 high = 1.055 * pow(max(linearColor.rgb, float3(0.0)),
                                    float3(1.0 / 2.4)) - 0.055;
    const float3 srgb = clamp(select(low, high, linearColor.rgb >= 0.0031308), 0.0, 1.0);
    output.write(half4(half3(srgb), half(clamp(linearColor.a, 0.0, 1.0))), pixel);
}
)METAL";

// Nominal bytes of a 2D image described by a sokol descriptor.
static inline std::uint64_t metalImageBytes (const sg_image_desc& desc) noexcept
{
    return arbitgpu::residency::nominalTextureBytes (
        static_cast<std::uint64_t> (desc.width), static_cast<std::uint64_t> (desc.height), 1,
        static_cast<std::uint64_t> (desc.num_mipmaps),
        static_cast<std::uint64_t> (sg_query_pixelformat (desc.pixel_format).bytes_per_pixel),
        static_cast<std::uint64_t> (desc.sample_count));
}

class MetalOpticalFlowExecutionBackend final : public NativeOpticalFlowExecutionBackend
{
public:
    videoopticalflow::BackendCapabilities opticalFlowCapabilities() const override
    {
        std::lock_guard<std::mutex> lock (sokolMutex());
        @autoreleasepool
        {
            return capabilitiesUnlocked();
        }
    }

    NativeOpticalFlowSubmission executeOpticalFlow (
        const videoopticalflow::AdmittedRequest& request,
        const NativeOpticalFlowInputResource& first,
        const NativeOpticalFlowInputResource& second,
        bool resetTemporalState) override
    {
        NativeOpticalFlowSubmission result;
        (void) resetTemporalState; // The bounded pair kernel retains no history.
        std::lock_guard<std::mutex> lock (sokolMutex());
        @autoreleasepool
        {
            const auto capabilities = capabilitiesUnlocked();
            if (capabilities.kind != videoopticalflow::BackendKind::NativeGpu
                || ! capabilities.supportsOpticalFlow)
            {
                result.error = "Metal optical-flow compute backend is unavailable";
                return result;
            }
            if (request.backendImplementation() != capabilities.implementation
                || request.backendImplementationRevision()
                       != capabilities.implementationRevision)
            {
                result.error = "Metal optical-flow request was admitted for another backend revision";
                return result;
            }
            const auto sameDescriptor = [] (
                const videoopticalflow::FrameDescription& left,
                const videoopticalflow::FrameDescription& right)
            {
                return left.identity.stream == right.identity.stream
                    && left.identity.content == right.identity.content
                    && left.identity.frameIndex == right.identity.frameIndex
                    && left.timestamp.ticks == right.timestamp.ticks
                    && left.timestamp.timescale == right.timestamp.timescale
                    && left.extent == right.extent
                    && left.format == right.format
                    && left.colorSpace == right.colorSpace;
            };
            const auto* pair = request.sourcePairV2()
                ? &*request.sourcePairV2() : nullptr;
            const bool v2Receipts = pair == nullptr
                || (exactOpticalFlowV2InputReceipt (request, first, pair->first)
                    && exactOpticalFlowV2InputReceipt (request, second, pair->second)
                    && first.structuralRevision == pair->structuralRevision
                    && first.nativeContextIdentity
                           == reinterpret_cast<std::uintptr_t> ((__bridge void*) gMetalDevice)
                    && second.nativeContextIdentity == first.nativeContextIdentity);
            const bool exactResources = v2Receipts
                && first.immutable && second.immutable
                && videoopticalflow::detail::anyNonZero (first.identity)
                && videoopticalflow::detail::anyNonZero (second.identity)
                && first.identity != second.identity
                && first.helperGeneration != 0
                && first.helperGeneration == second.helperGeneration
                && first.structuralRevision != 0
                && first.structuralRevision == second.structuralRevision
                && first.imageHandle != 0 && second.imageHandle != 0
                && first.imageHandle == first.textureViewHandle
                && second.imageHandle == second.textureViewHandle
                && first.imageHandle != second.imageHandle
                && sameDescriptor (first.descriptor, request.first())
                && sameDescriptor (second.descriptor, request.second());
            if (! exactResources)
            {
                result.error = "Metal optical-flow input resource receipts do not match admission";
                return result;
            }

            id<MTLTexture> firstTexture = (__bridge id<MTLTexture>)
                reinterpret_cast<void*> (first.textureViewHandle);
            id<MTLTexture> secondTexture = (__bridge id<MTLTexture>)
                reinterpret_cast<void*> (second.textureViewHandle);
            const auto extent = request.output().extent;
            const bool texturesMatch = firstTexture != nil && secondTexture != nil
                && firstTexture.device == gMetalDevice && secondTexture.device == gMetalDevice
                && firstTexture.textureType == MTLTextureType2D
                && secondTexture.textureType == MTLTextureType2D
                && firstTexture.pixelFormat == MTLPixelFormatRGBA16Float
                && secondTexture.pixelFormat == MTLPixelFormatRGBA16Float
                && firstTexture.width == extent.width && firstTexture.height == extent.height
                && secondTexture.width == extent.width && secondTexture.height == extent.height
                && (firstTexture.usage & MTLTextureUsageShaderRead) != 0
                && (secondTexture.usage & MTLTextureUsageShaderRead) != 0;
            if (! texturesMatch)
            {
                result.error = "Metal optical-flow inputs violate exact RGBA16F resource bindings";
                return result;
            }
            if (! ensurePipelineUnlocked (result.error))
                return result;

            MTLTextureDescriptor* descriptor =
                [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRG16Float
                                                                   width:extent.width
                                                                  height:extent.height
                                                               mipmapped:NO];
            descriptor.storageMode = MTLStorageModePrivate;
            descriptor.usage = MTLTextureUsageShaderRead | MTLTextureUsageShaderWrite;
            id<MTLTexture> output = [gMetalDevice newTextureWithDescriptor:descriptor];
            if (output == nil)
            {
                result.error = "Metal optical-flow output allocation failed";
                return result;
            }

            id<MTLCommandQueue> queue = (__bridge id<MTLCommandQueue>) sg_mtl_command_queue();
            id<MTLCommandBuffer> command = [queue commandBuffer];
            id<MTLComputeCommandEncoder> encoder = [command computeCommandEncoder];
            if (queue == nil || command == nil || encoder == nil)
            {
                result.error = "Metal optical-flow command allocation failed";
#if ! __has_feature(objc_arc)
                [output release];
#endif
                return result;
            }
            [encoder setComputePipelineState:pipeline_];
            [encoder setTexture:firstTexture atIndex:0];
            [encoder setTexture:secondTexture atIndex:1];
            [encoder setTexture:output atIndex:2];
            const NSUInteger width = pipeline_.threadExecutionWidth;
            const NSUInteger height = std::max<NSUInteger> (
                1, pipeline_.maxTotalThreadsPerThreadgroup / width);
            [encoder dispatchThreads:MTLSizeMake(extent.width, extent.height, 1)
                 threadsPerThreadgroup:MTLSizeMake(width, height, 1)];
            [encoder endEncoding];
            [command commit];
            [command waitUntilCompleted];
            if (command.status != MTLCommandBufferStatusCompleted)
            {
                result.error = command.error != nil
                    ? std::string ([[command.error localizedDescription] UTF8String])
                    : "Metal optical-flow command did not complete";
#if ! __has_feature(objc_arc)
                [output release];
#endif
                return result;
            }

            do result.lifecycle.value = nextLifecycle_++;
            while (! result.lifecycle || outputs_.find(result.lifecycle.value) != outputs_.end());
            // One entry holds the texture and its charge, so one insert covers both.
            // RG16Float is four bytes per texel.
            outputs_.emplace(result.lifecycle.value, OutputEntry {output, arbitgpu::residency::ResidencyCharge (
                arbitgpu::residency::BackingClass::other, arbitgpu::residency::nominalTextureBytes (
                    static_cast<std::uint64_t> (extent.width), static_cast<std::uint64_t> (extent.height), 1, 1, 4, 1))});
            do result.submission = nextSubmission_++;
            while (result.submission == 0);
            result.result.requestCacheKey = request.cacheKey();
            result.result.backendImplementation = request.backendImplementation();
            result.result.backendImplementationRevision =
                request.backendImplementationRevision();
            result.result.motionVectors.helperGeneration = first.helperGeneration;
            result.result.motionVectors.descriptor = request.output();
            result.result.motionVectors.byteCount = request.footprint().outputBytes;
            std::memcpy(result.result.motionVectors.identity.data(),
                        &result.lifecycle.value, sizeof(result.lifecycle.value));
            std::memcpy(result.result.motionVectors.identity.data()
                            + sizeof(result.lifecycle.value),
                        &result.submission, sizeof(result.submission));
            result.imageHandle = reinterpret_cast<std::uintptr_t> ((__bridge void*) output);
            result.textureViewHandle = result.imageHandle;
            result.completed = true;
            return result;
        }
    }

    void releaseOpticalFlowOutput (
        NativeOpticalFlowOutputLifecycleHandle lifecycle) noexcept override
    {
        if (! lifecycle) return;
        std::lock_guard<std::mutex> lock (sokolMutex());
        const auto found = outputs_.find(lifecycle.value);
        if (found == outputs_.end()) return;
#if ! __has_feature(objc_arc)
        [found->second.texture release];
#endif
        outputs_.erase(found);
    }

    std::shared_ptr<const NativeFixtureSceneFrame> renderMotionView (
        const std::shared_ptr<const videoopticalflow::PublishedNativeResult>& field,
        const motionviewoperation::Payload& presentation, std::string& error) override
    {
        if (! motionviewoperation::valid (presentation)
            || presentation.convention != motionviewoperation::Convention::OpticalFirstToSecondTopLeft)
        { error = "Metal Motion View requires a valid optical display range"; return {}; }
        std::lock_guard<std::mutex> lock(sokolMutex());
        @autoreleasepool
        {
            const auto capabilities = capabilitiesUnlocked();
            if (!field || capabilities.kind != videoopticalflow::BackendKind::NativeGpu
                || field->nativeContextIdentity()
                    != reinterpret_cast<std::uintptr_t>((__bridge void*)gMetalDevice)
                || field->structuralRevision() == 0 || field->helperGeneration() == 0
                || field->submissionSerial() == 0 || field->imageHandle() == 0
                || field->imageHandle() != field->textureViewHandle()
                || field->receipt().backendImplementation() != capabilities.implementation
                || field->receipt().backendImplementationRevision()
                    != capabilities.implementationRevision)
            { error="Metal Motion View field belongs to another device or backend"; return {}; }
            const auto& descriptor=field->receipt().motionVectors().descriptor;
            const auto width=descriptor.extent.width, height=descriptor.extent.height;
            const auto source=(__bridge id<MTLTexture>)reinterpret_cast<void*>(field->textureViewHandle());
            if (descriptor.format!=renderpassoutput::PixelFormat::RG16Float
                || width==0 || height==0 || source==nil
                || source.device!=gMetalDevice || source.textureType!=MTLTextureType2D
                || source.pixelFormat!=MTLPixelFormatRG16Float
                || source.width!=width || source.height!=height || source.sampleCount!=1
                || field->receipt().motionVectors().helperGeneration!=field->helperGeneration())
            { error="Metal Motion View requires an exact retained RG16F field"; return {}; }
            if (!ensureViewPipelineUnlocked(error)) return {};
            auto frame=std::make_shared<MetalFixtureSceneFrame>();
            frame->width_=width; frame->height_=height;
            frame->rendererGeneration_=nextMetalRendererGeneration();
            frame->declaredSrgb=true;
            frame->opticalFieldOwner=field;
            sg_image_desc image={};
            image.width=static_cast<int>(width); image.height=static_cast<int>(height);
            image.pixel_format=SG_PIXELFORMAT_BGRA8;
            image.usage.storage_image=true;
            image.label="arbit-metal-optical-motion-view";
            frame->colorImage=sg_make_image(&image);
            sg_view_desc view={}; view.texture.image=frame->colorImage;
            frame->colorTextureView=sg_make_view(&view);
            if (!resourceValid(sg_query_image_state(frame->colorImage))
                || !resourceValid(sg_query_view_state(frame->colorTextureView)))
            {
                frame->destroyUnlocked();
                error="Metal Motion View Image allocation failed";
                return {};
            }
            frame->colorImageCharge = arbitgpu::residency::ResidencyCharge (
                arbitgpu::residency::BackingClass::fixtureScene, metalImageBytes (image));
            const auto native=sg_mtl_query_image_info(frame->colorImage);
            const auto output=(__bridge id<MTLTexture>)native.tex[native.active_slot];
            id<MTLCommandQueue> queue=(__bridge id<MTLCommandQueue>)sg_mtl_command_queue();
            id<MTLCommandBuffer> command=[queue commandBuffer];
            id<MTLComputeCommandEncoder> encoder=[command computeCommandEncoder];
            if (output==nil || output.device!=gMetalDevice
                || output.pixelFormat!=MTLPixelFormatBGRA8Unorm
                || output.width!=width || output.height!=height
                || queue==nil || command==nil || encoder==nil)
            {
                frame->destroyUnlocked();
                error="Metal Motion View Image storage is incompatible";
                return {};
            }
            [encoder setComputePipelineState:viewPipeline_];
            [encoder setTexture:source atIndex:0];
            [encoder setTexture:output atIndex:1];
            const float displayRangePixels = static_cast<float>(presentation.displayRangePixels);
            [encoder setBytes:&displayRangePixels length:sizeof(displayRangePixels) atIndex:0];
            const NSUInteger lanes=viewPipeline_.threadExecutionWidth;
            const NSUInteger rows=std::max<NSUInteger>(1,
                viewPipeline_.maxTotalThreadsPerThreadgroup/lanes);
            [encoder dispatchThreads:MTLSizeMake(width,height,1)
                threadsPerThreadgroup:MTLSizeMake(lanes,rows,1)];
            [encoder endEncoding];
            [command commit]; [command waitUntilCompleted];
            if (command.status!=MTLCommandBufferStatusCompleted)
            {
                frame->destroyUnlocked();
                error=command.error!=nil
                    ? std::string([[command.error localizedDescription] UTF8String])
                    : "Metal Motion View Image draw failed";
                return {};
            }
            error.clear(); return frame;
        }
    }

    std::shared_ptr<const NativeFixtureSceneFrame> renderMotionBlur (
        const std::shared_ptr<const videoopticalflow::NativeSourceFrame>& image,
        const std::shared_ptr<const videoopticalflow::PublishedNativeResult>& field,
        const visualtemporalsampling::Payload& payload, std::string& error) override
    {
        std::lock_guard<std::mutex> lock(sokolMutex());
        @autoreleasepool
        {
            const auto capabilities = capabilitiesUnlocked();
            const auto deviceIdentity = reinterpret_cast<std::uintptr_t>((__bridge void*)gMetalDevice);
            if (!image || !field || capabilities.kind != videoopticalflow::BackendKind::NativeGpu
                || !visualtemporalsampling::validate(payload)
                || payload.mode != visualtemporalsampling::Mode::motionBlur
                || image->nativeContextIdentity() != deviceIdentity
                || field->nativeContextIdentity() != deviceIdentity
                || image->helperGeneration() == 0
                || image->helperGeneration() != field->helperGeneration()
                || image->structuralRevision() == 0
                || image->structuralRevision() != field->structuralRevision()
                || image->backendImplementation() != capabilities.implementation
                || image->backendImplementationRevision() != capabilities.implementationRevision
                || field->receipt().backendImplementation() != capabilities.implementation
                || field->receipt().backendImplementationRevision() != capabilities.implementationRevision
                || image->frame().extent != field->receipt().motionVectors().descriptor.extent
                || image->frame().format != renderpassoutput::PixelFormat::RGBA16Float
                || field->receipt().motionVectors().descriptor.format
                    != renderpassoutput::PixelFormat::RG16Float)
            { error="Metal Motion Blur requires the exact retained image and optical field"; return {}; }
            const auto width=image->frame().extent.width, height=image->frame().extent.height;
            const auto source=(__bridge id<MTLTexture>)reinterpret_cast<void*>(image->textureViewHandle());
            const auto motion=(__bridge id<MTLTexture>)reinterpret_cast<void*>(field->textureViewHandle());
            if (width==0 || height==0 || source==nil || motion==nil
                || source.device!=gMetalDevice || motion.device!=gMetalDevice
                || source.textureType!=MTLTextureType2D || motion.textureType!=MTLTextureType2D
                || source.pixelFormat!=MTLPixelFormatRGBA16Float
                || motion.pixelFormat!=MTLPixelFormatRG16Float
                || source.width!=width || source.height!=height
                || motion.width!=width || motion.height!=height
                || source.sampleCount!=1 || motion.sampleCount!=1
                || (source.usage & MTLTextureUsageShaderRead)==0
                || (motion.usage & MTLTextureUsageShaderRead)==0)
            { error="Metal Motion Blur source storage changed"; return {}; }
            if (!ensureBlurPipelineUnlocked(error)) return {};
            auto frame=std::make_shared<MetalFixtureSceneFrame>();
            frame->width_=width; frame->height_=height;
            frame->rendererGeneration_=nextMetalRendererGeneration();
            frame->declaredSrgb=true;
            frame->opticalFieldOwner=field;
            frame->opticalImageOwner=image;
            sg_image_desc imageDesc={};
            imageDesc.width=static_cast<int>(width); imageDesc.height=static_cast<int>(height);
            imageDesc.pixel_format=SG_PIXELFORMAT_BGRA8;
            imageDesc.usage.storage_image=true;
            imageDesc.label="arbit-metal-optical-motion-blur";
            frame->colorImage=sg_make_image(&imageDesc);
            sg_view_desc view={}; view.texture.image=frame->colorImage;
            frame->colorTextureView=sg_make_view(&view);
            if (!resourceValid(sg_query_image_state(frame->colorImage))
                || !resourceValid(sg_query_view_state(frame->colorTextureView)))
            { frame->destroyUnlocked(); error="Metal Motion Blur Image allocation failed"; return {}; }
            frame->colorImageCharge = arbitgpu::residency::ResidencyCharge (
                arbitgpu::residency::BackingClass::fixtureScene, metalImageBytes (imageDesc));
            const auto native=sg_mtl_query_image_info(frame->colorImage);
            const auto output=(__bridge id<MTLTexture>)native.tex[native.active_slot];
            id<MTLCommandQueue> queue=(__bridge id<MTLCommandQueue>)sg_mtl_command_queue();
            id<MTLCommandBuffer> command=[queue commandBuffer];
            id<MTLComputeCommandEncoder> encoder=[command computeCommandEncoder];
            if (output==nil || output.device!=gMetalDevice
                || output.pixelFormat!=MTLPixelFormatBGRA8Unorm
                || output.width!=width || output.height!=height
                || queue==nil || command==nil || encoder==nil)
            { frame->destroyUnlocked(); error="Metal Motion Blur Image storage is incompatible"; return {}; }
            const struct { std::uint32_t samples; float scale; } params {
                payload.sampleCount, payload.motionScale*payload.shutterAngleDegrees/360.0f };
            [encoder setComputePipelineState:blurPipeline_];
            [encoder setTexture:source atIndex:0];
            [encoder setTexture:motion atIndex:1];
            [encoder setTexture:output atIndex:2];
            [encoder setBytes:&params length:sizeof(params) atIndex:0];
            const NSUInteger lanes=blurPipeline_.threadExecutionWidth;
            const NSUInteger rows=std::max<NSUInteger>(1,
                blurPipeline_.maxTotalThreadsPerThreadgroup/lanes);
            [encoder dispatchThreads:MTLSizeMake(width,height,1)
                threadsPerThreadgroup:MTLSizeMake(lanes,rows,1)];
            [encoder endEncoding];
            [command commit]; [command waitUntilCompleted];
            if (command.status!=MTLCommandBufferStatusCompleted)
            {
                frame->destroyUnlocked();
                error=command.error!=nil
                    ? std::string([[command.error localizedDescription] UTF8String])
                    : "Metal Motion Blur Image draw failed";
                return {};
            }
            error.clear(); return frame;
        }
    }

private:
    videoopticalflow::BackendCapabilities capabilitiesUnlocked() const
    {
        videoopticalflow::BackendCapabilities result;
        if (! ensureSokolMetal()) return result;
        result.kind = videoopticalflow::BackendKind::NativeGpu;
        result.supportsOpticalFlow = true;
        static constexpr std::array<std::uint8_t, 16> identity = {
            'M','T','L','B','l','o','c','k','F','l','o','w','0','0','0','1' };
        result.implementation = identity;
        result.implementationRevision = 1;
        result.limits = {};
        result.temporaryBytesPerPixel = 0;
        result.fixedTemporaryBytes = 0;
        return result;
    }

    bool ensurePipelineUnlocked (std::string& error)
    {
        if (pipeline_ != nil) return true;
        NSError* libraryError = nil;
        NSString* source = [NSString stringWithUTF8String:kOpticalFlowKernel];
        id<MTLLibrary> library = [gMetalDevice newLibraryWithSource:source
                                                            options:nil
                                                              error:&libraryError];
        if (library == nil)
        {
            error = libraryError != nil
                ? std::string ([[libraryError localizedDescription] UTF8String])
                : "Metal optical-flow shader compilation failed";
            return false;
        }
        id<MTLFunction> function = [library newFunctionWithName:@"boundedBlockFlow"];
        NSError* pipelineError = nil;
        pipeline_ = [gMetalDevice newComputePipelineStateWithFunction:function
                                                                 error:&pipelineError];
#if ! __has_feature(objc_arc)
        [function release];
        [library release];
#endif
        if (pipeline_ == nil)
        {
            error = pipelineError != nil
                ? std::string ([[pipelineError localizedDescription] UTF8String])
                : "Metal optical-flow pipeline creation failed";
            return false;
        }
        return true;
    }

    bool ensureViewPipelineUnlocked(std::string& error)
    {
        if(viewPipeline_!=nil) return true;
        NSError* libraryError=nil;
        id<MTLLibrary> library=[gMetalDevice newLibraryWithSource:
            [NSString stringWithUTF8String:kOpticalFlowKernel] options:nil error:&libraryError];
        if(library==nil)
        { error=libraryError!=nil ? std::string([[libraryError localizedDescription] UTF8String])
            : "Metal Motion View shader library failed"; return false; }
        id<MTLFunction> function=[library newFunctionWithName:@"opticalMotionView"];
        NSError* pipelineError=nil;
        viewPipeline_=[gMetalDevice newComputePipelineStateWithFunction:function
            error:&pipelineError];
#if ! __has_feature(objc_arc)
        [function release]; [library release];
#endif
        if(viewPipeline_==nil)
        { error=pipelineError!=nil ? std::string([[pipelineError localizedDescription] UTF8String])
            : "Metal Motion View compute pipeline failed"; return false; }
        return true;
    }

    bool ensureBlurPipelineUnlocked(std::string& error)
    {
        if(blurPipeline_!=nil) return true;
        NSError* libraryError=nil;
        id<MTLLibrary> library=[gMetalDevice newLibraryWithSource:
            [NSString stringWithUTF8String:kOpticalFlowKernel] options:nil error:&libraryError];
        if(library==nil)
        { error=libraryError!=nil ? std::string([[libraryError localizedDescription] UTF8String])
            : "Metal Motion Blur shader library failed"; return false; }
        id<MTLFunction> function=[library newFunctionWithName:@"opticalMotionBlur"];
        NSError* pipelineError=nil;
        blurPipeline_=[gMetalDevice newComputePipelineStateWithFunction:function error:&pipelineError];
#if ! __has_feature(objc_arc)
        [function release]; [library release];
#endif
        if(blurPipeline_==nil)
        { error=pipelineError!=nil ? std::string([[pipelineError localizedDescription] UTF8String])
            : "Metal Motion Blur compute pipeline failed"; return false; }
        return true;
    }

    id<MTLComputePipelineState> pipeline_ = nil;
    id<MTLComputePipelineState> viewPipeline_ = nil;
    id<MTLComputePipelineState> blurPipeline_ = nil;
    std::uint64_t nextLifecycle_ = 1;
    std::uint64_t nextSubmission_ = 1;
    // A texture and the residency charge for its storage are inserted and erased together.
    struct OutputEntry final
    {
        id<MTLTexture> texture;
        arbitgpu::residency::ResidencyCharge charge;
    };
    std::unordered_map<std::uint64_t, OutputEntry> outputs_;
};

class MetalSdfExecutionBackend final : public NativeSdfExecutionBackend
{
public:
    NativeSdfExecutionCapabilities capabilities() const override
    {
        std::lock_guard<std::mutex> lock (sokolMutex());
        @autoreleasepool
        {
            auto result = capabilitiesUnlocked();
            if (result.available && sg_query_features().compute
                && sg_query_limits().max_storage_buffer_bindings_per_stage >= 7
                && gMetalDevice.maxBufferLength >= sizeof (NativeSdfTextSegment)
                && sg_query_pixelformat (SG_PIXELFORMAT_RG32F).render
                && sg_query_pixelformat (SG_PIXELFORMAT_RG32F).sample
                && ensurePipelineUnlocked (true, result.error))
                result.supportedOperations[static_cast<std::uint32_t> (
                    videowire::SdfOperation::textExtrusion)] = true;
            return result;
        }
    }

    NativeSdfSceneSubmission render (const NativeSdfDrawRequest& request) override
    {
        NativeSdfSceneSubmission result;
        NativeSdfWorkReceipt textWork;
        if (! videohelper::sdf::admitNativeSdfStagedTextWork (request, textWork, result.error))
            return result;
        std::string programError;
        const auto compiledProgram = resolveSdfProgram (request, programError);
        if (! compiledProgram)
        {
            result.error = programError.empty()
                ? "Metal native SDF program admission failed" : std::move (programError);
            return result;
        }
        const auto cpuBytes = compiledProgram->storageBytes();
        if ((request.geometryCacheBytes != 0 && request.geometryCacheBytes < cpuBytes)
            || request.geometryCacheBytes > renderpassoutput::kMaximumTotalBytes)
        {
            result.error = "Metal native SDF cache resource receipt is invalid";
            return result;
        }
        const auto available = capabilities();
        {
            if (! available.available)
            {
                result.error = available.error;
                return result;
            }
            const auto validQuality = [] (NativeSdfQuality quality)
            {
                return static_cast<std::uint8_t> (quality)
                    < static_cast<std::uint8_t> (NativeSdfQuality::count);
            };
            if (request.width == 0 || request.height == 0
                || request.width > available.maxExtent
                || request.height > available.maxExtent
                || static_cast<std::uint64_t> (request.width) * request.height
                    > available.maxPixels)
            {
                result.error = "Metal native SDF render dimensions exceed backend limits";
                return result;
            }
            if ((request.normalInspection && request.output != NativeSdfOutput::normal)
                || request.maximumSteps == 0 || request.maximumSteps > available.maxSteps
                || ! std::isfinite (request.epsilon)
                || request.epsilon < available.minEpsilon
                || request.epsilon > available.maxEpsilon
                || ! std::isfinite (request.maximumDistance)
                || request.maximumDistance < request.epsilon
                || request.maximumDistance > available.maxDistance
                || ! validQuality (request.adaptiveQuality)
                || ! validQuality (request.normalQuality)
                || ! validQuality (request.shadowQuality)
                || ! available.supports (request.output))
            {
                result.error = "Metal native SDF raymarch controls exceed backend limits";
                return result;
            }

            const bool hasText = ! compiledProgram->textResources().empty();
            if (hasText && ! available.supports (videowire::SdfOperation::textExtrusion))
            {
                result.error = "Metal native SDF text table consumer is unavailable";
                return result;
            }
            const std::array<sg_range, 7> textRanges {{
                { compiledProgram->textResourceIndices().data(), compiledProgram->textResourceIndices().size() * sizeof (std::uint32_t) },
                { compiledProgram->textResources().data(), compiledProgram->textResources().size() * sizeof (NativeSdfTextResourceHeader) },
                { compiledProgram->textContours().data(), compiledProgram->textContours().size() * sizeof (NativeSdfTextContourHeader) },
                { compiledProgram->textSegments().data(), compiledProgram->textSegments().size() * sizeof (NativeSdfTextSegment) },
                { compiledProgram->textIndexNodes().data(), compiledProgram->textIndexNodes().size() * sizeof (NativeSdfTextIndexNode) },
                { compiledProgram->textSegmentIndices().data(), compiledProgram->textSegmentIndices().size() * sizeof (std::uint32_t) },
                { compiledProgram->textIndexRoots().data(), compiledProgram->textIndexRoots().size() * sizeof (std::uint32_t) }
            }};
            if (hasText)
                for (const auto& range : textRanges)
                    if (range.size == 0 || range.size > gMetalDevice.maxBufferLength)
                    {
                        result.error = "Metal native SDF text table exceeds device buffer capacity";
                        return result;
                    }

            std::uint64_t reserved = request.geometryCacheBytes != 0 ? request.geometryCacheBytes : cpuBytes;
            for (auto bytes : { std::uint64_t (std::strlen (kSdfVertexShader) + std::strlen (kSdfFragmentShader)),
                                std::uint64_t (sizeof (SdfUniforms)),
                                std::uint64_t (request.width) * request.height * (hasText ? 28 : 20),
                                compiledProgram->textTableBytes() })
            {
                if (bytes > renderpassoutput::kMaximumTotalBytes
                    || reserved > renderpassoutput::kMaximumTotalBytes - bytes)
                {
                    result.error = "Metal native SDF resource reservation exceeds capacity";
                    return result;
                }
                reserved += bytes;
            }

            renderpassoutput::Description outputDescription;
            outputDescription.extent = { request.width, request.height };
            outputDescription.attachments.push_back ({
                renderpassoutput::Output::Color,
                renderpassoutput::PixelFormat::RGBA16Float,
                renderpassoutput::ColorSpace::LinearSRGB,
                outputDescription.extent });
            outputDescription.attachments.push_back ({
                renderpassoutput::Output::Depth,
                renderpassoutput::PixelFormat::R32Float,
                renderpassoutput::ColorSpace::Data,
                outputDescription.extent });
            outputDescription.attachments.push_back ({
                renderpassoutput::Output::Normal,
                renderpassoutput::PixelFormat::RGBA16Float,
                renderpassoutput::ColorSpace::Data,
                outputDescription.extent });
            renderpassoutput::AdmissionFailure outputFailure;
            const auto admittedOutputs = renderpassoutput::admit (
                outputDescription, outputFailure);
            if (! admittedOutputs)
            {
                result.error = "Metal native SDF output admission failed: "
                    + std::string (renderpassoutput::token (outputFailure));
                return result;
            }
            auto& outputBackend = nativeRenderPassOutputBackend();
            auto outputAdmission = outputBackend.admitRenderPassOutputs (*admittedOutputs);
            if (outputAdmission.lifecycle.value == 0 || outputAdmission.resources.size() != 3)
            {
                if (outputAdmission.lifecycle.value != 0)
                    outputBackend.releaseRenderPassOutputs (outputAdmission.lifecycle);
                result.error = outputAdmission.error.empty()
                    ? "Metal native SDF output allocation failed"
                    : std::move (outputAdmission.error);
                return result;
            }

            std::unique_lock<std::mutex> lock (sokolMutex());
            @autoreleasepool
            {
            auto frame = std::make_shared<MetalSdfSceneFrame>();
            frame->width_ = request.width;
            frame->height_ = request.height;
            frame->deviceIdentity_ = reinterpret_cast<std::uintptr_t>((__bridge void*)gMetalDevice);
            frame->outputBackend_ = &outputBackend;
            frame->lifecycle_ = outputAdmission.lifecycle;
            frame->frameMemory_ = outputAdmission.frameMemory;
            frame->receipt_.compiledRecordCount = static_cast<std::uint32_t> (
                compiledProgram->records().size());
            frame->receipt_.compiledRecordBytes = frame->receipt_.compiledRecordCount
                * sizeof (arbitgpu::NativeSdfCompiledRecord);
            frame->receipt_.geometryCacheBytes = request.geometryCacheBytes;
            frame->receipt_.backendProgramBytes = std::strlen (kSdfVertexShader)
                + std::strlen (kSdfFragmentShader);
            frame->receipt_.uniformBytes = sizeof (SdfUniforms);
            frame->receipt_.attachmentBytes = outputAdmission.frameMemory.requestedBytes;
            frame->receipt_.compiledTextTableBytes = compiledProgram->textTableBytes();
            frame->receipt_.distanceQueryCount = textWork.distanceQueryCount;
            frame->receipt_.recordVisits = textWork.recordVisits;
            frame->receipt_.segmentVisits = textWork.segmentVisits;
            frame->receipt_.textIndexNodeVisits = textWork.textIndexNodeVisits;
            frame->colorImage.id = static_cast<std::uint32_t> (
                outputAdmission.resources[0].image);
            frame->colorAttachmentView.id = static_cast<std::uint32_t> (
                outputAdmission.resources[0].attachmentView);
            frame->colorTextureView.id = static_cast<std::uint32_t> (
                outputAdmission.resources[0].textureView);
            frame->depthImage.id = static_cast<std::uint32_t> (
                outputAdmission.resources[1].image);
            frame->depthAttachmentView.id = static_cast<std::uint32_t> (
                outputAdmission.resources[1].attachmentView);
            frame->depthTextureView.id = static_cast<std::uint32_t> (
                outputAdmission.resources[1].textureView);
            frame->normalImage.id = static_cast<std::uint32_t> (
                outputAdmission.resources[2].image);
            frame->normalAttachmentView.id = static_cast<std::uint32_t> (
                outputAdmission.resources[2].attachmentView);
            frame->normalTextureView.id = static_cast<std::uint32_t> (
                outputAdmission.resources[2].textureView);
            auto fail = [&] (std::string diagnostic)
            {
                result.error = std::move (diagnostic);
                lock.unlock();
                frame.reset();
                return result;
            };

            if (! ensurePipelineUnlocked (hasText, result.error))
                return fail (std::move (result.error));

            const bool resourcesOk =
                resourceValid (sg_query_image_state (frame->colorImage))
                && resourceValid (sg_query_view_state (frame->colorAttachmentView))
                && resourceValid (sg_query_view_state (frame->colorTextureView))
                && resourceValid (sg_query_image_state (frame->depthImage))
                && resourceValid (sg_query_view_state (frame->depthAttachmentView))
                && resourceValid (sg_query_view_state (frame->depthTextureView))
                && resourceValid (sg_query_image_state (frame->normalImage))
                && resourceValid (sg_query_view_state (frame->normalAttachmentView))
                && resourceValid (sg_query_view_state (frame->normalTextureView));
            if (! resourcesOk)
                return fail ("Metal native SDF GPU resource creation failed");

            sg_bindings bindings {};
            std::vector<const void*> nativeAllocations;
            if (hasText)
                for (std::size_t table = 0; table < textRanges.size(); ++table)
                {
                    sg_buffer_desc bufferDesc = {};
                    bufferDesc.usage.storage_buffer = true;
                    bufferDesc.data = textRanges[table];
                    bufferDesc.label = "arbit-metal-sdf-text-table";
                    frame->textBuffers_[table] = sg_make_buffer (&bufferDesc);
                    sg_view_desc viewDesc = {};
                    viewDesc.storage_buffer.buffer = frame->textBuffers_[table];
                    frame->textViews_[table] = sg_make_view (&viewDesc);
                    if (! resourceValid (sg_query_buffer_state (frame->textBuffers_[table]))
                        || ! resourceValid (sg_query_view_state (frame->textViews_[table])))
                        return fail ("Metal native SDF text table allocation failed");
                    frame->textBufferCharges[table] = arbitgpu::residency::ResidencyCharge (
                        arbitgpu::residency::BackingClass::other,
                        arbitgpu::residency::nominalBufferBytes (textRanges[table].size));
                    const auto native = sg_mtl_query_buffer_info (frame->textBuffers_[table]);
                    if (native.active_slot < 0 || native.active_slot >= SG_NUM_INFLIGHT_FRAMES
                        || native.buf[native.active_slot] == nullptr)
                        return fail ("Metal native SDF text table has no native owner");
                    for (int slot = 0; slot < SG_NUM_INFLIGHT_FRAMES; ++slot)
                    {
                        id<MTLBuffer> buffer = (__bridge id<MTLBuffer>) native.buf[slot];
                        if (buffer == nil) continue;
                        const void* identity = (__bridge const void*) buffer;
                        if (buffer.device != gMetalDevice || buffer.length < textRanges[table].size
                            || buffer.length > gMetalDevice.maxBufferLength)
                            return fail ("Metal native SDF text table native allocation is invalid");
                        if (std::find (nativeAllocations.begin(), nativeAllocations.end(), identity)
                            != nativeAllocations.end()) continue;
                        if (buffer.allocatedSize < buffer.length
                            || buffer.allocatedSize > renderpassoutput::kMaximumTotalBytes
                                - frame->receipt_.nativeTextTableBytes)
                            return fail ("Metal native SDF text allocation receipt exceeds capacity");
                        nativeAllocations.push_back (identity);
                        frame->receipt_.nativeTextTableBytes += buffer.allocatedSize;
                    }
                    bindings.views[table] = frame->textViews_[table];
                }
            if (hasText) {
                sg_image_desc desc = {};
                desc.width = request.width; desc.height = request.height;
                desc.pixel_format = SG_PIXELFORMAT_RG32F; desc.sample_count = 1;
                desc.usage.color_attachment = true;
                desc.label = "arbit-metal-sdf-primary-hit-travel";
                frame->primaryImage_ = sg_make_image (&desc);
                sg_view_desc attachment = {}; attachment.color_attachment.image = frame->primaryImage_;
                frame->primaryAttachmentView_ = sg_make_view (&attachment);
                sg_view_desc texture = {}; texture.texture.image = frame->primaryImage_;
                frame->primaryTextureView_ = sg_make_view (&texture);
                if (! resourceValid (sg_query_image_state (frame->primaryImage_))
                    || ! resourceValid (sg_query_view_state (frame->primaryAttachmentView_))
                    || ! resourceValid (sg_query_view_state (frame->primaryTextureView_)))
                    return fail ("Metal native SDF primary result allocation failed");
                frame->primaryImageCharge = arbitgpu::residency::ResidencyCharge (
                    arbitgpu::residency::BackingClass::other, metalImageBytes (desc));
                const auto native = sg_mtl_query_image_info (frame->primaryImage_);
                if (native.active_slot < 0 || native.active_slot >= SG_NUM_INFLIGHT_FRAMES)
                    return fail ("Metal native SDF primary result has no native owner");
                const auto primary = (__bridge id<MTLTexture>) native.tex[native.active_slot];
                if (primary == nil || primary.device != gMetalDevice
                    || primary.allocatedSize > renderpassoutput::kMaximumTotalBytes - frame->receipt_.attachmentBytes)
                    return fail ("Metal native SDF primary result allocation exceeds capacity");
                frame->receipt_.attachmentBytes += primary.allocatedSize;
            }
            // The immutable renderer cache already owns CPU records and tables.
            // Direct backend requests instead charge that program once here.
            frame->receipt_.totalBytes = request.geometryCacheBytes != 0
                ? request.geometryCacheBytes : compiledProgram->storageBytes();
            for (auto bytes : { frame->receipt_.backendProgramBytes, frame->receipt_.uniformBytes,
                                frame->receipt_.attachmentBytes, frame->receipt_.nativeTextTableBytes })
            {
                if (bytes > renderpassoutput::kMaximumTotalBytes
                    || frame->receipt_.totalBytes > renderpassoutput::kMaximumTotalBytes - bytes)
                    return fail ("Metal native SDF aggregate resource receipt exceeds capacity");
                frame->receipt_.totalBytes += bytes;
            }
            // Immutable Sokol Metal buffers use newBufferWithBytes directly;
            // their source tables are already retained in the CPU cache.
            frame->receipt_.peakBytes = frame->receipt_.totalBytes;

            SdfUniforms uniforms {};
            for (std::size_t index = 0; index < compiledProgram->records().size(); ++index)
            {
                const auto& source = compiledProgram->records()[index];
                auto& destination = uniforms.records[index];
                destination.header[0] = source.operation;
                destination.header[1] = source.input0;
                destination.header[2] = source.input1;
                destination.header[3] = videohelper::sdf::nativeSdfMaterialColorCode (source.stableId);
                std::copy_n (source.parameters.data(), 4, destination.parameters0);
                std::copy_n (source.parameters.data() + 4, 4, destination.parameters1);
            }
            uniforms.raymarch[0] = static_cast<float> (request.epsilon);
            uniforms.raymarch[1] = static_cast<float> (request.maximumDistance);
            uniforms.raymarch[2] = static_cast<float> (request.width);
            uniforms.raymarch[3] = static_cast<float> (request.height);
            uniforms.quality[0] = request.maximumSteps;
            uniforms.quality[1] = static_cast<std::uint32_t> (request.normalQuality);
            uniforms.quality[2] = static_cast<std::uint32_t> (request.shadowQuality);
            uniforms.quality[3] = static_cast<std::uint32_t> (request.adaptiveQuality);
            uniforms.program[0] = static_cast<std::uint32_t> (request.output);
            uniforms.program[1] = compiledProgram->rootIndex();
            uniforms.program[2] = static_cast<std::uint32_t> (compiledProgram->records().size());
            uniforms.program[3] = request.normalInspection ? 1u : 0u;

            const sg_range uniformRange = { &uniforms, sizeof (uniforms) };
            if (hasText) {
                sg_pass primaryPass = {};
                primaryPass.attachments.colors[0] = frame->primaryAttachmentView_;
                primaryPass.action.colors[0].load_action = SG_LOADACTION_CLEAR;
                primaryPass.action.colors[0].store_action = SG_STOREACTION_STORE;
                primaryPass.action.colors[0].clear_value = { 0, 0, 0, 0 };
                primaryPass.label = "arbit-metal-sdf-primary-pass";
                sg_begin_pass (&primaryPass);
                sg_apply_pipeline (primaryPipeline_);
                sg_apply_bindings (&bindings);
                sg_apply_uniforms (0, &uniformRange);
                sg_draw (0, 3, 1);
                sg_end_pass();
                bindings.views[7] = frame->primaryTextureView_;
            }
            sg_pass pass = {};
            pass.attachments.colors[0] = frame->colorAttachmentView;
            pass.attachments.colors[1] = frame->normalAttachmentView;
            pass.action.colors[0].load_action = SG_LOADACTION_CLEAR;
            pass.action.colors[0].store_action = SG_STOREACTION_STORE;
            pass.action.colors[0].clear_value = {
                7.0f / 255.0f, 10.0f / 255.0f, 18.0f / 255.0f, 1.0f };
            pass.action.colors[1].load_action = SG_LOADACTION_CLEAR;
            pass.action.colors[1].store_action = SG_STOREACTION_STORE;
            pass.action.colors[1].clear_value = { 0, 0, 0, 0 };
            pass.label = "arbit-metal-sdf-scene-pass";
            sg_begin_pass (&pass);
            sg_apply_pipeline (pipeline_[hasText]);
            sg_apply_bindings (&bindings);
            sg_apply_uniforms (0, &uniformRange);
            sg_draw (0, 3, 1);
            sg_end_pass();
            sg_pass depthPass = {};
            depthPass.attachments.colors[0] = frame->depthAttachmentView;
            depthPass.action.colors[0].load_action = SG_LOADACTION_CLEAR;
            depthPass.action.colors[0].store_action = SG_STOREACTION_STORE;
            depthPass.action.colors[0].clear_value = { 1.0f, 0, 0, 1.0f };
            depthPass.label = "arbit-metal-sdf-depth-pass";
            sg_begin_pass (&depthPass);
            sg_apply_pipeline (depthPipeline_[hasText]);
            sg_apply_bindings (&bindings);
            sg_apply_uniforms (0, &uniformRange);
            sg_draw (0, 3, 1);
            sg_end_pass();
            sg_commit();
            // A queue fence completes every pass before any table owner can be
            // released or a successful frame published.
            id<MTLCommandQueue> queue = (__bridge id<MTLCommandQueue>) sg_mtl_command_queue();
            if (queue == nil || queue.device != gMetalDevice)
                return fail ("Metal native SDF submission queue owner changed");
            id<MTLCommandBuffer> completion = [queue commandBuffer];
            if (completion == nil)
                return fail ("Metal native SDF completion allocation failed");
            [completion commit];
            [completion waitUntilCompleted];
            if (completion.status != MTLCommandBufferStatusCompleted)
                return fail ("Metal native SDF submission did not complete");

            result.rendered = true;
            result.frame = std::move (frame);
            return result;
        }
        }
    }

private:
    bool ensurePipelineUnlocked (bool text, std::string& error) const
    {
        const auto device = reinterpret_cast<std::uintptr_t> ((__bridge void*) gMetalDevice);
        if (pipelineDevice_ != device)
        {
            // Handles belong to the previous Sokol device and are no longer
            // reusable in this device's resource pools.
            shader_ = {}; pipeline_ = {}; depthShader_ = {}; depthPipeline_ = {};
            primaryShader_ = {}; primaryPipeline_ = {};
            pipelineDevice_ = device;
        }
        if (resourceValid (sg_query_shader_state (shader_[text]))
            && resourceValid (sg_query_pipeline_state (pipeline_[text]))
            && resourceValid (sg_query_shader_state (depthShader_[text]))
            && resourceValid (sg_query_pipeline_state (depthPipeline_[text]))
            && (!text || (resourceValid (sg_query_shader_state (primaryShader_))
                && resourceValid (sg_query_pipeline_state (primaryPipeline_)))))
            return true;

        sg_shader_desc shaderDesc = {};
        shaderDesc.vertex_func.source = kSdfVertexShader;
        const std::string fragmentSource = text
            ? std::string ("#define SDF_TEXT_TABLES 1\n") + kSdfFragmentShader
            : std::string (kSdfFragmentShader);
        shaderDesc.fragment_func.source = fragmentSource.c_str();
        shaderDesc.uniform_blocks[0].stage = SG_SHADERSTAGE_FRAGMENT;
        shaderDesc.uniform_blocks[0].size = sizeof (SdfUniforms);
        shaderDesc.uniform_blocks[0].msl_buffer_n = 0;
        if (text)
            for (int table = 0; table < 7; ++table)
            {
                shaderDesc.views[table].storage_buffer.stage = SG_SHADERSTAGE_FRAGMENT;
                shaderDesc.views[table].storage_buffer.readonly = true;
                shaderDesc.views[table].storage_buffer.msl_buffer_n = 8 + table;
            }
        if (text) {
            shaderDesc.views[7].texture.stage = SG_SHADERSTAGE_FRAGMENT;
            shaderDesc.views[7].texture.image_type = SG_IMAGETYPE_2D;
            shaderDesc.views[7].texture.sample_type = SG_IMAGESAMPLETYPE_UNFILTERABLE_FLOAT;
            shaderDesc.views[7].texture.msl_texture_n = 0;
        }
        shaderDesc.label = "arbit-metal-sdf-scene-shader";
        shader_[text] = sg_make_shader (&shaderDesc);

        sg_pipeline_desc pipelineDesc = {};
        pipelineDesc.shader = shader_[text];
        pipelineDesc.colors[0].pixel_format = SG_PIXELFORMAT_RGBA16F;
        pipelineDesc.colors[1].pixel_format = SG_PIXELFORMAT_RGBA16F;
        pipelineDesc.depth.pixel_format = SG_PIXELFORMAT_NONE;
        pipelineDesc.primitive_type = SG_PRIMITIVETYPE_TRIANGLES;
        pipelineDesc.sample_count = 1;
        pipelineDesc.label = "arbit-metal-sdf-scene-pipeline";
        pipeline_[text] = sg_make_pipeline (&pipelineDesc);
        shaderDesc.fragment_func.entry = "_depth";
        shaderDesc.label = "arbit-metal-sdf-depth-shader";
        depthShader_[text] = sg_make_shader (&shaderDesc);
        pipelineDesc.shader = depthShader_[text];
        pipelineDesc.colors[0].pixel_format = SG_PIXELFORMAT_R32F;
        pipelineDesc.colors[1].pixel_format = SG_PIXELFORMAT_NONE;
        pipelineDesc.label = "arbit-metal-sdf-depth-pipeline";
        depthPipeline_[text] = sg_make_pipeline (&pipelineDesc);
        if (text) {
            shaderDesc.fragment_func.entry = "_primary";
            shaderDesc.views[7] = {};
            shaderDesc.label = "arbit-metal-sdf-primary-shader";
            primaryShader_ = sg_make_shader (&shaderDesc);
            pipelineDesc.shader = primaryShader_;
            pipelineDesc.colors[0].pixel_format = SG_PIXELFORMAT_RG32F;
            pipelineDesc.label = "arbit-metal-sdf-primary-pipeline";
            primaryPipeline_ = sg_make_pipeline (&pipelineDesc);
        }
        if (! resourceValid (sg_query_shader_state (shader_[text]))
            || ! resourceValid (sg_query_pipeline_state (pipeline_[text]))
            || ! resourceValid (sg_query_shader_state (depthShader_[text]))
            || ! resourceValid (sg_query_pipeline_state (depthPipeline_[text]))
            || (text && (! resourceValid (sg_query_shader_state (primaryShader_))
                || ! resourceValid (sg_query_pipeline_state (primaryPipeline_)))))
        {
            if (pipeline_[text].id != 0) sg_destroy_pipeline (pipeline_[text]);
            if (shader_[text].id != 0) sg_destroy_shader (shader_[text]);
            if (depthPipeline_[text].id != 0) sg_destroy_pipeline (depthPipeline_[text]);
            if (depthShader_[text].id != 0) sg_destroy_shader (depthShader_[text]);
            pipeline_[text] = {};
            shader_[text] = {};
            depthPipeline_[text] = {};
            depthShader_[text] = {};
            if (text) {
                if (primaryPipeline_.id != 0) sg_destroy_pipeline (primaryPipeline_);
                if (primaryShader_.id != 0) sg_destroy_shader (primaryShader_);
                primaryPipeline_ = {}; primaryShader_ = {};
            }
            error = "Metal native SDF shader or pipeline creation failed";
            return false;
        }
        return true;
    }

    static NativeSdfExecutionCapabilities capabilitiesUnlocked()
    {
        NativeSdfExecutionCapabilities result;
        if (! ensureSokolMetal())
        {
            result.error = gSokolError;
            return result;
        }
        result.backend = "metal";
        result.reusesPrimaryTrace = true;
        result.device = deviceName (gMetalDevice);
        if (sg_query_backend() != SG_BACKEND_METAL_MACOS)
        {
            result.error = "sokol_gfx did not select the macOS Metal backend";
            return result;
        }
        const auto nativeLimits = sg_query_limits();
        const auto format = sg_query_pixelformat (SG_PIXELFORMAT_RGBA16F);
        if (! format.render || ! format.sample || nativeLimits.max_image_size_2d <= 0)
        {
            result.error = "Metal does not support the native SDF RGBA16F target";
            return result;
        }
        result.available = true;
        for (std::uint32_t operation = static_cast<std::uint32_t> (
                 videowire::SdfOperation::sphere);
             operation <= static_cast<std::uint32_t> (videowire::SdfOperation::domainWarp);
             ++operation)
            result.supportedOperations[operation] = true;
        result.supportedOutputs[static_cast<std::size_t> (
            NativeSdfOutput::color)] = true;
        result.supportedOutputs[static_cast<std::size_t> (
            NativeSdfOutput::depth)] = true;
        result.supportedOutputs[static_cast<std::size_t> (
            NativeSdfOutput::normal)] = true;
        result.supportedOutputs[static_cast<std::size_t> (
            NativeSdfOutput::materialId)] = true;
        result.supportedOutputs[static_cast<std::size_t> (
            NativeSdfOutput::curvature)] = true;
        result.supportedOutputs[static_cast<std::size_t> (
            NativeSdfOutput::ambientOcclusion)] = true;
        result.supportedOutputs[static_cast<std::size_t> (
            NativeSdfOutput::softShadow)] = true;
        result.supportedOutputs[static_cast<std::size_t> (
            NativeSdfOutput::edgeDistance)] = true;
        result.maxOperations = kNativeSdfMaximumRecords;
        result.maxDepth = kNativeSdfMaximumDepth;
        result.maxExtent = static_cast<std::uint32_t> (
            std::min (nativeLimits.max_image_size_2d, 4096));
        result.maxPixels = std::min (
            static_cast<std::uint64_t> (result.maxExtent) * result.maxExtent,
            4096ull * 4096ull);
        result.maxSteps = 512;
        result.minEpsilon = 0.000001;
        result.maxEpsilon = 0.1;
        result.maxDistance = 1000.0;
        return result;
    }

    mutable std::uintptr_t pipelineDevice_ = 0;
    mutable std::array<sg_shader, 2> shader_ {};
    mutable std::array<sg_pipeline, 2> pipeline_ {};
    mutable std::array<sg_shader, 2> depthShader_ {};
    mutable std::array<sg_pipeline, 2> depthPipeline_ {};
    mutable sg_shader primaryShader_ {};
    mutable sg_pipeline primaryPipeline_ {};
};

std::string metalSelectedRoughShader()
{
    using namespace arbitgpu;
    const std::string fragment=kFixtureFragmentShader;
    std::string source=fragment.substr(0,fragment.find("struct VertexOut"));
    source+=R"metal(
constant float pi=3.14159265358979323846f;
float3 rotateQuaternion(float4 q,float3 v) {return v+2.0f*cross(q.xyz,cross(q.xyz,v)+q.w*v);}
struct Selection {float4 ray,position,normal;uint4 ids;int4 state;};
struct Result {float4 color,terminal,masked,tail;uint4 ids,work;};
)metal";
    source+=opaquevisibility::metalShader()+analyticsky::shader(true)+environmentimage::shader(true)
        +smoothglass::queryShader(true)+smoothglass::transportShader(true,true,true);
    const auto direct=fragment.find("float3 baseSurfaceUnit(");
    source+=fragment.substr(direct,fragment.find("fragment FragmentOut _main",direct)-direct);
    source+=R"metal(
float2 selectedPixel(uint index,uint4 tile) {return float2(tile.xy)+float2(index%tile.z,index/tile.z)+0.5f;}
kernel void selectedPrimary(constant Uniforms& u [[buffer(0)]],device Selection* saved [[buffer(1)]],
    device atomic_uint* executed [[buffer(3)]],constant uint* rectangle [[buffer(4)]],
    texture2d<float> glassTexture [[texture(1)]],uint index [[thread_position_in_grid]]) {
    uint4 tile=uint4(rectangle[0],rectangle[1],rectangle[2],rectangle[3]);
    if(index>=tile.z*tile.w)return;
    float2 pixel=selectedPixel(index,tile);
    float3 ray=normalize(rotateQuaternion(u.cameraRotation,float3(
        (2.0f*pixel.x/u.motionViewport.x-1.0f)*u.projection.x*u.projection.y,
        (1.0f-2.0f*pixel.y/u.motionViewport.y)*u.projection.x,-1.0f)));
    atomic_fetch_add_explicit(executed+index*4,1u,memory_order_relaxed);
    GlassClosestHit hit=glassSceneClosestHit(u.cameraTranslation.xyz,ray,0.0f,3.402823e38f,u.glassControl,glassTexture);
    atomic_fetch_add_explicit(executed+index*4+2,1u,memory_order_relaxed);
    saved[index].ray=float4(ray,0.0f);saved[index].position=float4(hit.position,hit.distance);
    saved[index].normal=float4(hit.outwardNormal,hit.entering?1.0f:0.0f);
    saved[index].ids=uint4(hit.objectId,hit.materialId,hit.instanceId,hit.triangleId);
    saved[index].state=int4(hit.status,1,0,0);
}
kernel void selectedTransport(constant Uniforms& u [[buffer(0)]],device const Selection* saved [[buffer(1)]],
    device Result* results [[buffer(2)]],device atomic_uint* executed [[buffer(3)]],constant uint* rectangle [[buffer(4)]],
    texture2d<float> opaqueTexture [[texture(0)]],texture2d<float> glassTexture [[texture(1)]],
    texture2d<float> environmentTexture [[texture(2)]],uint invocation [[thread_position_in_grid]]) {
    uint4 tile=uint4(rectangle[0],rectangle[1],rectangle[2],rectangle[3]);
    uint index=invocation+rectangle[4];
    if(index>=tile.z*tile.w)return;
    Selection selection=saved[index];
    Result result;result.color=float4(0.0f);result.terminal=float4(0.0f);result.masked=float4(0.0f);result.tail=float4(0.0f);
    result.ids=selection.ids;
    uint volume=uint(u.glassTransport.z)|(uint(u.glassTransport.w)<<16u);
    if(selection.state.x==1 && selection.ids.x==volume) {
        GlassClosestHit first;first.status=selection.state.x;first.distance=selection.position.w;
        first.position=selection.position.xyz;first.outwardNormal=selection.normal.xyz;first.entering=selection.normal.w==1.0f;
        first.objectId=selection.ids.x;first.materialId=selection.ids.y;first.instanceId=selection.ids.z;first.triangleId=selection.ids.w;
        float3 terminal,masked,tail;int status,queries,events;
        atomic_fetch_add_explicit(executed+index*4+1,1u,memory_order_relaxed);
        float3 color=roughGlassTransportV2Selected(u.cameraTranslation.xyz,selection.ray.xyz,first,u.materialParams.y,false,
            glassCameraPixelKey(selectedPixel(index,tile)),terminal,masked,tail,status,queries,events,u,
            opaqueTexture,glassTexture,environmentTexture);
        result.color=float4(color,float(status));result.terminal=float4(terminal,float(status));
        result.masked=float4(masked,float(queries));result.tail=float4(tail,float(events));
        if(queries>1)atomic_fetch_add_explicit(executed+index*4+2,uint(queries-1),memory_order_relaxed);
        if(events>0)atomic_fetch_add_explicit(executed+index*4+3,uint(events),memory_order_relaxed);
    }
    result.work=uint4(atomic_load_explicit(executed+index*4,memory_order_relaxed),
        atomic_load_explicit(executed+index*4+1,memory_order_relaxed),
        atomic_load_explicit(executed+index*4+2,memory_order_relaxed),
        atomic_load_explicit(executed+index*4+3,memory_order_relaxed));
    results[index]=result;
}
)metal";
    return source;
}

std::string metalSelectedRoughResolveShader()
{
    const std::string fragment=kFixtureFragmentShader;
    return fragment.substr(0,fragment.find("struct VertexOut"))+R"metal(
fragment float4 selectedResolve(float4 position [[position]],constant Uniforms& u [[buffer(0)]],
    texture2d<float> base [[texture(0)]],texture2d<float> selected [[texture(1)]],
    texture2d<uint> objectIds [[texture(2)]],texture2d<uint> materialIds [[texture(3)]]) {
    uint2 pixel=uint2(position.xy);
    float4 original=base.read(pixel);
    if(u.imageOutput.x!=0.0f)return original;
    int2 local=int2(pixel)-int2(u.roughCameraControl.yz);
    if(any(local<0)||local.x>=int(u.roughCameraControl.w)||local.y>=int(u.vertexTime.w))return original;
    uint2 at=uint2(local.x*3,local.y);
    float4 color=selected.read(at),ids=selected.read(at+uint2(1,0));
    uint object=uint(ids.x)|(uint(ids.y)<<16u),material=uint(ids.z)|(uint(ids.w)<<16u);
    uint volume=uint(u.glassTransport.z)|(uint(u.glassTransport.w)<<16u);
    if(object!=volume||object!=objectIds.read(pixel).r||material!=materialIds.read(pixel).r)return original;
    return float4(color.rgb,1.0f);
}
)metal";
}

id<MTLTexture> metalRoughTexture(sg_image image)
{
    const auto native=sg_mtl_query_image_info(image);
    return native.active_slot>=0&&native.active_slot<SG_NUM_INFLIGHT_FRAMES
        ?(__bridge id<MTLTexture>)native.tex[native.active_slot]:nil;
}

bool prepareMetalSelectedRoughCamera(MetalFixtureSceneFrame& frame,std::string& error)
{
    using namespace arbitgpu;
    if(!frame.roughTileSchedule || !smoothglass::multipleScatterCamera(frame.staticResources->smoothGlass)) {
        error="Metal selected camera requires its admitted V2 schedule";return false;
    }
    frame.selectedRough=std::make_unique<MetalSelectedRoughCamera>();
    auto& state=*frame.selectedRough;state.schedule=frame.roughTileSchedule;
    state.queue=(__bridge id<MTLCommandQueue>)sg_mtl_command_queue();
#if ! __has_feature(objc_arc)
    [state.queue retain];
#endif
    if(state.queue==nil ||state.queue.device!=gMetalDevice) {error="Metal selected camera owning queue is unavailable";return false;}
    const auto capacity=state.schedule->maximumTilePixels();
    const auto scratch=state.schedule->tiles().front();
    const auto limits=sg_query_limits();const auto format=sg_query_pixelformat(SG_PIXELFORMAT_RGBA32F);
    if(!format.sample || limits.max_image_size_2d<int(scratch.width*3) || limits.max_image_size_2d<int(scratch.height)
        || capacity*sizeof(MetalSelectedRoughCamera::Result)>gMetalDevice.maxBufferLength
        || sizeof(FixtureUniforms)>gMetalDevice.maxBufferLength) {
        error="Metal selected camera exceeds native texture or buffer capabilities";return false;
    }
    // This upper bound, including full-frame nonfeedback Color, was admitted
    // before any frame allocations. Reject actual Metal alignment above it.
    state.nativeReservation=capacity*(sizeof(MetalSelectedRoughCamera::Selection)+sizeof(MetalSelectedRoughCamera::Result)
        +sizeof(MetalSelectedRoughCamera::Work)+48)+sizeof(FixtureUniforms)+5*4095;
    state.uniforms=[gMetalDevice newBufferWithLength:sizeof(FixtureUniforms) options:MTLResourceStorageModeShared];
    state.selection=[gMetalDevice newBufferWithLength:capacity*sizeof(MetalSelectedRoughCamera::Selection) options:MTLResourceStorageModeShared];
    state.result=[gMetalDevice newBufferWithLength:capacity*sizeof(MetalSelectedRoughCamera::Result) options:MTLResourceStorageModeShared];
    state.work=[gMetalDevice newBufferWithLength:capacity*sizeof(MetalSelectedRoughCamera::Work) options:MTLResourceStorageModeShared];
    std::uint64_t actual=0;
    for(id<MTLBuffer> buffer:{state.uniforms,state.selection,state.result,state.work}) {
        if(buffer==nil||buffer.device!=gMetalDevice||buffer.contents==nullptr||buffer.length>gMetalDevice.maxBufferLength
            ||buffer.allocatedSize>state.nativeReservation-actual) {error="Metal selected camera buffer allocation exceeds admitted storage";return false;}
        actual+=buffer.allocatedSize;
    }
    state.uniformsCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,
        arbitgpu::residency::nominalBufferBytes(sizeof(FixtureUniforms)));
    state.selectionCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,
        arbitgpu::residency::nominalBufferBytes(capacity*sizeof(MetalSelectedRoughCamera::Selection)));
    state.resultCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,
        arbitgpu::residency::nominalBufferBytes(capacity*sizeof(MetalSelectedRoughCamera::Result)));
    state.workCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,
        arbitgpu::residency::nominalBufferBytes(capacity*sizeof(MetalSelectedRoughCamera::Work)));
    const auto source=metalSelectedRoughShader();NSError* nativeError=nil;
    state.library=[gMetalDevice newLibraryWithSource:[NSString stringWithUTF8String:source.c_str()] options:nil error:&nativeError];
    if(state.library==nil) {error="Metal selected camera shader compilation failed: "+std::string(nativeError.localizedDescription.UTF8String?:"unknown error");return false;}
    const auto pipelineFor=[&](NSString* name)->id<MTLComputePipelineState> {
        id<MTLFunction> function=[state.library newFunctionWithName:name];
        id<MTLComputePipelineState> pipeline=function!=nil
            ?[gMetalDevice newComputePipelineStateWithFunction:function error:&nativeError]:nil;
#if ! __has_feature(objc_arc)
        [function release];
#endif
        return pipeline;
    };
    state.select=pipelineFor(@"selectedPrimary");state.transport=pipelineFor(@"selectedTransport");
    if(state.select==nil ||state.transport==nil
        ||state.select.maxTotalThreadsPerThreadgroup<1||state.transport.maxTotalThreadsPerThreadgroup<1) {
        error="Metal selected camera compute pipeline unavailable";return false;
    }
    sg_image_desc shared={};shared.width=scratch.width*3;shared.height=scratch.height;
    shared.pixel_format=SG_PIXELFORMAT_RGBA32F;shared.usage.dynamic_update=true;shared.sample_count=1;
    shared.label="arbit-metal-selected-camera-shared-result";state.sharedImage=sg_make_image(&shared);
    if(resourceValid(sg_query_image_state(state.sharedImage)))
        state.sharedImageCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,
            arbitgpu::residency::nominalTextureBytes(static_cast<std::uint64_t>(shared.width),static_cast<std::uint64_t>(shared.height),1,1,16,1));
    sg_view_desc view={};view.texture.image=state.sharedImage;state.sharedView=sg_make_view(&view);
    sg_image_desc resolved={};resolved.width=frame.width_;resolved.height=frame.height_;
    resolved.pixel_format=frame.linearColor?SG_PIXELFORMAT_RGBA16F:SG_PIXELFORMAT_BGRA8;
    resolved.usage.color_attachment=true;resolved.sample_count=1;resolved.label="arbit-metal-selected-camera-nonfeedback-color";
    state.resolvedImage=sg_make_image(&resolved);view={};view.color_attachment.image=state.resolvedImage;
    if(resourceValid(sg_query_image_state(state.resolvedImage)))
        state.resolvedImageCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,
            arbitgpu::residency::nominalTextureBytes(static_cast<std::uint64_t>(resolved.width),static_cast<std::uint64_t>(resolved.height),1,1,frame.linearColor?8u:4u,1));
    state.resolvedAttachment=sg_make_view(&view);view={};view.texture.image=state.resolvedImage;state.resolvedView=sg_make_view(&view);
    const auto resultTexture=metalRoughTexture(state.sharedImage),resolvedTexture=metalRoughTexture(state.resolvedImage);
    const auto imageReserve=capacity*48*SG_NUM_INFLIGHT_FRAMES+state.schedule->pixels()*(frame.linearColor?8:4)+4*4095;
    std::uint64_t imageActual=0;
    const auto sharedInfo=sg_mtl_query_image_info(state.sharedImage);
    for(unsigned slot=0;slot<SG_NUM_INFLIGHT_FRAMES;++slot) {
        id<MTLTexture> texture=(__bridge id<MTLTexture>)sharedInfo.tex[slot];
        if(texture!=nil) {
            if(texture.device!=gMetalDevice ||texture.allocatedSize>imageReserve-imageActual) {
                error="Metal selected camera result texture exceeds admitted native allocation";return false;
            }
            imageActual+=texture.allocatedSize;
        }
    }
    if(!resourceValid(sg_query_image_state(state.sharedImage))||!resourceValid(sg_query_view_state(state.sharedView))
        ||!resourceValid(sg_query_image_state(state.resolvedImage))||!resourceValid(sg_query_view_state(state.resolvedAttachment))
        ||!resourceValid(sg_query_view_state(state.resolvedView))||resultTexture==nil||resolvedTexture==nil
        ||resolvedTexture.device!=gMetalDevice||resolvedTexture.allocatedSize>imageReserve-imageActual) {
        error="Metal selected camera result or separate Color allocation failed";return false;
    }
    const auto resolveSource=metalSelectedRoughResolveShader();
    sg_shader_desc shader={};shader.vertex_func.source=kSdfVertexShader;
    shader.fragment_func.source=resolveSource.c_str();shader.fragment_func.entry="selectedResolve";
    shader.uniform_blocks[0].stage=SG_SHADERSTAGE_FRAGMENT;shader.uniform_blocks[0].size=sizeof(FixtureUniforms);shader.uniform_blocks[0].msl_buffer_n=0;
    for(unsigned slot=0;slot<4;++slot) {
        shader.views[slot].texture.stage=SG_SHADERSTAGE_FRAGMENT;shader.views[slot].texture.image_type=SG_IMAGETYPE_2D;
        shader.views[slot].texture.sample_type=slot<2?SG_IMAGESAMPLETYPE_FLOAT:SG_IMAGESAMPLETYPE_UINT;
        shader.views[slot].texture.msl_texture_n=slot;
    }
    state.resolveShader=sg_make_shader(&shader);
    sg_pipeline_desc pipeline={};pipeline.shader=state.resolveShader;pipeline.depth.pixel_format=SG_PIXELFORMAT_NONE;
    pipeline.colors[0].pixel_format=resolved.pixel_format;pipeline.primitive_type=SG_PRIMITIVETYPE_TRIANGLES;pipeline.sample_count=1;
    state.resolvePipeline=sg_make_pipeline(&pipeline);
    if(!resourceValid(sg_query_shader_state(state.resolveShader))||!resourceValid(sg_query_pipeline_state(state.resolvePipeline))) {
        error="Metal selected camera fullscreen Color consumer unavailable: "+lastSokolLog();return false;
    }
    state.selections.resize(capacity);state.results.resize(capacity);state.nativeWork.resize(capacity);state.upload.resize(capacity*3);
    if(state.selections.capacity()>capacity||state.results.capacity()>capacity||state.nativeWork.capacity()>capacity
        ||state.upload.capacity()>capacity*3) {
        error="Metal selected camera retained CPU capacity exceeds admission";return false;
    }
    return true;
}

bool metalSelectedRoughRange(const std::vector<MetalSelectedRoughCamera::Selection>& selections,
    std::uint32_t volume,std::size_t begin,std::uint64_t completedWork,std::size_t& end,std::string& error)
{
    using namespace arbitgpu;
    end=begin;
    if(completedWork>smoothglass::kMaximumCameraMicroWork) {
        error="Metal selected camera whole-frame executed work exceeds its bound";return false;
    }
    const auto reserve=(smoothglass::kMaximumCameraMicroWork-completedWork)/smoothglass::kMaximumCameraPixelMicroWork;
    std::uint64_t starts=0;
    while(end<selections.size()) {
        const bool glass=selections[end].state[0]==1&&selections[end].ids[0]==volume;
        if(glass&&starts==reserve)break;
        starts+=glass?1u:0u;++end;
    }
    if(end==begin) {
        error="Metal selected camera whole-frame work reserve exhausted before transport";return false;
    }
    return true;
}

bool dispatchMetalSelectedRoughCamera(MetalFixtureSceneFrame& frame,const arbitgpu::roughglasstiles::Tile& tile,
    const FixtureUniforms& uniforms,std::uint64_t completedWork,std::string& error)
{
    using namespace arbitgpu;
    auto& state=*frame.selectedRough;state.completed=false;
    const auto& key=state.schedule->key();
    id<MTLCommandQueue> queue=(__bridge id<MTLCommandQueue>)sg_mtl_command_queue();
    const auto opaque=metalRoughTexture(frame.opaqueImage),glass=metalRoughTexture(frame.glassImage);
    const auto environment=metalRoughTexture(frame.staticResources->environmentTexture.id?frame.staticResources->environmentTexture:frame.opaqueImage);
    if(state.schedule!=frame.roughTileSchedule||!roughglasstiles::sameKey(key,frame.roughTileSchedule->key())
        ||key.owner.get()!=frame.staticResources.get()||key.runtime!=frame.roughReceiptInputs||key.program!=frame.roughReceiptProgram
        ||key.rendererGeneration!=frame.rendererGeneration_||tile.index>=state.schedule->tiles().size()
        ||!roughglasstiles::sameTile(tile,state.schedule->tiles()[tile.index])||queue!=state.queue
        ||queue.device!=gMetalDevice||opaque==nil||glass==nil||environment==nil
        ||opaque.device!=gMetalDevice||glass.device!=gMetalDevice||environment.device!=gMetalDevice) {
        error="Metal selected camera query, queue or immutable owner changed";return false;
    }
    FixtureUniforms expectedCamera={};storeQuaternion(expectedCamera.cameraRotation,key.camera.transform.rotation);
    storeVec3(expectedCamera.cameraTranslation,key.camera.transform.translation);
    const auto tangent=std::tan(key.camera.verticalFovRadians*0.5f);
    if(std::memcmp(uniforms.cameraRotation,expectedCamera.cameraRotation,sizeof(uniforms.cameraRotation))!=0
        ||std::memcmp(uniforms.cameraTranslation,expectedCamera.cameraTranslation,3*sizeof(float))!=0
        ||uniforms.projection[0]!=tangent||uniforms.projection[1]!=float(key.width)/float(key.height)
        ||uniforms.projection[2]!=key.camera.nearPlane||uniforms.projection[3]!=key.camera.farPlane) {
        error="Metal selected camera uniforms differ from the immutable camera key";return false;
    }
    std::memcpy(state.uniforms.contents,&uniforms,sizeof(uniforms));
    std::memset(state.work.contents,0,tile.pixels()*sizeof(MetalSelectedRoughCamera::Work));
    const std::array<std::uint32_t,8> rectangle={tile.x,tile.y,tile.width,tile.height,0,0,0,0};
    // Selection completes before deciding which disjoint transport ranges can
    // reserve every selected start against the remaining whole-frame budget.
    const auto dispatch=[&](id<MTLComputePipelineState> pipeline,std::uint32_t begin,std::uint32_t count)->id<MTLCommandBuffer> {
        @autoreleasepool {
            auto range=rectangle;range[4]=begin;
            id<MTLCommandBuffer> command=[queue commandBuffer];
            id<MTLComputeCommandEncoder> encoder=command!=nil?[command computeCommandEncoder]:nil;
            if(encoder==nil) {error="Metal selected camera native command or encoder unavailable";return nil;}
            [encoder setComputePipelineState:pipeline];[encoder setBuffer:state.uniforms offset:0 atIndex:0];
            [encoder setBuffer:state.selection offset:0 atIndex:1];[encoder setBuffer:state.result offset:0 atIndex:2];
            [encoder setBuffer:state.work offset:0 atIndex:3];[encoder setBytes:range.data() length:sizeof(range) atIndex:4];
            [encoder setTexture:opaque atIndex:0];[encoder setTexture:glass atIndex:1];[encoder setTexture:environment atIndex:2];
            [encoder dispatchThreads:MTLSizeMake(count,1,1) threadsPerThreadgroup:MTLSizeMake(1,1,1)];
            [encoder endEncoding];[command commit];[command waitUntilCompleted];
            if(command.status!=MTLCommandBufferStatusCompleted) {error="Metal selected camera native work did not complete";return nil;}
#if ! __has_feature(objc_arc)
            [state.completedCommand release];[command retain];
#endif
            state.completedCommand=command;
            return command;
        }
    };
    id<MTLCommandBuffer> command=dispatch(state.select,0,std::uint32_t(tile.pixels()));
    if(command==nil)return false;
    state.selections.resize(tile.pixels());state.results.resize(tile.pixels());state.nativeWork.resize(tile.pixels());state.upload.resize(tile.pixels()*3);
    std::memcpy(state.selections.data(),state.selection.contents,tile.pixels()*sizeof(MetalSelectedRoughCamera::Selection));
    std::memcpy(state.nativeWork.data(),state.work.contents,tile.pixels()*sizeof(MetalSelectedRoughCamera::Work));
    for(std::size_t pixel=0;pixel<tile.pixels();++pixel) {
        const auto& selection=state.selections[pixel];const auto& work=state.nativeWork[pixel];
        if(selection.state[0]<0||selection.state[0]>1||selection.state[1]!=1
            ||work.selections!=1||work.starts!=0||work.queries!=1||work.events!=0) {
            error="Metal selected camera closest-hit selection did not complete";return false;
        }
    }
    std::size_t begin=0;
    while(begin<state.selections.size()) {
        std::size_t end=begin;
        if(!metalSelectedRoughRange(state.selections,state.schedule->prepared().object.value,begin,completedWork,end,error))return false;
        // Reserve the unchanged worst case before execution. Charge only the
        // fenced native Work events before admitting the next range or tile.
        command=dispatch(state.transport,std::uint32_t(begin),std::uint32_t(end-begin));
        if(command==nil)return false;
        std::memcpy(state.results.data()+begin,static_cast<const MetalSelectedRoughCamera::Result*>(state.result.contents)+begin,
            (end-begin)*sizeof(MetalSelectedRoughCamera::Result));
        std::memcpy(state.nativeWork.data()+begin,static_cast<const MetalSelectedRoughCamera::Work*>(state.work.contents)+begin,
            (end-begin)*sizeof(MetalSelectedRoughCamera::Work));
        for(std::size_t pixel=begin;pixel<end;++pixel) {
            const auto& selection=state.selections[pixel];const auto& result=state.results[pixel];const auto& work=state.nativeWork[pixel];
            const bool glass=selection.state[0]==1&&selection.ids[0]==state.schedule->prepared().object.value;
            if(result.ids!=selection.ids||std::memcmp(&work,result.work.data(),sizeof(work))!=0
                ||work.selections!=1||work.starts!=(glass?1u:0u)||work.queries<1||work.queries>smoothglass::kMaximumRoughClosestHitQueries
                ||work.events>smoothglass::kMaximumCameraMicroEvents
                ||(glass&&(result.color[3]!=smoothglass::kMultipleScatterCameraComplete||work.queries!=result.masked[3]||work.events!=result.tail[3]))
                ||(!glass&&(work.queries!=1||work.events!=0))) {
                error="Metal selected camera native invocation did not complete within its work reserve";return false;
            }
            const auto charge=std::uint64_t(work.events)*smoothglass::kCameraMicroWorkPerEvent;
            if(charge>smoothglass::kMaximumCameraMicroWork-completedWork) {
                error="Metal selected camera native executed work exceeded its admitted reserve";return false;
            }
            completedWork+=charge;
        }
        begin=end;
    }
    NativeRawPassPixels objects,materials;
    if(!frame.readTextureRegionOwned(frame.rawImages[4],NativeTexturePixelFormat::R32Uint,frame.width_,frame.height_,tile.x,tile.y,tile.width,tile.height,objects,error)
        ||!frame.readTextureRegionOwned(frame.rawImages[3],NativeTexturePixelFormat::R32Uint,frame.width_,frame.height_,tile.x,tile.y,tile.width,tile.height,materials,error))return false;
    for(auto& receipt:state.receipts)receipt={NativeTexturePixelFormat::Rgba32Float,tile.width,tile.height,std::vector<std::uint8_t>(tile.pixels()*16)};
    for(std::size_t index=0;index<tile.pixels();++index) {
        const auto& selection=state.selections[index];const auto& result=state.results[index];const auto& work=state.nativeWork[index];
        const bool selected=selection.state[0]==1&&selection.ids[0]==state.schedule->prepared().object.value;
        std::uint32_t object=0,material=0;std::memcpy(&object,objects.bytes.data()+index*4,4);std::memcpy(&material,materials.bytes.data()+index*4,4);
        if(selection.state[0]<0||selection.state[0]>1||selection.state[1]!=1||result.ids!=selection.ids
            ||selection.ids[0]!=object||selection.ids[1]!=material||std::memcmp(&work,result.work.data(),sizeof(work))!=0
            ||work.selections!=1||work.starts!=(selected?1u:0u)||work.queries<1||work.queries>smoothglass::kMaximumRoughClosestHitQueries
            ||work.events>smoothglass::kMaximumCameraMicroEvents
            ||(selected&&(result.color[3]!=smoothglass::kMultipleScatterCameraComplete||result.work[2]!=result.masked[3]||result.work[3]!=result.tail[3]))
            ||(!selected&&(work.queries!=1||work.events!=0))
            ||std::any_of(result.color.begin(),result.color.begin()+3,[](float value){return !std::isfinite(value)||std::abs(value)>65504.0f;})) {
            error="Metal selected camera saved primary, raster identity or actual work receipt is incomplete";return false;
        }
        std::memcpy(state.receipts[0].bytes.data()+index*16,result.terminal.data(),16);
        std::memcpy(state.receipts[1].bytes.data()+index*16,result.masked.data(),16);
        std::memcpy(state.receipts[2].bytes.data()+index*16,result.tail.data(),16);
        state.upload[index*3]=result.color;
        for(unsigned id=0;id<4;++id) {
            state.upload[index*3+1+id/2][(id%2)*2]=float(result.ids[id]&65535u);
            state.upload[index*3+1+id/2][(id%2)*2+1]=float(result.ids[id]>>16u);
        }
    }
    // Edge tiles keep the admitted scratch extent. Pad upload rows using the
    // retained capacity, never stretch tile-local rays or the completed result.
    const auto scratch=state.schedule->tiles().front();
    if(tile.width!=scratch.width||tile.height!=scratch.height) {
        state.upload.resize(state.schedule->maximumTilePixels()*3);
        for(std::uint32_t y=tile.height;y-->0;)
            std::memmove(state.upload.data()+y*scratch.width*3,state.upload.data()+y*tile.width*3,tile.width*3*sizeof(state.upload[0]));
    }
    sg_image_data data={};data.mip_levels[0]={state.upload.data(),state.upload.size()*sizeof(state.upload[0])};
    sg_update_image(state.sharedImage,&data);
    state.completedTile=tile;state.completed=true;
    return true;
}

bool resolveMetalSelectedRoughCamera(MetalFixtureSceneFrame& frame,const arbitgpu::roughglasstiles::Tile& tile,
    FixtureUniforms uniforms,std::string& error)
{
    auto& state=*frame.selectedRough;
    if(!state.completed||state.completedCommand.status!=MTLCommandBufferStatusCompleted
        ||!arbitgpu::roughglasstiles::sameTile(tile,state.completedTile)||state.resolvedImage.id==frame.colorImage.id) {
        error="Metal selected Color requires a completed result and separate target";return false;
    }
    uniforms.roughCameraControl[1]=float(tile.x);uniforms.roughCameraControl[2]=float(tile.y);uniforms.roughCameraControl[3]=float(tile.width);
    uniforms.vertexTime[3]=float(tile.height);
    sg_pass pass={};pass.attachments.colors[0]=state.resolvedAttachment;
    pass.action.colors[0].load_action=SG_LOADACTION_DONTCARE;pass.action.colors[0].store_action=SG_STOREACTION_STORE;
    pass.label="arbit-metal-selected-camera-fullscreen-color";sg_begin_pass(&pass);sg_apply_pipeline(state.resolvePipeline);
    sg_bindings bindings={};bindings.views[0]=frame.colorTextureView;bindings.views[1]=state.sharedView;
    bindings.views[2]=frame.rawTextureViews[4];bindings.views[3]=frame.rawTextureViews[3];sg_apply_bindings(&bindings);
    const sg_range range={&uniforms,sizeof(uniforms)};sg_apply_uniforms(0,&range);sg_draw(0,3,1);sg_end_pass();
    std::swap(frame.colorImage,state.resolvedImage);std::swap(frame.colorImageCharge,state.resolvedImageCharge);
    std::swap(frame.colorAttachmentView,state.resolvedAttachment);
    std::swap(frame.colorTextureView,state.resolvedView);
    return true;
}

bool copyMetalRoughTileDepth(MetalFixtureSceneFrame& frame,const arbitgpu::roughglasstiles::Tile& tile,
    std::string& error)
{
    const auto texture=[](sg_image image)->id<MTLTexture> {
        const auto info=sg_mtl_query_image_info(image);
        return info.active_slot>=0&&info.active_slot<SG_NUM_INFLIGHT_FRAMES
            ?(__bridge id<MTLTexture>)info.tex[info.active_slot]:nil;
    };
    id<MTLTexture> source=texture(frame.depthStencilImage),destination=texture(frame.roughTileDepthImage);
    id<MTLCommandQueue> queue=(__bridge id<MTLCommandQueue>)sg_mtl_command_queue();
    if(source==nil||destination==nil||queue==nil||source.device!=gMetalDevice||destination.device!=gMetalDevice
        ||queue.device!=gMetalDevice||source.width!=frame.width_||source.height!=frame.height_
        ||source.pixelFormat!=MTLPixelFormatDepth32Float_Stencil8||source.pixelFormat!=destination.pixelFormat
        ||source.sampleCount!=1||destination.sampleCount!=1
        ||tile.x>source.width||tile.width>source.width-tile.x||tile.y>source.height||tile.height>source.height-tile.y
        ||tile.width>destination.width||tile.height>destination.height) {
        error="Metal rough tile depth owner or rectangle changed";return false;
    }
    id<MTLCommandBuffer> command=[queue commandBuffer];
    id<MTLBlitCommandEncoder> blit=[command blitCommandEncoder];
    if(command==nil||blit==nil) {error="Metal rough tile depth copy encoder unavailable";return false;}
    [blit copyFromTexture:source sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(tile.x,tile.y,0)
        sourceSize:MTLSizeMake(tile.width,tile.height,1) toTexture:destination destinationSlice:0 destinationLevel:0
        destinationOrigin:MTLOriginMake(0,0,0)];
    [blit endEncoding];[command commit];[command waitUntilCompleted];
    if(command.status!=MTLCommandBufferStatusCompleted) {error="Metal rough tile depth copy did not complete";return false;}
    return true;
}

bool completeMetalRoughTile(MetalFixtureSceneFrame& frame,const arbitgpu::roughglasstiles::Tile& tile,
    arbitgpu::roughglasstiles::Completion& completion,std::string& error)
{
    using namespace arbitgpu;
    if(!frame.roughTileSchedule||!frame.roughReceiptSubmission||!frame.staticResources
        ||frame.roughReceiptInputs!=frame.roughTileSchedule->key().runtime
        ||frame.roughReceiptProgram!=frame.roughTileSchedule->key().program
        ||frame.staticResources.get()!=frame.roughTileSchedule->key().owner.get()
        ||frame.rendererGeneration_!=frame.roughTileSchedule->key().rendererGeneration
        ||frame.roughReceiptBytes!=frame.roughTileSchedule->scratchBytes()) {
        error="Metal rough tile completed readback has stale immutable ownership";return false;
    }
    const auto scratch=frame.roughTileSchedule->tiles().front();
    std::array<NativeRawPassPixels,3> receipts;NativeRawPassPixels object,material,normal,color;
    if(frame.selectedRough) {
        const auto& state=*frame.selectedRough;
        if(!state.completed ||state.completedCommand.status!=MTLCommandBufferStatusCompleted
            ||state.queue!=(__bridge id<MTLCommandQueue>)sg_mtl_command_queue()
            ||state.schedule!=frame.roughTileSchedule||!roughglasstiles::sameTile(tile,state.completedTile)
            ||state.nativeWork.size()!=tile.pixels()) {
            error="Metal selected tile lacks exact completed native Work ownership";return false;
        }
        receipts=state.receipts;
    } else for(unsigned i=0;i<3;++i)
        if(!frame.readTextureRegionOwned(frame.roughReceiptImages[i],NativeTexturePixelFormat::Rgba32Float,
            scratch.width,scratch.height,0,0,tile.width,tile.height,receipts[i],error)) return false;
    if(!frame.readTextureRegionOwned(frame.rawImages[4],NativeTexturePixelFormat::R32Uint,
            frame.width_,frame.height_,tile.x,tile.y,tile.width,tile.height,object,error)
        ||!frame.readTextureRegionOwned(frame.rawImages[3],NativeTexturePixelFormat::R32Uint,
            frame.width_,frame.height_,tile.x,tile.y,tile.width,tile.height,material,error)
        ||!frame.readTextureRegionOwned(frame.rawImages[0],NativeTexturePixelFormat::Rgba16Float,
            frame.width_,frame.height_,tile.x,tile.y,tile.width,tile.height,normal,error)
        ||!frame.readTextureRegionOwned(frame.colorImage,frame.linearColor?NativeTexturePixelFormat::Rgba16Float
            :NativeTexturePixelFormat::Bgra8Unorm,frame.width_,frame.height_,tile.x,tile.y,tile.width,tile.height,color,error)) return false;
    // Every tight local attachment came from this job's exact frame resources
    // through a completed command on the owning Sokol queue.
    roughglasstiles::NativeTileReceipt receipt;
    receipt.gpuCompleted=true;receipt.terminal=&receipts[0];receipt.masked=&receipts[1];receipt.tail=&receipts[2];
    receipt.objectIds=&object;receipt.materialIds=&material;receipt.normal=&normal;receipt.color=&color;
    if(frame.selectedRough)receipt.nativeWork=&frame.selectedRough->nativeWork;
    return completion.accept(frame.roughTileSchedule->key(),tile,receipt,error);
}

bool prepareMetalFixtureCameraAttachments(MetalFixtureSceneFrame& owner,bool linearColor,
    bool diffractionDraw,std::string& error)
{
    auto* frame=&owner;const auto width=owner.width_,height=owner.height_;
    const auto fail=[&](const char* message){error=message;return false;};
    sg_image_desc colorDesc = {};
    colorDesc.usage.color_attachment = true;
    colorDesc.width = static_cast<int> (width);
    colorDesc.height = static_cast<int> (height);
    frame->linearColor = linearColor;
    colorDesc.pixel_format = linearColor ? SG_PIXELFORMAT_RGBA16F : SG_PIXELFORMAT_BGRA8;
    colorDesc.sample_count = 1;
    colorDesc.label = "arbit-metal-fixture-color";
    frame->colorImage = sg_make_image (&colorDesc);
    sg_view_desc colorAttachmentDesc = {};
    colorAttachmentDesc.color_attachment.image = frame->colorImage;
    frame->colorAttachmentView = sg_make_view (&colorAttachmentDesc);
    sg_view_desc colorTextureDesc = {};
    colorTextureDesc.texture.image = frame->colorImage;
    frame->colorTextureView = sg_make_view (&colorTextureDesc);
    if (diffractionDraw)
    {
        const auto accumulationFormat = sg_query_pixelformat(SG_PIXELFORMAT_RGBA16F);
        if (!accumulationFormat.render || !accumulationFormat.sample)
            return fail("Metal does not support sampleable RGBA16F diffraction accumulation");
        sg_image_desc accumulationDesc = colorDesc;
        accumulationDesc.pixel_format = SG_PIXELFORMAT_RGBA16F;
        accumulationDesc.label = "arbit-metal-fixture-diffraction-accumulation";
        frame->diffractionAccumulationImage = sg_make_image(&accumulationDesc);
        sg_view_desc attachment = {};
        attachment.color_attachment.image = frame->diffractionAccumulationImage;
        frame->diffractionAccumulationAttachmentView = sg_make_view(&attachment);
        sg_view_desc texture = {};
        texture.texture.image = frame->diffractionAccumulationImage;
        frame->diffractionAccumulationTextureView = sg_make_view(&texture);
        if (!resourceValid(sg_query_image_state(frame->diffractionAccumulationImage))
            || !resourceValid(sg_query_view_state(frame->diffractionAccumulationAttachmentView))
            || !resourceValid(sg_query_view_state(frame->diffractionAccumulationTextureView)))
            return fail("Metal diffraction accumulation allocation failed");
        frame->diffractionAccumulationImageCharge = arbitgpu::residency::ResidencyCharge (
            arbitgpu::residency::BackingClass::fixtureScene, metalImageBytes (accumulationDesc));
    }

    const auto r32Capabilities = sg_query_pixelformat (SG_PIXELFORMAT_R32F);
    if (! r32Capabilities.render || ! r32Capabilities.sample
        || r32Capabilities.bytes_per_pixel != 4)
        return fail ("Metal does not support sampleable R32F fixture depth");
    sg_image_desc depthDesc = {};
    depthDesc.usage.color_attachment = true;
    depthDesc.width = static_cast<int> (width);
    depthDesc.height = static_cast<int> (height);
    depthDesc.pixel_format = SG_PIXELFORMAT_R32F;
    depthDesc.sample_count = 1;
    depthDesc.label = "arbit-metal-fixture-linear-depth";
    frame->depthImage = sg_make_image (&depthDesc);
    sg_view_desc depthViewDesc = {};
    depthViewDesc.color_attachment.image = frame->depthImage;
    frame->depthView = sg_make_view (&depthViewDesc);
    sg_view_desc depthTextureViewDesc = {};
    depthTextureViewDesc.texture.image = frame->depthImage;
    frame->depthTextureView = sg_make_view (&depthTextureViewDesc);
    const std::array<sg_pixel_format, 6> rawFormats { SG_PIXELFORMAT_RGBA16F,
        SG_PIXELFORMAT_RGBA16F, SG_PIXELFORMAT_R8, SG_PIXELFORMAT_R32UI, SG_PIXELFORMAT_R32UI, SG_PIXELFORMAT_RG16F };
    for (std::size_t i = 0; i < rawFormats.size(); ++i)
    {
        if (diffractionDraw && !sg_query_pixelformat(rawFormats[i]).sample)
            return fail("Metal diffraction raw pass is not sampleable");
        sg_image_desc rawDesc = depthDesc;
        rawDesc.pixel_format = rawFormats[i];
        rawDesc.label = "arbit-metal-fixture-raw-pass";
        frame->rawImages[i] = sg_make_image(&rawDesc);
        sg_view_desc attachment = {};
        attachment.color_attachment.image = frame->rawImages[i];
        frame->rawAttachmentViews[i] = sg_make_view(&attachment);
        sg_view_desc texture = {};
        texture.texture.image = frame->rawImages[i];
        frame->rawTextureViews[i] = sg_make_view(&texture);
        if (!resourceValid(sg_query_image_state(frame->rawImages[i]))
            || !resourceValid(sg_query_view_state(frame->rawAttachmentViews[i]))
            || !resourceValid(sg_query_view_state(frame->rawTextureViews[i])))
            return fail("Metal raw Render 3D pass allocation failed");
        frame->rawImageCharges[i] = arbitgpu::residency::ResidencyCharge (
            arbitgpu::residency::BackingClass::fixtureScene, metalImageBytes (rawDesc));
    }

    sg_image_desc depthStencilDesc = {};
    depthStencilDesc.usage.depth_stencil_attachment = true;
    depthStencilDesc.width = static_cast<int> (width);
    depthStencilDesc.height = static_cast<int> (height);
    depthStencilDesc.pixel_format = SG_PIXELFORMAT_DEPTH_STENCIL;
    depthStencilDesc.sample_count = 1;
    depthStencilDesc.label = "arbit-metal-fixture-depth-stencil";
    frame->depthStencilImage = sg_make_image (&depthStencilDesc);
    sg_view_desc depthStencilViewDesc = {};
    depthStencilViewDesc.depth_stencil_attachment.image = frame->depthStencilImage;
    frame->depthStencilView = sg_make_view (&depthStencilViewDesc);

    const bool resourcesOk =
        resourceValid (sg_query_image_state (frame->colorImage))
        && resourceValid (sg_query_view_state (frame->colorAttachmentView))
        && resourceValid (sg_query_view_state (frame->colorTextureView))
        && resourceValid (sg_query_image_state (frame->depthImage))
        && resourceValid (sg_query_view_state (frame->depthView))
        && resourceValid (sg_query_view_state (frame->depthTextureView))
        && resourceValid (sg_query_image_state (frame->depthStencilImage))
        && resourceValid (sg_query_view_state (frame->depthStencilView));
    if (! resourcesOk)
        return fail ("Metal fixture GPU resource creation failed");
    frame->colorImageCharge = arbitgpu::residency::ResidencyCharge (
        arbitgpu::residency::BackingClass::fixtureScene, metalImageBytes (colorDesc));
    frame->depthImageCharge = arbitgpu::residency::ResidencyCharge (
        arbitgpu::residency::BackingClass::fixtureScene, metalImageBytes (depthDesc));
    frame->depthStencilImageCharge = arbitgpu::residency::ResidencyCharge (
        arbitgpu::residency::BackingClass::fixtureScene, metalImageBytes (depthStencilDesc));

    error.clear();return true;
}

static bool metalRasterAdd(std::uint64_t& total,std::uint64_t value) {
    return renderpassoutput::detail::checkedAdd(total,value,total);
}
static bool metalRasterProduct(std::uint64_t a,std::uint64_t b,std::uint64_t& value) {
    return renderpassoutput::detail::checkedMultiply(a,b,value);
}
struct MetalRasterCaptureBudget final {std::uint64_t host=0,native=0,payload=0,sourceLimit=0,geometryBytes=0,geometryAllocation=0;};
static bool metalRasterCaptureBudget(const MetalFixtureSceneResources& resources,
    const arbitgpu::glasscaustics::Frame& schedule,const arbitgpu::NativeFixtureSceneRuntimeInputs& runtime,
    std::uint64_t passes,std::uint64_t draws,MetalRasterCaptureBudget& output,std::string& error,
    std::uint64_t runtimeLightsCapacity=UINT64_MAX,std::uint64_t historicalGeometryBytes=UINT64_MAX,std::uint64_t historicalGeometryAllocation=UINT64_MAX)
{
    using namespace arbitgpu;
    const auto refuse=[&](){error="Metal raster capture explicit storage exceeds admission";return false;};
    MetalRasterCaptureBudget b;
    if(!passes||!metalRasterProduct(draws,sizeof(FixtureUniforms)+sizeof(MetalRasterDrawCapture),b.payload)
        ||!metalRasterAdd(b.payload,sizeof(MetalRasterPassStamp))
        ||!metalRasterProduct(std::strlen(kFixtureVertexShader),4,b.sourceLimit)
        ||!metalRasterAdd(b.sourceLimit,4096))return refuse();
    const auto previous=runtime.previousMotion?resources.previousVertexBuffer:sg_buffer{};
    if(historicalGeometryBytes!=UINT64_MAX) {
        b.geometryBytes=historicalGeometryBytes;b.geometryAllocation=historicalGeometryAllocation;
    }
    else for(auto handle:{resources.vertexBuffer,previous,resources.indexBuffer,resources.geometryInstanceBuffer}) {
        if(!handle.id)continue;
        if(!resourceValid(sg_query_buffer_state(handle)))return refuse();
        const auto info=sg_mtl_query_buffer_info(handle);
        if(info.active_slot<0||info.active_slot>=SG_NUM_INFLIGHT_FRAMES)return refuse();
        const auto buffer=(__bridge id<MTLBuffer>)info.buf[info.active_slot];
        if(!buffer||buffer.device!=gMetalDevice||!buffer.contents||buffer.length>gMetalDevice.maxBufferLength
            ||!metalRasterAdd(b.geometryBytes,buffer.length)
            ||!metalRasterAdd(b.geometryAllocation,std::max<std::uint64_t>(buffer.length,buffer.allocatedSize)))return refuse();
    }
    if(!metalRasterAdd(b.payload,b.geometryBytes))return refuse();
    b.host=sizeof(MetalRasterCaptureManifest)+2*sizeof(NativeFixtureSceneRuntimeInputs)+128;
    const auto charge=[&](std::uint64_t count,std::uint64_t stride) {
        std::uint64_t bytes=0;
        return metalRasterProduct(count,stride,bytes)&&metalRasterAdd(b.host,bytes);
    };
    std::uint64_t perPass=2*sizeof(MetalRasterPassCapture)+16*sizeof(const void*);
    std::uint64_t drawBytes=0,historicalBytes=0;
    if(!metalRasterProduct(draws,2*sizeof(MetalRasterDrawCapture),drawBytes)
        ||!metalRasterProduct(b.payload,2,historicalBytes)||!metalRasterAdd(perPass,drawBytes)
        ||!metalRasterAdd(perPass,historicalBytes)||!charge(passes,perPass)
        ||!charge(8,b.sourceLimit)||!charge(runtimeLightsCapacity==UINT64_MAX?runtime.animatedLights.capacity():runtimeLightsCapacity,
            2*sizeof(HarmonicMIDI::grid::SceneLightRecord))
        ||!charge(runtime.materialFrameTextures.size(),2*(sizeof(decltype(runtime.materialFrameTextures)::value_type)+64)))return refuse();
    if(runtime.previousMotion&&!charge(1,kNativeSceneMotionMaximumSnapshotBytes))return refuse();
    for(const auto* identity:{&schedule.identity,&schedule.cameraIdentity,&schedule.sourceIdentity})
        if(!charge(2,identity->size()+1))return refuse();
    std::uint64_t nativePerPass=b.payload;
    if(!metalRasterAdd(nativePerPass,64*1024)||!metalRasterAdd(nativePerPass,b.geometryAllocation)
        ||!metalRasterProduct(passes,nativePerPass,b.native)
        ||!metalRasterAdd(b.native,2*b.sourceLimit+64*1024))return refuse();
    for(auto ring:_sg.mtl.uniform_buffers) {
        if(!ring||ring.device!=gMetalDevice||!ring.contents||ring.length>gMetalDevice.maxBufferLength
            ||!metalRasterAdd(b.native,std::max<std::uint64_t>(ring.length,ring.allocatedSize)))return refuse();
    }
    if(b.host>renderpassoutput::kMaximumTotalBytes||b.native>renderpassoutput::kMaximumTotalBytes-b.host)return refuse();
    output=b;error.clear();return true;
}
static bool prepareMetalRasterCapture(MetalFixtureSceneFrame& frame,
    const arbitgpu::NativeFixtureSceneRuntimeInputs& runtime,std::size_t passes,std::size_t draws,
    const MetalRasterCaptureBudget& budget,std::string& error)
{
    const auto refuse=[&](){error="Metal raster capture actual host/native capacity exceeds reservation";return false;};
    auto& state=*frame.caustic;
    if(state.rasterCapture||state.rasterCaptureCandidate)return refuse();
    auto candidate=std::make_unique<MetalRasterCaptureManifest>();auto& m=*candidate;
    state.rasterCaptureAccounting.constructionCopies=budget.host;
    m.owner=&frame;m.resources=frame.staticResources;
    m.runtime=std::make_shared<const arbitgpu::NativeFixtureSceneRuntimeInputs>(runtime);
    m.runtimeLightsCapacity=runtime.animatedLights.capacity();
    m.generation=frame.rendererGeneration_;m.submission=state.submission;m.evaluationTime=runtime.timeSeconds;
    m.privateStaging=frame.privateCameraAttachments;m.drawsPerPass=draws;
    m.hostReservation=budget.host;m.nativeReservation=budget.native;m.sourceLimit=budget.sourceLimit;
    m.geometryBytes=budget.geometryBytes;m.geometryAllocation=budget.geometryAllocation;
    m.geometry={m.resources->vertexBuffer,runtime.previousMotion?m.resources->previousVertexBuffer:sg_buffer{},
        m.resources->indexBuffer,m.resources->geometryInstanceBuffer};
    m.frameIdentity=state.schedule.identity;m.cameraIdentity=state.schedule.cameraIdentity;m.sourceIdentity=state.schedule.sourceIdentity;
    m.passes.reserve(passes);
    if(m.passes.capacity()>2*passes||m.runtime->animatedLights.capacity()>2*runtime.animatedLights.capacity())return refuse();
    for(const auto* identity:{&m.frameIdentity,&m.cameraIdentity,&m.sourceIdentity})
        if(identity->capacity()>2*(identity->size()+1))return refuse();
    m.queue=(__bridge id<MTLCommandQueue>)sg_mtl_command_queue();
#if ! __has_feature(objc_arc)
    [m.queue retain];
#endif
    if(!m.queue||m.queue.device!=gMetalDevice)return refuse();
    for(unsigned i=0;i<m.rings.size();++i) {
        m.rings[i]=_sg.mtl.uniform_buffers[i];m.ringLengths[i]=m.rings[i].length;
        m.ringAllocations[i]=std::max<std::uint64_t>(m.rings[i].length,m.rings[i].allocatedSize);
#if ! __has_feature(objc_arc)
        [m.rings[i] retain];
#endif
    }
    for(std::size_t i=0;i<passes;++i) {
        auto pass=std::make_unique<MetalRasterPassCapture>();pass->stamp.draws=draws;
        pass->draws.reserve(draws);pass->historical.resize(budget.payload);
        if(pass->draws.capacity()>2*draws||pass->historical.capacity()>2*budget.payload)return refuse();
        pass->archive=[gMetalDevice newBufferWithLength:budget.payload options:MTLResourceStorageModeShared];
        if(!pass->archive||!pass->archive.contents||pass->archive.length!=budget.payload
            ||pass->archive.length>gMetalDevice.maxBufferLength
            ||std::max<std::uint64_t>(pass->archive.length,pass->archive.allocatedSize)>budget.payload+64*1024)return refuse();
        pass->archiveCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,arbitgpu::residency::nominalBufferBytes(budget.payload));
        pass->archiveAllocation=std::max<std::uint64_t>(pass->archive.length,pass->archive.allocatedSize);
        m.passes.push_back(std::move(pass));
    }
    state.cameraInputs=m.runtime;
    state.rasterCaptureCandidate=std::move(candidate);error.clear();return true;
}

bool prepareMetalCausticRaster(MetalFixtureSceneFrame& frame,std::string& error,bool initializeDepth=false)
{
    auto& state=*frame.caustic;
    const auto vertex=fixtureVertexModifierShader(kFixtureVertexShader,nullptr,
        videohelper::materialprogram::BackendTarget::Metal,error);
    if(vertex.empty())return false;
    // Uniforms and varyings are identical to the owning draw; no new uniform ABI.
    std::string fragment=vertex.substr(0,vertex.find("vertex VertexOut _main"));
    fragment+=R"METAL(
struct CausticRaster {uint4 identity [[color(0)]];float depth [[color(1)]];};
fragment CausticRaster causticRaster(VertexOut in [[stage_in]],uint primitive [[primitive_id]]) {
    CausticRaster out;
    uint object=uint(in.rawIdentifiers.z)|(uint(in.rawIdentifiers.w)<<16u);
    uint material=uint(in.rawIdentifiers.x)|(uint(in.rawIdentifiers.y)<<16u);
    out.identity=uint4(object,material,in.spectralInstance,primitive);out.depth=in.linearDepth;return out;
}
)METAL";
    if(!state.rasterCaptureCandidate||vertex.size()>state.rasterCaptureCandidate->sourceLimit
        ||fragment.size()>state.rasterCaptureCandidate->sourceLimit) {
        error="Metal raster shader sources exceed capture admission";return false;
    }
    auto& capture=*state.rasterCaptureCandidate;
    std::uint64_t sourceCopyEnvelope=0;
    if(!metalRasterProduct(vertex.size()+fragment.size(),4,sourceCopyEnvelope)
        ||!metalRasterAdd(state.rasterCaptureAccounting.constructionCopies,sourceCopyEnvelope)) {
        error="Metal raster shader capture copy accounting overflowed";return false;
    }
    capture.vertexSource=vertex;capture.fragmentSource=fragment;
    if(capture.vertexSource.capacity()>2*capture.sourceLimit||capture.fragmentSource.capacity()>2*capture.sourceLimit) {
        error="Metal raster retained shader source capacities exceed admission";return false;
    }
    const auto sourceLength=vertex.size()+fragment.size();
    capture.sourceArchive=[gMetalDevice newBufferWithLength:sourceLength options:MTLResourceStorageModeShared];
    if(!capture.sourceArchive||!capture.sourceArchive.contents||capture.sourceArchive.length!=sourceLength
        ||capture.sourceArchive.length>gMetalDevice.maxBufferLength
        ||std::max<std::uint64_t>(capture.sourceArchive.length,capture.sourceArchive.allocatedSize)>2*capture.sourceLimit+64*1024) {
        error="Metal raster native shader source archive exceeds admission";return false;
    }
    capture.sourceArchiveCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,arbitgpu::residency::nominalBufferBytes(capture.sourceArchive.length));
    capture.sourceAllocation=std::max<std::uint64_t>(capture.sourceArchive.length,capture.sourceArchive.allocatedSize);
    std::memcpy(capture.sourceArchive.contents,vertex.data(),vertex.size());
    std::memcpy(static_cast<unsigned char*>(capture.sourceArchive.contents)+vertex.size(),fragment.data(),fragment.size());
    sg_shader_desc shader={};shader.vertex_func.source=vertex.c_str();shader.fragment_func.source=fragment.c_str();
    shader.fragment_func.entry="causticRaster";
    shader.uniform_blocks[0].stage=SG_SHADERSTAGE_VERTEX;shader.uniform_blocks[0].size=sizeof(FixtureUniforms);
    shader.uniform_blocks[0].msl_buffer_n=0;
    for(unsigned i=0;i<13;++i) shader.attrs[i].base_type=SG_SHADERATTRBASETYPE_FLOAT;
    shader.label="arbit-metal-caustic-raster-shader";
    state.rasterShader=sg_make_shader(&shader);
    if(!resourceValid(sg_query_shader_state(state.rasterShader))) {
        error="Metal caustic raster shader creation failed: "+lastSokolLog();return false;
    }
    capture.shader=state.rasterShader;
    const auto shaderOwners=sg_mtl_query_shader_info(state.rasterShader);
    capture.shaderOwners={(__bridge id)shaderOwners.vertex_lib,(__bridge id)shaderOwners.fragment_lib,
        (__bridge id)shaderOwners.vertex_func,(__bridge id)shaderOwners.fragment_func};
    for(auto value:capture.shaderOwners) {
#if ! __has_feature(objc_arc)
        [value retain];
#endif
    }
    if(std::find(capture.shaderOwners.begin(),capture.shaderOwners.end(),nil)!=capture.shaderOwners.end()) {
        error="Metal raster native shader capture is unavailable";return false;
    }
    const std::array<sg_pixel_format,2> formats{SG_PIXELFORMAT_RGBA32UI,SG_PIXELFORMAT_R32F};
    for(unsigned i=0;i<2;++i) {
        const auto capability=sg_query_pixelformat(formats[i]);
        if(!capability.render||!capability.sample) {error="Metal caustic raster evidence format unavailable";return false;}
        sg_image_desc image={};image.width=frame.width_;image.height=frame.height_;image.pixel_format=formats[i];
        image.usage.color_attachment=true;image.sample_count=1;image.label="arbit-metal-caustic-raster-evidence";
        state.rasterImages[i]=sg_make_image(&image);
        sg_view_desc view={};view.color_attachment.image=state.rasterImages[i];state.rasterViews[i]=sg_make_view(&view);
        if(!resourceValid(sg_query_image_state(state.rasterImages[i]))||!resourceValid(sg_query_view_state(state.rasterViews[i]))) {
            error="Metal caustic raster evidence allocation failed";return false;
        }
        state.rasterImageCharges[i]=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,metalImageBytes(image));
    }
    auto pipeline=sg_query_pipeline_desc(frame.staticResources->pipelines.front());
    pipeline.shader=state.rasterShader;pipeline.depth.compare=initializeDepth?SG_COMPAREFUNC_LESS:SG_COMPAREFUNC_EQUAL;
    pipeline.depth.write_enabled=initializeDepth;
    pipeline.color_count=2;for(auto& color:pipeline.colors)color={};
    pipeline.colors[0].pixel_format=formats[0];pipeline.colors[1].pixel_format=formats[1];
    pipeline.label="arbit-metal-caustic-raster-pipeline";
    for(unsigned i=0;i<3;++i) {
        pipeline.cull_mode=i==0?SG_CULLMODE_NONE:SG_CULLMODE_BACK;
        pipeline.face_winding=i==2?SG_FACEWINDING_CW:SG_FACEWINDING_CCW;
        state.rasterPipelines[i]=sg_make_pipeline(&pipeline);
        if(!resourceValid(sg_query_pipeline_state(state.rasterPipelines[i]))) {
            error="Metal caustic raster pipeline creation failed: "+lastSokolLog();return false;
        }
        capture.descriptions[i]=sg_query_pipeline_desc(state.rasterPipelines[i]);capture.descriptions[i].label=nullptr;
        const auto native=sg_mtl_query_pipeline_info(state.rasterPipelines[i]);
        capture.pipelines[i]=(__bridge id<MTLRenderPipelineState>)native.rps;
        capture.depthStates[i]=(__bridge id<MTLDepthStencilState>)native.dss;
#if ! __has_feature(objc_arc)
        [capture.pipelines[i] retain];[capture.depthStates[i] retain];
#endif
        if(!capture.pipelines[i]||!capture.depthStates[i]) {
            error="Metal raster native pipeline capture is unavailable";return false;
        }
    }
    return true;
}

static bool beginMetalRasterCapture(MetalFixtureSceneFrame& frame,std::size_t index,
    const sg_pass& submitted,const std::array<int,4>& scissor,std::string& error)
{
    const auto refuse=[&](){error="Metal raster capture lost its actual owning pass or source buffers";return false;};
    auto& state=*frame.caustic;
    if(!state.rasterCaptureCandidate||index>=state.rasterCaptureCandidate->passes.size())return refuse();
    auto& m=*state.rasterCaptureCandidate;auto& p=*m.passes[index];
    if(p.command||!_sg.cur_pass.valid||!_sg.mtl.cmd_buffer||!_sg.mtl.render_cmd_encoder
        ||_sg.mtl.cmd_buffer.commandQueue!=m.queue||_sg.mtl.cur_frame_rotate_index>=m.rings.size())return refuse();
    std::uint64_t copyEnvelope=0;
    std::uint64_t compareEnvelope=0;
    if(!metalRasterProduct(p.archive.length,3,copyEnvelope)
        ||!metalRasterProduct(m.drawsPerPass,sizeof(FixtureUniforms),compareEnvelope)
        ||!metalRasterAdd(state.rasterCaptureAccounting.constructionCopies,copyEnvelope)
        ||!metalRasterAdd(state.rasterCaptureAccounting.constructionComparisons,compareEnvelope))return refuse();
    p.command=_sg.mtl.cmd_buffer;p.stamp.command=(__bridge const void*)p.command;
    p.stamp.ringSlot=int(_sg.mtl.cur_frame_rotate_index);p.uniformRing=m.rings[p.stamp.ringSlot];
    p.stamp.uniformRing=(__bridge const void*)p.uniformRing;p.stamp.ringLength=p.uniformRing.length;
    p.stamp.ringAllocation=std::max<std::uint64_t>(p.uniformRing.length,p.uniformRing.allocatedSize);
    p.stamp.viewport={0,0,int(frame.width_),int(frame.height_)};p.stamp.scissor=scissor;
    p.stamp.action=_sg.cur_pass.action;
    // Record the exact setters used for this owning pass, including defaults.
    sg_apply_viewport(0,0,frame.width_,frame.height_,true);
    sg_apply_scissor_rect(scissor[0],scissor[1],scissor[2],scissor[3],true);
#if ! __has_feature(objc_arc)
    [p.command retain];[p.uniformRing retain];
#endif
    p.geometry=m.geometry;
    std::uint64_t offset=m.drawsPerPass*sizeof(FixtureUniforms),geometryAllocation=0;
    for(unsigned i=0;i<p.geometry.size();++i) {
        p.stamp.geometryHandles[i]=p.geometry[i].id;
        p.stamp.geometryOffsets[i]=offset;
        if(!p.geometry[i].id)continue;
        const auto info=sg_mtl_query_buffer_info(p.geometry[i]);
        if(info.active_slot<0||info.active_slot>=SG_NUM_INFLIGHT_FRAMES)return refuse();
        p.nativeGeometry[i]=(__bridge id<MTLBuffer>)info.buf[info.active_slot];
        const auto value=p.nativeGeometry[i];
#if ! __has_feature(objc_arc)
        [value retain];
#endif
        if(!value||!value.contents||value.device!=gMetalDevice)return refuse();
        p.stamp.geometry[i]=(__bridge const void*)value;p.stamp.geometryLengths[i]=value.length;
        p.stamp.geometryAllocations[i]=std::max<std::uint64_t>(value.length,value.allocatedSize);
        if(offset>p.historical.size()||value.length>p.historical.size()-offset
            ||!metalRasterAdd(geometryAllocation,p.stamp.geometryAllocations[i])
            ||geometryAllocation>m.geometryAllocation)return refuse();
        std::memcpy(p.historical.data()+offset,value.contents,value.length);offset+=value.length;
    }
    if(geometryAllocation!=m.geometryAllocation)return refuse();
    p.recordsOffset=offset;
    if(!metalRasterAdd(offset,m.drawsPerPass*sizeof(MetalRasterDrawCapture)))return refuse();
    p.stampOffset=offset;
    if(!metalRasterAdd(offset,sizeof(MetalRasterPassStamp))||offset!=p.historical.size())return refuse();
    const std::array<sg_view,3> views{submitted.attachments.colors[0],submitted.attachments.colors[1],submitted.attachments.depth_stencil};
    for(unsigned i=0;i<views.size();++i) {
        if(!resourceValid(sg_query_view_state(views[i])))return refuse();
        const auto desc=sg_query_view_desc(views[i]);
        const auto image=i<2?desc.color_attachment.image:desc.depth_stencil_attachment.image;
        const auto info=sg_mtl_query_image_info(image);
        if(info.active_slot<0||info.active_slot>=SG_NUM_INFLIGHT_FRAMES)return refuse();
        p.textures[i]=(__bridge id<MTLTexture>)info.tex[info.active_slot];
#if ! __has_feature(objc_arc)
        [p.textures[i] retain];
#endif
        if(!p.textures[i]||p.textures[i].device!=gMetalDevice)return refuse();
        p.stamp.views[i]=views[i].id;p.stamp.images[i]=image.id;p.stamp.textures[i]=(__bridge const void*)p.textures[i];
        p.stamp.textureAllocations[i]=p.textures[i].allocatedSize;
    }
    error.clear();return true;
}
static bool captureMetalRasterDraw(MetalFixtureSceneFrame& frame,std::size_t passIndex,
    const FixtureUniforms& submitted,int uniformOffset,int count,std::size_t winding,std::string& error)
{
    const auto refuse=[&](){error="Metal raster draw was not submitted with its exact native uniform/binding state";return false;};
    auto& m=*frame.caustic->rasterCaptureCandidate;auto& p=*m.passes[passIndex];
    if(!count)return true;
    const auto* pipeline=_sg_pipeline_ref_ptr(&_sg.cur_pip);
    if(count<0||!pipeline||winding>=m.pipelines.size()||p.draws.size()>=m.drawsPerPass
        ||!_sg.cur_pass.valid||!_sg.next_draw_valid||!_sg.use_indexed_draw
        ||_sg.mtl.cmd_buffer!=p.command||_sg.mtl.render_cmd_encoder==nil||uniformOffset<0||p.uniformRing.length<sizeof(FixtureUniforms)
        ||std::uint64_t(uniformOffset)>p.uniformRing.length-sizeof(FixtureUniforms)
        ||_sg.mtl.cur_ub_offset!=_sg_roundup(uniformOffset+int(sizeof(FixtureUniforms)),_SG_MTL_UB_ALIGN)
        ||pipeline->slot.id!=frame.caustic->rasterPipelines[winding].id)return refuse();
#if defined(SOKOL_DEBUG)
    if(!_sg_validate_draw(0,count,1))return refuse();
#endif
    const auto* nativeUniforms=static_cast<const unsigned char*>(p.uniformRing.contents)+uniformOffset;
    if(std::memcmp(nativeUniforms,&submitted,sizeof(submitted)))return refuse();
    MetalRasterDrawCapture draw{};std::memcpy(&draw.uniforms,nativeUniforms,sizeof(draw.uniforms));
    draw.uniformOffset=uniformOffset;draw.count=count;draw.winding=winding;draw.pipeline=(__bridge const void*)m.pipelines[winding];
    for(unsigned slot=0;slot<draw.vertices.size();++slot) {
        const auto& binding=_sg.mtl.cache.cur_vsbufs[slot];
        const auto* buffer=_sg_lookup_buffer(binding.sref.id);
        if(!buffer||buffer->slot.state!=SG_RESOURCESTATE_VALID||binding.active_slot<0
            ||binding.active_slot>=SG_NUM_INFLIGHT_FRAMES||binding.offset<0)return refuse();
        const auto value=_sg_mtl_id(buffer->mtl.buf[binding.active_slot]);
        if(std::find(p.nativeGeometry.begin(),p.nativeGeometry.end(),value)==p.nativeGeometry.end())return refuse();
        draw.vertices[slot]=buffer->slot.id;draw.offsets[slot]=binding.offset;draw.nativeVertices[slot]=(__bridge const void*)value;
    }
    const auto* indices=_sg_buffer_ref_ptr(&_sg.mtl.cache.cur_ibuf);
    if(!indices||indices->slot.state!=SG_RESOURCESTATE_VALID||indices->cmn.active_slot<0
        ||indices->cmn.active_slot>=SG_NUM_INFLIGHT_FRAMES||_sg.mtl.cache.cur_ibuf_offset<0)return refuse();
    const auto nativeIndices=_sg_mtl_id(indices->mtl.buf[indices->cmn.active_slot]);
    if(nativeIndices!=p.nativeGeometry[2])return refuse();
    draw.indices=indices->slot.id;draw.nativeIndices=(__bridge const void*)nativeIndices;
    draw.indexOffset=_sg.mtl.cache.cur_ibuf_offset;
    std::memcpy(p.historical.data()+p.draws.size()*sizeof(FixtureUniforms),nativeUniforms,sizeof(FixtureUniforms));
    p.draws.push_back(draw);error.clear();return true;
}
static bool encodeMetalRasterHistory(MetalFixtureSceneFrame& frame,std::size_t index,std::string& error)
{
    const auto refuse=[&](){error="Metal raster history lost its actual draw sequence or owning command";return false;};
    auto& m=*frame.caustic->rasterCaptureCandidate;auto& p=*m.passes[index];
    if(p.draws.size()!=m.drawsPerPass||_sg.mtl.render_cmd_encoder||_sg.mtl.cmd_buffer!=p.command)return refuse();
    // Metadata records describe the actual calls above. Uniforms and geometry
    // come independently from the buffers consumed by those calls.
    std::memcpy(p.historical.data()+p.recordsOffset,p.draws.data(),p.draws.size()*sizeof(p.draws[0]));
    std::memcpy(p.historical.data()+p.stampOffset,&p.stamp,sizeof(p.stamp));
    std::memcpy(static_cast<unsigned char*>(p.archive.contents)+p.recordsOffset,
        p.historical.data()+p.recordsOffset,p.historical.size()-p.recordsOffset);
    const auto blit=[p.command blitCommandEncoder];
    if(!blit)return refuse();
    for(std::size_t i=0;i<p.draws.size();++i)
        [blit copyFromBuffer:p.uniformRing sourceOffset:p.draws[i].uniformOffset toBuffer:p.archive
            destinationOffset:i*sizeof(FixtureUniforms) size:sizeof(FixtureUniforms)];
    for(unsigned i=0;i<p.nativeGeometry.size();++i)
        if(p.nativeGeometry[i]) [blit copyFromBuffer:p.nativeGeometry[i] sourceOffset:0 toBuffer:p.archive
            destinationOffset:p.stamp.geometryOffsets[i] size:p.stamp.geometryLengths[i]];
    [blit endEncoding];error.clear();return true;
}
static bool completeMetalRasterHistory(MetalFixtureSceneFrame& frame,std::size_t index,std::string& error)
{
    auto& p=*frame.caustic->rasterCaptureCandidate->passes[index];
    [p.command waitUntilCompleted];
    if(p.command.status!=MTLCommandBufferStatusCompleted) {
        error="Metal actual owning raster command did not complete";return false;
    }
    p.completed=true;error.clear();return true;
}

struct MetalRasterScanCost final {
    std::uint64_t visits=0,copies=0,compares=0,construction=0,constructionComparisons=0,host=0,native=0;
};
static bool metalRasterCaptureShape(const MetalFixtureSceneFrame& frame,const MetalRasterCaptureManifest& m,
    MetalRasterScanCost& output,std::string& error)
{
    const auto refuse=[&](){error="Metal raster manifest metadata or actual capacities differ from admission";return false;};
    if(!frame.caustic||m.owner!=&frame||m.resources!=frame.staticResources||!m.resources||!m.resources->snapshot
        ||m.generation!=frame.rendererGeneration_||m.generation!=m.resources->rendererGeneration
        ||m.submission!=frame.caustic->submission||!m.runtime||frame.caustic->cameraInputs!=m.runtime
        ||m.runtime->timeSeconds!=m.evaluationTime||m.privateStaging!=frame.privateCameraAttachments
        ||!m.queue||m.queue.device!=gMetalDevice||m.queue!=(__bridge id<MTLCommandQueue>)sg_mtl_command_queue()
        ||m.passes.empty()||m.passes.size()!=(m.privateStaging?1:frame.roughTileSchedule?frame.roughTileSchedule->tiles().size():1)
        ||m.drawsPerPass>m.resources->snapshot->objectCount
        ||m.frameIdentity.size()!=frame.caustic->schedule.identity.size()
        ||m.cameraIdentity.size()!=frame.caustic->schedule.cameraIdentity.size()
        ||m.sourceIdentity.size()!=frame.caustic->schedule.sourceIdentity.size())return refuse();
    MetalRasterCaptureBudget admitted;
    if(m.runtime->animatedLights.capacity()>2*m.runtimeLightsCapacity
        ||!metalRasterCaptureBudget(*m.resources,frame.caustic->schedule,*m.runtime,m.passes.size(),m.drawsPerPass,admitted,error,
            m.runtimeLightsCapacity,m.geometryBytes,m.geometryAllocation)
        ||m.hostReservation!=admitted.host||m.nativeReservation!=admitted.native||m.sourceLimit!=admitted.sourceLimit
        ||m.passes.capacity()>2*m.passes.size()||m.vertexSource.size()>m.sourceLimit||m.fragmentSource.size()>m.sourceLimit
        ||m.vertexSource.capacity()>2*m.sourceLimit||m.fragmentSource.capacity()>2*m.sourceLimit
        ||!m.sourceArchive||!m.sourceArchive.contents||m.sourceArchive.device!=gMetalDevice
        ||m.sourceArchive.length!=m.vertexSource.size()+m.fragmentSource.size()
        ||m.sourceAllocation!=std::max<std::uint64_t>(m.sourceArchive.length,m.sourceArchive.allocatedSize))return refuse();
