        ||!metalRasterAdd(cost.host,m.runtime->animatedLights.capacity()*sizeof(HarmonicMIDI::grid::SceneLightRecord))
        ||!metalRasterAdd(cost.host,m.runtime->materialFrameTextures.size()*(sizeof(decltype(m.runtime->materialFrameTextures)::value_type)+64)))return refuse();
    if(m.runtime->previousMotion&&!metalRasterAdd(cost.host,arbitgpu::kNativeSceneMotionMaximumSnapshotBytes))return refuse();
