            ||std::size_t(s.ringSlot)>=m.rings.size()||p.uniformRing!=m.rings[s.ringSlot]
            ||s.uniformRing!=(__bridge const void*)p.uniformRing||s.ringLength!=m.ringLengths[s.ringSlot]
            ||s.ringAllocation!=m.ringAllocations[s.ringSlot]||p.draws.size()!=m.drawsPerPass
            ||p.draws.capacity()>2*m.drawsPerPass||p.historical.size()!=admitted.payload
            ||p.historical.capacity()>2*admitted.payload||!p.archive||!p.archive.contents||p.archive.device!=gMetalDevice
            ||p.archive.length!=admitted.payload||p.archiveAllocation!=std::max<std::uint64_t>(p.archive.length,p.archive.allocatedSize)
            ||p.archiveAllocation>admitted.payload+64*1024)return refuse();
