        if(!metalRasterProduct(m.drawsPerPass,sizeof(FixtureUniforms),offset))return refuse();
        for(unsigned i=0;i<p.nativeGeometry.size();++i) {
            const auto value=p.nativeGeometry[i];
            if(s.geometryOffsets[i]!=offset||s.geometry[i]!=(__bridge const void*)value
                ||s.geometryHandles[i]!=p.geometry[i].id||p.geometry[i].id!=m.geometry[i].id)return refuse();
