                ||value.length!=s.geometryLengths[i]||value.length>gMetalDevice.maxBufferLength
                ||std::max<std::uint64_t>(value.length,value.allocatedSize)!=s.geometryAllocations[i])return refuse();
            if(!metalRasterAdd(offset,value.length)||!metalRasterAdd(geometryBytes,value.length)
                ||!metalRasterAdd(geometryAllocation,s.geometryAllocations[i]))return refuse();
        }
        if(geometryBytes!=m.geometryBytes||geometryAllocation!=m.geometryAllocation
            ||p.recordsOffset!=offset||!metalRasterAdd(offset,m.drawsPerPass*sizeof(MetalRasterDrawCapture))
            ||p.stampOffset!=offset||!metalRasterAdd(offset,sizeof(MetalRasterPassStamp))||offset!=admitted.payload)return refuse();
        if(!metalRasterAdd(cost.host,sizeof(p)+p.draws.capacity()*sizeof(p.draws[0])+p.historical.capacity())
            ||!metalRasterAdd(cost.native,p.archiveAllocation)||!metalRasterAdd(cost.native,geometryAllocation)
            ||!metalRasterAdd(cost.visits,2+4+3+14*p.draws.size())
            ||!metalRasterAdd(cost.compares,p.historical.size()+p.draws.size()*(sizeof(FixtureUniforms)+sizeof(MetalRasterDrawCapture))+sizeof(s)))return refuse();
        std::uint64_t copies=0;
