            ||!metalRasterProduct(p.draws.size(),sizeof(FixtureUniforms),comparisons)
            ||!metalRasterAdd(cost.constructionComparisons,comparisons)
            ||!metalRasterAdd(cost.copies,3*(sizeof(sg_view_desc)+sizeof(sg_mtl_image_info))))return refuse();
    }
