}
static bool inspectMetalRasterCaptureUnlocked(const MetalFixtureSceneFrame& frame,std::string& error)
{
    const auto refuse=[&](){error="Metal raster historical draw capture is missing, mutated or stale";return false;};
    if(!gMetalDevice||!sg_isvalid()||!frame.caustic||!frame.caustic->rasterCapture
        ||frame.caustic->rasterCaptureCandidate)return refuse();
    const auto& m=*frame.caustic->rasterCapture;auto& accounting=frame.caustic->rasterCaptureAccounting;
    if(!m.sealed||accounting.manifest!=&m)return refuse();
    MetalRasterScanCost cost;
    // Bounded metadata preflight reads no captured content and allocates no
    // inspection scratch. Native contents are touched only after full charge.
    if(!metalRasterCaptureShape(frame,m,cost,error))return false;
    std::uint64_t visits=0,copies=0,compares=0,count=0;
    if(accounting.visitsPerScan!=cost.visits||accounting.copiesPerScan!=cost.copies||accounting.comparesPerScan!=cost.compares
        ||accounting.constructionCopies!=cost.construction
        ||accounting.constructionComparisons!=cost.constructionComparisons
        ||!metalRasterProduct(accounting.invocations,cost.visits,visits)||visits!=accounting.recordVisits
        ||!metalRasterProduct(accounting.invocations,cost.copies,copies)||copies!=accounting.bytesCopied
        ||!metalRasterProduct(accounting.invocations,cost.compares,compares)||compares!=accounting.bytesCompared
        ||!renderpassoutput::detail::checkedAdd(accounting.invocations,1,count)
        ||!metalRasterProduct(count,cost.visits,visits)||!metalRasterProduct(count,cost.copies,copies)
        ||!metalRasterProduct(count,cost.compares,compares))return refuse();
    accounting.invocations=count;accounting.recordVisits=visits;accounting.bytesCopied=copies;accounting.bytesCompared=compares;
    if(m.frameIdentity!=frame.caustic->schedule.identity||m.cameraIdentity!=frame.caustic->schedule.cameraIdentity
        ||m.sourceIdentity!=frame.caustic->schedule.sourceIdentity||m.shader.id!=frame.caustic->rasterShader.id
        ||!resourceValid(sg_query_shader_state(m.shader)))return refuse();
    const auto nativeShader=sg_mtl_query_shader_info(m.shader);
    const std::array<id,4> shaderOwners{(__bridge id)nativeShader.vertex_lib,(__bridge id)nativeShader.fragment_lib,
        (__bridge id)nativeShader.vertex_func,(__bridge id)nativeShader.fragment_func};
    if(shaderOwners!=m.shaderOwners)return refuse();
    if(std::memcmp(m.sourceArchive.contents,m.vertexSource.data(),m.vertexSource.size())
        ||std::memcmp(static_cast<const unsigned char*>(m.sourceArchive.contents)+m.vertexSource.size(),m.fragmentSource.data(),m.fragmentSource.size()))return refuse();
    for(unsigned i=0;i<m.pipelines.size();++i) {
        const auto handle=frame.caustic->rasterPipelines[i];
        if(!resourceValid(sg_query_pipeline_state(handle)))return refuse();
        auto desc=sg_query_pipeline_desc(handle);desc.label=nullptr;
        const auto native=sg_mtl_query_pipeline_info(handle);
        if(native.rps!=(__bridge const void*)m.pipelines[i]||native.dss!=(__bridge const void*)m.depthStates[i]
            ||m.pipelines[i].device!=gMetalDevice||m.depthStates[i].device!=gMetalDevice
            ||std::memcmp(&desc,&m.descriptions[i],sizeof(desc)))return refuse();
    }
    for(const auto& pointer:m.passes) {
        const auto& p=*pointer;const auto& s=p.stamp;const auto* bytes=static_cast<const unsigned char*>(p.archive.contents);
        if(std::memcmp(bytes,p.historical.data(),p.historical.size())||std::memcmp(bytes+p.stampOffset,&s,sizeof(s)))return refuse();
        if(s.viewport!=std::array<int,4>{0,0,int(frame.width_),int(frame.height_)}||s.scissor[0]<0||s.scissor[1]<0
            ||s.scissor[2]<=0||s.scissor[3]<=0||s.scissor[0]>int(frame.width_)-s.scissor[2]
            ||s.scissor[1]>int(frame.height_)-s.scissor[3])return refuse();
        for(unsigned i=0;i<p.textures.size();++i) {
            const sg_image image{s.images[i]};const sg_view view{s.views[i]};
            if(!resourceValid(sg_query_image_state(image))||!resourceValid(sg_query_view_state(view)))return refuse();
            const auto binding=sg_query_view_desc(view);const auto info=sg_mtl_query_image_info(image);
            const auto texture=p.textures[i];
            if((i<2?binding.color_attachment.image.id:binding.depth_stencil_attachment.image.id)!=image.id
                ||std::find(std::begin(info.tex),std::end(info.tex),(__bridge const void*)texture)==std::end(info.tex)
                ||s.textures[i]!=(__bridge const void*)texture||!texture||texture.device!=gMetalDevice
                ||texture.allocatedSize!=s.textureAllocations[i]
                ||texture.width!=frame.width_||texture.height!=frame.height_||texture.sampleCount!=1
                ||texture.pixelFormat!=(i==0?MTLPixelFormatRGBA32Uint:i==1?MTLPixelFormatR32Float:MTLPixelFormatDepth32Float_Stencil8)
                ||image.id!=(i<2?frame.caustic->rasterImages[i].id:m.privateStaging?frame.caustic->rasterDepthStencil.id:frame.depthStencilImage.id))return refuse();
        }
        for(std::size_t i=0;i<p.draws.size();++i) {
            const auto& draw=p.draws[i];
            if(draw.count<=0||draw.winding>=m.pipelines.size()||draw.pipeline!=(__bridge const void*)m.pipelines[draw.winding]
                ||draw.uniformOffset>s.ringLength-sizeof(FixtureUniforms)
                ||std::memcmp(bytes+i*sizeof(FixtureUniforms),&draw.uniforms,sizeof(draw.uniforms))
                ||std::memcmp(bytes+p.recordsOffset+i*sizeof(draw),&draw,sizeof(draw)))return refuse();
            for(unsigned slot=0;slot<draw.vertices.size();++slot) {
                const auto found=std::find(s.geometry.begin(),s.geometry.end(),draw.nativeVertices[slot]);
                if(found==s.geometry.end()||!draw.nativeVertices[slot]||draw.offsets[slot]<0)return refuse();
                const auto index=std::size_t(found-s.geometry.begin());
                if(draw.vertices[slot]!=p.geometry[index].id||std::uint64_t(draw.offsets[slot])>=s.geometryLengths[index])return refuse();
            }
            if(draw.indices!=p.geometry[2].id||draw.nativeIndices!=s.geometry[2]||draw.indexOffset<0
                ||std::uint64_t(draw.indexOffset)>s.geometryLengths[2]
                ||std::uint64_t(draw.count)>(s.geometryLengths[2]-draw.indexOffset)/sizeof(std::uint32_t))return refuse();
        }
    }
    error.clear();return true;
}
template<class Charge>
static bool chargeMetalRasterCaptureNative(const MetalCausticState& state,const Charge& charge,bool historicalOnly=false)
{
    const auto* m=state.rasterCapture?state.rasterCapture.get():state.rasterCaptureCandidate.get();
    if(!m||!m->sourceArchive)return false;
    for(auto ring:m->rings)
        if(!ring||!charge(ring,std::max<std::uint64_t>(ring.length,ring.allocatedSize)))return false;
    if(!charge(m->sourceArchive,std::max<std::uint64_t>(m->sourceArchive.length,m->sourceArchive.allocatedSize)))return false;
    for(const auto& p:m->passes) {
        if(!p||!p->archive||!charge(p->archive,std::max<std::uint64_t>(p->archive.length,p->archive.allocatedSize)))return false;
        if(!historicalOnly) {
            for(auto geometry:p->nativeGeometry)
                if(geometry&&!charge(geometry,std::max<std::uint64_t>(geometry.length,geometry.allocatedSize)))return false;
            for(auto texture:p->textures)
                if(texture&&!charge(texture,texture.allocatedSize))return false;
        }
    }
    return true;
}
static bool sealMetalRasterCapture(MetalFixtureSceneFrame& frame,std::string& error)
{
    auto& state=*frame.caustic;
    if(!state.rasterCaptureCandidate||state.rasterCapture) {
        error="Metal raster capture has no uncommitted exact candidate";return false;
    }
    auto& candidate=*state.rasterCaptureCandidate;MetalRasterScanCost cost;
    if(!metalRasterCaptureShape(frame,candidate,cost,error))return false;
    auto& accounting=state.rasterCaptureAccounting;
    if(accounting.constructionCopies!=cost.construction||accounting.constructionComparisons!=cost.constructionComparisons)return false;
    accounting.manifest=&candidate;accounting.visitsPerScan=cost.visits;
    accounting.copiesPerScan=cost.copies;accounting.comparesPerScan=cost.compares;
    candidate.sealed=true;state.rasterCapture=std::shared_ptr<const MetalRasterCaptureManifest>(state.rasterCaptureCandidate.release());
    return inspectMetalRasterCaptureUnlocked(frame,error);
}

void initializeMetalCausticParams(MetalFixtureSceneFrame& frame)
{
    auto& state=*frame.caustic;const auto& schedule=state.schedule;
    auto& p=state.params;p.query=schedule.query.control;p.source=schedule.sourceDirectionTrace;
    const auto& camera=schedule.camera;const auto& rotation=camera.transform.rotation;
    p.camera={camera.transform.translation.x,camera.transform.translation.y,camera.transform.translation.z,0};
    p.rotation={rotation.x,rotation.y,rotation.z,rotation.w};
    p.projection={std::tan(camera.verticalFovRadians*.5f),float(frame.width_)/frame.height_,camera.nearPlane,camera.farPlane};
    for(unsigned half=0;half<2;++half) {
        std::copy_n(schedule.ior.begin()+half*4,4,p.ior[half].begin());p.radiance[half]=schedule.sourceRadiance[half];
    }
    const auto weights=glasscaustics::resolveWeights();std::copy(weights.begin(),weights.end(),p.cie);
    p.extent={frame.width_,frame.height_,std::uint32_t(schedule.work.size()),std::uint32_t(schedule.triangles.size())};
    const auto& policy=state.prepared.branchPolicy->description();
    p.policy={std::uint32_t(policy.maximumInterfaces),std::uint32_t(policy.maximumVisits),std::uint32_t(policy.maximumPending),state.prepared.glass.object.value};
    p.tail={policy.minimumBranchFraction,policy.maximumUnresolvedFraction,schedule.roughness,float(schedule.interfaceSamples)};
    const auto& allowance=schedule.query.texels[std::size_t(schedule.query.control[0])-1];
    p.allowance={std::uint32_t(allowance[0])+(std::uint32_t(allowance[1])<<16u),0,0,0};
    const auto& deposition=schedule.bounds.deposition;
    p.deposition={std::uint32_t(deposition.paddedKeyCount),std::uint32_t(deposition.maximumDeposits),0,0};
}

