    state.trianglesBufferCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,arbitgpu::residency::nominalBufferBytes(state.triangles.length));
    state.pathsBufferCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,arbitgpu::residency::nominalBufferBytes(state.paths.length));
    state.depositsBufferCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,arbitgpu::residency::nominalBufferBytes(state.deposits.length));
    state.accumulationBufferCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,arbitgpu::residency::nominalBufferBytes(state.accumulation.length));
    state.diagnosticBufferCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,arbitgpu::residency::nominalBufferBytes(state.diagnostic.length));
    state.keysBufferCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,arbitgpu::residency::nominalBufferBytes(state.keys.length));
