            for(int slot=0;slot<SG_NUM_INFLIGHT_FRAMES;++slot) {
                id<MTLTexture> imageTexture=(__bridge id<MTLTexture>)native.tex[slot];
                if(imageTexture!=nil&&!charge(imageTexture,imageTexture.allocatedSize))return false;
