        if(!chargeMetalRasterCaptureNative(state,charge))return false;
        if(!charge(state.query,state.query.allocatedSize)||!charge(additional,additional.allocatedSize))return false;
        std::vector<const MetalFixtureSceneFrame*> retainedFrames;
        std::uint64_t retainedHost=0;
        const auto chargeFrame=[&](auto&& self,const MetalFixtureSceneFrame& owner)->bool {
            if(std::find(retainedFrames.begin(),retainedFrames.end(),&owner)!=retainedFrames.end())return true;
            retainedFrames.push_back(&owner);
