            }
            if(owner.selectedRough) {
                const auto& selected=*owner.selectedRough;
                for(id<MTLBuffer> input:{selected.uniforms,selected.selection,selected.result,selected.work})
                    if(input==nil||input.length>gMetalDevice.maxBufferLength||!charge(input,input.allocatedSize))return false;
                if(!chargeImage(selected.sharedImage)||!chargeImage(selected.resolvedImage))return false;
                if(&owner!=&frame && !owner.caustic) {
