    if(!chargeNative(nil))return refuse("Metal caustic actual peak allocation budget exceeded");
    const auto bind=[&](id<MTLComputeCommandEncoder> encoder,id<MTLComputePipelineState> pipeline) {
        [encoder setComputePipelineState:pipeline];[encoder setBytes:&p length:sizeof(p) atIndex:0];
        [encoder setBuffer:state.work offset:0 atIndex:1];[encoder setBuffer:state.triangles offset:0 atIndex:2];
        [encoder setBuffer:state.paths offset:0 atIndex:3];[encoder setBuffer:state.deposits offset:0 atIndex:4];
        [encoder setBuffer:state.accumulation offset:0 atIndex:5];[encoder setBuffer:state.diagnostic offset:0 atIndex:6];
