    const auto dispatch=[&](id<MTLComputeCommandEncoder> encoder,id<MTLComputePipelineState> pipeline,std::uint64_t count) {
        const auto threads=std::min<NSUInteger>(128,pipeline.maxTotalThreadsPerThreadgroup);
