    };
    auto phase=std::chrono::steady_clock::now();
    id<MTLCommandBuffer> command=[queue commandBuffer];id<MTLComputeCommandEncoder> encoder=[command computeCommandEncoder];
    if(command==nil||encoder==nil)return refuse("Metal caustic submission encoder unavailable");
    bind(encoder,state.trace);
    [encoder setTexture:state.query atIndex:0];[encoder setTexture:ids atIndex:1];[encoder setTexture:depth atIndex:2];
    dispatch(encoder,state.trace,schedule.work.size());[encoder endEncoding];
    [command commit];[command waitUntilCompleted];
    state.metrics.traceMilliseconds=elapsed(phase);
    if(command.status!=MTLCommandBufferStatusCompleted||!state.paths.contents||!state.deposits.contents
