    const auto* radiance=static_cast<const float*>(state.accumulation.contents);receipt.spectralRadiance.assign(radiance,radiance+pixels*8);
    glasscaustics::EnergyLedger ledger;
    if(!glasscaustics::validateNativeReadback(state.prepared,schedule,receipt,ledger,error,&state.identity))return false;
    state.metrics.readbackMilliseconds=elapsed(phase);phase=std::chrono::steady_clock::now();
    // Allocate a distinct target so no partial resolve can mutate public Color.
    MTLTextureDescriptor* resolvedDesc=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA16Float
        width:frame.width_ height:frame.height_ mipmapped:NO];
    resolvedDesc.usage=MTLTextureUsageShaderRead|MTLTextureUsageShaderWrite|MTLTextureUsageRenderTarget;
    id<MTLTexture> resolved=[gMetalDevice newTextureWithDescriptor:resolvedDesc];
    id<MTLTexture> color=texture(frame.colorImage);
    command=[queue commandBuffer];encoder=resolved!=nil?[command computeCommandEncoder]:nil;
    bool ok=resolved!=nil&&color!=nil&&color.device==gMetalDevice&&encoder!=nil&&chargeNative(resolved);
    if(ok) {
        [encoder setComputePipelineState:state.resolve];[encoder setBytes:&p length:sizeof(p) atIndex:0];
        [encoder setBuffer:state.accumulation offset:0 atIndex:1];[encoder setBuffer:state.diagnostic offset:0 atIndex:2];
        [encoder setTexture:color atIndex:0];[encoder setTexture:resolved atIndex:1];
        [encoder dispatchThreads:MTLSizeMake(frame.width_,frame.height_,1) threadsPerThreadgroup:MTLSizeMake(8,8,1)];
        [encoder endEncoding];encoder=nil;[command commit];[command waitUntilCompleted];
        ok=command.status==MTLCommandBufferStatusCompleted&&*static_cast<const std::uint32_t*>(state.diagnostic.contents)==0;
    }
    state.metrics.resolveMilliseconds=elapsed(phase);
    if(!ok && encoder!=nil) [encoder endEncoding];
    sg_image image={};sg_view attachment={},view={};
    if(ok) {
        sg_image_desc desc={};desc.width=frame.width_;desc.height=frame.height_;desc.pixel_format=SG_PIXELFORMAT_RGBA16F;
        desc.usage.color_attachment=true;desc.sample_count=1;desc.label="arbit-metal-validated-caustic-color";
#if ! __has_feature(objc_arc)
        [resolved retain];
#endif
        desc.mtl_textures[0]=(__bridge const void*)resolved;image=sg_make_image(&desc);
        sg_view_desc v={};v.color_attachment.image=image;attachment=sg_make_view(&v);v={};v.texture.image=image;view=sg_make_view(&v);
        ok=resourceValid(sg_query_image_state(image))&&resourceValid(sg_query_view_state(attachment))&&resourceValid(sg_query_view_state(view));
    }
#if ! __has_feature(objc_arc)
    [resolved release];
#endif
    if(!ok) {
        if(view.id)sg_destroy_view(view);if(attachment.id)sg_destroy_view(attachment);if(image.id)sg_destroy_image(image);
        return refuse("Metal caustic completed Color resolve failed");
    }
    NativeRawPassPixels completion;
    if(!frame.readTextureOwned(image,NativeTexturePixelFormat::Rgba16Float,completion,error)
        ||!smoothglass::finiteColorFrame(completion,error)) {
        sg_destroy_view(view);sg_destroy_view(attachment);sg_destroy_image(image);return false;
    }
    sg_destroy_view(frame.colorTextureView);sg_destroy_view(frame.colorAttachmentView);sg_destroy_image(frame.colorImage);
    frame.colorImage=image;frame.colorAttachmentView=attachment;frame.colorTextureView=view;
    // The validated Color replaces the fixture color target, so its charge moves with it.
    frame.colorImageCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::fixtureScene,arbitgpu::residency::nominalTextureBytes(static_cast<std::uint64_t>(frame.width_),static_cast<std::uint64_t>(frame.height_),1,1,8,1));
    state.receipt=std::move(receipt);state.energy=ledger;state.validated=true;state.metrics.frameMilliseconds=elapsed(started);error.clear();return true;
}

class MetalFixtureSceneBackend final : public NativeFixtureSceneBackend
{
public:
    bool supportsRetainedNoteMotion() const noexcept override { return true; }
    bool supportsAuthoredSpectralReceiverTransport() const noexcept override {
        return metalSpectralConsumerAvailable();
    }
    BackendInfo info() const override
    {
        return queryNativeBackend();
    }

    GeometryCoreExecutionCapabilities geometryCoreCapabilities() const override
    {
        GeometryCoreExecutionCapabilities capabilities;
        const auto available = info();
        if (! available.available) return capabilities;
        capabilities.immutableSourceBuffers = true;
        capabilities.stableElementIds = true;
        capabilities.typedFieldEvaluation = true;
        capabilities.gpuInstancingWithoutMeshExpansion = true;
        capabilities.supportedCarriers = (1u << static_cast<unsigned> (
            videowire::geometry::CarrierKind::geometry3D))
            | (1u << static_cast<unsigned> (
                videowire::geometry::CarrierKind::instances3D));
        capabilities.maxVertices = HarmonicMIDI::grid::Visual3DScene::kMaxVertices;
        capabilities.maxIndices = HarmonicMIDI::grid::Visual3DScene::kMaxIndices;
        capabilities.maxPoints = 1;
        capabilities.maxCurvePoints = 1;
        capabilities.maxSplines = 1;
        capabilities.maxInstances = HarmonicMIDI::grid::Visual3DScene::kMaxObjects;
        capabilities.maxFieldElements = HarmonicMIDI::grid::Visual3DScene::kMaxVertices;
        capabilities.maxAttributes = videowire::geometry::kMaximumAttributes;
        capabilities.maxOperations = videowire::geometry::kMaximumOperations;
        capabilities.maxDispatches = videowire::geometry::kMaximumDispatches;
        capabilities.maxBufferBytes = 64u * 1024u * 1024u;
        return capabilities;
    }

    NativeFixtureScenePreparation prepare (
        const std::shared_ptr<const HarmonicMIDI::grid::Visual3DScene>& scene,
        const std::shared_ptr<const NativeFixtureSurfaceMaterialProgram>& requestedMaterialProgram,
        NativeFixturePrepareUse = NativeFixturePrepareUse::Blocking) override
    {
        return prepareGeometryInstances(scene, requestedMaterialProgram, {}, false);
    }

    NativeFixtureScenePreparation prepareGeometryInstances (
        const std::shared_ptr<const HarmonicMIDI::grid::Visual3DScene>& scene,
        const std::shared_ptr<const NativeFixtureSurfaceMaterialProgram>& requestedMaterialProgram,
        const std::shared_ptr<const videohelper::geometry::AdmittedPlanValue>& geometryAdmission,
        bool diagnosticInstanceIdentityColors,
        const std::vector<videowire::geometry::AttributeData>* frameAttributes = nullptr,
        NativeFixturePrepareUse = NativeFixturePrepareUse::Blocking) override
    {
        return prepareGeometryInstancesOwned(scene,requestedMaterialProgram,geometryAdmission,
            diagnosticInstanceIdentityColors,frameAttributes,nullptr,{});
    }

    NativeFixtureScenePreparation prepareGrating(
        const std::shared_ptr<const HarmonicMIDI::grid::Visual3DScene>& scene,
        const std::shared_ptr<const NativeFixtureSurfaceMaterialProgram>& root,
        const smoothglass::DistinctGratingAdmission& admission,
        const std::shared_ptr<const NativeFixtureSurfaceMaterialProgram>& leaf)
    {
        NativeFixtureScenePreparation refused;
        if(!scene||!root||!leaf||!leaf->objectPrograms.empty()
            ||root->programIdentity!=leaf->programIdentity||root->sceneRevision!=leaf->sceneRevision
            ||root->bindingDigest!=leaf->bindingDigest||root->object!=leaf->object
            ||!smoothglass::validDistinctGrating(*root,admission)||!smoothglass::validDistinctGrating(*leaf,admission)) {
            refused.error="Metal mixed staging requires its original compiled discrete grating owner";return refused;
        }
        const auto frozenScene=std::make_shared<const HarmonicMIDI::grid::Visual3DScene>(*scene);
        return prepareGeometryInstancesOwned(frozenScene,root,{},false,nullptr,&admission,
            snapshotNativeSurfaceProgram(leaf));
    }

    NativeFixtureScenePreparation prepareGeometryInstancesOwned(
        const std::shared_ptr<const HarmonicMIDI::grid::Visual3DScene>& scene,
        const std::shared_ptr<const NativeFixtureSurfaceMaterialProgram>& requestedMaterialProgram,
        const std::shared_ptr<const videohelper::geometry::AdmittedPlanValue>& geometryAdmission,
        bool diagnosticInstanceIdentityColors,
        const std::vector<videowire::geometry::AttributeData>* frameAttributes,
        const smoothglass::DistinctGratingAdmission* distinctGrating,
        const std::shared_ptr<const NativeFixtureSurfaceMaterialProgram>& discreteGratingProgram)
    {
        using namespace HarmonicMIDI::grid;
        const auto diffractionConsumer=distinctGrating?NativeFixtureDiffractionConsumer::SmoothGlassDiscreteOrders
            :NativeFixtureDiffractionConsumer::FiniteLobe;
        NativeFixtureScenePreparation result;
        const auto materialProgram = snapshotNativeSurfaceProgram(requestedMaterialProgram);
        if (scene == nullptr || ! validateVisual3DScene (*scene).valid()
            || scene->objectCount == 0 || scene->materialCount == 0
            || scene->lightCount > Visual3DScene::kMaxLights
            || scene->cameraCount == 0 || scene->cameraCount > Visual3DScene::kMaxCameras
            || visual3d_detail::findById (scene->cameras, scene->cameraCount,
                                          scene->activeCamera) == nullptr)
        {
            result.error = "Metal fixture preparation requires a bounded renderable scene";
            return result;
        }
        const auto& sceneMaterial = scene->materials[0];
        const auto& firstObject = scene->objects[0];
        if (frameAttributes && (!geometryAdmission
            || !videowire::geometry::validInstanceAppearanceAttributes(*frameAttributes,scene->objectCount,result.error)))
            return result;
        bool instancedSharedGeometry = false;
        if (geometryAdmission != nullptr)
        {
            if (geometryAdmission->value().descriptor().carrier
                    != videowire::geometry::CarrierKind::instances3D)
            {
                result.error = "Metal Geometry Core preparation requires admitted Instances3D authority";
                return result;
            }
            const auto& admittedInstances = std::get<videowire::geometry::InstancesData>(
                geometryAdmission->value().descriptor().data).instances;
            instancedSharedGeometry = admittedInstances.size() == scene->objectCount
                && scene->objectCount > 0 && materialProgram == nullptr
                && !firstObject.parent.isValid()
                && firstObject.material == sceneMaterial.id
                && sceneMaterial.alphaMode != SceneAlphaMode::Blend;
            for (std::size_t index = 0;
                 instancedSharedGeometry && index < scene->objectCount; ++index)
            {
                const auto& candidate = scene->objects[index];
                instancedSharedGeometry = admittedInstances[index].stableId == candidate.id.value
                    && !candidate.parent.isValid() && candidate.material == firstObject.material
                    && candidate.firstVertex == firstObject.firstVertex
                    && candidate.vertexCount == firstObject.vertexCount
                    && candidate.firstIndex == firstObject.firstIndex
                    && candidate.indexCount == firstObject.indexCount;
            }
            if (!instancedSharedGeometry)
            {
                result.error = "Metal Geometry Core authority does not match the retained instance scene";
                return result;
            }
            instancedSharedGeometry = scene->objectCount>1;
            for (std::size_t index=0;index<scene->objectCount;++index) {
                const auto appearance=videowire::geometry::instanceAppearance(
                    frameAttributes ? *frameAttributes : geometryAdmission->value().descriptor().attributes,index);
                if (appearance.color[3]<1.0f || appearance.metallic>=0 || appearance.roughness>=0)
                    instancedSharedGeometry=false;
            }
        }
        const bool materialKindValid = materialProgram == nullptr
            || validNativeFixtureMaterialPrograms(*materialProgram, *scene, NativeFixtureMaterialBackend::Metal, metalSpectralConsumerAvailable(),diffractionConsumer);
        if (materialProgram != nullptr
            && (materialProgram->layoutVersion
                    != NativeFixtureSurfaceMaterialProgram::kLayoutVersion
                || materialProgram->backend != NativeFixtureMaterialBackend::Metal
                || materialProgram->programIdentity.empty()
                || materialProgram->bindingDigest.empty()
                || (materialProgram->vertexProgram
                    && (materialProgram->kind != NativeFixtureMaterialKind::SurfacePbr
                        || scene->objectCount != 1
                        || materialProgram->vertexProgram->programIdentity() != materialProgram->programIdentity))
                || ! materialKindValid))
        {
            result.error = "Metal fixture preparation requires an exact bounded material binding";
            return result;
        }
        if (!nativeObjectInstancesSupported(*scene, materialProgram.get(),
