                sg_image_desc textureDesc = {};
                textureDesc.width = static_cast<int> (layout.levels[0].width);
                textureDesc.height = static_cast<int> (layout.levels[0].height);
                textureDesc.num_mipmaps = static_cast<int> (layout.levelCount);
