            shaderDesc.views[5].texture.sample_type=SG_IMAGESAMPLETYPE_UNFILTERABLE_FLOAT;
            shaderDesc.views[5].texture.msl_texture_n=5;
            shaderDesc.views[6].texture.stage=SG_SHADERSTAGE_FRAGMENT;
            shaderDesc.views[6].texture.image_type=SG_IMAGETYPE_2D;
            shaderDesc.views[6].texture.sample_type=SG_IMAGESAMPLETYPE_UNFILTERABLE_FLOAT;
            shaderDesc.views[6].texture.msl_texture_n=6;
            shaderDesc.views[7].texture.stage=SG_SHADERSTAGE_FRAGMENT;
            shaderDesc.views[7].texture.image_type=SG_IMAGETYPE_2D;
            shaderDesc.views[7].texture.sample_type=SG_IMAGESAMPLETYPE_UNFILTERABLE_FLOAT;
            shaderDesc.views[7].texture.msl_texture_n=7;
