                shaderDesc.views[slot].texture.image_type=SG_IMAGETYPE_2D;
                shaderDesc.views[slot].texture.sample_type=SG_IMAGESAMPLETYPE_UNFILTERABLE_FLOAT;
                shaderDesc.views[slot].texture.msl_texture_n=slot;
            }
            shaderDesc.label = "arbit-metal-fixture-shader";
            resources->shader = sg_make_shader (&shaderDesc);
            if(sourceCreation) {
                if(!resourceValid(sg_query_shader_state(resources->shader)))
                    return fail("Metal fixture shader creation failed: "+lastSokolLog());
                sourceCreation->shader=resources->shader;
                const auto owners=sg_mtl_query_shader_info(resources->shader);
                sourceCreation->nativeOwners={(__bridge id)owners.vertex_lib,(__bridge id)owners.fragment_lib,
