                const auto* actualFragment=shaderDesc.fragment_func.source;
                const auto* entry=std::strstr(actualFragment,"fragment FragmentOut _main");
                std::string receiptSource(actualFragment,entry-actualFragment);
                receiptSource += R"METAL(
struct RoughReceiptOut {
    float4 terminal [[color(0)]];
    float4 masked [[color(1)]];
    float4 tail [[color(2)]];
};
fragment RoughReceiptOut roughReceiptMain(VertexOut in [[stage_in]],
    texture2d<float> opaqueTexture [[texture(5)]],
    texture2d<float> glassTexture [[texture(6)]],
    texture2d<float> environmentTexture [[texture(7)]],
    constant Uniforms& u [[buffer(0)]]) {
    RoughReceiptOut out;
    float3 terminal, masked, tail;
    int status, queries, events=0;
    if (u.glassTransport.x > 1.5f)
        roughThinInterfaceTransport(u.cameraTranslation.xyz,in.worldPosition,normalize(in.worldNormal),u.materialParams.y,true,
            terminal,masked,tail,status,queries,u,opaqueTexture,glassTexture,environmentTexture);
    else
        roughCameraTransport(u.cameraTranslation.xyz,in.worldPosition,u.materialParams.y,true,
            in.position.xy+u.roughCameraControl.yz,terminal,masked,tail,status,queries,events,u,opaqueTexture,glassTexture,environmentTexture);
    out.terminal = float4(terminal,float(status));
    out.masked = float4(masked,float(queries));
    out.tail = float4(tail,u.glassTransport.x<1.5f && u.roughCameraControl.x==2.0f?float(events):float(status));
    return out;
}
)METAL";
                if (!compileMetalShaderStage(receiptSource.c_str(), "rough receipt fragment", shaderError, "roughReceiptMain"))
                    return fail(shaderError);
                auto receiptDesc = shaderDesc;
                receiptDesc.fragment_func.source = receiptSource.c_str();
                receiptDesc.fragment_func.entry = "roughReceiptMain";
                for (auto& view : receiptDesc.views) view = {};
                for (auto& sampler : receiptDesc.samplers) sampler = {};
                for (auto& pair : receiptDesc.texture_sampler_pairs) pair = {};
                for (int slot = 5; slot < 8; ++slot) receiptDesc.views[slot] = shaderDesc.views[slot];
                receiptDesc.label = "arbit-metal-rough-glass-receipt-shader";
                resources->roughReceiptShader = sg_make_shader(&receiptDesc);
                if (!resourceValid(sg_query_shader_state(resources->roughReceiptShader)))
                    return fail("Metal rough glass receipt shader creation failed: " + lastSokolLog());
            }

            prepareStageScope.reset();
            prepareStageScope.emplace ("metal:fixture-scene-pipeline-create");
            sg_pipeline_desc pipelineDesc = {};
            pipelineDesc.shader = resources->shader;
            pipelineDesc.layout.buffers[0].stride = sizeof (SceneVertex);
            pipelineDesc.layout.attrs[0] = {
                0, static_cast<int> (offsetof (SceneVertex, position)), SG_VERTEXFORMAT_FLOAT3 };
            pipelineDesc.layout.attrs[1] = {
                0, static_cast<int> (offsetof (SceneVertex, normal)), SG_VERTEXFORMAT_FLOAT3 };
            pipelineDesc.layout.attrs[2] = {
                0, static_cast<int> (offsetof (SceneVertex, uv)), SG_VERTEXFORMAT_FLOAT2 };
            pipelineDesc.layout.attrs[3] = {
                0, static_cast<int> (offsetof (SceneVertex, color)), SG_VERTEXFORMAT_FLOAT4 };
            pipelineDesc.layout.attrs[4] = {
                0, static_cast<int> (offsetof (SceneVertex, tangent)), SG_VERTEXFORMAT_FLOAT4 };
            pipelineDesc.layout.buffers[1].stride = sizeof (MetalFixtureInstanceGpuRecord);
            pipelineDesc.layout.buffers[1].step_func = SG_VERTEXSTEP_PER_INSTANCE;
            for (int column = 0; column < 4; ++column)
                pipelineDesc.layout.attrs[5 + column] = {
                    1, column * 4 * static_cast<int> (sizeof (float)), SG_VERTEXFORMAT_FLOAT4 };
            pipelineDesc.layout.attrs[9] = {
                1, static_cast<int> (offsetof (MetalFixtureInstanceGpuRecord, identityColor)),
