        auto& factory=r->privateSurfaceFactoryJournal[factoryAttempt];
        factory=setupEntry(4*sizeof(MetalFixtureSceneResources)+4*sizeof(std::shared_ptr<MetalPrivateSurfaceCreation>));
        factory.arithmetic=factory.comparisons=factory.writes=multiply(64,setupEntryOperations);
