        if(selected==r->materialProgram->objectPrograms.end()||!object||(*selected)->kind!=NativeFixtureMaterialKind::SurfacePbr
            ||(*selected)->vertexProgram||(*selected)->authoredMaterial!=object->material||(*selected)->parameters.normalOpacity[3]!=1
            ||(*selected)->frameEndpoint||(*selected)->importedBaseColorTexture||!(*selected)->objectPrograms.empty())
