        candidate->parent=r.get();candidate->generation=r->rendererGeneration;candidate->parentBytes=parentBytes;
        candidate->scene=r->snapshot;candidate->root=r->materialProgram;candidate->selected=*selected;candidate->grating=r->discreteGratingProgram;candidate->selection=r->smoothGlass.distinctGrating;
        candidate->receiver=receiver;candidate->material=object->material;candidate->vertex=r->vertexBuffer;candidate->index=r->indexBuffer;
        candidate->identityBytes=identityBytes;
