bool readMetalRoughGlassReceipt(
    const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    std::array<NativeRawPassPixels, 3>& receipts,
    NativeRawPassPixels& objectIds, NativeRawPassPixels& materialIds, std::string& error)
{
    receipts = {}; objectIds = {}; materialIds = {};
    std::lock_guard<std::mutex> lock(sokolMutex());
    const auto frame = std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);
    if (!frame || !frame->roughReceiptValidated) {
        error = "Metal rough glass diagnostic requires a validated owning frame";
        return false;
    }
    if (!frame->readRoughReceiptOwned(receipts,error)
        || !frame->readRawPassOwned(renderpassoutput::Output::ObjectId,objectIds,error)
        || !frame->readRawPassOwned(renderpassoutput::Output::MaterialId,materialIds,error)) {
        receipts = {}; objectIds = {}; materialIds = {};
        return false;
    }
    return true;
}

NativeFixtureSceneSubmission renderMetalRoughGlassTiledFrame(
