}

bool readMetalRoughGlassTileAggregate(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    std::shared_ptr<const roughglasstiles::Schedule>& schedule,roughglasstiles::Aggregate& aggregate,std::string& error)
{
    std::lock_guard<std::mutex> lock(sokolMutex());
    const auto frame=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);
    if(!frame || !frame->roughTilesComplete || !frame->roughReceiptValidated || !frame->roughTileSchedule
        ||!frame->staticResources||frame->rendererGeneration_!=frame->staticResources->rendererGeneration
        ||frame->roughReceiptProgram!=frame->staticResources->materialProgram
        ||frame->roughReceiptInputs!=frame->roughTileSchedule->key().runtime
        ||frame->roughTileSchedule->key().owner.get()!=frame->staticResources.get()) {
        error="Metal rough tile diagnostic requires a completed exact native frame owner";return false;
    }
    schedule=frame->roughTileSchedule;aggregate=frame->roughTileAggregate;error.clear();return true;
}

// Read-only admission arithmetic over completed native selections. This does
// not execute transport or create a synthetic native receipt.
bool metalSelectedRoughBudgetGuardForFixture(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,std::string& error)
{
    std::lock_guard<std::mutex> lock(sokolMutex());
    const auto frame=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);
    if(!frame||!frame->selectedRough||!frame->roughTilesComplete||!frame->roughReceiptValidated) {
        error="Metal selected budget fixture requires a completed owning native frame";return false;
    }
    const auto& state=*frame->selectedRough;
    if(!state.completed||state.completedCommand.status!=MTLCommandBufferStatusCompleted
        ||state.schedule!=frame->roughTileSchedule||state.queue!=(__bridge id<MTLCommandQueue>)sg_mtl_command_queue()) {
        error="Metal selected budget fixture has stale completed selection ownership";return false;
    }
    const auto volume=state.schedule->prepared().object.value;
    const auto first=std::find_if(state.selections.begin(),state.selections.end(),[&](const auto& selection) {
        return selection.state[0]==1&&selection.ids[0]==volume;
    });
    if(first==state.selections.end()) {error="Metal selected budget fixture requires actual native glass selection";return false;}
    const auto begin=std::size_t(first-state.selections.begin());std::size_t end=begin;
    std::string refused;
    const auto ceiling=smoothglass::kMaximumCameraMicroWork,cost=smoothglass::kMaximumCameraPixelMicroWork;
    // Less than one worst-case invocation left, including a subsequent tile
    // after the whole frame reaches its ceiling, must refuse before dispatch.
    for(const auto completed:{ceiling-cost+1,ceiling,ceiling+1}) {
        if(metalSelectedRoughRange(state.selections,volume,begin,completed,end,refused)||end!=begin
            ||refused.find("Metal selected camera whole-frame")!=0) {
            error="Metal selected budget admitted transport without its full remaining work reserve";return false;
        }
    }
    if(!metalSelectedRoughRange(state.selections,volume,begin,ceiling-cost,end,error))return false;
    std::uint64_t starts=0;
    for(auto pixel=begin;pixel<end;++pixel)
        starts+=state.selections[pixel].state[0]==1&&state.selections[pixel].ids[0]==volume?1u:0u;
    if(starts!=1 || std::memcmp(state.work.contents,state.nativeWork.data(),state.nativeWork.size()*sizeof(MetalSelectedRoughCamera::Work))!=0) {
        error="Metal selected budget range changed completed native Work or reserved multiple starts";return false;
    }
    error.clear();return true;
}

bool prepareMetalGlassCaustic(const std::shared_ptr<const NativeFixtureSceneResources>& owner,
    HarmonicMIDI::grid::SceneLightId source,const glasscaustics::AdmittedBranchPolicy& policy,
    glasscaustics::Prepared& prepared,std::string& error)
{
    std::lock_guard<std::mutex> lock(sokolMutex());
    const auto resources=std::dynamic_pointer_cast<const MetalFixtureSceneResources>(owner);
    if(!resources || !resources->rendererGeneration || !resources->smoothGlass.enabled
        || resources->instancedSharedGeometry
        || resources->smoothGlass.sourceScene!=resources->snapshot
        || resources->smoothGlass.sourceMaterial!=resources->materialProgram) {
        error="Metal caustic preparation requires retained glass scene resources";return false;
    }
    glasscaustics::Prepared candidate;
    if(!glasscaustics::consumerCanRender(metalGlassCausticConsumerContract(),NativeFixtureMaterialBackend::Metal,
        resources->smoothGlass.roughness)) {error="Metal caustic native consumer contract is unavailable";return false;}
    if(!glasscaustics::prepare(resources->smoothGlass,source,policy,candidate,error)) return false;
    // Shared re-admission checked snapshot contents. Keep the equivalent native
    // immutable owners so raster, query, source and readback have one lifetime.
    candidate.glass.sourceScene=resources->snapshot;candidate.glass.sourceMaterial=resources->materialProgram;
    prepared=std::move(candidate);error.clear();return true;
}

NativeFixtureScenePreparation prepareMetalGlassGratingResources(
    const std::shared_ptr<const HarmonicMIDI::grid::Visual3DScene>& scene,
    const std::shared_ptr<const NativeFixtureSurfaceMaterialProgram>& root,
    const smoothglass::DistinctGratingAdmission& admission,
    const std::shared_ptr<const NativeFixtureSurfaceMaterialProgram>& originalCompiledLeaf)
{
    auto& backend=static_cast<MetalFixtureSceneBackend&>(nativeFixtureSceneBackend());
    return backend.prepareGrating(scene,root,admission,originalCompiledLeaf);
}

// Fixture-only ownership inspection. Pending camera storage contains no image
// receipt until the exact discrete camera material evaluator completes a draw.
bool inspectMetalGlassGratingCameraAllocationForFixture(
    const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const std::shared_ptr<const glasscaustics::GratingIncidentBinding>& binding,std::string& error)
{
    std::lock_guard<std::mutex> lock(sokolMutex());
    const auto frame=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);
    const auto refuse=[&](){error="Metal mixed pending camera allocation has no exact private owner";return false;};
    if(!frame||!frame->caustic||!binding||!frame->staticResources||!frame->privateCameraAttachments
        ||!frame->caustic->gratingStagingCompleted||frame->caustic->cameraBaseComplete||frame->caustic->cameraSubmission
        ||!frame->caustic->cameraInputs||!frame->caustic->cameraBinding
        ||frame->caustic->cameraBinding->identity!=binding->identity
        ||frame->caustic->identity.completedFence!=frame->caustic->submission
        ||frame->rendererGeneration_!=frame->staticResources->rendererGeneration
        ||frame->caustic->cameraInputs->timeSeconds!=float(binding->evaluationTime)
        ||binding->prepared.glass.sourceScene!=frame->staticResources->snapshot
        ||binding->prepared.glass.sourceMaterial!=frame->staticResources->materialProgram
        ||frame->width_!=binding->frame.width||frame->height_!=binding->frame.height
        ||frame->colorImageHandle()||frame->depthImageHandle()||frame->colorTextureDescriptor().complete()
        ||frame->depthTextureDescriptor().complete()
        ||frame->depthStencilImage.id==frame->caustic->rasterDepthStencil.id)return refuse();
    const auto attachment=[&](sg_image image,sg_view view,sg_pixel_format format) {
        if(!image.id||!view.id||!resourceValid(sg_query_image_state(image))||!resourceValid(sg_query_view_state(view)))return false;
        const auto desc=sg_query_image_desc(image);const auto textureView=sg_query_view_desc(view);
        const auto native=sg_mtl_query_image_info(image);
        id<MTLTexture> texture=native.active_slot>=0&&native.active_slot<SG_NUM_INFLIGHT_FRAMES
            ?(__bridge id<MTLTexture>)native.tex[native.active_slot]:nil;
        return desc.width==int(frame->width_)&&desc.height==int(frame->height_)&&desc.sample_count==1
            &&desc.pixel_format==format&&textureView.texture.image.id==image.id
            &&texture!=nil&&texture.device==gMetalDevice&&texture.width==frame->width_&&texture.height==frame->height_;
    };
    if(!attachment(frame->colorImage,frame->colorTextureView,SG_PIXELFORMAT_RGBA16F)
        ||!attachment(frame->depthImage,frame->depthTextureView,SG_PIXELFORMAT_R32F)
        ||!attachment(frame->diffractionAccumulationImage,frame->diffractionAccumulationTextureView,SG_PIXELFORMAT_RGBA16F))return refuse();
    const std::array<sg_pixel_format,6> formats{SG_PIXELFORMAT_RGBA16F,SG_PIXELFORMAT_RGBA16F,
        SG_PIXELFORMAT_R8,SG_PIXELFORMAT_R32UI,SG_PIXELFORMAT_R32UI,SG_PIXELFORMAT_RG16F};
    for(unsigned i=0;i<formats.size();++i)
        if(!attachment(frame->rawImages[i],frame->rawTextureViews[i],formats[i]))return refuse();
    error.clear();return true;
}

static bool encodeMetalDirectionalSourceUpload(MetalFixtureSceneFrame& frame,id<MTLCommandBuffer> command,std::string& error)
{
    auto& state=*frame.caustic;
    const auto source=arbitgpu::metalcaustic::directionalIrradianceShader(arbitgpu::metalcaustic::shader(false));
    if(source.empty()){error="Metal directional upload authority extraction is incomplete";return false;}
    NSError* nativeError=nil;MTLCompileOptions* options=[[MTLCompileOptions alloc] init];options.fastMathEnabled=NO;
    state.library=[gMetalDevice newLibraryWithSource:[NSString stringWithUTF8String:source.c_str()] options:options error:&nativeError];
#if ! __has_feature(objc_arc)
    [options release];
#endif
    if(state.library==nil){error="Metal directional upload shader failed: "+std::string(nativeError.localizedDescription.UTF8String?:"unknown");return false;}
    id<MTLFunction> function=[state.library newFunctionWithName:@"causticDirectionalUpload"];
    state.trace=function?[gMetalDevice newComputePipelineStateWithFunction:function error:&nativeError]:nil;
#if ! __has_feature(objc_arc)
    [function release];
#endif
    id<MTLComputeCommandEncoder> encoder=state.trace!=nil?[command computeCommandEncoder]:nil;
    if(encoder==nil){error="Metal directional upload pipeline is unavailable";return false;}
    [encoder setComputePipelineState:state.trace];[encoder setBytes:&state.params length:sizeof(state.params) atIndex:0];
    [encoder setBuffer:state.directionalInput offset:0 atIndex:14];[encoder setBuffer:state.directionalEcho offset:0 atIndex:15];
    [encoder dispatchThreads:MTLSizeMake(1,1,1) threadsPerThreadgroup:MTLSizeMake(1,1,1)];[encoder endEncoding];return true;
}

static bool stageMetalGlassGratingFrameBound(const std::shared_ptr<const NativeFixtureSceneResources>& owner,
    HarmonicMIDI::grid::SceneLightId source,const glasscaustics::AdmittedBranchPolicy& policy,
    std::uint32_t width,std::uint32_t height,NativeFixtureSceneRuntimeInputs runtime,double capturedTime,
    std::shared_ptr<const NativeFixtureSceneFrame>& frameOut,
    std::shared_ptr<const glasscaustics::GratingIncidentBinding>& bindingOut,std::string& error,
    glasscaustics::SchedulingDescription scheduling,
    const std::shared_ptr<const glasscaustics::GratingIncidentBinding>& frozen={})
{
    using namespace HarmonicMIDI::grid;
    if(runtime.objectWorlds){error="Metal static local object worlds do not yet admit diffraction gratings";return false;}
    glasscaustics::Prepared prepared;
    if(!prepareMetalGlassCaustic(owner,source,policy,prepared,error))return false;
    std::unique_lock<std::mutex> lock(sokolMutex());
    const auto resources=std::dynamic_pointer_cast<const MetalFixtureSceneResources>(owner);
    const auto refuse=[&](const char* message){error=message;return false;};
    if(!resources||!resources->discreteGratingProgram||!prepared.glass.distinctGrating
        ||!validFixtureRuntimeInputs(runtime)||!runtime.linearColor||runtime.imageOutput!=renderpassoutput::Output::Color
        ||runtime.rawExportMask||runtime.passProgram||!std::isfinite(capturedTime)||runtime.timeSeconds!=float(capturedTime)
        ||runtime.canonicalBlockCFrame||runtime.noteInstanceMapping
        ||runtime.materialFrameTexture||!runtime.materialFrameTextures.empty()||runtime.passComposite||runtime.previousMotion
        ||runtime.diffractionSourceProgram||runtime.diffractionEvaluatedProgram||runtime.lightOverride||!runtime.animatedLights.empty()
        ||!nativeFixtureDimensionsWithinBounds(width,height)||width>std::uint32_t(sg_query_limits().max_image_size_2d)
        ||height>std::uint32_t(sg_query_limits().max_image_size_2d))
        return refuse("Metal private mixed staging requires exact static resources and bounded runtime inputs");
    if(resources->privateSurfaceCreation&&!inspectMetalPrivateSurfaceCreationUnlocked(*resources,*resources->privateSurfaceCreation,error)) return false;
    const auto& scene=*resources->snapshot;
    if(scene.instancedObject.isValid())
        return refuse("Metal glass grating staging does not support instanced Solid 3D bodies");
    std::vector<opaquevisibility::Instance> instances;
    for(std::size_t o=0;o<scene.objectCount;++o) {
        SceneTransform3D transform{};
        if(runtimeTargetsObject(runtime,scene.objects[o])) {
            transform.translation={runtime.objectTranslationOffset[0],runtime.objectTranslationOffset[1],runtime.objectTranslationOffset[2]};
            transform=applyRuntimeObjectTransform(transform,runtime.objectRotationDegrees,runtime.objectScale);
        }
        instances.push_back({multiplyMetalFixtureMatrices(metalFixtureTransformMatrix(transform),
            metalFixtureWorldMatrix(scene,scene.objects[o])),o});
    }
    glasscaustics::Frame schedule;
    if(!glasscaustics::buildGratingStagingFrame(prepared,instances,&runtime,width,height,scheduling,schedule,error))return false;
    const bool directional=schedule.sourceDirectionalIrradiance.version!=0;
    const auto sourceUse=directional?glasscaustics::SourceMeasureUse::DirectionalIrradiancePreparation:glasscaustics::SourceMeasureUse::LegacyNative;
    std::shared_ptr<const glasscaustics::GratingIncidentBinding> binding;
    if(!glasscaustics::prepareGratingIncidentBinding(prepared,schedule,resources->discreteGratingProgram,
        prepared.glass.distinctGrating->material,capturedTime,binding,error,sourceUse))return false;
    if(frozen) {
        std::string actual,expected;
        if(binding->identity!=frozen->identity
            ||!glasscaustics::directGratingCommonIdentity(*binding,actual,error)
            ||!glasscaustics::directGratingCommonIdentity(*frozen,expected,error)||actual!=expected)
            return refuse("Metal directional cohort frozen staging differs from its actual resources");
        prepared=frozen->prepared;schedule=frozen->frame;binding=frozen;
    }
    if(schedule.query.height>std::size_t(sg_query_limits().max_image_size_2d)
        ||opaquevisibility::kTextureWidth>std::size_t(sg_query_limits().max_image_size_2d))
        return refuse("Metal mixed query staging exceeds native texture limits");
    const auto pixels=std::uint64_t(width)*height;
    const auto paddedQuery=std::uint64_t(opaquevisibility::kTextureWidth)*schedule.query.height*16;
    const auto rasterDraws=std::count_if(schedule.instances.begin(),schedule.instances.end(),
        [&](const auto& instance){return scene.objects[instance.object].indexCount!=0;});
    MetalRasterCaptureBudget rasterCaptureBudget;
    if(!metalRasterCaptureBudget(*resources,schedule,runtime,1,rasterDraws,rasterCaptureBudget,error))return false;
    // Re-admission/binding copies retain fixed Scene arrays and owned texture
    // payloads. Reserve their bounded copies before native allocation.
    const auto scenePayload=sizeof(Visual3DScene)+Visual3DScene::kMaxTextureTexels*sizeof(SceneTexelRgba8);
    std::uint64_t host=rasterCaptureBudget.host+8*scenePayload+128*1024+sizeof(MetalFixtureSceneResources)+sizeof(MetalFixtureSceneFrame)
        +sizeof(MetalCausticState)+sizeof(NativeFixtureSceneRuntimeInputs)+scene.objectCount*(sizeof(FixtureUniforms)+sizeof(sg_bindings))
        +(resources->opaqueVisibility.texels.capacity()+4*resources->smoothGlass.query.texels.capacity())*16
        +(resources->opaqueVisibility.meshes.capacity()+4*resources->smoothGlass.query.meshes.capacity())*sizeof(opaquevisibility::Mesh)
        +2*paddedQuery+2*binding->bounds.bytes+schedule.bounds.transientBytes
        +(directional?4*metalcaustic::shader(false).size()+sizeof(glasscaustics::NativeDirectionalSourceEcho):0);
    const auto chargeProgram=[&](const auto& program) {
        if(!program)return;
        host+=sizeof(NativeFixtureSurfaceMaterialProgram)+program->programIdentity.capacity()+program->bindingDigest.capacity()
            +program->diffractionProductDigest.capacity()
            +program->objectPrograms.capacity()*sizeof(std::shared_ptr<const NativeFixtureSurfaceMaterialProgram>);
    };
    chargeProgram(resources->materialProgram);chargeProgram(resources->discreteGratingProgram);
    for(const auto& child:resources->materialProgram->objectPrograms)chargeProgram(child);
    if(resources->privateSurfaceAdmission) host=surfacesource::add(host,resources->privateSurfaceAdmission->bytes());
    // Query/raster28 plus the released camera attachments57 bytes per pixel.
    const auto nativeEstimate=rasterCaptureBudget.native+resources->permanentBytes+pixels*(28+57)+paddedQuery
        +(schedule.workTexels.size()+schedule.triangleTexels.size())*16
        +(directional?glasscaustics::kDirectionalSourceInputBytes+glasscaustics::kDirectionalSourceEchoBytes:0);
    if(host>renderpassoutput::kMaximumTotalBytes||nativeEstimate>renderpassoutput::kMaximumTotalBytes-host)
        return refuse("Metal mixed staging retained owners and native storage exceed frame budget");
    auto frame=std::make_shared<MetalFixtureSceneFrame>();
    frame->width_=width;frame->height_=height;frame->rendererGeneration_=resources->rendererGeneration;
    frame->staticResources=resources;frame->privateCameraAttachments=true;
    frame->caustic=std::make_unique<MetalCausticState>();
    auto& state=*frame->caustic;state.prepared=std::move(prepared);state.schedule=std::move(schedule);
    state.submission=nextMetalRendererGeneration();initializeMetalCausticParams(*frame);
    state.cameraBinding=binding;
    const auto fail=[&](const char* message){frame->destroyUnlocked();return refuse(message);};
    if(!prepareMetalRasterCapture(*frame,runtime,1,rasterDraws,rasterCaptureBudget,error)) {
        frame->destroyUnlocked();return false;
    }
    if(!prepareMetalFixtureCameraAttachments(*frame,true,true,error)){frame->destroyUnlocked();return false;}
    sg_image_desc depth={};depth.width=width;depth.height=height;depth.sample_count=1;
    depth.pixel_format=SG_PIXELFORMAT_DEPTH_STENCIL;depth.usage.depth_stencil_attachment=true;
    state.rasterDepthStencil=sg_make_image(&depth);
    sg_view_desc view={};view.depth_stencil_attachment.image=state.rasterDepthStencil;
    state.rasterDepthStencilView=sg_make_view(&view);
    if(!resourceValid(sg_query_image_state(state.rasterDepthStencil))||!resourceValid(sg_query_view_state(state.rasterDepthStencilView)))
        return fail("Metal mixed staging depth allocation failed");
    state.rasterDepthStencilCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,metalImageBytes(depth));
    if(!prepareMetalCausticRaster(*frame,error,true)){frame->destroyUnlocked();return false;}
    const auto buffer=[&](const auto& values)->id<MTLBuffer> {
        const auto bytes=values.size()*sizeof(values[0]);
        return bytes&&bytes<=gMetalDevice.maxBufferLength
            ?[gMetalDevice newBufferWithBytes:values.data() length:bytes options:MTLResourceStorageModeShared]:nil;
    };
    state.work=buffer(state.schedule.workTexels);state.triangles=buffer(state.schedule.triangleTexels);
    if(directional) {
        const auto input=glasscaustics::directionalSourceInput(state.prepared,state.schedule);
        state.directionalInput=[gMetalDevice newBufferWithBytes:&input length:sizeof(input) options:MTLResourceStorageModeShared];
        state.directionalEcho=[gMetalDevice newBufferWithLength:sizeof(glasscaustics::NativeDirectionalSourceEcho) options:MTLResourceStorageModeShared];
        if(state.directionalInput==nil||state.directionalEcho==nil||!state.directionalInput.contents||!state.directionalEcho.contents)
            return fail("Metal directional upload storage allocation failed");
        state.directionalInputCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,arbitgpu::residency::nominalBufferBytes(state.directionalInput.length));
        state.directionalEchoCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,arbitgpu::residency::nominalBufferBytes(state.directionalEcho.length));
        std::memset(state.directionalEcho.contents,0,state.directionalEcho.length);
    }
    MTLTextureDescriptor* query=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA32Float
        width:opaquevisibility::kTextureWidth height:state.schedule.query.height mipmapped:NO];
    query.usage=MTLTextureUsageShaderRead;query.storageMode=MTLStorageModeShared;
    state.query=[gMetalDevice newTextureWithDescriptor:query];
    if(state.work==nil||state.triangles==nil||state.query==nil)return fail("Metal mixed staging query storage allocation failed");
    state.workBufferCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,arbitgpu::residency::nominalBufferBytes(state.work.length));
    state.trianglesBufferCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,arbitgpu::residency::nominalBufferBytes(state.triangles.length));
    state.queryTextureCharge=arbitgpu::residency::ResidencyCharge(arbitgpu::residency::BackingClass::roughCausticTile,arbitgpu::residency::nominalTextureBytes(query.width,query.height,1,1,16,1));
    // Charge every retained native slot at its actual aligned allocation size.
    std::uint64_t native=0;std::vector<const void*> seen;
    seen.reserve(128+resources->textureImages.size()*SG_NUM_INFLIGHT_FRAMES+6*state.rasterCaptureCandidate->passes.size());
    if(seen.capacity()>2*(128+resources->textureImages.size()*SG_NUM_INFLIGHT_FRAMES+6*state.rasterCaptureCandidate->passes.size()))
        return fail("Metal raster native inspector capacity exceeds reservation");
    const auto charge=[&](id value,std::uint64_t bytes) {
        if(value==nil)return true;const void* identity=(__bridge const void*)value;
        if(std::find(seen.begin(),seen.end(),identity)!=seen.end())return true;
        if(bytes>renderpassoutput::kMaximumTotalBytes-host-native)return false;
        if(seen.size()==seen.capacity())return false;
        seen.push_back(identity);native+=bytes;return true;
    };
    const auto chargeImage=[&](sg_image image) {
        if(!image.id)return true;const auto info=sg_mtl_query_image_info(image);
        for(int i=0;i<SG_NUM_INFLIGHT_FRAMES;++i) {
            id<MTLTexture> texture=(__bridge id<MTLTexture>)info.tex[i];
            if(texture!=nil&&!charge(texture,texture.allocatedSize))return false;
        }return true;
    };
    const auto chargeBuffer=[&](sg_buffer input) {
        if(!input.id)return true;const auto info=sg_mtl_query_buffer_info(input);
        for(int i=0;i<SG_NUM_INFLIGHT_FRAMES;++i) {
            id<MTLBuffer> value=(__bridge id<MTLBuffer>)info.buf[i];
            if(value!=nil&&!charge(value,std::max<std::uint64_t>(value.length,value.allocatedSize)))return false;
        }return true;
    };
    if(!chargeMetalRasterCaptureNative(state,charge)||!charge(state.query,state.query.allocatedSize)
        ||!charge(state.work,std::max<std::uint64_t>(state.work.length,state.work.allocatedSize))
        ||!charge(state.triangles,std::max<std::uint64_t>(state.triangles.length,state.triangles.allocatedSize))
        ||!charge(state.directionalInput,std::max<std::uint64_t>(state.directionalInput.length,state.directionalInput.allocatedSize))
        ||!charge(state.directionalEcho,std::max<std::uint64_t>(state.directionalEcho.length,state.directionalEcho.allocatedSize))
        ||!chargeImage(state.rasterDepthStencil)||!chargeImage(state.rasterImages[0])||!chargeImage(state.rasterImages[1]))
        return fail("Metal mixed staging aligned native allocation exceeds frame budget");
    for(auto image:{frame->colorImage,frame->depthImage,frame->depthStencilImage,frame->diffractionAccumulationImage})
        if(!chargeImage(image))return fail("Metal mixed pending camera storage exceeds frame budget");
    for(auto image:frame->rawImages)
        if(!chargeImage(image))return fail("Metal mixed pending raw attachments exceed frame budget");
    for(auto image:resources->textureImages)if(!chargeImage(image))return fail("Metal mixed staging retained texture exceeds frame budget");
    if(!chargeImage(resources->environmentTexture))return fail("Metal mixed staging environment exceeds frame budget");
    for(auto input:{resources->vertexBuffer,resources->previousVertexBuffer,resources->indexBuffer,resources->geometryInstanceBuffer})
        if(!chargeBuffer(input))return fail("Metal mixed staging retained geometry exceeds frame budget");
    state.bytes=state.metrics.admittedBytes=host+native;
    state.metrics.retainedNativeBytes=state.metrics.peakNativeBytes=native;
    std::vector<opaquevisibility::Texel> padded(std::size_t(opaquevisibility::kTextureWidth)*state.schedule.query.height);
    std::copy(state.schedule.query.texels.begin(),state.schedule.query.texels.end(),padded.begin());
    [state.query replaceRegion:MTLRegionMake2D(0,0,opaquevisibility::kTextureWidth,state.schedule.query.height)
        mipmapLevel:0 withBytes:padded.data() bytesPerRow:opaquevisibility::kTextureWidth*16];
    sg_pass pass={};pass.attachments.colors[0]=state.rasterViews[0];pass.attachments.colors[1]=state.rasterViews[1];
    for(unsigned i=0;i<2;++i){pass.action.colors[i].load_action=SG_LOADACTION_CLEAR;pass.action.colors[i].store_action=SG_STOREACTION_STORE;}
    pass.attachments.depth_stencil=state.rasterDepthStencilView;pass.action.depth.load_action=SG_LOADACTION_CLEAR;
    pass.action.depth.clear_value=1;pass.action.depth.store_action=SG_STOREACTION_STORE;
    pass.action.stencil.load_action=SG_LOADACTION_DONTCARE;pass.action.stencil.store_action=SG_STOREACTION_DONTCARE;
    sg_begin_pass(&pass);sg_apply_pipeline(state.rasterPipelines[0]);
    if(!beginMetalRasterCapture(*frame,0,pass,{0,0,int(width),int(height)},error)) {
        sg_end_pass();frame->destroyUnlocked();return false;
    }
    FixtureUniforms uniforms{};uniforms.noteMeshScale[0]=1;uniforms.geometryInstanceControl[3]=1;
    const auto& camera=state.schedule.camera;const auto& rotation=camera.transform.rotation;
    storeVec3(uniforms.cameraTranslation,camera.transform.translation,0);
    const float quaternion[]={rotation.x,rotation.y,rotation.z,rotation.w};std::copy_n(quaternion,4,uniforms.cameraRotation);
    std::copy(state.params.projection.begin(),state.params.projection.end(),uniforms.projection);
    for(std::size_t o=0;o<scene.objectCount;++o) {
        const auto& object=scene.objects[o];
        uniforms.rawIdentifiers[o][0]=float(object.material.value&65535u);uniforms.rawIdentifiers[o][1]=float(object.material.value>>16u);
        uniforms.rawIdentifiers[o][2]=float(object.id.value&65535u);uniforms.rawIdentifiers[o][3]=float(object.id.value>>16u);
    }
    for(const auto& instance:state.schedule.instances) {
        const auto& object=scene.objects[instance.object];uniforms.geometryInstanceControl[2]=std::uint32_t(instance.object);
        std::copy(instance.world.begin(),instance.world.end(),uniforms.objectMatrix);
        sg_bindings bindings={};bindings.vertex_buffers[0]=resources->vertexBuffer;bindings.vertex_buffers[1]=resources->geometryInstanceBuffer;bindings.vertex_buffers[2]=resources->vertexBuffer;
        bindings.vertex_buffer_offsets[0]=bindings.vertex_buffer_offsets[2]=int(object.firstVertex*sizeof(SceneVertex));
        bindings.index_buffer=resources->indexBuffer;bindings.index_buffer_offset=int(object.firstIndex*sizeof(std::uint32_t));
        sg_apply_bindings(&bindings);const sg_range range={&uniforms,sizeof(uniforms)};
        const auto nativeUniformOffset=_sg.mtl.cur_ub_offset;sg_apply_uniforms(0,&range);
        if(!captureMetalRasterDraw(*frame,0,uniforms,nativeUniformOffset,int(object.indexCount),0,error)) {
            sg_end_pass();frame->destroyUnlocked();return false;
        }
        sg_draw(0,int(object.indexCount),1);
    }
    sg_end_pass();
    if(!encodeMetalRasterHistory(*frame,0,error)){frame->destroyUnlocked();return false;}
    sg_commit();
    if(!completeMetalRasterHistory(*frame,0,error)||!sealMetalRasterCapture(*frame,error)){frame->destroyUnlocked();return false;}
    id<MTLCommandQueue> queue=(__bridge id<MTLCommandQueue>)sg_mtl_command_queue();
    id<MTLCommandBuffer> completed=queue!=nil&&queue.device==gMetalDevice?[queue commandBuffer]:nil;
    if(completed==nil)return fail("Metal mixed staging fence queue is unavailable");
    if(directional&&!encodeMetalDirectionalSourceUpload(*frame,completed,error)){frame->destroyUnlocked();return false;}
    [completed commit];[completed waitUntilCompleted];
    if(completed.status!=MTLCommandBufferStatusCompleted)return fail("Metal mixed staging command did not complete");
    if(frozen) {
        state.cohortStagingCommand=completed;
#if ! __has_feature(objc_arc)
        [state.cohortStagingCommand retain];
#endif
    }
    state.identity={state.schedule.identity,frame->rendererGeneration_,state.submission,state.submission,state.submission,state.submission,state.submission};
    if(directional) {
        auto& upload=state.directionalUpload;upload.backend=NativeFixtureMaterialBackend::Metal;
        upload.submission=state.identity;upload.submission.frameIdentity=binding->identity;upload.bindingGeneration=state.submission;
        std::memcpy(&upload.input,state.directionalInput.contents,sizeof(upload.input));upload.complete=true;
        glasscaustics::NativeDirectionalSourceEcho echo;
        std::memcpy(&echo,state.directionalEcho.contents,sizeof(echo));
        auto bound=state.schedule;bound.identity=binding->identity;bound.gratingIncidentBinding=binding;
        if(std::memcmp(&echo.input,&upload.input,sizeof(upload.input))!=0
            ||std::memcmp(echo.rawRadiance.data(),state.params.radiance,sizeof(echo.rawRadiance))!=0
            ||echo.directionTrace!=state.params.source
            ||!glasscaustics::validateDirectionalSourceTables(state.prepared,bound,*frame,error,true)) {
            if(error.empty())error="Metal directional upload echo differs from its exact native input";
            frame->destroyUnlocked();return false;
        }
    }
    state.gratingStagingCompleted=true;
    lock.unlock();
    frameOut=std::move(frame);bindingOut=std::move(binding);error.clear();return true;
}

bool stageMetalGlassGratingFrame(const std::shared_ptr<const NativeFixtureSceneResources>& owner,
    HarmonicMIDI::grid::SceneLightId source,const glasscaustics::AdmittedBranchPolicy& policy,
    std::uint32_t width,std::uint32_t height,NativeFixtureSceneRuntimeInputs runtime,double capturedTime,
    std::shared_ptr<const NativeFixtureSceneFrame>& frame,
    std::shared_ptr<const glasscaustics::GratingIncidentBinding>& binding,std::string& error,
    glasscaustics::SchedulingDescription scheduling)
{
    return stageMetalGlassGratingFrameBound(owner,source,policy,width,height,std::move(runtime),capturedTime,frame,binding,error,scheduling);
}

bool stageMetalDirectGratingIrradianceCohort(const std::shared_ptr<const NativeFixtureSceneResources>& resources,
    const std::shared_ptr<const glasscaustics::DirectGratingIrradianceCohort>& cohort,
    NativeFixtureSceneRuntimeInputs runtime,std::shared_ptr<const NativeFixtureSceneFrame>& output,std::string& error)
{
    if(!cohort||cohort->sources().empty()||!cohort->sources()[0]->prepared.branchPolicy) {
        error="Metal directional cohort has no frozen source roster";return false;
    }
    const auto& source=cohort->sources()[0];std::shared_ptr<const NativeFixtureSceneFrame> staged;
    std::shared_ptr<const glasscaustics::GratingIncidentBinding> binding;
    if(!stageMetalGlassGratingFrameBound(resources,source->prepared.sceneLight,*source->prepared.branchPolicy,
        source->frame.width,source->frame.height,std::move(runtime),source->evaluationTime,staged,binding,error,
        source->frame.scheduling,source))return false;
    std::lock_guard<std::mutex> lock(sokolMutex());
    const auto frame=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(staged);
    frame->caustic->stagedDirectCohort=cohort;output=std::move(staged);error.clear();return true;
}

NativeFixtureSceneSubmission renderMetalGlassCausticFrame(
    const std::shared_ptr<const HarmonicMIDI::grid::Visual3DScene>& scene,
    const std::shared_ptr<const NativeFixtureSceneResources>& resources,
    std::uint32_t width,std::uint32_t height,NativeFixtureSceneRuntimeInputs runtime,
    const glasscaustics::Prepared& prepared,glasscaustics::SchedulingDescription scheduling,
    const glasscaustics::MultipleScatterPolicy* multipleScatterPolicy)
{
    auto& backend=static_cast<MetalFixtureSceneBackend&>(nativeFixtureSceneBackend());
    return backend.renderCaustic(scene,resources,width,height,std::move(runtime),&prepared,scheduling,false,false,multipleScatterPolicy);
}

bool readMetalGlassCausticMetrics(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    MetalGlassCausticMetrics& metrics,std::string& error)
{
    const auto* frame=dynamic_cast<const MetalFixtureSceneFrame*>(owner.get());
    if(!frame||!frame->caustic||!frame->caustic->validated
        ||frame->caustic->identity.completedFence!=frame->caustic->submission
        ||frame->rendererGeneration_!=frame->staticResources->rendererGeneration
        ||frame->caustic->identity.rendererGeneration!=frame->rendererGeneration_) {
        error="Metal caustic metrics require completed owning deposition";return false;
    }
    metrics=frame->caustic->metrics;error.clear();return true;
}

namespace {
std::string metalGratingNativeOrderMath() {
    const std::string native=std::string(kFixtureFragmentShader)+metalSpectralTransportShader();
    const auto extract=[&](const char* begin,const char* end) {
        const auto at=native.find(begin),last=native.find(end,at);
        return at!=std::string::npos&&last!=std::string::npos?native.substr(at,last-at):std::string{};
    };
    const auto substrate=extract("float interfaceReflectance(","float spectralReflectance(");
    const auto profile=extract("float2 complexMultiply(","float diffractionOrderContribution(");
    // Reuse the forward native equation and efficiency block verbatim. Only
    // loop continuation becomes a zero-efficiency return in this callable.
    auto equation=extract("            float2 centre = -incident.xy + float(primary) * wavelength","            const float2 delta = outgoing.xy - centre;");
    if(substrate.empty()||profile.empty()||equation.empty())return {};
    const auto skip=equation.find("if (square >= 1.0f) continue;");
    if(skip==std::string::npos)return {};
    equation.replace(skip,std::strlen("if (square >= 1.0f) continue;"),"if (square >= 1.0f) {direction=float3(0.0f);return 0.0f;}");
    return std::string("constant float pi = 3.14159265358979323846f;\nconstant int profileBinaryRectangular=1,profileSinusoidal=2,profileBlazedSawtooth=3;\n")
        +substrate+profile+R"METAL(
float gratingNativeEfficiency(int primary,float wavelength,float3 incident,constant GParams& u,thread float3& direction) {
    const float4 localGeometry=u.diffractionGeometry,localSecondaryGeometry=float4(0.0f);
    const bool crossedTwoDimensional=false;const int secondary=0,profile=profileBinaryRectangular;
    const float duty=u.diffractionMicrostructure.x;
)METAL"+equation+"direction=float3(centre,z);return efficiency;\n}\n";
}
}

// Called with sokolMutex held, before either native allocation phase.
static bool metalGratingCellIncumbentBytes(const std::shared_ptr<const MetalFixtureSceneFrame>& frame,
    const std::shared_ptr<const glasscaustics::GratingEntryCellBinding>& sourceCells,
    const glasscaustics::NativeReadback& pointOutput,const glasscaustics::NativeGratingCellTransportReadback& output,
    std::uint64_t& retainedCellBytes,std::string& error)
{
    using namespace glasscaustics;
    const auto refuse=[&](const char* message){error=message;return false;};
    const auto maximum=renderpassoutput::kMaximumTotalBytes;
    const auto previousBinding=output.binding;
    const auto oldFrame=previousBinding?std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(previousBinding->nativeOwner):nullptr;
    auto& state=*frame->caustic;
    if(previousBinding&&(!oldFrame||!oldFrame->caustic||!validateGratingCellTransportBinding(*previousBinding,error)
        ||previousBinding->bounds.bytes>maximum||previousBinding->sourceCells->bounds.bytes>maximum
        ||previousBinding->sourceCells->incidentBinding->bounds.bytes>maximum))
        return refuse("Metal supplemental incumbent has no bounded retained native frame owner");
    std::uint64_t incumbentRecords=output.records.capacity()*sizeof(NativeGratingCellTransportRecord);
    for(const auto& record:output.records)for(const auto& path:record.paths)
        incumbentRecords+=path.capacity()*sizeof(NativeGratingCellTraceStep);
    // Caller readbacks own their value vectors even when their shared parents
    // match retained uploads. Copies must be charged while originals are live.
    const auto oldNative=oldFrame&&oldFrame!=frame?oldFrame->caustic->metrics.admittedBytes
        +oldFrame->caustic->cameraPrimitiveBytes+oldFrame->caustic->cellPrimitiveBytes+oldFrame->caustic->coveragePrimitiveBytes
        +oldFrame->caustic->directPrimitiveBytes:0;
    const auto priorSource=previousBinding?previousBinding->sourceCells:nullptr;
    const auto priorSourceBytes=priorSource&&priorSource!=sourceCells&&priorSource!=state.cellSourceUpload.sourceCells
        ?priorSource->bounds.bytes+priorSource->incidentBinding->bounds.bytes:0;
    const auto incumbent=incumbentRecords+oldNative+priorSourceBytes+(previousBinding?previousBinding->bounds.bytes:0);
    const auto directionalBytes=[](const auto& receipt)->std::uint64_t {
        return receipt?sizeof(*receipt)+receipt->potential.capacity()*sizeof(float)+receipt->submission.frameIdentity.capacity():0;
    };
    const auto oldPoint=pointOutput.gratingIncidents;
    const auto oldCamera=pointOutput.gratingCamera;
    const auto pointIncumbent=pointOutput.frameIdentity.capacity()+pointOutput.paths.capacity()*sizeof(NativePathReceipt)
        +pointOutput.deposits.capacity()*sizeof(NativeDeposit)+pointOutput.spectralRadiance.capacity()*sizeof(float)
        +pointOutput.deposition.keys.capacity()*sizeof(DepositionKey)
        +directionalBytes(pointOutput.directionalSource)
        +(oldPoint&&oldPoint!=state.cellSourceUpload.pointReadback?sizeof(*oldPoint)+oldPoint->submission.frameIdentity.capacity()
            +oldPoint->incidents.capacity()*sizeof(NativeGratingIncident)
            +oldPoint->paths.capacity()*sizeof(NativeGratingReadback::WorkReceipt)
            +oldPoint->children.capacity()*sizeof(NativeGratingReadback::ChildReceipt)+directionalBytes(oldPoint->directionalSource):0)
        +(oldCamera?sizeof(*oldCamera)+oldCamera->orders.capacity()*sizeof(NativeGratingCameraReadback::OrderReceipt)
            +oldCamera->submission.frameIdentity.capacity():0);
    const auto sourceBytes=sourceCells==state.cellSourceUpload.sourceCells?0:sourceCells->bounds.bytes;
    retainedCellBytes=sourceBytes+incumbent+pointIncumbent;
    if(retainedCellBytes>maximum)return refuse("Metal cell initial simultaneous incumbents exceed the existing byte cap");
    return true;
}

// Read-only fixture inspection of the same locked production reservation.
bool inspectMetalGlassGratingCellIncumbentBytesForFixture(
    const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const std::shared_ptr<const glasscaustics::GratingEntryCellBinding>& sourceCells,
    const glasscaustics::NativeReadback& point,const glasscaustics::NativeGratingCellTransportReadback& cells,
    std::uint64_t& bytes,std::string& error)
{
    std::lock_guard<std::mutex> lock(sokolMutex());
    const auto frame=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);
    if(!frame||!frame->caustic||!sourceCells||!frame->caustic->cameraBinding
        ||!glasscaustics::validateGratingEntryCellBinding(*sourceCells,frame->caustic->cameraBinding,error)) {
        error="Metal cell reservation inspection requires its exact retained source owner";return false;
    }
    return metalGratingCellIncumbentBytes(frame,sourceCells,point,cells,bytes,error);
}

static bool produceMetalGlassGratingReadback(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const std::shared_ptr<const glasscaustics::GratingIncidentBinding>& binding,
    glasscaustics::NativeGratingReadback& output,glasscaustics::NativeReadback* terminal,
    glasscaustics::EnergyLedger* terminalEnergy,std::string& error,bool cameraPass=false,
    MetalGratingPointNativeInput* cellPoint=nullptr)
{
    std::lock_guard<std::mutex> lock(sokolMutex());
    const auto frame=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);
    const auto refuse=[&](const char* message){error=message;return false;};
    if((cellPoint&&(!terminal||!cellPoint->sourceCells||!cellPoint->incumbentPoint||!cellPoint->incumbentCells))
        ||!frame||!frame->caustic||(!frame->caustic->validated&&!frame->caustic->gratingStagingCompleted)||!binding||!binding->material
        ||!frame->staticResources||frame->rendererGeneration_!=frame->staticResources->rendererGeneration
        ||frame->caustic->identity.completedFence!=frame->caustic->submission
        ||frame->caustic->schedule.identity!=binding->frame.identity||binding->frame.roughness!=0
        ||binding->frame.gratingIncidentBinding||binding->prepared.glass.sourceScene!=frame->staticResources->snapshot
        ||binding->prepared.glass.sourceMaterial!=frame->staticResources->materialProgram)
        return refuse("Metal grating producer requires its exact completed smooth staging owner");
    if(frame->caustic->gratingStagingCompleted
        && (!binding->frame.gratingStaging||!binding->prepared.glass.distinctGrating
            ||!frame->staticResources->discreteGratingProgram
            ||!binding->gratingOwner
            ||binding->gratingOwner->programIdentity!=frame->staticResources->discreteGratingProgram->programIdentity
            ||!frame->privateCameraAttachments||!frame->caustic->cameraInputs||!frame->caustic->cameraBinding
            ||frame->caustic->cameraBinding->identity!=binding->identity
            ||frame->caustic->cameraInputs->timeSeconds!=float(binding->evaluationTime)
            ||frame->caustic->validated))return refuse("Metal mixed staging marker or compiled owner changed");
    std::uint64_t retainedCellBytes=0;
    if(cellPoint&&(!glasscaustics::validateGratingEntryCellBinding(*cellPoint->sourceCells,binding,error)
        ||!metalGratingCellIncumbentBytes(frame,cellPoint->sourceCells,*cellPoint->incumbentPoint,
            *cellPoint->incumbentCells,retainedCellBytes,error)))return false;
    const bool directional=binding->frame.sourceDirectionalIrradiance.version!=0;
    const auto* sourceBinding=directional?static_cast<const glasscaustics::NativeDirectionalSourceBinding*>(frame.get()):nullptr;
    glasscaustics::GratingCameraBounds cameraBounds;
    if(cameraPass&&(!terminal||!directional||!frame->caustic->gratingStagingCompleted
        ||!glasscaustics::calculateGratingCameraBounds(*binding,cameraBounds,error)))
        return refuse("Metal private grating camera requires authored directional D and optional camera admission");
    if(frame->caustic->directWork>glasscaustics::kMaximumQueryWork
        -(cameraPass?cameraBounds.combinedWork:binding->bounds.combinedWork))
        return refuse("Metal grating consumer and retained direct contributions exceed original work");
    if(directional) {
        auto bound=binding->frame;bound.identity=binding->identity;bound.gratingIncidentBinding=binding;
        if(!frame->caustic->gratingStagingCompleted||frame->caustic->directionalInput==nil
            ||!frame->caustic->directionalInput.contents
            ||frame->caustic->directionalInput.length!=sizeof(glasscaustics::NativeDirectionalSourceInput)
            ||std::memcmp(frame->caustic->directionalInput.contents,&frame->upload().input,sizeof(frame->upload().input))!=0)
            return refuse("Metal directional transport lost its retained exact input buffer");
        if(!glasscaustics::validateDirectionalSourceTables(binding->prepared,bound,*sourceBinding,error,true))return false;
    }
    std::shared_ptr<const glasscaustics::GratingIncidentBinding> confirmed;
    if(!glasscaustics::prepareGratingIncidentBinding(binding->prepared,binding->frame,frame->caustic->gratingStagingCompleted
            ?frame->staticResources->discreteGratingProgram:binding->gratingOwner,
        binding->material,binding->evaluationTime,confirmed,error,directional
            ?glasscaustics::SourceMeasureUse::DirectionalIrradiancePreparation:glasscaustics::SourceMeasureUse::LegacyNative))return false;
    if(confirmed->identity!=binding->identity||confirmed->witnessTexels!=binding->witnessTexels)
        return refuse("Metal grating frozen witness or material identity changed");
    const auto& schedule=confirmed->frame;const auto& policy=confirmed->prepared.branchPolicy->description();
    const auto math=metalGratingNativeOrderMath();
    auto source=terminal?metalcaustic::gratingTerminalShader(math):metalcaustic::gratingIncidentShader(math);
    if(directional)source=metalcaustic::directionalIrradianceShader(std::move(source));
    if(source.empty())return refuse("Metal grating native authority extraction is incomplete");
    if(cameraPass)source+=metalcaustic::gratingCameraShader();
    struct Scratch {
        std::array<id<MTLBuffer>,15> buffers{};
        std::array<arbitgpu::residency::ResidencyCharge,15> charges{};
        arbitgpu::residency::ResidencyCharge cameraResolvedCharge;
        id<MTLLibrary> library=nil;id<MTLComputePipelineState> pipeline=nil;
        std::array<id<MTLComputePipelineState>,3> depositionPipelines{};
        std::array<id<MTLComputePipelineState>,4> cameraPipelines{};
        id<MTLTexture> cameraResolved=nil;
        ~Scratch() {
#if ! __has_feature(objc_arc)
            for(auto buffer:buffers)[buffer release];
            for(auto item:depositionPipelines)[item release];
            for(auto item:cameraPipelines)[item release];
            [cameraResolved release];[pipeline release];[library release];
#endif
        }
    } scratch;
    const auto workCount=std::uint64_t(schedule.work.size()),slots=confirmed->bounds.maximumIncidents;
    const auto depositStride=terminal?sizeof(metalcaustic::CoupledDeposit):sizeof(metalcaustic::Deposit);
    const auto pixels=std::uint64_t(schedule.width)*schedule.height;
    std::uint64_t cameraKeys=1;
    if(cameraPass)while(cameraKeys<slots*3)cameraKeys*=2;
    std::uint64_t sortStages=0;for(auto count=cameraKeys;count>1;count/=2)++sortStages;
    const auto cameraSortWork=cameraPass?(cameraKeys/2)*(sortStages*(sortStages+1)/2)
        +3*cameraKeys+pixels+slots*3*schedule.triangles.size():0;
    if(cameraPass&&(cameraSortWork>glasscaustics::kMaximumQueryWork-cameraBounds.combinedWork-frame->caustic->directWork))
        return refuse("Metal private camera sort and resolve exceed whole-frame work");
    if(cameraPass&&frame->caustic->directWork
        &&frame->caustic->cellWork+frame->caustic->coverageWork>glasscaustics::kMaximumQueryWork
            -cameraBounds.combinedWork-cameraSortWork-frame->caustic->directWork)
        return refuse("Metal camera, cell and direct consumers exceed original combined work");
    const std::array<std::uint64_t,15> bytes{binding->witnessTexels.size()*16,slots*24*16,slots*3*4*16,
        workCount*2*16,workCount*sizeof(metalcaustic::Path),slots*depositStride,4,
        terminal?slots*3*8*16:0,terminal?schedule.bounds.deposition.paddedKeyCount*16:0,terminal?pixels*8*4:0,
        directional?sizeof(glasscaustics::NativeDirectionalSourceEcho):0,directional?workCount*sizeof(float):0,
        cameraPass?slots*3*sizeof(metalcaustic::CameraOrder):0,cameraPass?cameraKeys*16:0,cameraPass?pixels*8*4:0};
    // Binding bytes reserve packed incidents/orders and decoded records. Add
    // all private trace buffers and fixed local arrays/copies conservatively.
    const auto locals=workCount*((glasscaustics::kMaximumPendingBranches+2)*96+2048);
    const auto oldAdjunct=terminal?terminal->gratingIncidents:nullptr;
    const auto incumbentAdjunct=oldAdjunct?oldAdjunct->incidents.capacity()*sizeof(glasscaustics::NativeGratingIncident)
        +oldAdjunct->paths.capacity()*sizeof(glasscaustics::NativeGratingReadback::WorkReceipt)
        +oldAdjunct->children.capacity()*sizeof(glasscaustics::NativeGratingReadback::ChildReceipt)+oldAdjunct->submission.frameIdentity.capacity():0;
    const auto sourceReceiptBytes=[](const auto& receipt)->std::uint64_t {
        return receipt?sizeof(glasscaustics::NativeDirectionalSourceReceipt)+receipt->potential.capacity()*sizeof(float)
            +receipt->submission.frameIdentity.capacity():0;
    };
    const auto incumbent=incumbentAdjunct+sourceReceiptBytes(output.directionalSource)
        +(oldAdjunct?sourceReceiptBytes(oldAdjunct->directionalSource):0)
        +(terminal?sourceReceiptBytes(terminal->directionalSource):0)
        +output.incidents.capacity()*sizeof(glasscaustics::NativeGratingIncident)
        +output.paths.capacity()*sizeof(glasscaustics::NativeGratingReadback::WorkReceipt)
        +output.children.capacity()*sizeof(glasscaustics::NativeGratingReadback::ChildReceipt)
        +(terminal?terminal->paths.capacity()*sizeof(glasscaustics::NativePathReceipt)
            +terminal->deposits.capacity()*sizeof(glasscaustics::NativeDeposit)
            +terminal->spectralRadiance.capacity()*4+terminal->deposition.keys.capacity()*16:0);
    const auto oldCamera=terminal?terminal->gratingCamera:nullptr;
    const auto incumbentCamera=oldCamera?sizeof(*oldCamera)+oldCamera->orders.capacity()
        *sizeof(glasscaustics::NativeGratingCameraReadback::OrderReceipt)+oldCamera->submission.frameIdentity.capacity():0;
    // The frame retains private camera storage across ordinary producer calls.
    const auto cameraHost=frame->caustic->cameraPrimitiveBytes
        +(cameraPass?cameraBounds.bytes+bytes[13]+2*bytes[14]+pixels*8+incumbentCamera:0);
