bool produceMetalGlassGratingIncidents(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const std::shared_ptr<const glasscaustics::GratingIncidentBinding>& binding,
    glasscaustics::NativeGratingReadback& output,std::string& error)
{return produceMetalGlassGratingReadback(owner,binding,output,nullptr,nullptr,error);}

bool validateMetalDirectGratingIrradiance(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const glasscaustics::SubmissionIdentity& expected,double evaluationTime,
    const glasscaustics::NativeDirectGratingContributionReadback& output,std::string& error)
{
    std::lock_guard<std::mutex> lock(sokolMutex());
    const auto frame=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);
    const auto* b=frame?frame->directBatch():nullptr;
    if(!b||!b->binding) {
        error="Metal direct contribution has no exact retained native result";return false;
    }
    MetalDirectQueryLease lease(frame.get());
    return glasscaustics::validateDirectGratingContributionReadback(*b->binding,*frame,expected,evaluationTime,output,error);
}

