        bands*sizeof(metalcaustic::GlassCameraTraceResult),bands*64*sizeof(metalcaustic::GlassCameraTraceVisit),
        b.witnesses.size()*sizeof(metalcaustic::DirectGratingWitness),sizeof(b.params)};
