static bool validateMetalCameraTraceSceneInputsUnlocked(const MetalFixtureSceneFrame& frame,
    const arbitgpu::glasscaustics::GratingIncidentBinding& binding,std::string& error)
{
    using namespace arbitgpu;
    const auto refuse=[&](){error="Metal camera glass trace scene differs from its actual native geometry or query upload";return false;};
    if(!inspectMetalRasterCaptureUnlocked(frame,error))return false;
    const auto& geometry=binding.frame.triangleTexels;const auto triangles=frame.caustic->triangles;const auto query=frame.caustic->query;
    if(!gMetalDevice||!triangles||triangles.device!=gMetalDevice||!triangles.contents
        ||triangles.length!=geometry.size()*sizeof(geometry[0])||std::memcmp(triangles.contents,geometry.data(),triangles.length)!=0
        ||!query||query.device!=gMetalDevice||query.pixelFormat!=MTLPixelFormatRGBA32Float||query.storageMode!=MTLStorageModeShared
        ||query.width!=opaquevisibility::kTextureWidth||query.height!=binding.frame.query.height
        ||binding.frame.query.texels.size()!=opaquevisibility::kTextureWidth*query.height)return refuse();
    // Bounded input readback authenticates the same actual world geometry and
    // query data that certify the camera's initial exterior medium.
    std::array<glasscaustics::Texel,opaquevisibility::kTextureWidth> row;
    for(NSUInteger y=0;y<query.height;++y) {
        [query getBytes:row.data() bytesPerRow:sizeof(row)
            fromRegion:MTLRegionMake2D(0,y,opaquevisibility::kTextureWidth,1) mipmapLevel:0];
        if(std::memcmp(row.data(),binding.frame.query.texels.data()+y*opaquevisibility::kTextureWidth,sizeof(row))!=0)return refuse();
    }
    error.clear();return true;
}

static bool validateMetalCameraTraceNativeBuffersUnlocked(const MetalFixtureSceneFrame& frame,
    const MetalCameraGratingTraceBatch& b,std::string& error)
{
    using namespace arbitgpu;
    const auto refuse=[&](){error="Metal camera glass trace lost its actual input, output, query, device or completed command";return false;};
    if(metalDirectQueryLease!=&frame||!frame.caustic||!frame.staticResources||!gMetalDevice||!sg_isvalid()
        ||!frame.privateCameraAttachments||!frame.caustic->gratingStagingCompleted||frame.caustic->validated
        ||!b.binding||b.binding!=frame.caustic->cameraBinding||!frame.caustic->cameraInputs
        ||frame.caustic->cameraInputs->timeSeconds!=float(b.binding->evaluationTime)
        ||b.binding->prepared.glass.sourceScene!=frame.staticResources->snapshot
        ||b.binding->prepared.glass.sourceMaterial!=frame.staticResources->materialProgram
        ||!metalDirectGratingProgramMatches(b.binding->gratingOwner,frame.staticResources->discreteGratingProgram)
        ||frame.rendererGeneration_!=frame.staticResources->rendererGeneration
        ||frame.caustic->identity.completedFence!=frame.caustic->submission
        ||!b.dispatched||!b.command||b.command.status!=MTLCommandBufferStatusCompleted||!b.queue
        ||b.command.commandQueue!=b.queue||b.queue!=(__bridge id<MTLCommandQueue>)sg_mtl_command_queue()
        ||b.queue.device!=gMetalDevice||!b.library||b.library.device!=gMetalDevice||!b.pipeline||b.pipeline.device!=gMetalDevice
        ||b.query!=frame.caustic->query||!b.query||b.query.device!=gMetalDevice
        ||b.query.pixelFormat!=MTLPixelFormatRGBA32Float||b.query.width!=opaquevisibility::kTextureWidth
        ||b.query.storageMode!=MTLStorageModeShared||b.query.height!=b.binding->frame.query.height
        ||b.params.query!=frame.caustic->params.query||b.params.query!=b.binding->frame.query.control
        ||frame.caustic->schedule.identity!=b.binding->frame.identity
        ||frame.caustic->schedule.cameraIdentity!=b.binding->frame.cameraIdentity||frame.caustic->schedule.ior!=b.binding->frame.ior
        ||b.params.camera!=frame.caustic->params.camera||b.params.rotation!=frame.caustic->params.rotation
        ||b.params.projection!=frame.caustic->params.projection
        ||std::memcmp(b.params.ior.data(),frame.caustic->params.ior,sizeof(b.params.ior))!=0
        ||b.params.extent!=std::array<std::uint32_t,4>{frame.width_,frame.height_,std::uint32_t(b.inputs.size()),std::uint32_t(b.witnesses.size())}
        ||b.params.glass!=std::array<std::uint32_t,4>{b.binding->prepared.glass.object.value,b.binding->prepared.glass.material.value,1,0}
        ||b.inputs.empty()||b.packed.size()!=b.inputs.size()*8||b.visits.size()!=b.packed.size()*64
        ||b.witnesses.size()!=b.binding->triangles.size())return refuse();
    if(!validateMetalCameraTraceSceneInputsUnlocked(frame,*b.binding,error))return false;
    const std::array<id<MTLBuffer>,5> buffers{b.input,b.result,b.visit,b.witness,b.uniforms};
    const std::array<std::uint64_t,5> lengths{b.inputs.size()*sizeof(b.inputs[0]),b.packed.size()*sizeof(b.packed[0]),
        b.visits.size()*sizeof(b.visits[0]),b.witnesses.size()*sizeof(b.witnesses[0]),sizeof(b.params)};
    const std::array<const void*,5> copies{b.inputs.data(),b.packed.data(),b.visits.data(),b.witnesses.data(),&b.params};
    std::uint64_t aligned=0;
    for(unsigned i=0;i<buffers.size();++i) {
        const auto v=buffers[i];
        if(!v||v.device!=gMetalDevice||!v.contents||v.length!=lengths[i]||v.length>gMetalDevice.maxBufferLength
            ||std::memcmp(v.contents,copies[i],lengths[i])!=0)return refuse();
        aligned+=std::max<std::uint64_t>(v.length,v.allocatedSize)-v.length;
    }
    if(aligned!=b.alignedBytes)return refuse();
    for(unsigned band=0;band<8;++band)
        if(b.params.wavelength[band/4][band%4]!=diffractionmaterial::kProductionWavelengthsNanometres[band])return refuse();
    for(std::size_t i=0;i<b.witnesses.size();++i) {
        const auto& w=b.witnesses[i];const auto& t=b.binding->triangles[i];
        if(w.primitive!=std::array<std::uint32_t,4>{t.object,t.material,t.instance,t.triangle}
            ||w.geometry[3]!=glasscaustics::Texel{t.normal[0],t.normal[1],t.normal[2],0})return refuse();
        for(unsigned v=0;v<3;++v)if(w.geometry[v]!=glasscaustics::Texel{t.positions[v][0],t.positions[v][1],t.positions[v][2],0})return refuse();
    }
    for(std::size_t i=0;i<b.packed.size();++i) {
        const auto& r=b.packed[i];
        if(std::memcmp(&r.input,&b.inputs[i/8],sizeof(r.input))!=0||r.control[0]!=1||r.control[1]!=i/8||r.control[2]!=i%8
            ||r.control[3]>64||r.work[0]>1||(r.work[1]&~255u)||r.work[3]||bool(r.work[0])!=(r.work[1]==0)
            ||r.padding!=std::array<std::uint32_t,4>{}
            ||r.parameters[0]!=glasscaustics::glassCameraTraceFloatBits(b.binding->frame.ior[i%8])
            ||r.parameters[1]!=glasscaustics::glassCameraTraceFloatBits(diffractionmaterial::kProductionWavelengthsNanometres[i%8])
            ||!std::isfinite(glasscaustics::glassCameraTraceFloat(r.parameters[2]))
            ||glasscaustics::glassCameraTraceFloat(r.parameters[2])<0||glasscaustics::glassCameraTraceFloat(r.parameters[2])>1.0002f
            ||r.parameters[3]!=1)return refuse();
        std::uint64_t work=0;
        for(unsigned j=0;j<64;++j) {
            const auto& v=b.visits[i*64+j];
            if(j>=r.control[3]){if(v!=metalcaustic::GlassCameraTraceVisit{})return refuse();continue;}
            if(v[0][0]!=j||v[0][3]>32||v[1][0]>1||v[1][2]>4||v[1][3]>1||v[5][2]>1||v[5][3]
                ||v[7][3]||v[14][2]||v[14][3]||v[15]!=std::array<std::uint32_t,4>{}
                ||(v[4][0]>1&&v[4][0]!=std::numeric_limits<std::uint32_t>::max()))return refuse();
            work+=v[5][1];
        }
        if(work!=r.work[2])return refuse();
    }
    error.clear();return true;
}

static bool validateMetalCameraTraceReadbackUnlocked(const MetalFixtureSceneFrame& frame,
    const MetalCameraGratingTraceBatch& b,const arbitgpu::glasscaustics::SubmissionIdentity& expected,
    const arbitgpu::glasscaustics::NativeGlassCameraGratingTraceReadback& supplied,std::string& error)
{
    using namespace arbitgpu;using namespace glasscaustics;
    const auto refuse=[&](const char* message){error=message;return false;};
    if(!validateMetalCameraTraceNativeBuffersUnlocked(frame,b,error))return false;
    if(!(b.upload.submission==expected)||!(b.readback.submission==expected)||!b.upload.complete
        ||b.upload.backend!=NativeFixtureMaterialBackend::Metal||!b.upload.generation
        ||b.readback.inputGeneration!=b.upload.generation||expected.completedFence!=expected.submissionSerial
        ||expected.rendererGeneration!=frame.rendererGeneration_||expected.rasterGeneration!=frame.caustic->identity.rasterGeneration
        ||expected.queryGeneration!=frame.caustic->identity.queryGeneration||b.upload.inputs.size()!=b.inputs.size())
        return refuse("Metal camera glass trace input or fence generation changed");
    for(std::size_t i=0;i<b.inputs.size();++i)
        if(std::memcmp(&b.inputs[i],&b.upload.inputs[i],sizeof(b.inputs[i]))!=0)
            return refuse("Metal camera glass trace differs from its actual input buffer");
    if(!admitGlassCameraGratingTraceCamera(b.binding->frame,error))return false;
    GlassCameraGratingTraceBounds admitted;
    if(!calculateGlassCameraGratingTraceBounds(*b.binding,b.inputs.size(),b.upload.otherOwnedBytes,b.upload.otherWork,admitted,error)
        ||admitted.bytes!=b.bounds.bytes||admitted.combinedWork!=b.bounds.combinedWork
        ||b.reservedWork!=admitted.queryWork+admitted.branchWork)return refuse("Metal camera glass trace reservation changed");
    const auto& state=*frame.caustic;const auto maximum=renderpassoutput::kMaximumTotalBytes;
    if(state.directWork>kMaximumQueryWork-b.binding->bounds.combinedWork
        ||state.adjunctWork>kMaximumQueryWork-b.binding->bounds.combinedWork-state.directWork)
        return refuse("Metal camera glass trace exceeded cumulative attempted work");
    std::uint64_t current=b.binding->frame.bounds.transientBytes;
    for(auto bytes:{b.binding->bounds.bytes,state.metrics.admittedBytes,state.directPrimitiveBytes,
        state.cameraPrimitiveBytes,state.cellPrimitiveBytes,state.coveragePrimitiveBytes,
        state.cameraTraceCandidate==&b?b.reservedBytes:std::uint64_t(0)}) {
        if(bytes>maximum-current)return refuse("Metal camera glass trace exceeded cumulative retained storage");current+=bytes;
    }
    auto actual=b.readback;actual.bands.clear();actual.bands.reserve(b.packed.size());actual.queryWork=0;
    for(std::size_t i=0;i<b.packed.size();++i) {
        NativeGlassCameraGratingTracePackedHeader header;std::memcpy(header.data(),&b.packed[i],sizeof(header));
        NativeGlassCameraGratingTraceBand band;
        if(!decodeGlassCameraGratingTraceBand(header,b.visits.data()+i*kMaximumBranchVisits,kMaximumBranchVisits,band,error))return false;
        actual.queryWork+=band.queryWork;actual.bands.push_back(std::move(band));
    }
    if(!sameGlassCameraGratingTraceReadback(actual,b.readback)||!sameGlassCameraGratingTraceReadback(supplied,actual))
        return refuse("Metal camera glass trace differs from its actual retained native output");
    error.clear();return true;
}

static bool produceMetalGlassCameraGratingTraceUnlocked(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const std::shared_ptr<const glasscaustics::GratingIncidentBinding>& binding,
    const std::vector<glasscaustics::NativeGlassCameraGratingTraceInput>& inputs,
    glasscaustics::NativeGlassCameraGratingTraceReadback& output,std::string& error,bool failedQuery=false)
{
    @autoreleasepool {
    using namespace glasscaustics;
    const auto frame=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);
    const auto refuse=[&](const char* message){error=message;return false;};
    if(frame&&frame->caustic&&!validateMetalDirectAttemptLedgerUnlocked(*frame,error))return false;
    if(frame&&frame->caustic&&frame->caustic->directAttemptCount>=frame->caustic->directAttempts.size())
        return refuse("Metal direct attempt registry is full");
    if(!frame||!frame->caustic||!frame->staticResources||!binding||!binding->gratingOwner||!binding->material
        ||!frame->privateCameraAttachments||!frame->caustic->gratingStagingCompleted||frame->caustic->validated
        ||frame->caustic->cameraBinding!=binding||!frame->caustic->cameraInputs
        ||frame->caustic->cameraInputs->timeSeconds!=float(binding->evaluationTime)
        ||binding->prepared.glass.sourceScene!=frame->staticResources->snapshot
        ||binding->prepared.glass.sourceMaterial!=frame->staticResources->materialProgram
        ||!metalDirectGratingProgramMatches(binding->gratingOwner,frame->staticResources->discreteGratingProgram)
        ||frame->rendererGeneration_!=frame->staticResources->rendererGeneration
        ||frame->caustic->schedule.identity!=binding->frame.identity||binding->frame.roughness!=0||binding->frame.multipleScatterPolicy
        ||!binding->frame.gratingStaging||frame->caustic->identity.completedFence!=frame->caustic->submission
        ||!gMetalDevice||!sg_isvalid()||!frame->caustic->query||frame->caustic->query.device!=gMetalDevice
        ||inputs.empty()||inputs.size()>kMaximumEntrySamples||inputs.capacity()>2*inputs.size())
        return refuse("Metal camera glass trace requires its exact completed smooth staging frame");
    if(!admitGlassCameraGratingTraceCamera(binding->frame,error))return false;
    for(const auto& input:inputs) {
        NativeGlassCameraGratingTraceInput canonical;
        if(!makeGlassCameraGratingTraceInput(binding->frame,input.pixel[0],input.pixel[1],input.pixel[2],canonical,error)
            ||!sameGlassCameraGratingTraceInput(input,canonical))return refuse("Metal camera glass trace input differs from its owning camera sample");
    }
    auto& state=*frame->caustic;const auto maximum=renderpassoutput::kMaximumTotalBytes;
    if(state.cameraTraceBatches.size()>=kMaximumEntrySamples||output.bands.capacity()>maximum/sizeof(NativeGlassCameraGratingTraceBand)
        ||output.submission.frameIdentity.capacity()>maximum||binding->triangles.size()>maximum/(3*sizeof(metalcaustic::DirectGratingWitness)))
        return refuse("Metal camera glass trace retained owner or incumbent storage is unbounded");
