    if(!calculateGlassCameraGratingTraceBounds(*binding,inputs.size(),other,state.directWork+state.adjunctWork,bounds,error))return false;
    if(!validateTables(binding->prepared,binding->frame,error,true,binding->frame.sourceDirectionalIrradiance.version
        ?SourceMeasureUse::DirectionalIrradiancePreparation:SourceMeasureUse::LegacyNative))return false;
    if(!validateMetalCameraTraceSceneInputsUnlocked(*frame,*binding,error))return false;
    auto batch=std::make_unique<MetalCameraGratingTraceBatch>();auto& b=*batch;b.binding=binding;b.bounds=bounds;
    b.upload.backend=NativeFixtureMaterialBackend::Metal;b.upload.otherOwnedBytes=other;b.upload.otherWork=state.directWork+state.adjunctWork;
    b.reservedWork=bounds.queryWork+bounds.branchWork;b.reservedBytes=bounds.bytes+overhead;
    b.inputs.resize(inputs.size());std::memcpy(b.inputs.data(),inputs.data(),inputs.size()*sizeof(inputs[0]));
    if(!dispatchMetalCameraGratingTraceUnlocked(*frame,b,error,failedQuery))return false;
    const auto serial=nextMetalRendererGeneration();
    b.upload.submission={binding->identity,frame->rendererGeneration_,serial,state.identity.rasterGeneration,state.identity.queryGeneration,serial,serial};
    b.upload.generation=serial;b.upload.inputs.resize(inputs.size());std::memcpy(b.upload.inputs.data(),b.input.contents,inputs.size()*sizeof(inputs[0]));
    b.upload.complete=true;b.readback.version=kGlassCameraGratingTraceVersion;b.readback.submission=b.upload.submission;
    b.readback.inputGeneration=serial;b.readback.dispatchComplete=true;b.readback.bands.reserve(bounds.maximumBands);
    for(std::size_t i=0;i<b.packed.size();++i) {
        NativeGlassCameraGratingTracePackedHeader header;std::memcpy(header.data(),&b.packed[i],sizeof(header));
        NativeGlassCameraGratingTraceBand band;
        if(!decodeGlassCameraGratingTraceBand(header,b.visits.data()+i*kMaximumBranchVisits,kMaximumBranchVisits,band,error))return false;
        b.readback.queryWork+=band.queryWork;b.readback.bands.push_back(std::move(band));
    }
