        ~Candidate(){state.cameraTraceCandidate=nullptr;}
    } candidate(state,b);
    MetalDirectQueryLease lease(frame.get());
    if(failedQuery&&std::any_of(b.readback.bands.begin(),b.readback.bands.end(),[](const auto& band){
        return band.traceComplete||band.reasons!=GlassCameraQueryFailed||band.visits.size()!=1||band.visits[0].hit.status!=-1;
    }))return refuse("Metal camera query fixture did not execute its actual native failed query");
    if(!validateGlassCameraGratingTraceReadback(*binding,*frame,b.readback.submission,binding->evaluationTime,b.readback,error))return false;
    if(b.inputs.capacity()>2*inputs.size()||b.packed.capacity()>2*b.packed.size()||b.visits.capacity()>2*b.visits.size()
        ||b.witnesses.capacity()>2*b.witnesses.size()||b.reservedBytes>maximum-state.directPrimitiveBytes||b.reservedBytes>maximum-state.bytes)
        return refuse("Metal camera glass trace retained copies exceed reservation");
    auto delivered=b.readback;state.cameraTraceBatches.reserve(state.cameraTraceBatches.size()+1);
    if(delivered.bands.capacity()>2*b.packed.size()||state.cameraTraceBatches.capacity()>2*kMaximumEntrySamples
        ||delivered.submission.frameIdentity.capacity()>2*binding->identity.size()
        ||std::any_of(delivered.bands.begin(),delivered.bands.end(),[](const auto& band){return band.visits.capacity()>2*kMaximumBranchVisits;}))
        return refuse("Metal camera glass trace publication owners exceed reservation");
    output=std::move(delivered);state.directPrimitiveBytes+=b.reservedBytes;state.bytes+=b.reservedBytes;
    std::uint64_t native=0;for(auto v:{b.input,b.result,b.visit,b.witness,b.uniforms})native+=std::max<std::uint64_t>(v.length,v.allocatedSize);
    state.metrics.retainedNativeBytes+=native;state.metrics.peakNativeBytes=std::max(state.metrics.peakNativeBytes,state.metrics.retainedNativeBytes);
    state.cameraTraceBatches.push_back(std::move(batch));error.clear();return true;
    }
}

bool produceMetalGlassCameraGratingTrace(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const std::shared_ptr<const glasscaustics::GratingIncidentBinding>& binding,
    const std::vector<glasscaustics::NativeGlassCameraGratingTraceInput>& inputs,
    glasscaustics::NativeGlassCameraGratingTraceReadback& output,std::string& error)
{
    std::lock_guard<std::mutex> lock(sokolMutex());
    return produceMetalGlassCameraGratingTraceUnlocked(owner,binding,inputs,output,error);
}

bool validateMetalGlassCameraGratingTrace(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const glasscaustics::SubmissionIdentity& expected,double time,
    const glasscaustics::NativeGlassCameraGratingTraceReadback& supplied,std::string& error)
