    std::lock_guard<std::mutex> lock(sokolMutex());
    const auto frame=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);const auto* b=frame?frame->cameraTraceBatch():nullptr;
    if(!b){error="Metal camera glass trace has no retained native owner";return false;}
    MetalDirectQueryLease lease(frame.get());
    return glasscaustics::validateGlassCameraGratingTraceReadback(*b->binding,*frame,expected,time,supplied,error);
}

