    auto alteredQuery=originalQuery;std::uint32_t queryWord=0;std::memcpy(&queryWord,&alteredQuery[0],sizeof(queryWord));queryWord^=1u;
    std::memcpy(&alteredQuery[0],&queryWord,sizeof(queryWord));
