    const auto query=b->query;b->query=nil;const bool queryAccepted=validate();b->query=query;
    const auto device=gMetalDevice;gMetalDevice=nil;const bool deviceAccepted=validate();gMetalDevice=device;
    const auto queryGeneration=state.identity.queryGeneration;state.identity.queryGeneration^=1u;
    const bool generationAccepted=validate();state.identity.queryGeneration=queryGeneration;
    const auto fence=state.identity.completedFence;state.identity.completedFence=0;
    const bool fenceAccepted=validate();state.identity.completedFence=fence;
    const auto oldInputs=state.cameraInputs;auto staleInputs=std::make_shared<NativeFixtureSceneRuntimeInputs>(*oldInputs);
    staleInputs->timeSeconds+=.125f;state.cameraInputs=staleInputs;const bool timeAccepted=validate();state.cameraInputs=oldInputs;
    if(triangleAccepted||queryBytesAccepted||queryAccepted||deviceAccepted||generationAccepted||fenceAccepted||timeAccepted||!validate())
        return refuse("Metal camera native hook accepted stale query, device, generation, fence or time");
