        &&state.cameraTraceBatches.size()==batches&&frame->cameraTraceBatch()==b;};
    auto malformed=b->upload.inputs;malformed[0].directionMaximum[0]=std::nextafter(malformed[0].directionMaximum[0],1.0f);
    if(produceMetalGlassCameraGratingTraceUnlocked(owner,b->binding,malformed,output,error)||state.directWork!=savedWork||!unchanged())
        return refuse("Metal camera undispatched malformed sample changed prior output or work");
    state.directPrimitiveBytes=renderpassoutput::kMaximumTotalBytes;
    const bool storageAccepted=produceMetalGlassCameraGratingTraceUnlocked(owner,b->binding,b->upload.inputs,output,error);
    state.directPrimitiveBytes=savedBytes;
    if(storageAccepted||state.directWork!=savedWork||!unchanged())return refuse("Metal camera storage refusal dispatched or replaced prior output");
    const auto remaining=kMaximumQueryWork-b->binding->bounds.combinedWork-state.adjunctWork;
    if(b->reservedWork>remaining||savedWork>remaining-b->reservedWork)return refuse("Metal camera failure fixture has no bounded work headroom");
    const bool failureAccepted=produceMetalGlassCameraGratingTraceUnlocked(owner,b->binding,b->upload.inputs,output,error,true);
    if(failureAccepted||state.directWork!=savedWork+b->reservedWork||!unchanged())
        return refuse("Metal camera submitted query failure lost work or replaced prior accepted native ownership");
    struct RestoreWork {MetalCausticState& state;std::uint64_t realWork;~RestoreWork(){state.directWork=realWork;}} restore{state,state.directWork};
    const auto attempts=state.directAttemptCount;
    state.directWork=remaining;
    if(produceMetalGlassCameraGratingTraceUnlocked(owner,b->binding,b->upload.inputs,output,error)
        ||state.directWork!=remaining||state.directAttemptCount!=attempts||!unchanged())
        return refuse("Metal camera unjournaled cap counter allowed another dispatch or changed prior output");
    state.directWork=restore.realWork;
    if(!validate())return false;
    error.clear();return true;
}

bool produceMetalDirectGratingIrradiance(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const std::shared_ptr<const glasscaustics::GratingIncidentBinding>& binding,
    const std::vector<glasscaustics::NativeDirectGratingEndpointInput>& endpoints,
    glasscaustics::NativeDirectGratingContributionReadback& output,std::string& error)
{
    std::lock_guard<std::mutex> lock(sokolMutex());
    return produceMetalDirectGratingIrradianceReadbackUnlocked(owner,binding,endpoints,output,error);
}

