bool MetalDirectGratingSourceView::validateDirectProductionQuery(const arbitgpu::glasscaustics::SubmissionIdentity& expected,
    const arbitgpu::glasscaustics::NativeDirectGratingContributionReadback& supplied,std::string& error) const
{
    using namespace arbitgpu;using namespace glasscaustics;
    const auto refuse=[&](){error="Metal cohort source lost its exact native input, result, query or completed command";return false;};
    const auto& b=*batch;const auto& state=*common.caustic;
    if(metalDirectQueryLease!=&common||!gMetalDevice||!sg_isvalid()||!common.staticResources
        ||!common.privateCameraAttachments||!state.gratingStagingCompleted||state.validated
        ||state.stagedDirectCohort!=cohort.prepared||state.cameraBinding!=cohort.prepared->sources()[0]
        ||common.rendererGeneration_!=common.staticResources->rendererGeneration
        ||!state.cameraInputs||state.cameraInputs->timeSeconds!=float(b.binding->evaluationTime)
        ||state.identity.completedFence!=state.submission||b.binding->frame.cameraIdentity!=state.schedule.cameraIdentity
        ||b.binding->frame.query.control!=state.params.query||b.binding->frame.ior!=state.schedule.ior
        ||!metalDirectGratingProgramMatches(b.binding->gratingOwner,common.staticResources->discreteGratingProgram)
        ||!b.dispatched||!b.command||b.command.status!=MTLCommandBufferStatusCompleted
        ||!b.queue||b.command.commandQueue!=b.queue||b.queue!=(__bridge id<MTLCommandQueue>)sg_mtl_command_queue()
        ||b.queue.device!=gMetalDevice||!b.library||b.library!=cohort.library||b.library.device!=gMetalDevice
        ||!b.pipeline||b.pipeline!=cohort.pipeline||b.pipeline.device!=gMetalDevice
        ||!(b.upload.submission==expected)||!(b.readback.submission==expected)||!(b.sourceUpload.submission==expected)
        ||expected.rendererGeneration!=common.rendererGeneration_||expected.completedFence!=expected.submissionSerial
        ||expected.rasterGeneration!=state.identity.rasterGeneration||expected.queryGeneration!=state.identity.queryGeneration
        ||b.sourceUpload.bindingGeneration!=b.readback.sourceGeneration||b.upload.generation!=b.readback.endpointGeneration
        ||!b.sourceInput||!b.sourceInput.contents||b.sourceInput.device!=gMetalDevice
        ||b.sourceInput.length!=sizeof(NativeDirectionalSourceInput)||b.sourceInput.length>gMetalDevice.maxBufferLength
        ||std::max<std::uint64_t>(b.sourceInput.length,b.sourceInput.allocatedSize)-b.sourceInput.length>64*1024
        ||std::memcmp(b.sourceInput.contents,&b.sourceUpload.input,sizeof(b.sourceUpload.input))!=0
        ||b.query!=state.query||!b.query||b.query.device!=gMetalDevice
        ||b.params.query!=state.params.query||b.params.source!=b.binding->frame.sourceDirectionTrace
        ||b.params.radiance!=b.binding->frame.sourceRadiance
        ||b.params.control!=std::array<std::uint32_t,4>{std::uint32_t(b.upload.inputs.size()),std::uint32_t(b.binding->triangles.size()),1,0})return refuse();
    if(!arbitgpu::validateMetalCameraTraceSceneInputsUnlocked(common,*b.binding,error))return false;
    const auto& frozen=b.binding->prepared.glass;
    if(sceneaov::detail::encodeScene(*common.staticResources->snapshot)!=sceneaov::detail::encodeScene(*frozen.sourceScene))return refuse();
    const auto* actualGlass=nativeSurfaceForObject(common.staticResources->materialProgram.get(),frozen.object);
    const auto* frozenGlass=nativeSurfaceForObject(frozen.sourceMaterial.get(),frozen.object);
    if(!actualGlass||!frozenGlass||!metalDirectGratingProgramMatches(
        std::shared_ptr<const NativeFixtureSurfaceMaterialProgram>(frozen.sourceMaterial,frozenGlass),
        std::shared_ptr<const NativeFixtureSurfaceMaterialProgram>(common.staticResources->materialProgram,actualGlass)))return refuse();
    const std::array<id<MTLBuffer>,4> buffers{b.input,b.result,b.witness,b.uniforms};
    const std::array<std::uint64_t,4> lengths{b.upload.inputs.size()*sizeof(NativeDirectGratingEndpointInput),
        b.packed.size()*sizeof(metalcaustic::DirectGratingResult),b.witnesses.size()*sizeof(metalcaustic::DirectGratingWitness),sizeof(b.params)};
    const std::array<const void*,4> copies{b.upload.inputs.data(),b.packed.data(),b.witnesses.data(),&b.params};
    std::uint64_t alignment=0;
    for(unsigned i=0;i<buffers.size();++i) {
        const auto v=buffers[i];
        if(!v||!v.contents||v.device!=gMetalDevice||v.length!=lengths[i]||v.length>gMetalDevice.maxBufferLength
            ||std::memcmp(v.contents,copies[i],lengths[i])!=0)return refuse();
        alignment+=std::max<std::uint64_t>(v.length,v.allocatedSize)-v.length;
    }
    DirectGratingContributionBounds bounds;
    if(alignment!=b.alignedBytes||!calculateDirectGratingContributionBounds(*b.binding,b.upload.inputs.size(),
        b.upload.otherOwnedBytes,b.upload.otherWork,bounds,error)||bounds.bytes!=b.bounds.bytes
        ||bounds.combinedWork!=cohort.frameWork||b.reservedWork!=bounds.queryWork+bounds.bandWork
        ||b.packed.size()!=b.readback.samples.size()||b.witnesses.size()!=b.binding->triangles.size())return refuse();
    for(std::size_t i=0;i<b.witnesses.size();++i) {
        const auto& w=b.witnesses[i];const auto& t=b.binding->triangles[i];
        if(w.primitive!=std::array<std::uint32_t,4>{t.object,t.material,t.instance,t.triangle}
            ||w.geometry[3]!=Texel{t.normal[0],t.normal[1],t.normal[2],0})return refuse();
        for(unsigned v=0;v<3;++v)if(w.geometry[v]!=Texel{t.positions[v][0],t.positions[v][1],t.positions[v][2],0})return refuse();
    }
    for(std::size_t i=0;i<b.packed.size();++i) {
        const auto& r=b.packed[i];const auto decoded=metalcaustic::decodeDirectGrating(r);
        if(r.control!=std::array<std::uint32_t,4>{1,1,std::uint32_t(decoded.outcome),0}
            ||r.work[0]!=r.endpoint.value.work||r.work[1]!=r.shadow.value.work||r.work[2]!=8||r.work[3]
            ||r.endpoint.padding!=std::array<std::uint32_t,6>{}||r.shadow.padding!=std::array<std::uint32_t,6>{}
            ||r.barycentric[3]||!sameDirectGratingEndpointInput(r.input,b.upload.inputs[i])
            ||!metalcaustic::sameDirectGratingSample(decoded,b.readback.samples[i]))return refuse();
    }
    if(!sameDirectGratingContributionReadback(supplied,b.readback)) {
        error="Metal cohort source differs from its actual retained native output";return false;
    }
    error.clear();return true;
}

static bool metalDirectCohortFrozenCapacities(const arbitgpu::glasscaustics::DirectGratingIrradianceCohort& c)
{
    using namespace arbitgpu::glasscaustics;
    const auto vectorFits=[](const auto& v){return v.capacity()<=2*v.size();};
    const auto stringFits=[](const auto& v){return v.capacity()<=std::max<std::size_t>(32,2*v.size());};
    if(c.sources().empty()||c.sources().size()>16||!vectorFits(c.sources())||c.inputs().empty()
        ||c.inputs().size()>kMaximumEntrySamples||!vectorFits(c.inputs())||!stringFits(c.identity()))return false;
    for(const auto& b:c.sources()) {
        if(!b||!vectorFits(b->triangles)||!vectorFits(b->witnessTexels)||!stringFits(b->identity))return false;
        const auto& f=b->frame;
        if(!vectorFits(f.query.texels)||!vectorFits(f.instances)||!vectorFits(f.triangles)||!vectorFits(f.entries)
            ||!vectorFits(f.triangleTexels)||!vectorFits(f.work)||!vectorFits(f.workTexels)
            ||!stringFits(f.identity)||!stringFits(f.sourceIdentity)||!stringFits(f.branchPolicyIdentity)||!stringFits(f.cameraIdentity))return false;
    }
    return true;
}

static bool metalDirectCohortIncumbentRetained(const MetalCausticState& state,
    const arbitgpu::glasscaustics::DirectGratingIrradianceCohort& prepared,
    const std::shared_ptr<const arbitgpu::glasscaustics::DirectGratingIrradianceCohort>& incumbent,
    std::uint64_t beforeSerial)
{
    if(!incumbent||incumbent.get()==&prepared)return true;
    for(const auto& prior:state.directCohorts)if(prior&&prior->seal.submissionSerial<beforeSerial
        &&(prior->prepared==incumbent||prior->incumbent.cohort==incumbent))return true;
    return false;
}

// Reconstruct the same conservative reservation for admission and inspection.
static bool metalDirectCohortReservation(const arbitgpu::glasscaustics::DirectGratingIrradianceCohort& prepared,
    const arbitgpu::glasscaustics::DirectGratingIrradianceCohortReadback& incumbent,bool incumbentRetained,
    unsigned incumbentCopies,std::uint64_t& bytes,std::string& error)
{
    using namespace arbitgpu;using namespace glasscaustics;
    const auto maximum=renderpassoutput::kMaximumTotalBytes;
    const auto refuse=[&](){error="Metal directional cohort actual retained capacities exceed their reservation";return false;};
    if(!metalDirectCohortFrozenCapacities(prepared)||prepared.bounds().bytes>maximum
        ||incumbent.endpoints.capacity()>maximum/sizeof(DirectGratingEndpointIrradianceSum)
        ||incumbent.submission.frameIdentity.capacity()>maximum)return refuse();
    std::uint64_t total=prepared.bounds().bytes;
    const auto add=[&](std::uint64_t amount){if(amount>maximum-total)return false;total+=amount;return true;};
    if(!add(sizeof(MetalDirectGratingCohort)+2*kMaximumEntrySamples*sizeof(std::unique_ptr<MetalDirectGratingCohort>))
        ||!add(prepared.identity().size()*4+opaquevisibility::kTextureWidth*sizeof(Texel)))return refuse();
    for(const auto& binding:prepared.sources()) {
        DirectGratingContributionBounds bound;
        if(!calculateDirectGratingContributionBounds(*binding,prepared.inputs().size(),0,0,bound,error))return false;
        if(!add(sizeof(MetalDirectGratingSourceView)+sizeof(MetalDirectGratingBatch)+6*128*1024+5*64*1024
            +3*binding->triangles.size()*sizeof(metalcaustic::DirectGratingWitness)+2*sizeof(metalcaustic::DirectGratingParams)
            +2*sizeof(NativeDirectGratingContributionReadback)+8*binding->identity.size()
            +prepared.inputs().size()*(3*sizeof(NativeDirectGratingEndpointInput)
                +3*sizeof(metalcaustic::DirectGratingResult)+4*sizeof(NativeDirectGratingContributionSample))
            +4*sizeof(std::unique_ptr<MetalDirectGratingSourceView>)))return refuse();
    }
    for(unsigned copy=0;copy<incumbentCopies;++copy)
        if(!add(incumbent.endpoints.capacity()*sizeof(DirectGratingEndpointIrradianceSum))
            ||!add(incumbent.submission.frameIdentity.capacity()))return refuse();
    if(!incumbentRetained&&(!incumbent.cohort||!metalDirectCohortFrozenCapacities(*incumbent.cohort)
        ||!add(incumbent.cohort->bounds().bytes)))return refuse();
    bytes=total;return true;
}

static bool metalDirectCohortStoredBytes(const MetalCausticState& state,const MetalDirectGratingCohort& c,
    std::uint64_t& reservation,std::uint64_t& native,std::string& error)
{
    using namespace arbitgpu;using namespace glasscaustics;
    const auto refuse=[&](){error="Metal directional cohort actual native or host owners exceed their reservation";return false;};
    if(!c.prepared||c.sources.size()!=c.prepared->sources().size()||c.sources.capacity()>2*c.sources.size()
        ||c.readbacks.size()!=c.sources.size()||c.readbacks.capacity()>2*c.readbacks.size()
        ||c.seal.frameIdentity.capacity()>2*c.prepared->identity().size())return refuse();
    const auto serial=c.sources.empty()||!c.sources[0]||!c.sources[0]->batch?0:c.sources[0]->batch->readback.submission.submissionSerial;
    if(!serial||!c.command||c.command.status!=MTLCommandBufferStatusCompleted
        ||c.command.commandQueue!=c.sources[0]->batch->queue||c.seal.frameIdentity!=c.prepared->identity()
        ||c.seal.rendererGeneration!=state.identity.rendererGeneration||c.seal.rasterGeneration!=state.identity.rasterGeneration
        ||c.seal.queryGeneration!=state.identity.queryGeneration||c.seal.scratchGeneration!=c.seal.submissionSerial
        ||c.seal.completedFence!=c.seal.submissionSerial||!metalDirectCohortReservation(*c.prepared,c.incumbent,
        metalDirectCohortIncumbentRetained(state,*c.prepared,c.incumbent.cohort,serial),2,reservation,error)
        ||reservation!=c.reservedBytes)return refuse();
    std::uint64_t actual=c.prepared->bounds().bytes+sizeof(c)+c.sources.capacity()*sizeof(c.sources[0])
        +c.readbacks.capacity()*sizeof(c.readbacks[0])+c.seal.frameIdentity.capacity();native=0;
    if(actual>reservation)return refuse();
    const auto add=[&](std::uint64_t amount){if(amount>reservation-actual)return false;actual+=amount;return true;};
    std::uint64_t previousSerial=state.submission;
    for(std::size_t index=0;index<c.sources.size();++index) {
        const auto& view=c.sources[index];if(!view||!view->batch)return refuse();const auto& b=*view->batch;
        const auto count=c.prepared->inputs().size(),triangles=c.prepared->sources()[index]->triangles.size();
        if(&view->cohort!=&c||view->common.caustic.get()!=&state||b.binding!=c.prepared->sources()[index]
            ||b.readback.submission.submissionSerial<=previousSerial||b.readback.submission.submissionSerial>=c.seal.submissionSerial
            ||b.upload.inputs.size()!=count||b.upload.inputs.capacity()>2*count
            ||b.packed.size()!=count||b.packed.capacity()>2*count||b.readback.samples.size()!=count||b.readback.samples.capacity()>2*count
            ||c.readbacks[index].samples.size()!=count||c.readbacks[index].samples.capacity()>2*count
            ||b.witnesses.size()!=triangles||b.witnesses.capacity()>2*triangles||b.source.capacity()>2*128*1024
            ||b.upload.submission.frameIdentity.capacity()>2*b.binding->identity.size()
            ||b.readback.submission.frameIdentity.capacity()>2*b.binding->identity.size()
            ||b.sourceUpload.submission.frameIdentity.capacity()>2*b.binding->identity.size()
            ||c.readbacks[index].submission.frameIdentity.capacity()>2*b.binding->identity.size()
            ||!add(sizeof(*view)+sizeof(b)+b.source.capacity()+b.upload.inputs.capacity()*sizeof(b.upload.inputs[0])
                +b.packed.capacity()*sizeof(b.packed[0])+b.witnesses.capacity()*sizeof(b.witnesses[0])
                +(b.readback.samples.capacity()+c.readbacks[index].samples.capacity())*sizeof(NativeDirectGratingContributionSample)
                +b.upload.submission.frameIdentity.capacity()+b.readback.submission.frameIdentity.capacity()
                +b.sourceUpload.submission.frameIdentity.capacity()+c.readbacks[index].submission.frameIdentity.capacity()))return refuse();
        const std::array<id<MTLBuffer>,5> buffers{b.input,b.result,b.witness,b.uniforms,b.sourceInput};
        const std::array<std::uint64_t,5> lengths{count*sizeof(NativeDirectGratingEndpointInput),count*sizeof(metalcaustic::DirectGratingResult),
            triangles*sizeof(metalcaustic::DirectGratingWitness),sizeof(b.params),sizeof(NativeDirectionalSourceInput)};
        std::uint64_t alignment=0;
        for(unsigned i=0;i<buffers.size();++i) {
            const auto v=buffers[i];
            if(!v||!v.contents||v.device!=gMetalDevice||v.length!=lengths[i]||v.length>gMetalDevice.maxBufferLength)return refuse();
            const auto allocation=std::max<std::uint64_t>(v.length,v.allocatedSize);
            if(allocation-v.length>5*64*1024-alignment||!add(allocation))return refuse();
            alignment+=allocation-v.length;native+=allocation;
        }
        const auto source=directionalSourceInput(b.binding->prepared,b.binding->frame);
        if(std::memcmp(b.sourceInput.contents,&source,sizeof(source))!=0)return refuse();
        for(std::size_t endpoint=0;endpoint<count;++endpoint)
            if(!sameDirectGratingEndpointInput(b.upload.inputs[endpoint],c.prepared->inputs()[endpoint]))return refuse();
        for(std::size_t prior=0;prior<index;++prior) {
            const auto& other=*c.sources[prior]->batch;
            if(other.sourceInput==b.sourceInput||other.input==b.input||other.result==b.result
                ||other.sourceUpload.bindingGeneration==b.sourceUpload.bindingGeneration)return refuse();
        }
        if(!view->validateDirectProductionQuery(b.readback.submission,c.readbacks[index],error))return false;
        previousSerial=b.readback.submission.submissionSerial;
    }
    if(!add(2*c.incumbent.endpoints.capacity()*sizeof(DirectGratingEndpointIrradianceSum))
        ||!add(2*c.incumbent.submission.frameIdentity.capacity()))return refuse();
    if(!metalDirectCohortIncumbentRetained(state,*c.prepared,c.incumbent.cohort,serial)
        &&!add(c.incumbent.cohort->bounds().bytes))return refuse();
    return true;
}

static bool metalTerminalPayloadBytes(const arbitgpu::glasscaustics::DirectGratingTerminalOrderLedger& value,
    std::uint64_t& bytes,std::string& error)
{
    using namespace arbitgpu;using namespace glasscaustics;
    bytes=sizeof(DirectGratingTerminalOrderLedger);
    const auto add=[&](std::uint64_t n,std::uint64_t stride=1){
        if(n>(renderpassoutput::kMaximumTotalBytes-bytes)/stride)return false;bytes+=n*stride;return true;};
    if(!add(value.sources.capacity(),sizeof(NativeDirectGratingContributionReadback))
        ||!add(value.bands.capacity(),sizeof(DirectGratingTerminalBand))
        ||!add(value.orders.capacity(),sizeof(DirectGratingTerminalOrder))
        ||!add(value.incident.endpoints.capacity(),sizeof(DirectGratingEndpointIrradianceSum))
        ||!add(value.incident.submission.frameIdentity.capacity())) {
        error="Metal terminal payload capacity exceeds original bytes";return false;
    }
    for(const auto& source:value.sources)
        if(!add(source.samples.capacity(),sizeof(NativeDirectGratingContributionSample))||!add(source.submission.frameIdentity.capacity())) {
            error="Metal terminal source capacity exceeds original bytes";return false;
        }
    return true;
}
static bool metalTerminalOwnerBytes(const MetalFixtureSceneFrame& frame,const MetalCausticState::TerminalAttempt& attempt,
    std::uint64_t& bytes,std::string& error)
{
    using namespace arbitgpu;using namespace glasscaustics;bytes=0;
    if(!attempt.result)return true;
    const auto& value=attempt.result->retained();const auto* c=attempt.cohort;
    if(!c||attempt.result->owner()!=&frame||value.nativeResult||value.incident.cohort!=c->prepared
        ||std::tie(value.bounds.bytes,value.bounds.combinedWork,value.bounds.depositionWork,value.bounds.maximumBands,value.bounds.maximumOrders)
            !=std::tie(attempt.bounds.bytes,attempt.bounds.combinedWork,attempt.bounds.depositionWork,attempt.bounds.maximumBands,attempt.bounds.maximumOrders)
        ||!(value.incident.submission==c->seal)||value.sources.size()!=c->readbacks.size()
        ||value.incident.endpoints.size()!=c->prepared->inputs().size()
        ||value.bands.size()!=attempt.bounds.maximumBands||value.orders.size()>attempt.bounds.maximumOrders
        ||value.sources.capacity()>2*value.sources.size()||value.incident.endpoints.capacity()>2*value.incident.endpoints.size()
        ||value.bands.capacity()>2*attempt.bounds.maximumBands||value.orders.capacity()>2*attempt.bounds.maximumOrders
        ||value.incident.submission.frameIdentity.capacity()>2*c->prepared->identity().size()) {
        error="Metal terminal retained owner lost its immutable cohort association";return false;
    }
    for(std::size_t s=0;s<value.sources.size();++s)
        if(!sameDirectGratingContributionReadback(value.sources[s],c->readbacks[s])
            ||value.sources[s].samples.capacity()>2*c->prepared->inputs().size()
            ||value.sources[s].submission.frameIdentity.capacity()>2*c->prepared->sources()[s]->identity.size()) {
            error="Metal terminal retained source owner or capacity changed";return false;
        }
    if(!metalTerminalPayloadBytes(value,bytes,error))return false;
    // Charge the maximum allowed returned capacities for the lifetime of the
    // sealed owner. Copies retained outside the frame cannot erase this charge.
    const auto add=[&](std::uint64_t n,std::uint64_t stride=1){
        if(n>(renderpassoutput::kMaximumTotalBytes-bytes)/stride)return false;bytes+=n*stride;return true;};
    if(!add(sizeof(NativeDirectGratingTerminalResult)+128+sizeof(DirectGratingTerminalOrderLedger))
        ||!add(2*attempt.bounds.maximumBands,sizeof(DirectGratingTerminalBand))
        ||!add(2*attempt.bounds.maximumOrders,sizeof(DirectGratingTerminalOrder))
        ||!add(2*value.sources.size(),sizeof(NativeDirectGratingContributionReadback))
        ||!add(2*c->prepared->inputs().size(),sizeof(DirectGratingEndpointIrradianceSum))
        ||!add(2*c->prepared->identity().size()))return false;
    for(const auto& binding:c->prepared->sources())
        if(!add(2*c->prepared->inputs().size(),sizeof(NativeDirectGratingContributionSample))||!add(2*binding->identity.size()))return false;
    return true;
}
static bool metalTerminalReturnedCapacities(const arbitgpu::glasscaustics::DirectGratingTerminalOrderLedger& value,
    const MetalDirectGratingCohort& c,const arbitgpu::glasscaustics::DirectGratingTerminalOrderBounds& bounds)
{
    const auto endpoints=c.prepared->inputs().size(),sources=c.prepared->sources().size();
    if(value.sources.size()!=sources||value.sources.capacity()>2*sources
        ||value.incident.endpoints.size()!=endpoints||value.incident.endpoints.capacity()>2*endpoints
        ||value.incident.submission.frameIdentity.capacity()>2*c.prepared->identity().size()
        ||value.bands.size()!=bounds.maximumBands||value.bands.capacity()>2*bounds.maximumBands
        ||value.orders.size()>bounds.maximumOrders||value.orders.capacity()>2*bounds.maximumOrders)return false;
    for(std::size_t i=0;i<sources;++i)if(value.sources[i].samples.size()!=endpoints||value.sources[i].samples.capacity()>2*endpoints
        ||value.sources[i].submission.frameIdentity.capacity()>2*c.prepared->sources()[i]->identity.size())return false;
    return true;
}
static bool metalTerminalRegistry(const MetalFixtureSceneFrame& frame,std::uint64_t& bytes,
    std::uint64_t& work,std::uint64_t& deposition,std::string& error)
{
    using namespace arbitgpu;using namespace glasscaustics;const auto& state=*frame.caustic;
    bytes=work=deposition=0;
    if(state.terminalAttemptCount>state.terminalAttempts.size())return false;
    for(std::size_t i=0;i<state.terminalAttemptCount;++i) {
        const auto& a=state.terminalAttempts[i];
        const auto found=std::find_if(state.directCohorts.begin(),state.directCohorts.end(),[&](const auto& c){return c.get()==a.cohort;});
        if(found==state.directCohorts.end()||!a.serial||a.serial<=a.cohort->seal.submissionSerial
            ||(i&&a.serial<=state.terminalAttempts[i-1].serial))return false;
        const auto bands=a.cohort->sources.size()*a.cohort->prepared->inputs().size()*8;
        const auto orders=bands*kGratingOrdersPerIncident;
        std::uint64_t owned=0;
        if(a.bounds.maximumBands!=bands||a.bounds.maximumOrders!=orders
            ||bands+orders>kMaximumQueryWork-work||orders>kMaximumDepositionWork-deposition
            ||!metalTerminalOwnerBytes(frame,a,owned,error)||owned>renderpassoutput::kMaximumTotalBytes-bytes)return false;
        work+=bands+orders;deposition+=orders;bytes+=owned;
    }
    return true;
}
static bool metalDirectAttemptWork(const MetalCausticState& state,std::uint64_t& work,
    std::uint64_t& deposition,std::string& error)
{
    using namespace arbitgpu;using namespace glasscaustics;work=deposition=0;
    if(state.directAttemptCount>state.directAttempts.size())return false;
    for(std::size_t i=0;i<state.directAttemptCount;++i) {
        const auto& a=state.directAttempts[i];std::uint64_t own=0,deposit=0;
        if(!a.binding||!a.endpoints||a.endpoints>kMaximumEntrySamples)return false;
        if(a.cohort) {
            if(a.cohort!=state.stagedDirectCohort||a.binding!=a.cohort->sources()[0]||a.endpoints!=a.cohort->inputs().size())return false;
            own=a.cohort->bounds().combinedWork;deposit=a.cohort->bounds().depositionWork;
        } else if(a.camera) {
            GlassCameraGratingTraceBounds bounds;
            if(!calculateGlassCameraGratingTraceBounds(*a.binding,a.endpoints,0,0,bounds,error))return false;
            own=bounds.queryWork+bounds.branchWork;
        } else {
            DirectGratingContributionBounds bounds;
            if(!calculateDirectGratingContributionBounds(*a.binding,a.endpoints,0,0,bounds,error))return false;
            own=bounds.queryWork+bounds.bandWork;
        }
        if(own>kMaximumQueryWork-work||deposit>kMaximumDepositionWork-deposition)return false;
        work+=own;deposition+=deposit;
    }
    return true;
}
static bool validateMetalDirectAttemptLedgerUnlocked(const MetalFixtureSceneFrame& frame,std::string& error)
{
    using namespace arbitgpu;using namespace glasscaustics;
    if(!frame.caustic){error="Metal native attempt ledger has no frame owner";return false;}
    const auto& state=*frame.caustic;
    // These adjunct producers have no complete attempted-work journal here.
    if(state.adjunctWork||state.cameraWork||state.cellWork||state.coverageWork||state.cameraPrimitiveBytes
        ||state.cellPrimitiveBytes||state.coveragePrimitiveBytes||state.cameraReceipt||state.cameraSpectral||state.cameraResolved
        ||state.cellInput||state.cellEcho||state.cellPointNative||state.cellBoundaryNative||state.cellLocatorNative||state.coverageNative) {
        error="Metal native attempt ledger cannot authenticate later adjunct ownership";return false;
    }
    std::uint64_t terminalBytes=0,terminalWork=0,terminalDeposition=0,directWork=0,directDeposition=0,receiverBytes=0,receiverWork=0,receiverNative=0,coverageBytes=0,coverageWork=0,coverageNative=0;
    if(!metalTerminalRegistry(frame,terminalBytes,terminalWork,terminalDeposition,error)
        ||!metalDirectAttemptWork(state,directWork,directDeposition,error)
        ||!metalReceiverRegistry(frame,receiverBytes,receiverWork,receiverNative,error)
        ||!metalCameraCoverageRegistry(frame,coverageBytes,coverageWork,coverageNative,error)
        ||coverageWork>kMaximumQueryWork-terminalWork||receiverWork>kMaximumQueryWork-terminalWork-coverageWork
        ||directWork>kMaximumQueryWork-terminalWork-receiverWork-coverageWork||directDeposition>kMaximumDepositionWork-terminalDeposition
        ||state.directWork!=directWork+terminalWork+receiverWork+coverageWork||state.cohortDepositionWork!=directDeposition+terminalDeposition) {
        error="Metal native attempt work/deposition differs from retained journals";return false;
    }
    return validateMetalDirectRetainedBytesUnlocked(frame,error);
}

static bool metalDirectCohortFrameReservation(const MetalFixtureSceneFrame& frame,const MetalDirectGratingCohort& c,
    std::uint64_t stagedBytes,std::string& error)
{
    using namespace arbitgpu;using namespace glasscaustics;
    const auto refuse=[&](){error="Metal directional cohort source reservation differs from its actual common admission";return false;};
    const auto& state=*frame.caustic;const auto serial=c.sources[0]->batch->readback.submission.submissionSerial;
    std::uint64_t bytes=state.cameraBinding->frame.bounds.transientBytes;
    const auto add=[&](std::uint64_t amount){if(amount>renderpassoutput::kMaximumTotalBytes-bytes)return false;bytes+=amount;return true;};
    if(!add(state.cameraBinding->bounds.bytes)||!add(stagedBytes)||!add(c.reservedBytes)
        ||!add(state.cameraPrimitiveBytes)||!add(state.cellPrimitiveBytes)||!add(state.coveragePrimitiveBytes))return refuse();
    for(const auto& b:state.directBatches)if(b->readback.submission.submissionSerial<serial&&!add(b->reservedBytes))return refuse();
    for(const auto& b:state.cameraTraceBatches)if(b->readback.submission.submissionSerial<serial&&!add(b->reservedBytes))return refuse();
    for(const auto& prior:state.directCohorts)if(prior->seal.submissionSerial<serial&&!add(prior->reservedBytes))return refuse();
    for(std::size_t i=0;i<state.terminalAttemptCount;++i)if(state.terminalAttempts[i].serial<serial) {
        std::uint64_t owned=0;if(!metalTerminalOwnerBytes(frame,state.terminalAttempts[i],owned,error)||!add(owned))return refuse();
    }
    for(std::size_t i=0;i<state.receiverAttemptCount;++i)
        if(state.receiverAttempts[i].serial<serial&&!add(state.receiverAttempts[i].retainedBytes))return refuse();
    for(std::size_t i=0;i<state.cameraCoverageAttemptCount;++i)
        if(state.cameraCoverageAttempts[i].serial<serial&&!add(state.cameraCoverageAttempts[i].retainedBytes))return refuse();
    for(std::size_t i=0;i<state.finiteSourceAttemptCount;++i)
        if(state.finiteSourceAttempts[i].serial<serial&&!add(state.finiteSourceAttempts[i].retainedBytes))return refuse();
    for(std::size_t i=0;i<state.finiteReceiverAttemptCount;++i)
        if(state.finiteReceiverAttempts[i].serial<serial&&!add(state.finiteReceiverAttempts[i].retainedBytes))return refuse();
    for(std::size_t i=0;i<state.lambertianAttemptCount;++i)
        if(state.lambertianAttempts[i].serial<serial&&!add(state.lambertianAttempts[i].retainedBytes))return refuse();
    if(state.lambertianFixtureSerial<serial&&!add(state.lambertianFixtureBytes))return refuse();
    if(state.finiteRadianceAdmission){
        if(state.finiteRadianceControlSerial<serial&&!add(state.finiteRadianceControlBytes))return refuse();
        for(std::size_t i=0;i<state.finiteRadianceAdmission->attempts();++i){const auto& a=state.finiteRadianceAdmission->record(i);
            if(a.live&&a.serial<serial&&!add(a.bytes))return refuse();}
    }
    if(state.finiteRgbAdmission){
        if(state.finiteRgbControlSerial<serial&&!add(state.finiteRgbControlBytes))return refuse();
        for(std::size_t i=0;i<state.finiteRgbAdmission->attempts();++i){const auto& a=state.finiteRgbAdmission->record(i);
            if(a.live&&a.serial<serial&&!add(a.bytes))return refuse();}
    }
    if(bytes!=c.frameBytes)return refuse();
    for(const auto& view:c.sources) {
        const auto& b=*view->batch;DirectGratingContributionBounds own;
        if(!calculateDirectGratingContributionBounds(*b.binding,b.upload.inputs.size(),0,0,own,error))return false;
        const auto ownBytes=b.binding->frame.bounds.transientBytes+b.binding->bounds.bytes+own.bytes;
        if(ownBytes>bytes||b.upload.otherOwnedBytes!=bytes-ownBytes)return refuse();
    }
    return true;
}

static bool metalDirectCohortStageBytes(const MetalFixtureSceneFrame& frame,
    std::uint64_t& admitted,std::uint64_t& native,std::string& error)
{
    using namespace arbitgpu;using namespace glasscaustics;using HarmonicMIDI::grid::Visual3DScene;
    const auto refuse=[&](){error="Metal directional cohort staged native byte ledger differs from actual owners";return false;};
    if(!frame.staticResources||!frame.staticResources->snapshot||!frame.staticResources->materialProgram
        ||!frame.caustic||!frame.caustic->cameraBinding||!gMetalDevice)return refuse();
    const auto& resources=*frame.staticResources;const auto& state=*frame.caustic;const auto& schedule=state.schedule;
    const auto& binding=*state.cameraBinding;const auto& scene=*resources.snapshot;
    if(!inspectMetalRasterCaptureUnlocked(frame,error))return false;
    const auto scenePayload=sizeof(Visual3DScene)+Visual3DScene::kMaxTextureTexels*sizeof(HarmonicMIDI::grid::SceneTexelRgba8);
    const auto paddedQuery=std::uint64_t(opaquevisibility::kTextureWidth)*schedule.query.height*16;
    std::uint64_t host=state.rasterCapture->hostReservation+8*scenePayload+128*1024+sizeof(MetalFixtureSceneResources)+sizeof(MetalFixtureSceneFrame)
        +sizeof(MetalCausticState)+sizeof(NativeFixtureSceneRuntimeInputs)+scene.objectCount*(sizeof(FixtureUniforms)+sizeof(sg_bindings))
        +(resources.opaqueVisibility.texels.capacity()+4*resources.smoothGlass.query.texels.capacity())*16
        +(resources.opaqueVisibility.meshes.capacity()+4*resources.smoothGlass.query.meshes.capacity())*sizeof(opaquevisibility::Mesh)
        +2*paddedQuery+2*binding.bounds.bytes+schedule.bounds.transientBytes
        +(schedule.sourceDirectionalIrradiance.version?4*metalcaustic::shader(false).size()+sizeof(NativeDirectionalSourceEcho):0);
    const auto chargeProgram=[&](const auto& program){
        if(program)host+=sizeof(NativeFixtureSurfaceMaterialProgram)+program->programIdentity.capacity()+program->bindingDigest.capacity()
            +program->diffractionProductDigest.capacity()
            +program->objectPrograms.capacity()*sizeof(std::shared_ptr<const NativeFixtureSurfaceMaterialProgram>);
    };
    chargeProgram(resources.materialProgram);chargeProgram(resources.discreteGratingProgram);
    for(const auto& child:resources.materialProgram->objectPrograms)chargeProgram(child);
    if(resources.privateSurfaceAdmission) host=surfacesource::add(host,resources.privateSurfaceAdmission->bytes());
    if(host>renderpassoutput::kMaximumTotalBytes)return refuse();native=0;
    std::vector<const void*> seen;
    seen.reserve(128+resources.textureImages.size()*SG_NUM_INFLIGHT_FRAMES+6*state.rasterCapture->passes.size());
    if(seen.capacity()>2*(128+resources.textureImages.size()*SG_NUM_INFLIGHT_FRAMES+6*state.rasterCapture->passes.size()))return refuse();
    const auto charge=[&](id value,std::uint64_t bytes){
        if(value==nil)return true;const void* identity=(__bridge const void*)value;
        if(std::find(seen.begin(),seen.end(),identity)!=seen.end())return true;
        if(bytes>renderpassoutput::kMaximumTotalBytes-host-native)return false;
        if(seen.size()==seen.capacity())return false;
        seen.push_back(identity);native+=bytes;return true;
    };
    const auto chargeImage=[&](sg_image image){
        if(!image.id)return true;if(!resourceValid(sg_query_image_state(image)))return false;
        const auto info=sg_mtl_query_image_info(image);
        for(int i=0;i<SG_NUM_INFLIGHT_FRAMES;++i) {
            id<MTLTexture> v=(__bridge id<MTLTexture>)info.tex[i];
            if(v!=nil&&(v.device!=gMetalDevice||!charge(v,v.allocatedSize)))return false;
        }return true;
    };
    const auto chargeBuffer=[&](sg_buffer buffer){
        if(!buffer.id)return true;if(!resourceValid(sg_query_buffer_state(buffer)))return false;
        const auto info=sg_mtl_query_buffer_info(buffer);
        for(int i=0;i<SG_NUM_INFLIGHT_FRAMES;++i) {
            id<MTLBuffer> v=(__bridge id<MTLBuffer>)info.buf[i];
            if(v!=nil&&(v.device!=gMetalDevice||!charge(v,std::max<std::uint64_t>(v.length,v.allocatedSize))))return false;
        }return true;
    };
    if(!chargeMetalRasterCaptureNative(state,charge)||!state.query||state.query.device!=gMetalDevice||!charge(state.query,state.query.allocatedSize))return refuse();
    for(auto buffer:{state.work,state.triangles})
        if(!buffer||buffer.device!=gMetalDevice||!charge(buffer,std::max<std::uint64_t>(buffer.length,buffer.allocatedSize)))return refuse();
    if(schedule.sourceDirectionalIrradiance.version) {
        for(auto buffer:{state.directionalInput,state.directionalEcho})
            if(!buffer||buffer.device!=gMetalDevice||!charge(buffer,std::max<std::uint64_t>(buffer.length,buffer.allocatedSize)))return refuse();
    } else if(state.directionalInput||state.directionalEcho)return refuse();
    for(auto image:{state.rasterDepthStencil,state.rasterImages[0],state.rasterImages[1],frame.colorImage,
        frame.depthImage,frame.depthStencilImage,frame.diffractionAccumulationImage})if(!chargeImage(image))return refuse();
    for(auto image:frame.rawImages)if(!chargeImage(image))return refuse();
    for(auto image:resources.textureImages)if(!chargeImage(image))return refuse();
    if(!chargeImage(resources.environmentTexture))return refuse();
    for(auto buffer:{resources.vertexBuffer,resources.previousVertexBuffer,resources.indexBuffer,resources.geometryInstanceBuffer})
        if(!chargeBuffer(buffer))return refuse();
    admitted=host+native;return true;
}

// Producers and the common inspector use the same actual retained-owner proof.
// An in-flight candidate is separately reserved and is not a retained owner.
static bool validateMetalDirectRetainedBytesUnlocked(const MetalFixtureSceneFrame& frame,std::string& error)
{
    using namespace arbitgpu;using namespace glasscaustics;
    const auto refuse=[&](){error="Metal native retained bytes differ from actual owners";return false;};
    if(!frame.caustic||!frame.staticResources||!frame.staticResources->materialProgram||!gMetalDevice)return refuse();
    const auto supportedProgram=[](const auto& program){
        return program&&!program->vertexProgram&&!program->importedBaseColorTexture&&!program->frameEndpoint;
    };
    if(!supportedProgram(frame.staticResources->materialProgram)||!supportedProgram(frame.staticResources->discreteGratingProgram))return refuse();
    for(const auto& child:frame.staticResources->materialProgram->objectPrograms)if(!supportedProgram(child))return refuse();
    const auto& state=*frame.caustic;MetalDirectQueryLease lease(&frame);
    if(state.directCohorts.capacity()>2*kMaximumEntrySamples||state.directBatches.capacity()>2*kMaximumEntrySamples
        ||state.cameraTraceBatches.capacity()>2*kMaximumEntrySamples)return refuse();
    std::uint64_t retainedBytes=0,retainedNative=0,retainedDeposition=0;
    const auto chargeRetained=[&](std::uint64_t amount){
        if(amount>renderpassoutput::kMaximumTotalBytes-retainedBytes)return false;
        retainedBytes+=amount;return true;
    };
    for(const auto& b:state.directBatches) {
        if(!b||!b->binding)return refuse();DirectGratingContributionBounds bounds;
        if(!calculateDirectGratingContributionBounds(*b->binding,b->upload.inputs.size(),0,0,bounds,error))return refuse();
        if(b->binding!=state.cameraBinding||b->source.capacity()>2*128*1024
            ||b->upload.inputs.capacity()>2*b->upload.inputs.size()||b->packed.capacity()>2*b->upload.inputs.size()
            ||b->readback.samples.capacity()>2*b->upload.inputs.size()||b->witnesses.capacity()>2*b->binding->triangles.size()
            ||b->upload.submission.frameIdentity.capacity()>2*b->binding->identity.size()
            ||b->readback.submission.frameIdentity.capacity()>2*b->binding->identity.size()
            ||b->sourceUpload.submission.frameIdentity.capacity()>2*b->binding->identity.size())return refuse();
        const auto overhead=sizeof(MetalDirectGratingBatch)+3*128*1024+128*1024+4*64*1024
            +3*b->binding->triangles.size()*sizeof(metalcaustic::DirectGratingWitness)
            +b->upload.inputs.size()*(sizeof(NativeDirectGratingEndpointInput)+sizeof(metalcaustic::DirectGratingResult)
                +2*sizeof(NativeDirectGratingContributionSample))+2*sizeof(metalcaustic::DirectGratingParams)
            +2*kMaximumEntrySamples*sizeof(std::unique_ptr<MetalDirectGratingBatch>);
        if(b->reservedBytes!=bounds.bytes+overhead||!chargeRetained(bounds.bytes+overhead))return refuse();
        const std::array<id<MTLBuffer>,4> buffers{b->input,b->result,b->witness,b->uniforms};
        const std::array<std::uint64_t,4> lengths{b->upload.inputs.size()*sizeof(NativeDirectGratingEndpointInput),
            b->packed.size()*sizeof(metalcaustic::DirectGratingResult),b->witnesses.size()*sizeof(metalcaustic::DirectGratingWitness),sizeof(b->params)};
        std::uint64_t alignment=0;
        for(unsigned i=0;i<buffers.size();++i) {
            const auto v=buffers[i];
            if(!v||!v.contents||v.device!=gMetalDevice||v.length!=lengths[i]||v.length>gMetalDevice.maxBufferLength)return refuse();
            const auto actual=std::max<std::uint64_t>(v.length,v.allocatedSize);
            if(actual-v.length>4*64*1024-alignment)return refuse();alignment+=actual-v.length;retainedNative+=actual;
        }
    }
    for(const auto& b:state.cameraTraceBatches) {
        if(!b||!b->binding)return refuse();GlassCameraGratingTraceBounds bounds;
        if(!calculateGlassCameraGratingTraceBounds(*b->binding,b->upload.inputs.size(),0,0,bounds,error))return refuse();
        if(b->binding!=state.cameraBinding||b->source.capacity()>2*128*1024
            ||b->inputs.capacity()>2*b->upload.inputs.size()||b->upload.inputs.capacity()>2*b->upload.inputs.size()
            ||b->packed.capacity()>2*b->upload.inputs.size()*8||b->visits.capacity()>2*b->upload.inputs.size()*8*kMaximumBranchVisits
            ||b->witnesses.capacity()>2*b->binding->triangles.size()||b->readback.bands.capacity()>2*b->upload.inputs.size()*8
            ||b->upload.submission.frameIdentity.capacity()>2*b->binding->identity.size()
            ||b->readback.submission.frameIdentity.capacity()>2*b->binding->identity.size())return refuse();
        for(const auto& band:b->readback.bands)if(band.visits.capacity()>2*kMaximumBranchVisits)return refuse();
        const auto overhead=sizeof(MetalCameraGratingTraceBatch)+5*128*1024+128*1024+5*64*1024
            +3*b->binding->triangles.size()*sizeof(metalcaustic::DirectGratingWitness)+2*sizeof(metalcaustic::GlassCameraTraceParams)
            +opaquevisibility::kTextureWidth*sizeof(Texel)+2*kMaximumEntrySamples*sizeof(std::unique_ptr<MetalCameraGratingTraceBatch>);
        if(b->reservedBytes!=bounds.bytes+overhead||!chargeRetained(bounds.bytes+overhead))return refuse();
        const std::array<id<MTLBuffer>,5> buffers{b->input,b->result,b->visit,b->witness,b->uniforms};
        const std::array<std::uint64_t,5> lengths{b->inputs.size()*sizeof(metalcaustic::GlassCameraTraceInput),
            b->packed.size()*sizeof(metalcaustic::GlassCameraTraceResult),b->visits.size()*sizeof(metalcaustic::GlassCameraTraceVisit),
            b->witnesses.size()*sizeof(metalcaustic::DirectGratingWitness),sizeof(b->params)};
        std::uint64_t alignment=0;
        for(unsigned i=0;i<buffers.size();++i) {
            const auto v=buffers[i];
            if(!v||!v.contents||v.device!=gMetalDevice||v.length!=lengths[i]||v.length>gMetalDevice.maxBufferLength)return refuse();
            const auto actual=std::max<std::uint64_t>(v.length,v.allocatedSize);
            if(actual-v.length>5*64*1024-alignment)return refuse();alignment+=actual-v.length;retainedNative+=actual;
        }
    }
    for(const auto& accepted:state.directCohorts) {
        std::uint64_t reservation=0,native=0;
        if(!accepted||!accepted->prepared||!accepted->originalCharged
            ||!metalDirectCohortStoredBytes(state,*accepted,reservation,native,error)||!chargeRetained(reservation)
            ||accepted->prepared->bounds().depositionWork>kMaximumDepositionWork-retainedDeposition)return refuse();
        retainedNative+=native;
        retainedDeposition+=accepted->prepared->bounds().depositionWork;
    }
    std::uint64_t terminalBytes=0,terminalWork=0,terminalDeposition=0;
    if(!metalTerminalRegistry(frame,terminalBytes,terminalWork,terminalDeposition,error)||!chargeRetained(terminalBytes))return refuse();
    std::uint64_t receiverBytes=0,receiverWork=0,receiverNative=0;
    if(!metalReceiverRegistry(frame,receiverBytes,receiverWork,receiverNative,error)||!chargeRetained(receiverBytes))return refuse();
    retainedNative+=receiverNative;
    std::uint64_t coverageBytes=0,coverageWork=0,coverageNative=0;
    if(!metalCameraCoverageRegistry(frame,coverageBytes,coverageWork,coverageNative,error)||!chargeRetained(coverageBytes))return refuse();
    retainedNative+=coverageNative;
    std::uint64_t numericalBytes=0,numericalNative=0;
    if(!metalLambertianRegistry(frame,numericalBytes,numericalNative,error)||!chargeRetained(numericalBytes))return refuse();
    retainedNative+=numericalNative;
    std::uint64_t completeBytes=0,completeNative=0;
    if(!metalCompleteBaseRegistry(frame,completeBytes,completeNative,error)||!chargeRetained(completeBytes))return refuse();
    retainedNative+=completeNative;
    std::uint64_t radianceBytes=0;
    if(!metalFiniteRadianceRegistry(frame,radianceBytes,error)||!chargeRetained(radianceBytes))return refuse();
    std::uint64_t rgbBytes=0,rgbNative=0;
    if(!metalFiniteRgbRegistry(frame,rgbBytes,rgbNative,error)||!chargeRetained(rgbBytes))return refuse();
    retainedNative+=rgbNative;
    if(retainedBytes!=state.directPrimitiveBytes)return refuse();
    if(state.cohortCandidate&&state.cohortCandidate->originalCharged) {
        if(!state.cohortCandidate->prepared
            ||state.cohortCandidate->prepared->bounds().depositionWork>kMaximumDepositionWork-retainedDeposition)return refuse();
        retainedDeposition+=state.cohortCandidate->prepared->bounds().depositionWork;
    }
    if(state.cohortDepositionWork<retainedDeposition)return refuse();
    std::uint64_t stagedBytes=0,stagedNative=0;
    if(!metalDirectCohortStageBytes(frame,stagedBytes,stagedNative,error)||state.metrics.admittedBytes!=stagedBytes
        ||retainedBytes>renderpassoutput::kMaximumTotalBytes-stagedBytes
        ||retainedNative>renderpassoutput::kMaximumTotalBytes-stagedNative
        ||state.bytes!=stagedBytes+retainedBytes||state.metrics.retainedNativeBytes!=stagedNative+retainedNative
        ||state.metrics.peakNativeBytes<state.metrics.retainedNativeBytes)return refuse();
    for(const auto& accepted:state.directCohorts)
        if(!metalDirectCohortFrameReservation(frame,*accepted,stagedBytes,error))return refuse();
    return true;
}

static bool validateMetalDirectCohortUnlocked(const MetalFixtureSceneFrame& frame,const MetalDirectGratingCohort& c,
    const arbitgpu::glasscaustics::SubmissionIdentity& expected,
    const std::vector<arbitgpu::glasscaustics::NativeDirectGratingContributionReadback>& supplied,std::string& error)
{
    using namespace arbitgpu;using namespace glasscaustics;
    const auto refuse=[&](){error="Metal directional cohort lost its common frame, seal or cumulative reservation";return false;};
    if(metalDirectQueryLease!=&frame||!frame.caustic||!c.prepared||c.prepared!=frame.caustic->stagedDirectCohort
        ||!(c.seal==expected)||c.sources.size()!=c.prepared->sources().size()||supplied.size()!=c.sources.size()
        ||c.readbacks.size()!=c.sources.size()||!c.originalCharged||!c.command||!gMetalDevice
        ||c.command.status!=MTLCommandBufferStatusCompleted||c.sources.empty())return refuse();
    const auto& state=*frame.caustic;const auto queue=c.sources[0]->batch->queue;
    if(!validateMetalDirectAttemptLedgerUnlocked(frame,error))return false;
    if(c.command.commandQueue!=queue||queue!=(__bridge id<MTLCommandQueue>)sg_mtl_command_queue()||queue.device!=gMetalDevice
        ||!state.cohortStagingCommand||state.cohortStagingCommand.status!=MTLCommandBufferStatusCompleted
        ||state.cohortStagingCommand.commandQueue!=queue
        ||expected.rendererGeneration!=frame.rendererGeneration_||expected.rasterGeneration!=state.identity.rasterGeneration
        ||expected.queryGeneration!=state.identity.queryGeneration||expected.completedFence!=expected.submissionSerial
        ||expected.frameIdentity!=c.prepared->identity()||state.directWork<c.startingWork+c.originalWork+c.attemptWork
        ||c.originalWork+c.attemptWork!=c.prepared->bounds().combinedWork
        ||state.cohortDepositionWork<c.prepared->bounds().depositionWork
        ||state.directWork>kMaximumQueryWork-state.cameraBinding->bounds.combinedWork
        ||state.adjunctWork>kMaximumQueryWork-state.cameraBinding->bounds.combinedWork-state.directWork
        ||state.cohortDepositionWork>kMaximumDepositionWork-state.cameraBinding->frame.bounds.deposition.depositionWork
            -state.cameraBinding->bounds.orderWork)return refuse();
    const std::array<sg_pixel_format,2> formats{SG_PIXELFORMAT_RGBA32UI,SG_PIXELFORMAT_R32F};
    for(unsigned i=0;i<2;++i) {
        const auto image=state.rasterImages[i];const auto view=state.rasterViews[i];
        const auto desc=sg_query_image_desc(image);const auto native=sg_mtl_query_image_info(image);
        const auto attachment=sg_query_view_desc(view);
        id<MTLTexture> texture=native.active_slot>=0&&native.active_slot<SG_NUM_INFLIGHT_FRAMES
            ?(__bridge id<MTLTexture>)native.tex[native.active_slot]:nil;
        if(image.id!=c.rasterImages[i].id||view.id!=c.rasterViews[i].id||!resourceValid(sg_query_image_state(image))
            ||!resourceValid(sg_query_view_state(view))||attachment.color_attachment.image.id!=image.id
            ||desc.width!=int(frame.width_)||desc.height!=int(frame.height_)||desc.sample_count!=1||desc.pixel_format!=formats[i]
            ||!texture||texture.device!=gMetalDevice||texture.width!=frame.width_||texture.height!=frame.height_)return refuse();
    }
    const auto depth=state.rasterDepthStencil;const auto depthView=state.rasterDepthStencilView;
    const auto depthDesc=sg_query_image_desc(depth);const auto depthNative=sg_mtl_query_image_info(depth);
    id<MTLTexture> depthTexture=depthNative.active_slot>=0&&depthNative.active_slot<SG_NUM_INFLIGHT_FRAMES
        ?(__bridge id<MTLTexture>)depthNative.tex[depthNative.active_slot]:nil;
    if(depth.id!=c.rasterDepth.id||depthView.id!=c.rasterDepthView.id
        ||!resourceValid(sg_query_image_state(depth))||!resourceValid(sg_query_view_state(depthView))
        ||sg_query_view_desc(depthView).depth_stencil_attachment.image.id!=depth.id
        ||depthDesc.width!=int(frame.width_)||depthDesc.height!=int(frame.height_)||depthDesc.sample_count!=1
        ||depthDesc.pixel_format!=SG_PIXELFORMAT_DEPTH_STENCIL||!depthTexture||depthTexture.device!=gMetalDevice
        ||depthTexture.width!=frame.width_||depthTexture.height!=frame.height_)return refuse();
    const bool retained=std::any_of(state.directCohorts.begin(),state.directCohorts.end(),
        [&](const auto& accepted){return accepted.get()==&c;});
    if((!retained&&state.cohortCandidate!=&c)||(retained&&state.cohortCandidate==&c))return refuse();
    std::uint64_t reservation=0,candidateNative=0,stagedBytes=0,stagedNative=0;
    if(!metalDirectCohortStoredBytes(state,c,reservation,candidateNative,error)
        ||!metalDirectCohortStageBytes(frame,stagedBytes,stagedNative,error))return refuse();
    if(!metalDirectCohortFrameReservation(frame,c,stagedBytes,error))return refuse();
    std::uint64_t bytes=state.cameraBinding->frame.bounds.transientBytes;
    for(auto amount:{state.cameraBinding->bounds.bytes,state.metrics.admittedBytes,state.directPrimitiveBytes,
        state.cameraPrimitiveBytes,state.cellPrimitiveBytes,state.coveragePrimitiveBytes,state.cohortCandidate==&c?c.reservedBytes:std::uint64_t(0)}) {
        if(amount>renderpassoutput::kMaximumTotalBytes-bytes)return refuse();bytes+=amount;
    }
    std::uint64_t work=0,previousSerial=state.submission;
    for(std::size_t i=0;i<c.sources.size();++i) {
        const auto& view=*c.sources[i];const auto& b=*view.batch;
        if(&view.common!=&frame||&view.cohort!=&c||b.binding!=c.prepared->sources()[i]
            ||b.command.commandQueue!=queue||b.readback.submission.submissionSerial>=expected.submissionSerial
            ||b.readback.submission.submissionSerial<=previousSerial
            ||!sameDirectGratingContributionReadback(supplied[i],c.readbacks[i])
            ||!view.validateDirectProductionQuery(b.readback.submission,supplied[i],error))return refuse();
        for(std::size_t prior=0;prior<i;++prior) {
            const auto& other=*c.sources[prior]->batch;
            if(other.sourceInput==b.sourceInput||other.input==b.input||other.result==b.result
                ||other.sourceUpload.bindingGeneration==b.sourceUpload.bindingGeneration)return refuse();
        }
        work+=b.reservedWork;previousSerial=b.readback.submission.submissionSerial;
    }
    if(work!=c.attemptWork)return refuse();error.clear();return true;
}

class MetalTerminalLease final : public arbitgpu::glasscaustics::NativeDirectGratingTerminalLease {
public:
    struct SourceRegistration {
        const MetalDirectGratingSourceView* owner=nullptr;
        std::array<id<MTLBuffer>,5> buffers{};
        id<MTLCommandBuffer> command=nil;
        std::uint64_t sourceGeneration=0,endpointGeneration=0;
    };
    const MetalFixtureSceneFrame& frame;
    const MetalDirectGratingCohort& cohort;
    std::unique_lock<std::mutex> lock;
    MetalDirectQueryLease queryLease;
    const std::vector<arbitgpu::glasscaustics::NativeDirectGratingContributionReadback>& sources;
    const arbitgpu::glasscaustics::SubmissionIdentity seal;
    const double time;
    const std::uintptr_t cache;
    const id<MTLDevice> device;
    const id<MTLTexture> query;
    const id<MTLCommandBuffer> sealCommand;
    std::array<SourceRegistration,16> registeredSources{};
    arbitgpu::glasscaustics::DirectGratingTerminalNativeBudget baseline;
    std::shared_ptr<const arbitgpu::glasscaustics::NativeDirectGratingTerminalResult> staged;
    std::size_t attempt=SIZE_MAX;
    std::uint64_t stagedBytes=0;
    MetalTerminalLease(const MetalFixtureSceneFrame& f,const MetalDirectGratingCohort& c,
        std::unique_lock<std::mutex>&& guard,
        const std::vector<arbitgpu::glasscaustics::NativeDirectGratingContributionReadback>& s,double t)
        :frame(f),cohort(c),lock(std::move(guard)),queryLease(&f),sources(s),seal(c.seal),time(t),
        cache(f.nativeResourceCacheIdentity()),device(gMetalDevice),query(f.caustic->query),sealCommand(c.command) {
        for(std::size_t i=0;i<c.sources.size();++i) {
            const auto& view=*c.sources[i];const auto& b=*view.batch;auto& registration=registeredSources[i];
            registration.owner=&view;registration.buffers={b.input,b.result,b.witness,b.uniforms,b.sourceInput};
            registration.command=b.command;registration.sourceGeneration=b.readback.sourceGeneration;
            registration.endpointGeneration=b.readback.endpointGeneration;
        }
    }
    const arbitgpu::NativeFixtureSceneFrame& owner() const noexcept override{return frame;}
    ~MetalTerminalLease() override {
        // Candidate storage dies while the native context and query guard live.
        staged.reset();frame.caustic->terminalLease=nullptr;
    }
private:
    void commit() noexcept override {
        auto& state=*frame.caustic;
        state.terminalAttempts[attempt].result=std::move(staged);
        state.directPrimitiveBytes+=stagedBytes;state.bytes+=stagedBytes;
    }
};
static bool metalTerminalBudget(const MetalFixtureSceneFrame& frame,const MetalDirectGratingCohort& c,
    arbitgpu::glasscaustics::DirectGratingTerminalNativeBudget& budget,std::string& error)
{
    using namespace arbitgpu;using namespace glasscaustics;const auto& state=*frame.caustic;
    const auto refuse=[&](){error="Metal terminal whole-frame ownership or attempt journal is unsupported";return false;};
    const auto supportedProgram=[](const auto& program){
        return program&&!program->vertexProgram&&!program->importedBaseColorTexture&&!program->frameEndpoint;
    };
    if(!supportedProgram(frame.staticResources->materialProgram)||!supportedProgram(frame.staticResources->discreteGratingProgram))return refuse();
    for(const auto& child:frame.staticResources->materialProgram->objectPrograms)if(!supportedProgram(child))return refuse();
    // These later producers have distinct native lifetime contracts. Until
    // their storage/work is independently inspectable here, fail closed.
    if(state.adjunctWork||state.cameraWork||state.cellWork||state.coverageWork||state.cameraPrimitiveBytes
        ||state.cellPrimitiveBytes||state.coveragePrimitiveBytes||state.cameraReceipt||state.cameraSpectral||state.cameraResolved
        ||state.cellInput||state.cellEcho||state.cellPointNative||state.cellBoundaryNative||state.cellLocatorNative||state.coverageNative
        ||!validateMetalDirectCohortUnlocked(frame,c,c.seal,c.readbacks,error))return refuse();
    if(!validateMetalDirectAttemptLedgerUnlocked(frame,error))return refuse();
    budget={state.cameraBinding->frame.bounds.transientBytes, state.cameraBinding->bounds.combinedWork,
        state.cameraBinding->frame.bounds.deposition.depositionWork+state.cameraBinding->bounds.orderWork};
    for(auto amount:{state.cameraBinding->bounds.bytes,state.bytes,std::uint64_t(sizeof(MetalTerminalLease)+128),
        std::uint64_t(2*c.seal.frameIdentity.capacity())}) {
        if(amount>renderpassoutput::kMaximumTotalBytes-budget.retainedBytes)return refuse();budget.retainedBytes+=amount;
    }
    if(state.directWork>kMaximumQueryWork-budget.combinedWork
        ||state.cohortDepositionWork>kMaximumDepositionWork-budget.depositionWork)return refuse();
    budget.combinedWork+=state.directWork;budget.depositionWork+=state.cohortDepositionWork;return true;
}
static const MetalTerminalLease* metalTerminalAssociation(const MetalFixtureSceneFrame& frame,
    const arbitgpu::glasscaustics::NativeDirectGratingTerminalLease& value,std::string& error)
{
    const auto* lease=dynamic_cast<const MetalTerminalLease*>(&value);
    if(!lease||&lease->frame!=&frame||!frame.caustic||frame.caustic->terminalLease!=lease
        ||!lease->lock.owns_lock()||metalDirectQueryLease!=&frame||frame.directCohortBatch()!=&lease->cohort
        ||!lease->cohort.prepared||lease->cohort.prepared->sources().empty()
        ||lease->cache!=frame.nativeResourceCacheIdentity()||lease->device!=gMetalDevice||lease->query!=frame.caustic->query
        ||lease->sealCommand!=lease->cohort.command||!(lease->seal==lease->cohort.seal)
        ||lease->time!=lease->cohort.prepared->sources()[0]->evaluationTime
        ||!validateMetalDirectCohortUnlocked(frame,lease->cohort,lease->seal,lease->sources,error)) {
        error="Metal terminal lease is not the exact registered native operation";return nullptr;
    }
    for(std::size_t i=0;i<lease->cohort.sources.size();++i) {
        const auto& view=*lease->cohort.sources[i];const auto& b=*view.batch;const auto& registered=lease->registeredSources[i];
        if(registered.owner!=&view||registered.buffers!=std::array<id<MTLBuffer>,5>{b.input,b.result,b.witness,b.uniforms,b.sourceInput}
            ||registered.command!=b.command||registered.sourceGeneration!=b.readback.sourceGeneration
            ||registered.endpointGeneration!=b.readback.endpointGeneration) {
            error="Metal terminal lease source registration changed";return nullptr;
        }
    }
    return lease;
}
bool MetalFixtureSceneFrame::beginDirectCohortTerminalLease(const arbitgpu::glasscaustics::SubmissionIdentity& expected,double time,
    const std::vector<arbitgpu::glasscaustics::NativeDirectGratingContributionReadback>& sources,
    std::unique_ptr<arbitgpu::glasscaustics::NativeDirectGratingTerminalLease>& output,
    arbitgpu::glasscaustics::DirectGratingTerminalNativeBudget& budget,std::string& error) const
{
    // Existing unlocked inspectors must never recursively acquire sokolMutex.
    if(metalDirectQueryLease||metalTerminalEntryFrame!=this||!metalTerminalEntryGuard||!metalTerminalEntryGuard->owns_lock()) {
        error="Metal terminal begin requires its guarded production entrypoint";return false;
    }
    std::unique_lock<std::mutex> guard(std::move(*metalTerminalEntryGuard));const auto* c=directCohortBatch();
    if(!c||!caustic||caustic->terminalLease||!c->prepared||c->prepared->sources().empty()
        ||!(expected==c->seal)||time!=c->prepared->sources()[0]->evaluationTime
        ||c->sources.size()>16||caustic->terminalAttemptCount>=caustic->terminalAttempts.size()) {
        error="Metal terminal begin lost its complete native cohort or registry capacity";return false;
    }
    arbitgpu::glasscaustics::DirectGratingTerminalNativeBudget admitted;
    {
        MetalDirectQueryLease inspection(this);
        if(!validateMetalDirectCohortUnlocked(*this,*c,expected,sources,error)||!metalTerminalBudget(*this,*c,admitted,error))return false;
    }
    auto lease=std::make_unique<MetalTerminalLease>(*this,*c,std::move(guard),sources,time);
    if(lease->seal.frameIdentity.capacity()>2*c->seal.frameIdentity.capacity()) {
        error="Metal terminal lease seal copy exceeds admitted metadata";return false;
    }
    lease->baseline=admitted;caustic->terminalLease=lease.get();output=std::move(lease);budget=admitted;error.clear();return true;
}
bool MetalFixtureSceneFrame::reserveDirectCohortTerminalLease(arbitgpu::glasscaustics::NativeDirectGratingTerminalLease& value,
    const arbitgpu::glasscaustics::DirectGratingTerminalOrderBounds& bounds,
    const arbitgpu::glasscaustics::DirectGratingTerminalOrderLedger& incumbent,std::string& error) const
{
    using namespace arbitgpu::glasscaustics;
    auto* lease=const_cast<MetalTerminalLease*>(metalTerminalAssociation(*this,value,error));
    if(!lease||lease->attempt!=SIZE_MAX)return false;
    DirectGratingTerminalNativeBudget actual;DirectGratingTerminalOrderBounds reconstructed;
    if(!metalTerminalBudget(*this,lease->cohort,actual,error)
        ||std::tie(actual.retainedBytes,actual.combinedWork,actual.depositionWork)
            !=std::tie(lease->baseline.retainedBytes,lease->baseline.combinedWork,lease->baseline.depositionWork)
        ||!calculateDirectGratingTerminalOrderBounds(*lease->cohort.prepared,lease->sources,actual,incumbent,reconstructed,error)
        ||std::tie(bounds.bytes,bounds.combinedWork,bounds.depositionWork,bounds.maximumBands,bounds.maximumOrders)
            !=std::tie(reconstructed.bytes,reconstructed.combinedWork,reconstructed.depositionWork,reconstructed.maximumBands,reconstructed.maximumOrders)) {
        error="Metal terminal reservation differs from complete actual ownership";return false;
    }
    auto& state=*caustic;lease->attempt=state.terminalAttemptCount++;
    auto& attempt=state.terminalAttempts[lease->attempt];attempt.cohort=&lease->cohort;attempt.bounds=bounds;
    attempt.serial=nextMetalRendererGeneration();
    state.directWork+=bounds.maximumBands+bounds.maximumOrders;
    state.cohortDepositionWork+=bounds.maximumOrders;
    error.clear();return true;
}
static bool sameMetalTerminalPayload(const arbitgpu::glasscaustics::DirectGratingTerminalOrderLedger& a,
    const arbitgpu::glasscaustics::DirectGratingTerminalOrderLedger& b)
{
    using namespace arbitgpu::glasscaustics;
    if(a.incident.cohort!=b.incident.cohort||!(a.incident.submission==b.incident.submission)
        ||a.incident.sourceMeasure!=b.incident.sourceMeasure||a.incident.endpoints.size()!=b.incident.endpoints.size()
        ||a.sources.size()!=b.sources.size()||a.bands.size()!=b.bands.size()||a.orders.size()!=b.orders.size()
        ||std::tie(a.bounds.bytes,a.bounds.combinedWork,a.bounds.depositionWork,a.bounds.maximumBands,a.bounds.maximumOrders)
            !=std::tie(b.bounds.bytes,b.bounds.combinedWork,b.bounds.depositionWork,b.bounds.maximumBands,b.bounds.maximumOrders))return false;
    for(std::size_t i=0;i<a.incident.endpoints.size();++i) {
        const auto& x=a.incident.endpoints[i];const auto& y=b.incident.endpoints[i];const auto& h=x.endpoint;const auto& k=y.endpoint;
        if(!sameDirectGratingEndpointInput(x.input,y.input)||x.barycentric!=y.barycentric||x.surfaceIrradiance!=y.surfaceIrradiance
            ||std::tie(h.status,h.objectId,h.materialId,h.instanceId,h.triangleId,h.entering,h.work,h.distance,h.position,h.outwardNormal)
                !=std::tie(k.status,k.objectId,k.materialId,k.instanceId,k.triangleId,k.entering,k.work,k.distance,k.position,k.outwardNormal))return false;
    }
    for(std::size_t i=0;i<a.sources.size();++i)if(!sameDirectGratingContributionReadback(a.sources[i],b.sources[i]))return false;
    for(std::size_t i=0;i<a.bands.size();++i) {
        const auto& x=a.bands[i];const auto& y=b.bands[i];
        if(std::tie(x.source,x.endpoint,x.band,x.witness,x.frame.tangent,x.frame.bitangent,x.frame.normal,x.toSource,x.uv,
            x.wavelengthNanometres,x.incidentIrradiance,x.substrateReflectedPower,x.resolvedReflectedPower,x.unresolvedReflectedPower,
            x.substrateReflectedIrradiance,x.resolvedReflectedIrradiance,x.unresolvedReflectedIrradiance,x.absorbedIrradiance,x.firstOrder,x.orderCount,x.responseEvaluated)
            !=std::tie(y.source,y.endpoint,y.band,y.witness,y.frame.tangent,y.frame.bitangent,y.frame.normal,y.toSource,y.uv,
            y.wavelengthNanometres,y.incidentIrradiance,y.substrateReflectedPower,y.resolvedReflectedPower,y.unresolvedReflectedPower,
            y.substrateReflectedIrradiance,y.resolvedReflectedIrradiance,y.unresolvedReflectedIrradiance,y.absorbedIrradiance,y.firstOrder,y.orderCount,y.responseEvaluated))return false;
    }
    for(std::size_t i=0;i<a.orders.size();++i) {
        const auto& x=a.orders[i];const auto& y=b.orders[i];
        if(std::tie(x.source,x.endpoint,x.band,x.order.primary,x.order.secondary,x.order.direction,x.order.reflectedPower,
            x.order.selectionProbability,x.order.angularStandardDeviationRadians,x.orderIrradiance)
            !=std::tie(y.source,y.endpoint,y.band,y.order.primary,y.order.secondary,y.order.direction,y.order.reflectedPower,
            y.order.selectionProbability,y.order.angularStandardDeviationRadians,y.orderIrradiance))return false;
    }
    return true;
}
bool MetalFixtureSceneFrame::finishDirectCohortTerminalLease(arbitgpu::glasscaustics::NativeDirectGratingTerminalLease& value,
    const arbitgpu::glasscaustics::DirectGratingTerminalOrderLedger& candidate,
    std::shared_ptr<const arbitgpu::glasscaustics::NativeDirectGratingTerminalResult>& output,std::string& error) const
{
    auto* lease=const_cast<MetalTerminalLease*>(metalTerminalAssociation(*this,value,error));
    if(!lease||lease->attempt==SIZE_MAX||lease->staged)return false;
    const auto& attempt=caustic->terminalAttempts[lease->attempt];
    if(candidate.nativeResult||candidate.incident.cohort!=lease->cohort.prepared||!(candidate.incident.submission==lease->seal)
        ||!metalTerminalReturnedCapacities(candidate,lease->cohort,attempt.bounds)
        ||std::tie(candidate.bounds.bytes,candidate.bounds.combinedWork,candidate.bounds.depositionWork,candidate.bounds.maximumBands,candidate.bounds.maximumOrders)
            !=std::tie(attempt.bounds.bytes,attempt.bounds.combinedWork,attempt.bounds.depositionWork,attempt.bounds.maximumBands,attempt.bounds.maximumOrders)) {
        error="Metal terminal finish lost its complete reservation";return false;
    }
    if(metalTerminalFixtureFault==0){error="Metal terminal fixture refused admitted finish";return false;}
    lease->staged=makeDirectCohortTerminalResult(candidate);
    if(metalTerminalFixtureFault==3)
        const_cast<arbitgpu::glasscaustics::DirectGratingTerminalOrderLedger&>(lease->staged->retained()).orders.reserve(2*attempt.bounds.maximumOrders+1);
    auto stagedAttempt=attempt;stagedAttempt.result=lease->staged;
    std::uint64_t returned=0;
    if(!metalTerminalOwnerBytes(*this,stagedAttempt,lease->stagedBytes,error)
        ||!metalTerminalPayloadBytes(candidate,returned,error)
        ||lease->stagedBytes>attempt.bounds.bytes-lease->baseline.retainedBytes
        ||returned>lease->stagedBytes)return false;
    if(metalTerminalFixtureFault==1){error="Metal terminal fixture refused staged finish";return false;}
    if(metalTerminalFixtureFault==2&&!lease->staged->retained().bands.empty())
        const_cast<arbitgpu::glasscaustics::DirectGratingTerminalOrderLedger&>(lease->staged->retained()).bands.front().absorbedIrradiance+=1;
    if(metalTerminalFixtureFault==4)
        const_cast<arbitgpu::glasscaustics::DirectGratingTerminalOrderLedger&>(candidate).bands.reserve(2*attempt.bounds.maximumBands+1);
    if(metalTerminalFixtureFault>=5) {
        auto& c=const_cast<MetalDirectGratingCohort&>(lease->cohort);auto& b=*c.sources.front()->batch;
        const auto fence=c.seal.completedFence;const auto result=b.result;const auto query=caustic->query;
        struct Restore {
            MetalDirectGratingCohort& c;MetalDirectGratingBatch& b;MetalCausticState& state;
            std::uint64_t fence;id<MTLBuffer> result;id<MTLTexture> query;MetalTerminalLease* lease;
            ~Restore(){c.seal.completedFence=fence;b.result=result;state.query=query;state.terminalLease=lease;}
        } restore{c,b,*caustic,fence,result,query,lease};
        if(metalTerminalFixtureFault==5)c.seal.completedFence=0;
        if(metalTerminalFixtureFault==6)b.result=nil;
        if(metalTerminalFixtureFault==7)caustic->query=nil;
        if(metalTerminalFixtureFault==8)caustic->terminalLease=nullptr;
        const bool accepted=metalTerminalAssociation(*this,value,error)!=nullptr;
        metalTerminalFixtureRegistrationRefused=!accepted;
        error=accepted?"Metal terminal fixture accepted a changed native registration":"Metal terminal fixture refused a changed native registration";
        return false;
    }
    output=lease->staged;error.clear();return true;
}
bool MetalFixtureSceneFrame::validateDirectCohortTerminalResult(const arbitgpu::glasscaustics::NativeDirectGratingTerminalLease& value,
    const arbitgpu::glasscaustics::DirectGratingTerminalOrderLedger& candidate,std::string& error) const
{
    const auto* lease=metalTerminalAssociation(*this,value,error);
    if(!lease||lease->attempt==SIZE_MAX||!lease->staged||candidate.nativeResult!=lease->staged
        ||caustic->terminalAttempts[lease->attempt].result
        ||!metalTerminalReturnedCapacities(candidate,lease->cohort,caustic->terminalAttempts[lease->attempt].bounds)
        ||!sameMetalTerminalPayload(candidate,lease->staged->retained())) {
        error="Metal terminal inspection requires its registered immutable result";return false;
    }
    arbitgpu::glasscaustics::DirectGratingTerminalNativeBudget actual;
    const auto& attempt=caustic->terminalAttempts[lease->attempt];auto stagedAttempt=attempt;stagedAttempt.result=lease->staged;
    std::uint64_t owned=0;
    if(!metalTerminalBudget(*this,lease->cohort,actual,error)||!metalTerminalOwnerBytes(*this,stagedAttempt,owned,error)
        ||owned!=lease->stagedBytes||actual.retainedBytes!=lease->baseline.retainedBytes
        ||actual.combinedWork!=attempt.bounds.combinedWork||actual.depositionWork!=attempt.bounds.depositionWork
        ||owned>attempt.bounds.bytes-actual.retainedBytes) {
        error="Metal terminal inspection lost actual storage or charged attempt work";return false;
    }
    error.clear();return true;
}
static id<MTLTexture> metalReceiverRaster(sg_image image) {
    const auto info=sg_mtl_query_image_info(image);
    return info.active_slot>=0&&info.active_slot<SG_NUM_INFLIGHT_FRAMES
        ?(__bridge id<MTLTexture>)info.tex[info.active_slot]:nil;
}
static bool sameMetalReceiverRow(const arbitgpu::glasscaustics::DirectGratingTerminalReceiverRow& a,
    const arbitgpu::glasscaustics::DirectGratingTerminalReceiverRow& b) {
    using namespace arbitgpu::glasscaustics;const auto& h=a.hit;const auto& k=b.hit;
    return sameDirectGratingTerminalReceiverInput(a.input,b.input)&&sameDirectGratingTerminalEmittedOrder(a.emitted,b.emitted)
        &&std::tie(h.status,h.distance,h.position,h.outwardNormal,h.objectId,h.materialId,h.instanceId,h.triangleId,h.entering,h.work)
            ==std::tie(k.status,k.distance,k.position,k.outwardNormal,k.objectId,k.materialId,k.instanceId,k.triangleId,k.entering,k.work)
        &&std::tie(a.disposition,a.pixel.projected,a.pixel.x,a.pixel.y,a.pixel.linearDepth,a.pixel.worldArea,a.rasterSample,
            a.raster.object,a.raster.material,a.raster.instance,a.raster.triangle,a.raster.linearDepth,a.queryWork)
            ==std::tie(b.disposition,b.pixel.projected,b.pixel.x,b.pixel.y,b.pixel.linearDepth,b.pixel.worldArea,b.rasterSample,
                b.raster.object,b.raster.material,b.raster.instance,b.raster.triangle,b.raster.linearDepth,b.queryWork);
}
static bool metalReceiverNative(const MetalFixtureSceneFrame& frame,const MetalCausticState::ReceiverAttempt& attempt,
    std::string& error) {
    using namespace arbitgpu;using namespace glasscaustics;const auto& state=*frame.caustic;
    const auto refuse=[&](){error="Metal terminal receiver lost its completed native query/raster payload";return false;};
    if(!attempt.native||!attempt.terminal||!attempt.cohort)return refuse();const auto& b=*attempt.native;
    const auto& terminal=attempt.terminal->retained();const auto& frozen=attempt.cohort->prepared->sources()[0]->frame;
    const auto count=terminal.orders.size(),allocated=std::max<std::size_t>(count,1);
    if(!b.dispatched||!b.command||b.command.status!=MTLCommandBufferStatusCompleted||!b.queue
        ||b.command.commandQueue!=b.queue||b.queue!=(__bridge id<MTLCommandQueue>)sg_mtl_command_queue()
        ||b.queue.device!=gMetalDevice||!b.library||b.library.device!=gMetalDevice||!b.pipeline||b.pipeline.device!=gMetalDevice
        ||b.query!=state.query||b.raster!=metalReceiverRaster(state.rasterImages[0])||b.depth!=metalReceiverRaster(state.rasterImages[1])
        ||!b.query||!b.raster||!b.depth||b.query.device!=gMetalDevice||b.raster.device!=gMetalDevice||b.depth.device!=gMetalDevice
        ||b.raster.pixelFormat!=MTLPixelFormatRGBA32Uint||b.depth.pixelFormat!=MTLPixelFormatR32Float
        ||b.raster.width!=frame.width_||b.raster.height!=frame.height_||b.depth.width!=frame.width_||b.depth.height!=frame.height_
        ||b.inputs.size()!=count||b.packed.size()!=count||b.readback.rows.size()!=count
        ||b.inputs.capacity()>2*attempt.bounds.maximumRows||b.packed.capacity()>2*attempt.bounds.maximumRows
        ||b.readback.rows.capacity()>2*attempt.bounds.maximumRows||b.source.capacity()>2*128*1024
