            ||!mul(w[1],cameraraycoefficients::maximumWordMoves(256),w[4])
            ||!mul(w[2],camerapixelsigns::maximumWordMoves(),extra)||!add(w[4],extra)
            ||!mul(w[1],cameraraycoefficients::maximumScalarOperations(256),w[5])
            ||!mul(w[2],camerapixelsigns::maximumScalarOperations(),extra)||!add(w[5],extra))return false;
