            ||!mul(w[1],4*camerawideline::kHostValidationScalarOperations,w[6])
            ||!mul(w[2],4*camerapixelsigns::kHostValidationScalarOperations,extra)||!add(w[6],extra)
            ||!mul(w[1],4*(4*557+4*57),extra)||!add(w[7],extra)
            ||!mul(w[2],4*(3*73+65),extra)||!add(w[7],extra)
            ||!mul(a.bounds.maximumPixels,t,w[8])||!mul(w[8],8,w[8]))return false;
