        const std::shared_ptr<const arbitgpu::glasscaustics::NativeDirectGratingTerminalReceiverResult>& p,
        const MetalCausticState::ReceiverAttempt* r,std::size_t slot,std::uint64_t serial)
        :frame(f),guard(std::move(g)),queryLease(&f),parent(p),receiver(r),cache(f.nativeResourceCacheIdentity()),device(gMetalDevice),
        attempt(slot),generation(serial){}
