static std::uint64_t metalCameraCoverageFixedBytes(const arbitgpu::glasscaustics::Frame& frozen) {
    using namespace arbitgpu;using namespace glasscaustics;
    constexpr std::uint64_t hostScratch=4*557*4+3*57*4+2*13*4*4+4*20*4+512;
    return 8*metalCameraCoverageSourceLimit+4*64*1024+2*sizeof(MetalCameraCoverageLease)
        +sizeof(MetalCameraCoverageBatch)+sizeof(NativeCameraCellCoverageResult)+128+hostScratch
        +4*23*4+4ull*frozen.triangles.size()*metalcaustic::kCameraDiagonalTriangleWords*4
        +2*frozen.query.texels.size()*sizeof(Texel)+opaquevisibility::kTextureWidth*sizeof(Texel)+64;
}
