static bool metalCameraRangeInputs(const MetalCameraRangeBatch& b,std::vector<std::uint32_t>* output) {
    using namespace arbitgpu::metalcaustic;const auto& g=*b.geometry;
    const auto p=b.parent->retained().preparation.pixels.size();
    if(output){output->resize(p*kCameraRangeRequestWords);if(output->capacity()>2*output->size())return false;}
    else if(b.inputs.size()!=p*kCameraRangeRequestWords)return false;
    const auto put=[&](std::size_t at,std::uint32_t word){if(output){(*output)[at]=word;return true;}return b.inputs[at]==word;};
    for(std::size_t pixel=0;pixel<p;++pixel){const auto stride=16+g.bounds.triangles*kCameraDiagonalPairWords;
        const auto* h=g.certificate.data()+pixel*stride;
        if(h[0]!=1||h[2]>=g.bounds.triangles)return false;
        const auto* record=h+16+h[2]*kCameraDiagonalPairWords;
        const auto base=pixel*kCameraRangeRequestWords;
        for(unsigned k=0;k<557;++k)if(!put(base+k,record[k]))return false;
        if(!put(base+557,b.interval[0])||!put(base+558,b.interval[1])||!put(base+559,1)||!put(base+560,256)
            ||!put(base+561,kCameraRangeWireTag))return false;
        const std::array<std::uint64_t,6> tags{b.generation,b.identities[4],b.identities[5],g.generation,b.identities[0],b.identities[1]};
        for(unsigned k=0;k<tags.size();++k)if(!put(base+562+2*k,std::uint32_t(tags[k]))
            ||!put(base+563+2*k,std::uint32_t(tags[k]>>32)))return false;
        if(!put(base+574,std::uint32_t(pixel)))return false;
    }
    return true;
}
static bool metalCameraRangeDecode(const MetalCameraRangeBatch& b,bool upperRefusal=false) {
    using namespace arbitgpu::metalcaustic;const auto p=b.parent->retained().preparation.pixels.size();
    if(b.results.size()!=std::max<std::size_t>(1,p*kCameraRangeResultWords))return false;
    if(!p)return !upperRefusal&&b.results[0]==0;
    bool refused=false;
    for(std::size_t pixel=0;pixel<p;++pixel){CameraRangeRequest q{};std::copy_n(b.inputs.begin()+pixel*kCameraRangeRequestWords,q.size(),q.begin());
        const auto* r=b.results.data()+pixel*kCameraRangeResultWords;std::array<CameraRangeDyadic,31> reconstructed{};std::uint32_t axis=0;
        const bool upper=r[7]==1;refused=refused||upper;
        if((upper&&!upperRefusal)||!cameraRangeReconstruct(q,reconstructed,axis,upper)||r[0]!=(upper?0u:1u)
            ||r[1]!=kCameraRangeScalarOperations||!r[2]||r[2]>kCameraRangeVisits
            ||r[3]!=axis||r[4]!=kCameraRangeWireTag||r[5]!=1||r[6]!=256||r[7]!=(upper?1u:0u))return false;
        for(unsigned k=0;k<q.size();++k)if(r[8+k]!=q[k])return false;
