}
static bool metalInspectCameraRange(const MetalFixtureSceneFrame& frame,MetalCameraRangeBatch& b,
    const std::shared_ptr<const arbitgpu::MetalCameraGeometricRangeResult>& supplied,std::string& error,bool upperRefusal=false) {
    using namespace arbitgpu;using namespace metalcaustic;
    const auto refuse=[&](){error="Metal geometric range native bound, interval, source or completion changed";return false;};
    const MetalCausticState::CameraRangeAttempt* attempt=nullptr;
    for(std::size_t i=0;i<frame.caustic->cameraRangeAttemptCount;++i)if(frame.caustic->cameraRangeAttempts[i].native.get()==&b)attempt=&frame.caustic->cameraRangeAttempts[i];
    std::array<std::uint64_t,11> exact{},next{};std::uint64_t count=0;
    if((upperRefusal&&(supplied||b.sealed))||!attempt||!metalCameraRangeCosts(frame,attempt->parent,exact)||exact!=attempt->costs
        ||!renderpassoutput::detail::checkedAdd(b.inspections,1,count))return refuse();
