        ||b.capture!=frame.caustic->rasterCapture||!b.capture||b.geometry->rasterCapture!=b.capture
        ||supplied!=b.sealed||b.generation!=attempt->serial||!b.command||!b.queue
        ||b.command.status!=MTLCommandBufferStatusCompleted||b.command.commandQueue!=b.queue
        ||b.queue!=(__bridge id<MTLCommandQueue>)sg_mtl_command_queue()||b.queue.device!=gMetalDevice
        ||!b.library||b.library.device!=gMetalDevice||!b.function||b.function.device!=gMetalDevice
        ||![b.function.name isEqualToString:@"cameraGeometricRange"]||!b.pipeline||b.pipeline.device!=gMetalDevice
        ||!b.pipeline.maxTotalThreadsPerThreadgroup||b.source.empty()||b.source.size()>metalCameraCoverageSourceLimit
        ||b.source.capacity()>2*metalCameraCoverageSourceLimit)return refuse();
