    if(b.limits!=std::array<std::uint32_t,4>{std::uint32_t(p),0,std::uint32_t(b.generation),std::uint32_t(b.generation>>32)})return refuse();
    const std::array<const void*,9> owners{(__bridge const void*)b.input,(__bridge const void*)b.result,(__bridge const void*)b.uniforms,
        (__bridge const void*)b.sourceArchive,(__bridge const void*)b.library,(__bridge const void*)b.function,
        (__bridge const void*)b.pipeline,(__bridge const void*)b.command,(__bridge const void*)b.queue};
    if(owners!=b.owners)return refuse();
