        ||(!b.inputs.empty()&&std::memcmp(b.input.contents,b.inputs.data(),4*b.inputs.size()))
        ||(b.inputs.empty()&&*static_cast<const std::uint32_t*>(b.input.contents)!=0)
        ||std::memcmp(b.result.contents,b.results.data(),b.result.length)||std::memcmp(b.uniforms.contents,b.limits.data(),sizeof(b.limits))
        ||std::memcmp(b.sourceArchive.contents,b.source.data(),b.source.size())
        ||!metalInspectCameraCoverage(frame,*b.geometry,b.parent->retained(),error)||!metalCameraRangeTrace(frame,b,false,error)
        ||!metalCameraRangeInputs(b,nullptr)||!metalCameraRangeDecode(b,upperRefusal))return refuse();
