// Private integer arithmetic ownership. These costs never enter directWork.
static bool metalLrAdd(arbitgpu::lambertian::native::Costs& a,const arbitgpu::lambertian::native::Costs& b) {
    auto next=a;
    for(unsigned k=0;k<next.size();++k)
        if(!renderpassoutput::detail::checkedAdd(next[k],b[k],next[k]))return false;
    a=next;return true;
}
static bool metalLrJournal(std::uint64_t& count,arbitgpu::lambertian::native::Costs& costs,
    const arbitgpu::lambertian::native::Costs& per) {
    using renderpassoutput::detail::checkedMultiply;
    std::uint64_t nextCount=0;arbitgpu::lambertian::native::Costs next{};
    if(!renderpassoutput::detail::checkedAdd(count,1,nextCount))return false;
    for(unsigned k=0;k<per.size();++k){std::uint64_t old=0;
        if(!checkedMultiply(count,per[k],old)||old!=costs[k]||!checkedMultiply(nextCount,per[k],next[k]))return false;}
    count=nextCount;costs=next;return true;
}
static bool metalLrJournalValid(std::uint64_t count,const arbitgpu::lambertian::native::Costs& costs,
    const arbitgpu::lambertian::native::Costs& per) {
    for(unsigned k=0;k<per.size();++k){std::uint64_t exact=0;
        if(!renderpassoutput::detail::checkedMultiply(count,per[k],exact)||exact!=costs[k])return false;}
    return true;
