        2*kHostCeilings.scalarOperations+1000000,2*kHostCeilings.parserOperations+100000,
        2*kHostCeilings.comparisons+1000000,kHostCeilings.scratchBytes+16000};
    return {preparation.limbVisits+57*kNativeCeilings.limbVisits+279*kHostCeilings.limbVisits,
        preparation.wordMoves+57*kNativeCeilings.wordMoves+279*kHostCeilings.wordMoves+1000000,
        preparation.scalarOperations+57*kNativeCeilings.scalarOperations+279*kHostCeilings.scalarOperations+10000000,
        preparation.parserOperations+57*kNativeCeilings.parserOperations+279*kHostCeilings.parserOperations+100000,
        preparation.comparisons+57*kNativeCeilings.comparisons+279*kHostCeilings.comparisons+10000000,
        preparation.scratchBytes+kNativeCeilings.scratchBytes+kHostCeilings.scratchBytes+16000};
