    //57 native dispatches are charged by their actual attempts.279 host checks,
    // preparation and fixture mutations have this separate permanent journal.
    w[HostVisits]=total.limbVisits-57*kNativeCeilings.limbVisits;
    w[HostMoves]=total.wordMoves-57*kNativeCeilings.wordMoves;
    w[HostScalars]=total.scalarOperations-57*kNativeCeilings.scalarOperations;
    w[HostParser]=total.parserOperations-57*kNativeCeilings.parserOperations;
    w[HostComparisons]=total.comparisons-57*kNativeCeilings.comparisons;
    w[LogicalScratch]=total.scratchBytes;
