                ||!r.command||r.command.commandQueue!=r.queue||r.command.status!=MTLCommandBufferStatusCompleted
                ||!r.library||r.library.device!=r.device||!r.function||r.function.device!=r.device
                ||!r.pipeline||r.pipeline.device!=r.device||!r.creationSource||owners!=r.owners
                ||!r.source.size||r.source.size>=kSourceCapacity||r.source.bytes[r.source.size]
                ||r.source.decimalCalls!=kDecimalCalls||r.lengths!=std::array<std::uint64_t,4>{88,1000,16,r.source.size}
                ||r.request!=b.request||r.sentinel!=b.sentinel
                ||std::memcmp(r.input.contents,r.request.data(),88)||std::memcmp(r.result.contents,r.readback.data(),1000)
                ||std::memcmp(r.limits.contents,r.uniforms.data(),16)||std::memcmp(r.archive.contents,r.source.bytes.data(),r.source.size))return refuse();
