static bool metalLrInspect(const MetalFixtureSceneFrame& frame,MetalCausticState::LambertianAttempt& a,
    const std::shared_ptr<const arbitgpu::MetalLambertianArithmeticResult>& sealed,std::string& error) {
    using namespace arbitgpu;using namespace lambertian;using namespace native;
    const auto refuse=[&](){error="Metal Lambertian arithmetic lost its source, native command or numerical certificate";return false;};
    Costs per;metalLrInspectCosts(per);
    if(!metalLrJournal(a.inspections,a.inspectionCosts,per))return refuse();
    if(!a.native||!a.native->resources)return refuse();
    const auto& b=*a.native;const auto& r=*b.resources;
    if(b.generation!=frame.rendererGeneration_||b.identity!=frame.caustic->schedule.identity
        ||b.cache!=frame.nativeResourceCacheIdentity()||b.serial!=a.serial||b.request!=r.request||b.sentinel!=r.sentinel
        ||r.recipe!=kSourceVersion||!r.completed||r.device!=gMetalDevice||!r.queue||r.queue.device!=r.device
        ||!r.command||r.command.commandQueue!=r.queue||r.command.status!=MTLCommandBufferStatusCompleted
        ||!r.library||r.library.device!=r.device||!r.function||r.function.device!=r.device
        ||!r.pipeline||r.pipeline.device!=r.device||!r.pipeline.maxTotalThreadsPerThreadgroup
        ||!r.creationSource||r.source.decimalCalls!=kDecimalCalls||!r.source.size||r.source.size>=kSourceCapacity
        ||r.source.bytes[r.source.size]||r.source.arithmeticOffset!=sizeof(kMetalPrefix)-1)return refuse();
    const std::array<const void*,11> owners{(__bridge const void*)r.input,(__bridge const void*)r.result,
        (__bridge const void*)r.limits,(__bridge const void*)r.archive,(__bridge const void*)r.library,
        (__bridge const void*)r.function,(__bridge const void*)r.pipeline,(__bridge const void*)r.queue,
        (__bridge const void*)r.command,(__bridge const void*)r.device,(__bridge const void*)r.creationSource};
    if(owners!=r.owners||r.lengths!=std::array<std::uint64_t,4>{88,1000,16,r.source.size}
        ||r.uniforms!=std::array<std::uint32_t,4>{22,246,std::uint32_t(a.serial),std::uint32_t(a.serial>>32)})return refuse();
    const std::array<id<MTLBuffer>,4> buffers{r.input,r.result,r.limits,r.archive};
    const std::array<const void*,4> data{r.request.data(),r.readback.data(),r.uniforms.data(),r.source.bytes.data()};
    for(unsigned k=0;k<4;++k){const auto v=buffers[k];
        if(!v||!v.contents||v.device!=r.device||v.length!=r.lengths[k]
            ||std::max<std::uint64_t>(v.length,v.allocatedSize)!=r.allocations[k]
            ||std::memcmp(v.contents,data[k],r.lengths[k]))return refuse();}
    const auto creationBytes=[r.creationSource lengthOfBytesUsingEncoding:NSUTF8StringEncoding];
    const auto* creation=[r.creationSource UTF8String];
    if(creationBytes!=r.source.size||!creation||std::memcmp(creation,r.archive.contents,r.source.size))return refuse();
    if(r.readback[246]!=kEntryMarker||r.readback[247]>1||r.readback[248]!=std::uint32_t(a.serial)
        ||r.readback[249]!=std::uint32_t(a.serial>>32))return refuse();
    if(sealed&&(sealed!=b.sealed||sealed->owner!=&frame||sealed->resources!=b.resources
        ||sealed->serial!=a.serial||sealed->frameGeneration!=b.generation||sealed->cache!=b.cache||sealed->identity!=b.identity
        ||sealed->request!=b.request||sealed->sentinel!=b.sentinel||sealed->words!=r.readback||sealed->owners!=owners
        ||sealed->source.size!=r.source.size||sealed->source.decimalCalls!=r.source.decimalCalls
        ||sealed->source.arithmeticOffset!=r.source.arithmeticOffset||sealed->source.arithmeticBytes!=r.source.arithmeticBytes
        ||std::memcmp(sealed->source.bytes.data(),r.source.bytes.data(),kSourceCapacity)))return refuse();
    Result result{};std::copy_n(r.readback.begin(),kResultWords,result.begin());
    if(!r.readback[247]){if(nativeAdmitted(r.request)||result!=r.sentinel)return refuse();}
    else {const auto outcome=inspect(r.request,result,kHostCeilings);
        if(outcome!=Inspection::Certified&&outcome!=Inspection::Refused)return refuse();}
    return validateMetalDirectAttemptLedgerUnlocked(frame,error);
}

static const MetalCausticState::FiniteSourceAttempt* metalFiniteReceiverParent(const MetalFixtureSceneFrame& frame,
    const std::shared_ptr<const arbitgpu::MetalFiniteGratingSourceResult>& parent) {
    if(!parent||parent->owner!=&frame||!frame.caustic
        ||frame.caustic->finiteSourceAttemptCount>frame.caustic->finiteSourceAttempts.size())return nullptr;
    const MetalCausticState::FiniteSourceAttempt* found=nullptr;
    for(std::size_t i=0;i<frame.caustic->finiteSourceAttemptCount;++i){const auto& a=frame.caustic->finiteSourceAttempts[i];
        if(a.committed&&a.native&&a.native->sealed==parent){if(found)return nullptr;found=&a;}}
    return found;
}
static MetalCameraRangeBatch* metalFiniteReceiverRange(const MetalFixtureSceneFrame& frame,
    const std::shared_ptr<const arbitgpu::MetalCameraGeometricRangeResult>& parent) {
    if(!parent||parent->owner!=&frame||!frame.caustic
        ||frame.caustic->cameraRangeAttemptCount>frame.caustic->cameraRangeAttempts.size())return nullptr;
    MetalCameraRangeBatch* found=nullptr;
    for(std::size_t i=0;i<frame.caustic->cameraRangeAttemptCount;++i){const auto& a=frame.caustic->cameraRangeAttempts[i];
        if(a.committed&&a.native&&a.native->sealed==parent){if(found)return nullptr;found=a.native.get();}}
