}
static bool metalFiniteReceiverCosts(const MetalFixtureSceneFrame& frame,std::array<std::uint64_t,14>& output) {
    using namespace arbitgpu;using namespace metalcaustic;
    if(!frame.caustic||!frame.caustic->cameraBinding)return false;
    const auto& frozen=frame.caustic->cameraBinding->frame;const auto t=std::uint64_t(frozen.triangles.size());
    if(!t||t>256)return false;
    const auto mul=[](std::uint64_t x,std::uint64_t y,std::uint64_t& z){return renderpassoutput::detail::checkedMultiply(x,y,z);};
    const auto add=[](std::uint64_t& x,std::uint64_t y){return renderpassoutput::detail::checkedAdd(x,y,x);};
    std::array<std::uint64_t,14> w{};w[0]=1;w[1]=15*t+27;
    w[2]=finiteReceiverVisits(t);w[3]=finiteReceiverWordMoves(t);w[4]=finiteReceiverScalars(t);
    w[5]=w[2];w[6]=w[3];w[7]=w[4];
    const auto wire=std::uint64_t(finiteReceiverRequestWords(t))+finiteReceiverResultWords(t);
    w[8]=32*wire+4096;
    // Complete receiver callgraph: admission/local scans, three input joins,
    // two publication inspectors, source construction and four buffer setup,
    // registry-ledger reconstruction, immutable/result copies and unwinds.
    // Each join invokes source and range inspectors, whose own permanent
    // invocation journals remain charged independently. This journal charges
    // receiver wrappers and every nested byte/identifier walk as well.
    // A walk can inspect 2 GiB/4 words; 32 passes per source/light/registry
    // owner cover query, BVH, historical archive, material, trace and ledger
    // comparisons. The 2048x2048 identifier scan is separate from word moves.
    constexpr std::uint64_t cap=glasscaustics::kMaximumEntrySamples;
    constexpr std::uint64_t lights=HarmonicMIDI::grid::Visual3DScene::kMaxLights;
    std::uint64_t extra=0;
    if(!mul(renderpassoutput::kMaximumTotalBytes/4,32*(cap+1)*(lights+1),w[9])
        ||!mul(t,frozen.query.texels.size(),extra)||!mul(extra,256,extra)||!add(w[9],extra)
        ||!mul(32,cap*cap+t*cap,w[10])||!add(w[6],w[9])
        ||!mul(w[9],64,extra)||!add(w[7],extra)||!add(w[7],w[8])
        ||!mul(renderpassoutput::kMaximumTotalBytes,32*(cap+1)*(lights+1),w[11])
        ||!mul(wire,128,extra)||!add(w[11],extra))return false;
    w[12]=w[11];w[13]=w[11];
    if(!add(w[13],w[12])||!add(w[13],8*metalCameraCoverageSourceLimit))return false;
    output=w;return true;
}
static bool metalFiniteReceiverLocalResult(const MetalFixtureSceneFrame& frame,
    const std::shared_ptr<const arbitgpu::MetalFiniteGratingReceiverResult>& r) {
    if(!r)return true;
    if(!frame.caustic||r->owner!=&frame||frame.caustic->finiteReceiverAttemptCount>frame.caustic->finiteReceiverAttempts.size())return false;
    unsigned matches=0;
    for(std::size_t i=0;i<frame.caustic->finiteReceiverAttemptCount;++i){const auto& a=frame.caustic->finiteReceiverAttempts[i];
        if(a.native&&a.native->sealed==r){const auto& b=*a.native;
            if(!a.retainedBytes||!b.completed||b.ownedBytes!=a.retainedBytes||b.parent!=a.parent||r->parent!=a.parent
                ||r->generation!=a.serial||b.generation!=a.serial||r->support!=b.support||r->range!=b.range)return false;++matches;}}
    return matches==1;
}
static bool metalFiniteReceiverOwnedBytes(const MetalFixtureSceneFrame& frame,
    const std::shared_ptr<const arbitgpu::MetalFiniteGratingSourceResult>& parent,
    const std::shared_ptr<const arbitgpu::MetalFiniteGratingReceiverResult>& incumbent,std::uint64_t& bytes) {
    using namespace arbitgpu;using namespace metalcaustic;
    const auto* registered=metalFiniteReceiverParent(frame,parent);
    if(!metalFiniteReceiverLocalResult(frame,incumbent)||!registered||!registered->native)return false;
    if(!frame.caustic->cameraBinding)return false;
    const auto t=frame.caustic->cameraBinding->frame.triangles.size();
    if(!t||t>kFiniteSourceMaximumTriangles)return false;
    // Native request/result, two host capacities each, immutable capacity,
    // inspector/caller copy and zero/setup storage fit eight wire copies. Parent
    // and incumbent graphs are credited ONLY by exact local registry membership.
    // Source/NSString/inspection strings fit eight source limits; four buffers
    // get independent 64KiB alignment margins. Three logical scratch copies
    // include host reconstruction, value temporaries and the native thread.
    bytes=8*metalCameraCoverageSourceLimit+4*64*1024+3*kFiniteReceiverScratchBytes
        +sizeof(MetalFiniteReceiverBatch)+sizeof(MetalFiniteGratingReceiverResult)+256+4*sizeof(std::array<std::uint32_t,4>)
        +2*kMetalFiniteReceiverDiagnosticWords*sizeof(std::uint32_t);
    std::uint64_t data=0;
    return renderpassoutput::detail::checkedMultiply(finiteReceiverRequestWords(t)+finiteReceiverResultWords(t),4*8,data)
        &&renderpassoutput::detail::checkedAdd(bytes,data,bytes)&&bytes<=renderpassoutput::kMaximumTotalBytes;
}
static bool metalFiniteReceiverRegistryCosts(std::array<std::uint64_t,14>& out) {
    using namespace arbitgpu;
    constexpr std::uint64_t cap=glasscaustics::kMaximumEntrySamples;
    // This inspector performs no native arithmetic, shader construction, copy
    // allocation or transfer. It scans up to2048 parent/incumbent/support
    // records per retained attempt, compares at most four complete host byte
    // capacities, and visits fixed resource/length/capacity fields. Charge its
    // actual callgraph separately from the much larger native-result inspector.
    std::array<std::uint64_t,14> w{};
    w[8]=512*(cap+1);w[9]=renderpassoutput::kMaximumTotalBytes/4+32*cap*cap;
    w[10]=4*cap*cap;w[6]=256*(cap+1)+w[9];
    w[7]=64*(w[9]+w[10])+8*w[6]+w[8];w[11]=256*(cap+1)*4;
    w[13]=4*renderpassoutput::kMaximumTotalBytes;out=w;return true;
}

// Public membership/readback/refusal wrappers also have an independent journal,
// including failed escaped-owner lookup. Admit before their first registry walk.
static bool metalFiniteReceiverPublicInspection(const MetalFixtureSceneFrame& frame) {
    using namespace arbitgpu;auto& s=*frame.caustic;std::array<std::uint64_t,14> per{},next{};std::uint64_t count=0;
    if(!metalFiniteReceiverRegistryCosts(per)
        ||!renderpassoutput::detail::checkedAdd(s.finiteReceiverPublicInspections,1,count))return false;
    for(unsigned k=0;k<per.size();++k){std::uint64_t old=0;
        if(!renderpassoutput::detail::checkedMultiply(s.finiteReceiverPublicInspections,per[k],old)||old!=s.finiteReceiverPublicCosts[k]
            ||!renderpassoutput::detail::checkedMultiply(count,per[k],next[k]))return false;}
    s.finiteReceiverPublicInspections=count;s.finiteReceiverPublicCosts=next;return true;
}
static bool metalFiniteReceiverRegistry(const MetalFixtureSceneFrame& frame,std::uint64_t& bytes,
    std::uint64_t& native,std::string& error) {
    using namespace arbitgpu;bytes=native=0;if(!frame.caustic)return false;
    auto& s=*frame.caustic;std::array<std::uint64_t,14> totals{};
    const auto refuse=[&](){error="Metal finite receiver lost its immutable work, support or storage registry";return false;};
    if(s.finiteReceiverAttemptCount>s.finiteReceiverAttempts.size())return refuse();
    std::array<std::uint64_t,14> publicPer{};
    if(!metalFiniteReceiverRegistryCosts(publicPer))return refuse();
    for(unsigned k=0;k<publicPer.size();++k){std::uint64_t expected=0;
        if(!renderpassoutput::detail::checkedMultiply(s.finiteReceiverPublicInspections,publicPer[k],expected)
            ||expected!=s.finiteReceiverPublicCosts[k])return refuse();}
    if(!s.finiteReceiverAttemptCount)return (!s.finiteReceiverRegistryInspections
        &&s.finiteReceiverRegistryCosts==std::array<std::uint64_t,14>{}&&s.finiteReceiverCosts==totals)||refuse();
    std::array<std::uint64_t,14> per{},next{};std::uint64_t count=0;
    if(!metalFiniteReceiverRegistryCosts(per)||!renderpassoutput::detail::checkedAdd(s.finiteReceiverRegistryInspections,1,count))return refuse();
    for(unsigned k=0;k<per.size();++k){std::uint64_t old=0;
        if(!renderpassoutput::detail::checkedMultiply(s.finiteReceiverRegistryInspections,per[k],old)||old!=s.finiteReceiverRegistryCosts[k]
            ||!renderpassoutput::detail::checkedMultiply(count,per[k],next[k]))return refuse();}
    s.finiteReceiverRegistryInspections=count;s.finiteReceiverRegistryCosts=next;
    for(std::size_t i=0;i<s.finiteReceiverAttemptCount;++i){const auto& a=s.finiteReceiverAttempts[i];
        std::array<std::uint64_t,14> exact{};
