            ||b.parent!=a.parent||!metalFiniteReceiverRange(frame,b.range)||b.cohort!=parent->native->cohort||b.generation!=a.serial
            ||b.inputs.capacity()>2*b.inputs.size()||b.results.capacity()>2*b.results.size()
            ||b.source.capacity()>2*metalCameraCoverageSourceLimit)return refuse();
        if(b.inspections!=a.inspections||b.inspectionCosts!=a.inspectionCosts)return refuse();
        const std::array<id<MTLBuffer>,4> buffers{b.input,b.result,b.uniforms,b.sourceArchive};
        const std::array<std::uint64_t,4> lengths{4*b.inputs.size(),4*b.results.size(),sizeof(b.limits),b.source.size()};
        for(unsigned k=0;k<4;++k){const auto value=buffers[k];if(!value){if(b.completed)return refuse();continue;}
            if(!value.contents||value.device!=gMetalDevice||value.length!=lengths[k]||value.length>gMetalDevice.maxBufferLength)return refuse();
            const auto actual=std::max<std::uint64_t>(value.length,value.allocatedSize);
            if(actual-value.length>4*64*1024-alignment||!renderpassoutput::detail::checkedAdd(observed,actual,observed))return refuse();
            alignment+=actual-value.length;}
        if(observed!=b.nativeBytes||observed>renderpassoutput::kMaximumTotalBytes-native)return refuse();native+=observed;
        if(b.sealed&&(b.sealed->owner!=&frame||b.sealed->parent!=a.parent||b.sealed->generation!=a.serial||b.sealed->support!=b.support||b.sealed->range!=b.range
            ||b.sealed->words!=b.results||b.sealed->words.capacity()>2*b.results.size()||!b.completed))return refuse();
        if(a.committed&&!b.sealed)return refuse();
