static bool metalFiniteReceiverInputs(const MetalFixtureSceneFrame& frame,MetalFiniteReceiverBatch& b,
    std::vector<std::uint32_t>* output,std::string& error) {
    using namespace arbitgpu;using namespace glasscaustics;using namespace metalcaustic;
    const auto refuse=[&](){error="Metal finite receiver requires exact registered source, emitted rows, rectangle and captured cell";return false;};
    const auto* source=metalFiniteReceiverParent(frame,b.parent);auto* range=metalFiniteReceiverRange(frame,b.range);
    if(!source||!source->native||!range||!range->geometry||range->upperRefused||b.cohort!=source->native->cohort
        ||b.capture!=frame.caustic->rasterCapture||range->capture!=b.capture
        ||!metalInspectFiniteSource(frame,*source->native,b.parent,error)
        ||!metalInspectCameraRange(frame,*range,b.range,error))return refuse();
    const auto& geometry=*range->geometry;
    const auto& preparation=range->parent->retained().preparation;
    const auto* emitted=metalCameraCoverageParent(frame,geometry.parent);
    if(!emitted||!emitted->native||emitted->terminal!=b.parent->parent||emitted->cohort!=b.cohort
        ||geometry.parent!=range->parent->retained().parent||geometry.sealed!=range->parent
        ||preparation.pixels.size()!=1||frame.width_!=1||frame.height_!=1
        ||!metalReceiverNative(frame,*emitted,error))return refuse();
    const auto& rays=*emitted->native;const auto& terminal=b.parent->parent->retained();
    const auto& binding=*b.cohort->prepared->sources()[0];const auto& frozen=binding.frame;
    if(terminal.orders.size()!=8||terminal.bands.size()!=8||terminal.incident.endpoints.size()!=1
        ||rays.inputs.size()!=8||rays.readback.rows.size()!=8||geometry.certificate.size()<16
        ||source->native->inputs.size()<kFiniteSourceHeaderWords)return refuse();
    std::array<std::uint32_t,13> camera{};
    if(!metalCameraCoverageCamera(frame,rays,camera,error)||camera!=geometry.camera)return refuse();
    const auto* h=geometry.certificate.data();unsigned left=h[1],right=h[2];
    if(left>=frozen.triangles.size()||right>=frozen.triangles.size()||left==right)return refuse();
    CameraDiagonalTriangle a{},c{};
    if(!metalCameraCoverageTriangle(frame,frozen,left,a)||!metalCameraCoverageTriangle(frame,frozen,right,c))return refuse();
    // Coverage independently establishes the complementary closed union and
    // seam tie. Canonicalize only its two retained triangle indices here.
    if(a[11]==a[8]){std::swap(a,c);std::swap(left,right);}
    const auto& ta=frozen.triangles[left];const auto& tb=frozen.triangles[right];
    if(ta.glass||tb.glass||ta.normal!=glasscaustics::Point{0,0,-1}||tb.normal!=glasscaustics::Point{0,0,-1}
        ||!ta.reflectance||!tb.reflectance||ta.reflectance->version!=tb.reflectance->version
        ||ta.reflectance->coefficients!=tb.reflectance->coefficients
        ||std::tie(ta.object,ta.material,ta.instance)!=std::tie(tb.object,tb.material,tb.instance))return refuse();
    const std::array<const void*,9> lineage{source->native.get(),range,&geometry,&rays,
        (__bridge const void*)rays.input,(__bridge const void*)rays.result,(__bridge const void*)rays.command,
        (__bridge const void*)frame.caustic->query,b.capture.get()};
    if(output){b.support=b.parent->support;b.sourceOwners=lineage;
        output->assign(finiteReceiverRequestWords(frozen.triangles.size()),0);if(output->capacity()>2*output->size())return refuse();}
    else if(b.support!=b.parent->support||b.sourceOwners!=lineage
        ||b.inputs.size()!=finiteReceiverRequestWords(frozen.triangles.size()))return refuse();
    const auto put=[&](std::size_t at,std::uint32_t value){if(output){(*output)[at]=value;return true;}return b.inputs[at]==value;};
    const auto put64=[&](std::size_t at,std::uint64_t value){return put(at,std::uint32_t(value))&&put(at+1,std::uint32_t(value>>32));};
    const auto real=[&](std::size_t at,double value){std::uint64_t bits=0;std::memcpy(&bits,&value,8);return put64(at,bits);};
