        ||b.capture!=frame.caustic->rasterCapture||!b.capture||b.inputs.size()<kFiniteReceiverHeaderWords
        ||b.inputs.capacity()>2*b.inputs.size()||b.results.capacity()>2*b.results.size()
        ||b.source.empty()||b.source.size()>metalCameraCoverageSourceLimit||b.source.capacity()>2*metalCameraCoverageSourceLimit
        ||!b.command||b.command.status!=MTLCommandBufferStatusCompleted||!b.queue||b.command.commandQueue!=b.queue
        ||b.queue!=(__bridge id<MTLCommandQueue>)sg_mtl_command_queue()||b.queue.device!=gMetalDevice
