bool MetalFixtureSceneFrame::finishCameraCellCoverageLease(arbitgpu::glasscaustics::NativeCameraCellCoverageLease& token,
    const arbitgpu::glasscaustics::CameraCellCoverageReadback& candidate,
    std::shared_ptr<const arbitgpu::glasscaustics::NativeCameraCellCoverageResult>& output,std::string& error) const {
