bool MetalFixtureSceneFrame::dispatchDirectTerminalReceivers(arbitgpu::glasscaustics::NativeDirectGratingTerminalReceiverLease& value,
    const std::vector<arbitgpu::glasscaustics::NativeDirectGratingTerminalReceiverInput>& inputs,
    arbitgpu::glasscaustics::DirectGratingTerminalReceiverReadback& output,std::string& error) const {
