            ||r.pixel[0]<0||r.pixel[1]<0||r.pixel[0]>=width_||r.pixel[1]>=height_
            ||r.pixel[0]!=std::floor(r.pixel[0])||r.pixel[1]!=std::floor(r.pixel[1])) {
