bool MetalFixtureSceneFrame::validateDirectTerminalReceiverResult(
    const arbitgpu::glasscaustics::NativeDirectGratingTerminalReceiverLease& value,
    const arbitgpu::glasscaustics::DirectGratingTerminalReceiverReadback& candidate,std::string& error) const {
    using namespace arbitgpu::glasscaustics;const auto* lease=metalReceiverAssociation(*this,value,error);
    if(!lease||lease->attempt==SIZE_MAX)return false;const auto& a=caustic->receiverAttempts[lease->attempt];
    std::uint64_t attemptWork=0;
    if(!metalReceiverAttemptWork(lease->cohort,a.bounds,attemptWork)
        ||a.committed||!a.native||candidate.nativeResult!=a.native->sealed
        ||candidate.rows.capacity()>2*a.bounds.maximumRows
        ||candidate.submission.frameIdentity.capacity()>2*lease->cohort.seal.frameIdentity.size()
