        error="Metal receiver inspection lost registered payload, reservation or admitted work";return false;
    }
    error.clear();return true;
}
bool MetalFixtureSceneFrame::finishDirectTerminalReceiverLease(arbitgpu::glasscaustics::NativeDirectGratingTerminalReceiverLease& value,
    const arbitgpu::glasscaustics::DirectGratingTerminalReceiverReadback& candidate,
    std::shared_ptr<const arbitgpu::glasscaustics::NativeDirectGratingTerminalReceiverResult>& output,std::string& error) const {
    auto* lease=const_cast<MetalTerminalReceiverLease*>(metalReceiverAssociation(*this,value,error));
    if(!lease||lease->attempt==SIZE_MAX||!validateDirectTerminalReceiverResult(value,candidate,error))return false;
    auto& b=*caustic->receiverAttempts[lease->attempt].native;if(b.sealed)return false;
    b.sealed=makeDirectTerminalReceiverResult(candidate);
