    if(metalReceiverFixtureFault==3&&!b.sealed->retained().rows.empty())
        const_cast<arbitgpu::glasscaustics::DirectGratingTerminalReceiverReadback&>(b.sealed->retained()).rows.front().input.key[3]^=1;
    if(metalReceiverFixtureFault>=4) {
        const auto command=b.command;const auto result=b.result;const auto raster=b.raster;const auto query=caustic->query;
