static bool produceMetalDirectCohortUnlocked(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const std::shared_ptr<const glasscaustics::DirectGratingIrradianceCohort>& prepared,
    glasscaustics::DirectGratingIrradianceCohortReadback& output,std::string& error,int failedSource=-1)
{
    @autoreleasepool {
    using namespace glasscaustics;const auto frame=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);
    const auto refuse=[&](const char* m){error=m;return false;};
    if(!frame||!frame->caustic||!prepared||frame->caustic->stagedDirectCohort!=prepared
        ||prepared->sources().empty()||prepared->sources().size()>16||prepared->inputs().empty()
        ||prepared->inputs().size()>kMaximumEntrySamples||!frame->staticResources||!gMetalDevice
        ||!frame->caustic->gratingStagingCompleted||frame->caustic->validated||!frame->privateCameraAttachments
        ||frame->caustic->cameraBinding!=prepared->sources()[0]||frame->caustic->directCohorts.size()>=kMaximumEntrySamples)
        return refuse("Metal directional cohort requires its exact frozen common staging frame");
    auto& state=*frame->caustic;const auto maximum=renderpassoutput::kMaximumTotalBytes;
    if(!validateMetalDirectAttemptLedgerUnlocked(*frame,error))return false;
    if(state.directAttemptCount>=state.directAttempts.size())return refuse("Metal direct attempt registry is full");
    const bool incumbentRetained=metalDirectCohortIncumbentRetained(state,*prepared,output.cohort,UINT64_MAX);
    std::uint64_t reserved=0;
    // The caller and a preserved capacity snapshot coexist before publication.
    if(!metalDirectCohortReservation(*prepared,output,incumbentRetained,4,reserved,error))return false;
    std::uint64_t attemptWork=0;
    for(const auto& binding:prepared->sources()) {
        DirectGratingContributionBounds b;
        if(!calculateDirectGratingContributionBounds(*binding,prepared->inputs().size(),0,0,b,error))return false;
        attemptWork+=b.queryWork+b.bandWork;
    }
    std::uint64_t frameBytes=state.cameraBinding->frame.bounds.transientBytes;
    for(auto bytes:{state.cameraBinding->bounds.bytes,state.metrics.admittedBytes,state.directPrimitiveBytes,
        state.cameraPrimitiveBytes,state.cellPrimitiveBytes,state.coveragePrimitiveBytes,reserved}) {
        if(bytes>maximum-frameBytes)return refuse("Metal directional cohort exceeds cumulative original storage");frameBytes+=bytes;
    }
    const auto baseWork=state.cameraBinding->bounds.combinedWork;
    if(state.directWork>kMaximumQueryWork-baseWork||state.adjunctWork>kMaximumQueryWork-baseWork-state.directWork
        ||prepared->bounds().combinedWork>kMaximumQueryWork-baseWork-state.directWork-state.adjunctWork
        ||attemptWork>prepared->bounds().combinedWork)return refuse("Metal directional cohort exceeds cumulative original work");
    const auto baseDeposition=state.cameraBinding->frame.bounds.deposition.depositionWork+state.cameraBinding->bounds.orderWork;
    if(baseDeposition>kMaximumDepositionWork||state.cohortDepositionWork>kMaximumDepositionWork-baseDeposition
        ||prepared->bounds().depositionWork>kMaximumDepositionWork-baseDeposition-state.cohortDepositionWork)
        return refuse("Metal directional cohort exceeds cumulative original deposition work");
    if(!validateMetalCameraTraceSceneInputsUnlocked(*frame,*prepared->sources()[0],error))return false;
    std::uint64_t stagedBytes=0,stagedNative=0;
    if(!metalDirectCohortStageBytes(*frame,stagedBytes,stagedNative,error)||stagedBytes!=state.metrics.admittedBytes)return false;
    // All complete-source reservations precede the first source allocation.
    auto candidate=std::make_unique<MetalDirectGratingCohort>();auto& c=*candidate;c.prepared=prepared;
    c.incumbent=output;c.incumbent.endpoints.reserve(output.endpoints.capacity());
    c.incumbent.submission.frameIdentity.reserve(output.submission.frameIdentity.capacity());
    if(c.incumbent.endpoints.capacity()>2*output.endpoints.capacity()
        ||c.incumbent.submission.frameIdentity.capacity()>2*output.submission.frameIdentity.capacity())
        return refuse("Metal directional cohort incumbent copy exceeds the reserved capacities");
