    c.reservedBytes=reserved;c.startingWork=state.directWork;c.attemptWork=attemptWork;
    c.originalWork=prepared->bounds().combinedWork-attemptWork;c.frameBytes=frameBytes;
    c.rasterImages=state.rasterImages;c.rasterViews=state.rasterViews;
    c.rasterDepth=state.rasterDepthStencil;c.rasterDepthView=state.rasterDepthStencilView;
    c.frameWork=baseWork+state.directWork+state.adjunctWork+prepared->bounds().combinedWork;
    c.sources.reserve(prepared->sources().size());c.readbacks.resize(prepared->sources().size());
    struct Candidate {MetalCausticState& s;Candidate(MetalCausticState& state,MetalDirectGratingCohort& c):s(state){s.cohortCandidate=&c;}
        ~Candidate(){s.cohortCandidate=nullptr;}} association(state,c);
    MetalDirectQueryLease lease(frame.get());
    for(std::size_t i=0;i<prepared->sources().size();++i)
        if(!produceMetalDirectGratingIrradianceReadbackUnlocked(owner,prepared->sources()[i],prepared->inputs(),
            c.readbacks[i],error,int(i)==failedSource,&c))return false;
    c.command=[c.sources[0]->batch->queue commandBuffer];
#if ! __has_feature(objc_arc)
    [c.command retain];
#endif
    if(!c.command)return refuse("Metal directional cohort seal command is unavailable");
    [c.command commit];[c.command waitUntilCompleted];
    if(c.command.status!=MTLCommandBufferStatusCompleted)return refuse("Metal directional cohort seal command did not complete");
    const auto serial=nextMetalRendererGeneration();
    c.seal={prepared->identity(),frame->rendererGeneration_,serial,state.identity.rasterGeneration,state.identity.queryGeneration,serial,serial};
    DirectGratingIrradianceCohortReadback delivered;
    if(!accumulateDirectGratingIrradianceCohort(prepared,*frame,c.seal,prepared->sources()[0]->evaluationTime,c.readbacks,delivered,error))return false;
    state.directCohorts.reserve(state.directCohorts.size()+1);
    if(state.directCohorts.capacity()>2*kMaximumEntrySamples||c.sources.capacity()>2*c.sources.size()
        ||c.readbacks.capacity()>2*c.readbacks.size()||delivered.endpoints.capacity()>2*prepared->inputs().size())
        return refuse("Metal directional cohort publication exceeds reserved capacities");
    std::uint64_t native=0;for(const auto& view:c.sources)for(auto b:{view->batch->input,view->batch->result,
        view->batch->witness,view->batch->uniforms,view->batch->sourceInput})native+=std::max<std::uint64_t>(b.length,b.allocatedSize);
    state.directPrimitiveBytes+=reserved;state.bytes+=reserved;state.metrics.retainedNativeBytes+=native;
    state.metrics.peakNativeBytes=std::max(state.metrics.peakNativeBytes,state.metrics.retainedNativeBytes);
    output=std::move(delivered);state.directCohorts.push_back(std::move(candidate));error.clear();return true;
    }
}

bool produceMetalDirectGratingIrradianceCohort(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const std::shared_ptr<const glasscaustics::DirectGratingIrradianceCohort>& cohort,
    glasscaustics::DirectGratingIrradianceCohortReadback& output,std::string& error)
{
    std::lock_guard<std::mutex> lock(sokolMutex());return produceMetalDirectCohortUnlocked(owner,cohort,output,error);
}
bool produceMetalDirectGratingTerminalOrders(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const std::shared_ptr<const glasscaustics::DirectGratingIrradianceCohort>& cohort,
    const glasscaustics::SubmissionIdentity& expected,double time,
    const std::vector<glasscaustics::NativeDirectGratingContributionReadback>& sources,
    glasscaustics::DirectGratingTerminalOrderLedger& output,std::string& error)
{
    if(metalDirectQueryLease||metalTerminalEntryGuard){error="Metal terminal entrypoint is already leased";return false;}
    const auto frame=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);
    if(!frame){error="Metal terminal entrypoint requires an actual Metal frame";return false;}
    std::unique_lock<std::mutex> guard(sokolMutex());
    struct Entry {
        Entry(std::unique_lock<std::mutex>& g,const MetalFixtureSceneFrame& f){metalTerminalEntryGuard=&g;metalTerminalEntryFrame=&f;}
        ~Entry(){metalTerminalEntryFrame=nullptr;metalTerminalEntryGuard=nullptr;}
    } entry(guard,*frame);
    return glasscaustics::evaluateDirectGratingTerminalOrders(cohort,*frame,expected,time,sources,output,error);
}
bool produceMetalFiniteGratingSourceForFixture(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const std::shared_ptr<const glasscaustics::NativeDirectGratingTerminalResult>& parent,
    std::shared_ptr<const MetalFiniteGratingSourceResult>& output,std::string& error,int stop,
    std::shared_ptr<const MetalFiniteGratingSourceResult>* escaped) {
