    stamp.generation=b.generation;stamp.serial=b.serial;stamp.lengths=b.lengths;stamp.allocations=b.allocations;
    for(unsigned i=0;i<9;++i)stamp.textures[i]=(__bridge const void*)b.textures[i];
    for(unsigned i=0;i<3;++i)stamp.geometry[i]=(__bridge const void*)b.nativeGeometry[i];
    stamp.uniforms=b.uniformOffsets;stamp.pass=b.pass;stamp.bindings=b.bindings;stamp.viewport=b.viewport;stamp.scissor=b.scissor;
    stamp.draws=b.draws;stamp.uploads=b.uniformUploads;return stamp;
