static bool metalCompleteBaseRegistryImpl(const MetalFixtureSceneFrame& f,std::uint64_t& bytes,std::uint64_t& native,std::string& error) {
    bytes=native=0;if(!f.caustic)return false;const auto& state=*f.caustic;
    if(!state.completeBaseAdmission)return true;
    auto& ledger=*state.completeBaseAdmission;
    try {
        ledger.registry();if(!ledger.inspectJournal())return false;bytes=ledger.bytes();
        for(std::size_t i=0;i<ledger.attempts();++i){const auto& record=ledger.record(i);if(!record.live)continue;
            const auto* payload=state.completeBasePayloads[i];
            if(!payload||payload->lease.slot!=i||payload->owner.get()!=&f
                ||payload->lease.ledger!=state.completeBaseAdmission||record.bytes!=payload->reservation
                ||record.serial!=payload->serial||payload->lease.nativeBytes!=payload->nativeBytes)return false;
            native=surfacesource::add(native,payload->nativeBytes);
        }
        return true;
    }catch(const std::exception& e){error=e.what();return false;}
}
constexpr std::array<sg_pixel_format,9> completeBaseFormats{SG_PIXELFORMAT_RGBA16F,SG_PIXELFORMAT_R32F,
    SG_PIXELFORMAT_RGBA16F,SG_PIXELFORMAT_RGBA16F,SG_PIXELFORMAT_R8,SG_PIXELFORMAT_R32UI,
    SG_PIXELFORMAT_R32UI,SG_PIXELFORMAT_RG16F,SG_PIXELFORMAT_DEPTH_STENCIL};
constexpr std::array<MTLPixelFormat,9> completeBaseNativeFormats{MTLPixelFormatRGBA16Float,MTLPixelFormatR32Float,
    MTLPixelFormatRGBA16Float,MTLPixelFormatRGBA16Float,MTLPixelFormatR8Unorm,MTLPixelFormatR32Uint,
    MTLPixelFormatR32Uint,MTLPixelFormatRG16Float,MTLPixelFormatDepth32Float_Stencil8};
static std::uint64_t completeBaseQueryLimit(const MetalFixtureSceneFrame& f) {
    using namespace surfacesource;const auto& prepared=f.staticResources->opaqueVisibility;
    const auto count=f.caustic->schedule.instances.size();
    if(count>opaquevisibility::kMaximumInstances)throw std::length_error("Complete base opaque instance census exceeds released bound");
    // Four inverse-matrix texels per instance, at most2n-1 two-texel TLAS
    // nodes, and one all-surfaces work record. The prepared BLAS and optional
    // identities precede that tail. Padding occupies complete1024-texel rows.
    auto texels=add(prepared.texels.size(),prepared.mode==opaquevisibility::AdmissionMode::allSurfaces?prepared.identities.size():0);
    texels=add(texels,add(multiply(8,count),1));
    texels=multiply(add(texels,opaquevisibility::kTextureWidth-1)/opaquevisibility::kTextureWidth,opaquevisibility::kTextureWidth);
    if(texels>opaquevisibility::kTextureWidth*opaquevisibility::kTextureHeight)throw std::length_error("Complete base opaque padded census exceeds released bound");
    return multiply(texels,sizeof(opaquevisibility::Texel));
}
static bool completeBaseBudget(std::uint64_t nativeAttachments,std::uint64_t rings,std::uint64_t geometry,
    std::uint64_t query,std::uint64_t& reservation,completebase::Costs& costs) {
    using namespace surfacesource;
    const auto fixed=4*(sizeof(MetalCompleteBasePayload)+sizeof(MetalRestrictedCompleteBaseResult)+256)
        +sizeof(sg_pipeline_desc)+sizeof(sg_bindings)+sizeof(sg_pass);
    const auto history=add(2*sizeof(FixtureUniforms),add(geometry,query+768+sizeof(MetalCompleteBaseStamp)+sizeof(std::uint32_t)));
    // Four history copies cover native archive, frozen host archive, caller
    // and inspector scratch. Eight query copies cover both2x host capacities,
    // independent reconstruction, padded upload, native texture and scratch.
    // Alignment is checked against observed native allocation, not predicted.
    reservation=add(fixed,add(nativeAttachments,add(rings,add(multiply(4,history),add(multiply(8,query),
        8*64*1024+8*sizeof(FixtureUniforms)+4*sizeof(MetalFixtureInstanceGpuRecord)+1024)))));
    costs={65536,65536,65536,completebase::scanBytes/4*64,2*sizeof(FixtureUniforms)+query+sizeof(MetalFixtureInstanceGpuRecord),
        1,8*opaquevisibility::kMaximumClosestHitWork,history+256,multiply(16,reservation),multiply(16,reservation),128,16};
    return true;
}
static std::uint64_t completeBaseParentBytes(const MetalFixtureSceneFrame& f) {
    using surfacesource::add;
    return add(f.caustic->bytes-(f.caustic->completeBaseAdmission?f.caustic->completeBaseAdmission->bytes():0),add(metalPrivateSurfaceParentBytes(*f.staticResources),
        f.staticResources->privateSurfaceAdmission?f.staticResources->privateSurfaceAdmission->bytes():0));
}
static bool completeBaseDescription(const MetalPrivateSurfaceCreation& c,sg_pipeline_desc& expected) {
    expected=c.pipelineDescription;expected.shader=c.creation->shader;expected.label=nullptr;
    expected.cull_mode=SG_CULLMODE_BACK;expected.face_winding=SG_FACEWINDING_CCW;
    if(expected.color_count!=8||expected.sample_count!=1||expected.index_type!=SG_INDEXTYPE_UINT32
        ||expected.primitive_type!=SG_PRIMITIVETYPE_TRIANGLES||expected.depth.pixel_format!=SG_PIXELFORMAT_DEPTH_STENCIL
        ||expected.depth.compare!=SG_COMPAREFUNC_LESS||!expected.depth.write_enabled)return false;
    // The whole descriptor is later compared with the actual Sokol object.
    // Independently check every released input/output layout field used here.
    const std::array<sg_vertex_attr_state,13> attrs{{
        {0,int(offsetof(HarmonicMIDI::grid::SceneVertex,position)),SG_VERTEXFORMAT_FLOAT3},
        {0,int(offsetof(HarmonicMIDI::grid::SceneVertex,normal)),SG_VERTEXFORMAT_FLOAT3},
        {0,int(offsetof(HarmonicMIDI::grid::SceneVertex,uv)),SG_VERTEXFORMAT_FLOAT2},
        {0,int(offsetof(HarmonicMIDI::grid::SceneVertex,color)),SG_VERTEXFORMAT_FLOAT4},
        {0,int(offsetof(HarmonicMIDI::grid::SceneVertex,tangent)),SG_VERTEXFORMAT_FLOAT4},
        {1,0,SG_VERTEXFORMAT_FLOAT4},{1,16,SG_VERTEXFORMAT_FLOAT4},{1,32,SG_VERTEXFORMAT_FLOAT4},{1,48,SG_VERTEXFORMAT_FLOAT4},
        {1,int(offsetof(MetalFixtureInstanceGpuRecord,identityColor)),SG_VERTEXFORMAT_FLOAT4},
        {1,int(offsetof(MetalFixtureInstanceGpuRecord,color)),SG_VERTEXFORMAT_FLOAT4},
        {1,int(offsetof(MetalFixtureInstanceGpuRecord,emission)),SG_VERTEXFORMAT_FLOAT4},
        {2,int(offsetof(HarmonicMIDI::grid::SceneVertex,position)),SG_VERTEXFORMAT_FLOAT3}}};
    for(unsigned i=0;i<attrs.size();++i)if(std::memcmp(&attrs[i],&expected.layout.attrs[i],sizeof(attrs[i])))return false;
    if(expected.layout.buffers[0].stride!=sizeof(HarmonicMIDI::grid::SceneVertex)
        ||expected.layout.buffers[1].stride!=sizeof(MetalFixtureInstanceGpuRecord)
        ||expected.layout.buffers[1].step_func!=SG_VERTEXSTEP_PER_INSTANCE||expected.layout.buffers[1].step_rate!=1
        ||expected.layout.buffers[2].stride!=sizeof(HarmonicMIDI::grid::SceneVertex))return false;
    for(unsigned i=0;i<8;++i)if(expected.colors[i].pixel_format!=completeBaseFormats[i]
        ||expected.colors[i].blend.enabled||expected.colors[i].write_mask!=SG_COLORMASK_RGBA)return false;
    return true;
}
static bool completeBaseUniforms(const MetalFixtureSceneFrame& f,const MetalPrivateSurfaceCreation& c,
    const MetalFiniteReceiverBatch& receiver,FixtureUniforms& u,std::string& error) {
    using namespace HarmonicMIDI::grid;
    const auto refuse=[&](){error="Restricted complete base needs unchanged opaque receiver material, placement and +Z source";return false;};
    const auto& scene=*f.staticResources->snapshot;const auto& runtime=*f.caustic->cameraInputs;
    const auto* object=visual3d_detail::findById(scene.objects,scene.objectCount,c.receiver);
    const auto* material=object?visual3d_detail::findById(scene.materials,scene.materialCount,object->material):nullptr;
    const auto* program=object?nativeSurfaceForObject(f.staticResources->materialProgram.get(),object->id):nullptr;
    if(!object||!material||!program||program!=c.selected.get()||program->kind!=NativeFixtureMaterialKind::SurfacePbr
        ||program->baseColorSource!=NativeFixtureSurfaceMaterialProgram::BaseColorSource::ConstantLinear
        ||program->vertexProgram||program->frameEndpoint||program->importedBaseColorTexture||!program->objectPrograms.empty()
        ||!program->spectralReflectance||!program->spectralReflectance->version||program->parameters.identifiers[1]
        ||program->parameters.transmissionIorClearcoat[0]!=0||program->parameters.normalOpacity[3]!=1
        ||material->doubleSided||material->alphaMode!=SceneAlphaMode::Opaque||material->opacity!=1
        ||material->baseColorTexture.isValid()||material->normalTexture.isValid()||material->emissiveTexture.isValid()
        ||material->occlusionTexture.isValid()||material->metallicRoughnessTexture.isValid()
        ||object->vertexCount!=4||object->indexCount!=6||scene.lightCount!=1||scene.ambientColor.x||scene.ambientColor.y||scene.ambientColor.z
        ||runtime.cameraOverride||runtime.animatedCamera||runtime.lightOverride||!runtime.animatedLights.empty()
        ||runtime.previousMotion||runtime.canonicalBlockCFrame||runtime.noteInstanceMapping||runtime.compositionFrame||runtime.passComposite||runtime.passProgram
        ||runtime.materialFrameTexture||!runtime.materialFrameTextures.empty()||!runtime.diffractionParameters.empty()
        ||runtime.diffractionSourceProgram||runtime.diffractionEvaluatedProgram||runtime.emissionGain!=1||runtime.morphWeight!=1
        ||runtime.rawExportMask||runtime.imageOutput!=renderpassoutput::Output::Color
        ||std::any_of(runtime.vertexSpectrum.begin(),runtime.vertexSpectrum.end(),[](float value){return value!=0;})
        ||runtime.objectTranslationOffset!=std::array<float,3>{}
        ||runtime.objectRotationDegrees!=std::array<float,3>{}||runtime.objectScale!=1
        ||runtime.cameraTranslationOffset!=std::array<float,3>{}
        ||runtime.cameraRotationDegrees!=std::array<float,3>{}||runtime.cameraVerticalFovDegrees!=0||!runtime.linearColor
        ||!f.staticResources->instanceAppearances.empty()||f.staticResources->instancedSharedGeometry)return refuse();
    const auto identity=metalFixtureTransformMatrix(SceneTransform3D{});
    if(nativeObjectWorldMatrix(runtime.objectWorlds.get(),*object,metalFixtureWorldMatrix(scene,*object))!=identity)return refuse();
    for(unsigned band=0;band<8;++band)if(!std::isfinite(program->spectralReflectance->coefficients[band])
        ||program->spectralReflectance->coefficients[band]<=0||program->spectralReflectance->coefficients[band]>1)return refuse();
    for(unsigned channel=0;channel<3;++channel)if(program->parameters.emissionRoughness[channel]!=0
        ||!std::isfinite(program->parameters.baseColorMetallic[channel])||program->parameters.baseColorMetallic[channel]<=0
        ||!std::isfinite(scene.lights[0].color.x)||!std::isfinite(scene.lights[0].color.y)||!std::isfinite(scene.lights[0].color.z))return refuse();
    for(unsigned v=0;v<4;++v){const auto& vertex=scene.vertices[object->firstVertex+v];
        if(vertex.normal.x||vertex.normal.y||vertex.normal.z!=-1||vertex.color[3]!=1)return refuse();}
    if(receiver.inputs.size()<320||receiver.inputs[5]>=f.caustic->cameraBinding->frame.triangles.size()
        ||receiver.inputs[6]>=f.caustic->cameraBinding->frame.triangles.size())return refuse();
    const auto& frozen=f.caustic->cameraBinding->frame;
    unsigned receiverTriangles=0,instances=0,instanceIndex=UINT32_MAX;
    for(std::size_t i=0;i<frozen.instances.size();++i){const auto& instance=frozen.instances[i];
        if(scene.objects[instance.object].id==object->id){if(instance.world!=identity)return refuse();instanceIndex=unsigned(i);++instances;}}
    for(const auto& triangle:frozen.triangles)if(triangle.object==object->id.value){
        if(triangle.normal!=glasscaustics::Point{0,0,-1}||triangle.material!=object->material.value||triangle.instance!=instanceIndex
            ||!triangle.reflectance||triangle.reflectance->coefficients!=program->spectralReflectance->coefficients)return refuse();++receiverTriangles;}
    if(instances!=1||receiverTriangles!=2)return refuse();
    for(unsigned index:{receiver.inputs[5],receiver.inputs[6]})if(frozen.triangles[index].object!=object->id.value)return refuse();
    const auto& light=scene.lights[0];
    if(light.kind!=SceneLightKind::Directional||light.sky.version||light.environmentImage.version
        ||light.transform.rotation.x||light.transform.rotation.y||light.transform.rotation.z||light.transform.rotation.w!=1
        ||!std::isfinite(light.intensity)||light.intensity<=0)return refuse();
    u={};std::copy(identity.begin(),identity.end(),u.objectMatrix);
    std::copy_n(std::array<float,4>{1,1,1,0}.begin(),4,u.noteAppearanceLow);
    std::copy_n(std::array<float,4>{1,1,1,0}.begin(),4,u.noteAppearanceHigh);
    u.noteInstanceTransforms[0][3]=1;u.noteMeshScale[0]=1;u.geometryInstanceControl[1]=UINT32_MAX;u.geometryInstanceControl[2]=unsigned(object-scene.objects.data());u.geometryInstanceControl[3]=1;
    storeQuaternion(u.cameraRotation,f.caustic->schedule.camera.transform.rotation);
    storeVec3(u.cameraTranslation,f.caustic->schedule.camera.transform.translation);
    std::copy(f.caustic->params.projection.begin(),f.caustic->params.projection.end(),u.projection);
    u.vertexTime[0]=runtime.timeSeconds;
    const auto& p=program->parameters;
    std::copy_n(p.baseColorMetallic.begin(),3,u.baseColor);u.baseColor[3]=p.normalOpacity[3];
    u.materialParams[0]=p.baseColorMetallic[3];u.materialParams[1]=p.emissionRoughness[3];u.materialParams[2]=1;
    std::copy_n(p.transmissionIorClearcoat.begin(),3,u.surfaceCoating);u.surfaceCoating[3]=1;
    u.materialKind[0]=std::uint32_t(NativeFixtureMaterialKind::SurfacePbr);
    std::memcpy(&u.materialKind[3],&material->alphaCutoff,sizeof(float));
    u.passProgram.control={0,0,1,0};u.imageOutput[0]=float(renderpassoutput::Output::Color);
    u.ambient[3]=1;storeQuaternion(u.lightRotations[0],light.transform.rotation);
    storeVec3(u.lightColors[0],light.color,light.intensity);storeVec3(u.lightPositions[0],light.transform.translation,light.range);
    u.lightCones[0][0]=std::cos(light.innerConeAngle);u.lightCones[0][1]=std::cos(light.outerConeAngle);
    u.lightKinds[0][0]=std::uint32_t(light.kind);
    for(std::size_t i=0;i<scene.objectCount;++i){const auto& o=scene.objects[i];
        u.rawIdentifiers[i][0]=float(o.material.value&65535u);u.rawIdentifiers[i][1]=float(o.material.value>>16u);
        u.rawIdentifiers[i][2]=float(o.id.value&65535u);u.rawIdentifiers[i][3]=float(o.id.value>>16u);}
    return true;
}
static MetalFiniteReceiverBatch* completeBaseRegisteredReceiver(const MetalFixtureSceneFrame& f,
    const std::shared_ptr<const MetalFiniteGratingReceiverResult>& receiver) {
    if(!receiver||receiver->owner!=&f)return nullptr;
    for(std::size_t i=0;i<f.caustic->finiteReceiverAttemptCount;++i){auto& a=f.caustic->finiteReceiverAttempts[i];
        if(a.committed&&a.native&&a.native->sealed==receiver)return a.native.get();}
    return nullptr;
}
static bool inspectCompleteBaseUnlocked(const MetalFixtureSceneFrame& f,const MetalCompleteBasePayload& b,
    const std::shared_ptr<const MetalRestrictedCompleteBaseResult>& supplied,std::string& error,bool published) {
    const auto refuse=[&](){error="Restricted complete base lost its registered owning draw, native history or finite black unit-alpha pixel";return false;};
    try {
        if(!b.lease.ledger||b.lease.ledger!=f.caustic->completeBaseAdmission)return refuse();
        b.lease.ledger->inspect(b.lease.slot);
        const auto& record=b.lease.ledger->record(b.lease.slot);
        if(!b.lease.ledger->inspectJournal()||!record.live||record.serial!=b.serial||record.bytes!=b.reservation
            ||b.hostAllocationBytes<sizeof(MetalCompleteBasePayload)+sizeof(MetalRestrictedCompleteBaseResult)
            ||b.hostAllocationBytes>4*(sizeof(MetalCompleteBasePayload)+sizeof(MetalRestrictedCompleteBaseResult)+256)
            ||record.published!=published||!supplied||supplied->payload.get()!=&b
            ||f.caustic->completeBaseRegistry[b.lease.slot].lock()!=supplied||b.owner.get()!=&f
            ||b.generation!=f.rendererGeneration_||!b.creation
            ||b.coverageCapture!=f.caustic->rasterCapture||!b.coverageCapture||!b.transportExcluded
            ||!b.completed||b.draws!=1||b.uniformUploads!=2||!b.command||b.command.status!=MTLCommandBufferStatusCompleted
            ||!b.queue||b.queue.device!=gMetalDevice||b.command.commandQueue!=b.queue
            ||b.queue!=(__bridge id<MTLCommandQueue>)sg_mtl_command_queue()
            ||surfacesource::add(completeBaseParentBytes(f),b.lease.ledger->bytes())>renderpassoutput::kMaximumTotalBytes)return refuse();
        // Each child preserves its existing, separately charged full inspector.
        auto* receiver=completeBaseRegisteredReceiver(f,b.receiver);
        if(!receiver||!metalInspectFiniteReceiver(f,*receiver,b.receiver,error)
            ||!inspectMetalPrivateSurfaceCreationUnlocked(*f.staticResources,*b.creation,error))return false;
        FixtureUniforms expected{};
        if(!completeBaseUniforms(f,*b.creation,*receiver,expected,error))return false;
        opaquevisibility::Frame expectedQuery;
        if(!opaquevisibility::frame(f.staticResources->opaqueVisibility,f.caustic->schedule.instances,expectedQuery,error)
            ||surfacesource::multiply(expectedQuery.texels.capacity(),sizeof(opaquevisibility::Texel))>2*b.queryLimit
            ||expectedQuery.height!=b.queryFrame.height||expectedQuery.control!=b.queryFrame.control
            ||expectedQuery.texels.size()!=b.queryFrame.texels.size()
            ||std::memcmp(expectedQuery.texels.data(),b.queryFrame.texels.data(),b.queryBytes))return refuse();
        std::copy(expectedQuery.control.begin(),expectedQuery.control.end(),expected.opaqueControl);
        if(std::memcmp(&expected,&b.uniforms,sizeof(expected)))return refuse();
        sg_pipeline_desc description{};if(!completeBaseDescription(*b.creation,description))return refuse();
        auto actual=sg_query_pipeline_desc(b.pipeline);actual.label=nullptr;
        const auto native=sg_mtl_query_pipeline_info(b.pipeline);
        if(std::memcmp(&description,&b.description,sizeof(description))||std::memcmp(&actual,&description,sizeof(actual))
            ||native.rps!=(__bridge const void*)b.nativePipeline||native.dss!=(__bridge const void*)b.nativeDepth
            ||!b.nativePipeline||b.nativePipeline.device!=gMetalDevice||!b.nativeDepth||b.nativeDepth.device!=gMetalDevice)return refuse();
        if(b.viewport!=std::array<int,4>{0,0,1,1}||b.scissor!=b.viewport
            ||b.pass.action.colors[0].load_action!=SG_LOADACTION_CLEAR||b.pass.action.colors[0].store_action!=SG_STOREACTION_STORE
            ||b.pass.action.colors[0].clear_value.r!=.25f||b.pass.action.colors[0].clear_value.g!=.5f
            ||b.pass.action.colors[0].clear_value.b!=.75f||b.pass.action.colors[0].clear_value.a!=0)return refuse();
        std::uint64_t observed=0;
        for(unsigned i=0;i<9;++i){const auto image=sg_query_image_desc(b.images[i]);const auto view=sg_query_view_desc(b.attachments[i]);
            const auto info=sg_mtl_query_image_info(b.images[i]);const auto value=b.textures[i];
            if(!resourceValid(sg_query_image_state(b.images[i]))||!resourceValid(sg_query_view_state(b.attachments[i]))
                ||image.width!=1||image.height!=1||image.sample_count!=1||image.pixel_format!=completeBaseFormats[i]
                ||(i<8?!image.usage.color_attachment:!image.usage.depth_stencil_attachment)
                ||(i<8?view.color_attachment.image.id:view.depth_stencil_attachment.image.id)!=b.images[i].id
                ||info.active_slot<0||info.active_slot>=SG_NUM_INFLIGHT_FRAMES
                ||info.tex[info.active_slot]!=(__bridge const void*)value||!value||value.device!=gMetalDevice
                ||value.width!=1||value.height!=1||value.sampleCount!=1||value.pixelFormat!=completeBaseNativeFormats[i]
                ||value.allocatedSize!=b.textureAllocations[i]||value.allocatedSize>b.textureLimits[i]
                ||(i<8?b.pass.attachments.colors[i].id:b.pass.attachments.depth_stencil.id)!=b.attachments[i].id)return refuse();
            observed=surfacesource::add(observed,value.allocatedSize);}
        const auto& scene=*f.staticResources->snapshot;
        const auto* object=HarmonicMIDI::grid::visual3d_detail::findById(scene.objects,scene.objectCount,b.creation->receiver);
        if(!object||b.geometry[0].id!=f.staticResources->vertexBuffer.id||b.geometry[1].id!=f.staticResources->indexBuffer.id
            ||b.geometry[2].id!=b.instanceBuffer.id||b.vertexOffsets!=std::array<int,3>{int(object->firstVertex*sizeof(HarmonicMIDI::grid::SceneVertex)),0,int(object->firstVertex*sizeof(HarmonicMIDI::grid::SceneVertex))}
            ||b.indexOffset!=int(object->firstIndex*sizeof(std::uint32_t)))return refuse();
        std::uint64_t offset=2*sizeof(FixtureUniforms);
        if(b.bindings.vertex_buffers[0].id!=b.geometry[0].id||b.bindings.vertex_buffers[1].id!=b.geometry[2].id
            ||b.bindings.vertex_buffers[2].id!=b.geometry[0].id||b.bindings.index_buffer.id!=b.geometry[1].id
            ||b.bindings.index_buffer_offset!=b.indexOffset)return refuse();
        for(unsigned i=0;i<3;++i)if(b.bindings.vertex_buffer_offsets[i]!=b.vertexOffsets[i])return refuse();
        for(unsigned i=0;i<3;++i){const auto value=b.nativeGeometry[i];const auto info=sg_mtl_query_buffer_info(b.geometry[i]);
            if(!resourceValid(sg_query_buffer_state(b.geometry[i]))||info.active_slot<0||info.active_slot>=SG_NUM_INFLIGHT_FRAMES
                ||info.buf[info.active_slot]!=(__bridge const void*)value
                ||!value||!value.contents||value.device!=gMetalDevice||value.length!=b.lengths[i]
                ||std::max<std::uint64_t>(value.length,value.allocatedSize)!=b.allocations[i]||b.historyOffsets[i]!=offset)return refuse();
            offset=surfacesource::add(offset,value.length);}
        if(surfacesource::add(offset,255)/256*256!=b.queryHistoryOffset||surfacesource::add(b.queryHistoryOffset,b.queryBytes)!=b.stampOffset
            ||surfacesource::add(b.stampOffset,sizeof(MetalCompleteBaseStamp))!=b.diagnosticOffset
            ||surfacesource::add(surfacesource::add(b.diagnosticOffset,sizeof(std::uint32_t)),255)/256*256!=b.whiteOffset
            ||surfacesource::add(b.whiteOffset,256)!=b.historyBytes||!b.history||!b.history.contents||b.history.device!=gMetalDevice||b.history.length!=b.historyBytes
            ||!b.frozenHistory||std::memcmp(b.history.contents,b.frozenHistory.get(),b.historyBytes))return refuse();
        const auto* history=static_cast<const unsigned char*>(b.history.contents);
        const auto stamp=completeBaseStamp(b);if(std::memcmp(history+b.stampOffset,&stamp,sizeof(stamp)))return refuse();
        if(b.lengths[0]!=scene.vertexCount*sizeof(HarmonicMIDI::grid::SceneVertex)||b.lengths[1]!=scene.indexCount*sizeof(std::uint32_t)
            ||std::memcmp(history+b.historyOffsets[0],scene.vertices.data(),b.lengths[0])
            ||std::memcmp(history+b.historyOffsets[1],scene.indices.data(),b.lengths[1]))return refuse();
        MetalFixtureInstanceGpuRecord instance{};instance.matrix=metalFixtureTransformMatrix(HarmonicMIDI::grid::SceneTransform3D{});
        if(b.lengths[2]!=sizeof(instance)||std::memcmp(history+b.historyOffsets[2],&instance,sizeof(instance)))return refuse();
        for(unsigned i=0;i<2;++i)if(std::memcmp(history+i*sizeof(FixtureUniforms),&b.uniforms,sizeof(FixtureUniforms))
            ||b.uniformOffsets[i]>b.ring.length-sizeof(FixtureUniforms))return refuse();
        for(unsigned i=0;i<b.rings.size();++i){const auto value=b.rings[i];
            if(!value||value.device!=gMetalDevice||value.length!=b.ringLengths[i]
