    const auto& c=ledger.work();work={c.setup,c.parser,c.provenance,c.scalar,c.upload,c.draw,c.shadow,c.transfer,c.copy,c.compare,c.retain,c.publication};
    for(std::size_t i=0;i<ledger.attempts();++i)if(ledger.record(i).live)++storage[4];error.clear();return true;
}
bool inspectMetalRestrictedCompleteBaseRefusalsForFixture(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const std::shared_ptr<const MetalRestrictedCompleteBaseResult>& result,std::string& error) {
    if(metalDirectQueryLease||metalTerminalEntryGuard||!result||!result->payload)return false;
    const auto frame=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);if(!frame||!frame->caustic)return false;
    std::lock_guard<std::mutex> guard(sokolMutex());MetalDirectQueryLease lease(frame.get());auto& b=const_cast<MetalCompleteBasePayload&>(*result->payload);
    const auto inspect=[&](){return inspectCompleteBaseUnlocked(*frame,b,result,error,true);};
    if(!inspect())return false;
