        auto* half=static_cast<std::uint16_t*>(b.row.contents);const auto old=half[channel];
        half[channel]=value;b.half[channel]=value;std::memcpy(b.pixel.bytes.data(),half,8);
        const bool accepted=inspect();half[channel]=old;b.half[channel]=old;std::memcpy(b.pixel.bytes.data(),half,8);
        return !accepted;
    };
