    for(auto bad:{std::uint16_t(0x7c00),std::uint16_t(0x7e00)})if(!badPixel(0,bad))return false;
    const auto command=b.command;b.command=nil;bool accepted=inspect();b.command=command;if(accepted)return false;
    ++b.generation;accepted=inspect();--b.generation;if(accepted)return false;
    for(unsigned i:{0u,1u,2u}){++b.vertexOffsets[i];accepted=inspect();--b.vertexOffsets[i];if(accepted)return false;}
    ++b.indexOffset;accepted=inspect();--b.indexOffset;if(accepted)return false;
    const auto draws=b.draws;b.draws=0;accepted=inspect();b.draws=draws;if(accepted)return false;
    const auto pipeline=b.nativePipeline;b.nativePipeline=nil;accepted=inspect();b.nativePipeline=pipeline;if(accepted)return false;
    const auto shader=b.description.shader;b.description.shader.id=0;accepted=inspect();b.description.shader=shader;if(accepted)return false;
    const auto coverage=b.coverageCapture;b.coverageCapture.reset();accepted=inspect();b.coverageCapture=coverage;if(accepted)return false;
    for(unsigned i=0;i<9;++i){const auto texture=b.textures[i];b.textures[i]=nil;accepted=inspect();b.textures[i]=texture;if(accepted)return false;}
    for(unsigned i=0;i<2;++i){++b.uniformOffsets[i];accepted=inspect();--b.uniformOffsets[i];if(accepted)return false;}
    const auto transport=b.transportExcluded;b.transportExcluded=false;accepted=inspect();b.transportExcluded=transport;if(accepted)return false;
    auto* history=static_cast<unsigned char*>(b.history.contents);
    for(auto offset:{std::uint64_t(0),std::uint64_t(sizeof(FixtureUniforms)),b.historyOffsets[0],b.historyOffsets[1],b.historyOffsets[2],b.queryHistoryOffset}){
        const auto old=history[offset];history[offset]^=1;accepted=inspect();history[offset]=old;if(accepted)return false;}
    const auto& scene=*frame->staticResources->snapshot;
    const auto* object=HarmonicMIDI::grid::visual3d_detail::findById(scene.objects,scene.objectCount,b.creation->receiver);
    if(!object)return false;
    for(auto offset:{b.historyOffsets[0]+object->firstVertex*sizeof(HarmonicMIDI::grid::SceneVertex)+offsetof(HarmonicMIDI::grid::SceneVertex,normal),b.historyOffsets[2]}){
        const auto old=history[offset];history[offset]^=1;b.frozenHistory[offset]^=1;
        accepted=inspect();history[offset]=old;b.frozenHistory[offset]=old;if(accepted)return false;
    }
    const auto oldCamera=b.uniforms.cameraTranslation[0];b.uniforms.cameraTranslation[0]+=.125f;
    accepted=inspect();b.uniforms.cameraTranslation[0]=oldCamera;if(accepted)return false;
    const auto oldLight=b.uniforms.lightRotations[0][1];b.uniforms.lightRotations[0][1]=1;
    accepted=inspect();b.uniforms.lightRotations[0][1]=oldLight;if(accepted)return false;
    const auto oldMaterial=b.uniforms.baseColor[0];b.uniforms.baseColor[0]=0;
    accepted=inspect();b.uniforms.baseColor[0]=oldMaterial;if(accepted)return false;
    const auto oldSource=b.receiver;b.receiver.reset();accepted=inspect();b.receiver=oldSource;if(accepted)return false;
    // Coherent native source/echo changes still lose authored eight-band rho.
    auto* receiver=completeBaseRegisteredReceiver(*frame,b.receiver);if(!receiver||receiver->inputs.size()<=190||receiver->results.size()<=198)return false;
    auto* input=static_cast<std::uint32_t*>(receiver->input.contents);auto* output=static_cast<std::uint32_t*>(receiver->result.contents);
    const auto rho=receiver->inputs[190],echo=receiver->results[198];
