    accepted=inspect();receiver->inputs[190]=input[190]=rho;receiver->results[198]=output[198]=echo;if(accepted)return false;
    return inspect();
}

struct MetalFiniteRadianceLease final {
    std::shared_ptr<finiteradiance::Admission> ledger;
    const MetalFixtureSceneFrame* frame=nullptr;
    std::size_t slot=finiteradiance::Admission::maximumAttempts;
    ~MetalFiniteRadianceLease(){if(ledger&&frame&&slot<ledger->attempts()){
        auto& s=*frame->caustic;const auto bytes=ledger->record(slot).live?ledger->record(slot).bytes:0;
        ledger->retire(slot);s.finiteRadiancePayloads[slot]=nullptr;s.finiteRadianceRegistry[slot].reset();
        s.bytes-=bytes;s.directPrimitiveBytes-=bytes;
    }}
};
struct MetalFiniteRadiancePayload final {
    // The last base owner may acquire the same mutex in its destructor. Move it
    // here before clearing members so it dies only after this guard unlocks.
    std::shared_ptr<const MetalRestrictedCompleteBaseResult> destructionBase;
    std::shared_ptr<const MetalFixtureSceneFrame> destructionOwner;
    std::unique_lock<std::mutex> destructionGuard;
    MetalFiniteRadianceLease lease;
    std::shared_ptr<const MetalFixtureSceneFrame> owner;
    std::shared_ptr<const MetalFiniteGratingReceiverResult> receiver;
    std::shared_ptr<const MetalRestrictedCompleteBaseResult> base;
    std::shared_ptr<const MetalFiniteGratingSourceResult> source;
    std::shared_ptr<const MetalCameraGeometricRangeResult> range;
    std::shared_ptr<const glasscaustics::NativeCameraCellCoverageResult> coverage;
    std::shared_ptr<const glasscaustics::NativeDirectGratingTerminalResult> terminal;
    std::shared_ptr<const glasscaustics::GratingIncidentBinding> binding;
    std::shared_ptr<const MetalRasterCaptureManifest> capture;
    glasscaustics::SubmissionIdentity submission;
    std::string identity;
    const MetalFiniteGratingRadianceResult* sealed=nullptr;
    std::array<std::shared_ptr<const MetalLambertianArithmeticResult>,8> children{};
    std::array<lambertian::Request,8> requests{};
    std::array<std::array<std::uint32_t,250>,8> certificates{};
    std::array<std::uint32_t,8> encodings{},bands{},wavelengths{};
    std::array<std::array<std::uint32_t,5>,8> mappings{};
    std::array<std::uint32_t,5> support{},receiverKey{};
    std::array<std::uint32_t,13> inputIdentity{};
    std::array<std::uint64_t,7> generations{};
    std::array<std::uint64_t,8> childSerials{};
    std::uint64_t firstChildSlot=0;
    std::uint64_t serial=0,reservation=0,hostAllocationBytes=0,identityBound=0;
    std::uint32_t metres=0,table=0,runtimeTime=0,cellX=0,cellY=0,width=0,height=0;
    unsigned childCount=0;
    bool completed=false;
    ~MetalFiniteRadiancePayload(){
        destructionGuard=std::unique_lock<std::mutex>(sokolMutex());
        destructionBase=std::move(base);
        // Dispose the payload before its lease retires. Completed arithmetic
        // children remain owned and charged by the frame's native registry.
        children={};receiver.reset();source.reset();range.reset();coverage.reset();terminal.reset();binding.reset();capture.reset();owner.reset();
    }
};
namespace {
static bool finiteRadiancePublic(const MetalFixtureSceneFrame& f) {
    return finiteradiance::journal(f.caustic->finiteRadiancePublicInspections,f.caustic->finiteRadiancePublicCosts,finiteradiance::scanCost);
}
static std::uint64_t finiteRadianceFixed() {
    // Payload/result/allocator control blocks, caller and inspector copies,
    // eight complete requests/certificates, deferred escape and no-elision unwind.
    return 4*(sizeof(MetalFiniteRadiancePayload)+sizeof(MetalFiniteGratingRadianceResult)+256)
        +8*8*(sizeof(lambertian::Request)+250*sizeof(std::uint32_t))+16*sizeof(finiteradiance::Costs)+sizeof(std::shared_ptr<const MetalFiniteGratingRadianceResult>)+1024;
}
static bool finiteRadianceBudget(std::uint64_t length,std::uint64_t bound,std::uint64_t& bytes,finiteradiance::Costs& costs) {
    if(bound!=std::max<std::uint64_t>(15,length)||bound>renderpassoutput::kMaximumTotalBytes/16)return false;
    bytes=surfacesource::add(finiteRadianceFixed(),surfacesource::multiply(16,surfacesource::add(bound,1)));
    costs=finiteradiance::scanCost;
    costs[finiteradiance::CopiedBytes]=surfacesource::add(costs[finiteradiance::CopiedBytes],surfacesource::multiply(16,surfacesource::add(length,1)));
    return bytes<=renderpassoutput::kMaximumTotalBytes;
}
static std::uint64_t finiteRadianceWholeParent(const MetalFixtureSceneFrame& f) {
    // This includes escaped base/receiver/carrier owners, private source parent
    // and creation ledger, and every earlier retained numerical attempt.
    return surfacesource::add(completeBaseParentBytes(f),f.caustic->completeBaseAdmission?f.caustic->completeBaseAdmission->bytes():0);
}
static bool finiteRadianceLocal(const MetalFixtureSceneFrame& f,const std::shared_ptr<const MetalFiniteGratingRadianceResult>& result,bool published) {
    if(!result)return !published;
    const auto& s=*f.caustic;if(!s.finiteRadianceAdmission||result->version!=1||!result->payload)return false;
    const auto& b=*result->payload;if(b.lease.slot>=s.finiteRadianceAdmission->attempts())return false;
    const auto& a=s.finiteRadianceAdmission->record(b.lease.slot);
    return a.live&&(!published||a.published)&&s.finiteRadianceRegistry[b.lease.slot].lock()==result
        &&s.finiteRadiancePayloads[b.lease.slot]==&b&&b.sealed==result.get()&&b.lease.ledger==s.finiteRadianceAdmission&&b.owner.get()==&f;
}
static bool finiteRadianceRequest(const MetalFiniteReceiverBatch& r,unsigned band,lambertian::Request& q) {
    if(band>=8||r.inputs.size()<320)return false;
    const auto count=metalcaustic::finiteReceiverRequestWords(r.inputs[3]);
    const auto at=8+count+100+70*band;
    if(count!=r.inputs.size()||at+10>r.results.size())return false;
    const auto* m=r.results.data()+at;
    q={};q[0]=lambertian::kVersion;q[1]=lambertian::kP32Bits;q[2]=128;q[3]=640;
    bool zero=true;for(unsigned k=0;k<8;++k){if(m[2+k])zero=false;if(k>=4&&m[2+k])return false;}
    if(zero){if(m[0]||m[1])return false;}
    else {const auto exponent=std::int32_t(m[0]);
        if(m[1]!=1||!(m[2]&1)||exponent< -253||exponent>17)return false;
        q[4]=m[0];for(unsigned k=0;k<4;++k)q[5+k]=m[2+k];}
    lambertian::putBudgets(q,lambertian::kNativeCeilings);return true;
}
static bool finiteRadianceParents(const MetalFixtureSceneFrame& f,MetalFiniteRadiancePayload& b,bool prepare,std::string& error) {
    auto* r=completeBaseRegisteredReceiver(f,b.receiver);
    if(!r||!b.base||!b.base->payload||b.base->payload->owner.get()!=&f
        ||b.base->payload->receiver!=b.receiver||b.base->payload->coverageCapture!=r->capture
        ||!inspectCompleteBaseUnlocked(f,*b.base->payload,b.base,error,true)
        ||!metalInspectFiniteReceiver(f,*r,b.receiver,error)||!r->cohort||!r->cohort->prepared
        ||r->cohort->sources.size()!=1||r->cohort->prepared->sources().size()!=1)return false;
    const auto source=r->parent;const auto range=r->range;
    if(!source||!range||!range->parent||!source->parent||r->inputs.size()<320)return false;
    const auto binding=r->cohort->prepared->sources()[0];const auto& native=*r->cohort->sources[0]->batch;
    const auto& d=native.sourceUpload.input;const auto& sample=r->cohort->readbacks[0].samples[0];
    if(!binding||!binding->material||!native.sourceUpload.complete||d.identifiers!=sample.source.input.identifiers
        ||d.coefficients!=sample.source.input.coefficients
        ||d.identifiers!=std::array<std::uint32_t,4>{1,std::uint32_t(diffractionmaterial::DirectionalSpectralMeasure::IrradianceCoefficient),
            glasscaustics::kDirectionalSourceWorldMetres,binding->prepared.sceneLight.value}
        ||!native.sourceInput||!native.sourceInput.contents||std::memcmp(native.sourceInput.contents,&d,sizeof(d))
        ||f.width_!=1||f.height_!=1||!f.caustic->cameraInputs||!r->capture
        ||f.caustic->cameraInputs->timeSeconds!=float(binding->evaluationTime)
        ||r->capture->evaluationTime!=f.caustic->cameraInputs->timeSeconds)return false;
    const auto& description=binding->material->description();
    if(description.spectrum.wavelengthsNanometres!=diffractionmaterial::kProductionWavelengthsNanometres
        ||description.spectrum.wavelengthCount!=8||description.spectrum.integrationModel!=diffractionmaterial::SpectralIntegrationModel::Cie1931Xyz)return false;
    std::uint64_t time=0;std::memcpy(&time,&binding->evaluationTime,8);
    if(r->inputs[286]!=std::uint32_t(time)||r->inputs[287]!=std::uint32_t(time>>32)
        ||binding!=f.caustic->cameraBinding||r->capture!=f.caustic->rasterCapture)return false;
    const auto left=r->inputs[5],right=r->inputs[6];const auto& triangles=binding->frame.triangles;
    if(left>=triangles.size()||right>=triangles.size())return false;
    const auto& a=triangles[left];const auto& c=triangles[right];
    if(!a.reflectance||!c.reflectance||a.reflectance->coefficients!=c.reflectance->coefficients)return false;
    for(auto rho:a.reflectance->coefficients)if(!(rho>0)||rho>1||!std::isfinite(rho))return false;
    const std::array<std::uint32_t,5> key{a.object,a.material,a.instance,a.triangle,c.triangle};
    std::array<std::uint32_t,13> identity{};std::copy_n(r->inputs.begin()+280,13,identity.begin());
    const std::array<std::uint64_t,7> generations{f.rendererGeneration_,source->generation,r->generation,range->generation,
        range->parent->retained().proof.generation,b.base->payload->serial,f.nativeResourceCacheIdentity()};
    const auto runtimeTime=glasscaustics::glassCameraTraceFloatBits(f.caustic->cameraInputs->timeSeconds);
    if(prepare){b.source=source;b.range=range;b.coverage=range->parent;b.terminal=source->parent;b.binding=binding;b.capture=r->capture;
        b.submission=r->cohort->seal;b.support=r->support;b.receiverKey=key;b.inputIdentity=identity;b.generations=generations;
        b.metres=glasscaustics::kDirectionalSourceWorldMetres;b.table=glasscaustics::kTableVersion;
        b.runtimeTime=runtimeTime;b.width=b.height=1;
        for(unsigned k=0;k<8;++k){const auto& row=b.terminal->retained().orders[k];
            b.bands[k]=k;b.mappings[k]={row.source,row.endpoint,row.band,std::uint32_t(row.order.primary),std::uint32_t(row.order.secondary)};
            b.wavelengths[k]=glasscaustics::glassCameraTraceFloatBits(diffractionmaterial::kProductionWavelengthsNanometres[k]);
            if(b.terminal->retained().bands[k].wavelengthNanometres!=double(diffractionmaterial::kProductionWavelengthsNanometres[k])
                ||!finiteRadianceRequest(*r,k,b.requests[k]))return false;}
    }else {
        if(b.source!=source||b.range!=range||b.coverage!=range->parent||b.terminal!=source->parent||b.binding!=binding||b.capture!=r->capture
            ||!(b.submission==r->cohort->seal)||b.support!=r->support||b.receiverKey!=key||b.inputIdentity!=identity||b.generations!=generations
            ||b.metres!=glasscaustics::kDirectionalSourceWorldMetres||b.table!=glasscaustics::kTableVersion
            ||b.runtimeTime!=runtimeTime||b.width!=1||b.height!=1||b.cellX||b.cellY)return false;
        for(unsigned k=0;k<8;++k){lambertian::Request expected{};
            const auto& row=b.terminal->retained().orders[k];
            if(b.bands[k]!=k||b.mappings[k]!=std::array<std::uint32_t,5>{row.source,row.endpoint,row.band,std::uint32_t(row.order.primary),std::uint32_t(row.order.secondary)}
                ||b.mappings[k]!=std::array<std::uint32_t,5>{0,0,k,0,0}
                ||b.wavelengths[k]!=glasscaustics::glassCameraTraceFloatBits(diffractionmaterial::kProductionWavelengthsNanometres[k])
                ||b.terminal->retained().bands[k].wavelengthNanometres!=double(diffractionmaterial::kProductionWavelengthsNanometres[k])
                ||!finiteRadianceRequest(*r,k,expected)||expected!=b.requests[k])return false;}
    }
    return true;
}
static bool metalFiniteRadianceRegistryImpl(const MetalFixtureSceneFrame& f,std::uint64_t& bytes,std::string& error) {
    bytes=0;auto& s=*f.caustic;
    try {
        if(!finiteradiance::journal(s.finiteRadianceRegistryInspections,s.finiteRadianceRegistryCosts,finiteradiance::scanCost)
            ||!finiteradiance::validJournal(s.finiteRadiancePublicInspections,s.finiteRadiancePublicCosts,finiteradiance::scanCost))return false;
        if(!s.finiteRadianceAdmission)return !s.finiteRadianceControlBytes&&!s.finiteRadianceControlSerial;
        auto& ledger=*s.finiteRadianceAdmission;
        if(s.finiteRadianceFactories>finiteradiance::Admission::maximumAttempts||s.lambertianAttemptCount>s.lambertianAttempts.size()
            ||s.finiteReceiverAttemptCount>s.finiteReceiverAttempts.size()||!ledger.inspectJournal()||ledger.factories()!=s.finiteRadianceFactories)return false;
        bytes=ledger.bytes();
        if(s.finiteRadianceControlBytes<sizeof(finiteradiance::Admission)||s.finiteRadianceControlBytes>sizeof(finiteradiance::Admission)+256
            ||!s.finiteRadianceControlSerial||s.finiteRadianceControlSerial<=f.rendererGeneration_)return false;
        for(std::size_t i=0;i<ledger.attempts();++i){const auto& a=ledger.record(i);
            std::uint64_t reservation=0;finiteradiance::Costs exact{};
            if(a.identityBytes!=s.schedule.identity.size()||!finiteRadianceBudget(a.identityBytes,a.identityBound,reservation,exact)
                ||a.construction!=exact)return false;
            if(!a.live){if(s.finiteRadiancePayloads[i]||!s.finiteRadianceRegistry[i].expired())return false;continue;}
            const auto* b=s.finiteRadiancePayloads[i];
            // Accounted in-progress wrappers are structural owners, not optical
            // authority. This registry must never recursively inspect parents.
            if(!b||!b->sealed||b->lease.slot!=i||b->lease.ledger!=s.finiteRadianceAdmission
                ||b->lease.frame!=&f||b->owner.get()!=&f||b->destructionOwner.get()!=&f||b->serial!=a.serial
                ||a.bytes!=reservation||b->reservation!=reservation||b->identity!=s.schedule.identity||b->identityBound!=a.identityBound
                ||b->identity.capacity()>2*a.identityBound||b->identity.c_str()[b->identity.size()]
                ||b->submission.frameIdentity.capacity()>2*std::max<std::size_t>(15,b->submission.frameIdentity.size())
                ||b->submission.frameIdentity.c_str()[b->submission.frameIdentity.size()]
                ||b->hostAllocationBytes<sizeof(MetalFiniteRadiancePayload)+sizeof(MetalFiniteGratingRadianceResult)
                ||b->hostAllocationBytes>finiteRadianceFixed()||b->childCount>8||b->firstChildSlot!=a.firstChildSlot
                ||b->firstChildSlot>s.lambertianAttemptCount||b->childCount>s.lambertianAttemptCount-b->firstChildSlot||!b->receiver||!b->base||!b->base->payload
                ||b->base->version!=1||b->base->payload->owner.get()!=&f||b->base->payload->receiver!=b->receiver
                ||b->base->payload->lease.ledger!=s.completeBaseAdmission||!s.completeBaseAdmission
                ||b->base->payload->lease.slot>=s.completeBaseAdmission->attempts()
                ||!s.completeBaseAdmission->record(b->base->payload->lease.slot).live
                ||!s.completeBaseAdmission->record(b->base->payload->lease.slot).published
                ||s.completeBasePayloads[b->base->payload->lease.slot]!=b->base->payload.get()
                ||s.completeBaseRegistry[b->base->payload->lease.slot].lock()!=b->base
                ||!completeBaseRegisteredReceiver(f,b->receiver))return false;
            for(unsigned k=0;k<b->childCount;++k){if(!b->children[k]||!metalLrLocal(f,b->children[k],true))return false;
                const auto& numerical=s.lambertianAttempts[b->firstChildSlot+k];
                if(!numerical.committed||!numerical.native||numerical.native->sealed!=b->children[k]
                    ||b->children[k]->serial!=b->childSerials[k]||b->childSerials[k]<=b->serial
                    ||(k&&b->childSerials[k]<=b->childSerials[k-1]))return false;
                for(unsigned j=0;j<k;++j)if(b->children[j]==b->children[k])return false;}
            if(a.published&&(!b->completed||b->childCount!=8||a.support!=b->support||a.cellX!=b->cellX||a.cellY!=b->cellY))return false;
            if(a.published)for(std::size_t j=0;j<i;++j){
                if(ledger.record(j).published&&ledger.record(j).support==b->support&&ledger.record(j).cellX==b->cellX&&ledger.record(j).cellY==b->cellY)return false;}
        }
        return true;
    }catch(const std::exception& exception){error=exception.what();return false;}
}
static bool inspectFiniteRadianceUnlocked(const MetalFixtureSceneFrame& f,MetalFiniteRadiancePayload& b,
    const std::shared_ptr<const MetalFiniteGratingRadianceResult>& result,bool published,std::string& error) {
    const auto refuse=[&](){error="Finite radiance lost its exact metric parents, band mapping or certified native arithmetic";return false;};
