            if(!metalLrLocal(f,child,true)||child->serial!=b.childSerials[k]||child->serial<=b.serial
                ||(k&&child->serial<=b.children[k-1]->serial)||child->request!=b.requests[k]||child->words!=b.certificates[k]
                ||child->words[247]!=1||child->words[0]!=1||child->words[2]!=b.encodings[k])return refuse();
            for(unsigned j=0;j<k;++j)if(child==b.children[j])return refuse();
