            &&validateMetalDirectAttemptLedgerUnlocked(f,error);
    }catch(const std::exception& exception){error=exception.what();return false;}
}
}
bool produceMetalFiniteGratingRadianceForFixture(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const std::shared_ptr<const MetalFiniteGratingReceiverResult>& receiver,const std::shared_ptr<const MetalRestrictedCompleteBaseResult>& base,
    std::shared_ptr<const MetalFiniteGratingRadianceResult>& output,std::string& error,int stop,
    std::shared_ptr<const MetalFiniteGratingRadianceResult>* escaped,std::uint64_t limit) {
