        payload=std::allocate_shared<MetalFiniteRadiancePayload>(MetalLrAllocator<MetalFiniteRadiancePayload>(allocated,finiteRadianceFixed()));auto& b=*payload;
        b.lease.ledger=s.finiteRadianceAdmission;b.lease.slot=slot;b.lease.frame=frame.get();b.destructionOwner=frame;
        // The initialized lease owns retirement before any fallible member copy.
