    }catch(const std::exception& exception){error=exception.what();return false;}
}
bool readMetalFiniteGratingRadianceForFixture(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const std::shared_ptr<const MetalFiniteGratingRadianceResult>& result,std::array<std::uint32_t,8>& encodings,
