    }catch(const std::exception& exception){error=exception.what();return false;}
}
bool inspectMetalFiniteGratingRadianceRefusalsForFixture(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const std::shared_ptr<const MetalFiniteGratingRadianceResult>& result,std::string& error) {
    if(metalDirectQueryLease||metalTerminalEntryGuard)return false;
    const auto f=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);
    if(!f||!f->caustic)return false;
    std::unique_lock<std::mutex> guard(sokolMutex());MetalDirectQueryLease entry(f.get());auto& s=*f->caustic;
    try {if(!finiteRadiancePublic(*f))return false;if(!finiteRadianceLocal(*f,result,true))return false;
        auto& b=const_cast<MetalFiniteRadiancePayload&>(*result->payload);
        const auto inspect=[&](){return finiteRadiancePublic(*f)&&inspectFiniteRadianceUnlocked(*f,b,result,true,error);};
        if(!inspect())return false;
        const auto bytes=s.bytes,primitive=s.directPrimitiveBytes,native=s.metrics.retainedNativeBytes;const auto attempts=s.lambertianAttemptCount;
        const auto reject=[&](){const auto count=b.lease.ledger->record(b.lease.slot).inspections;
            return !inspect()&&b.lease.ledger->record(b.lease.slot).inspections==count+1&&s.bytes==bytes
                &&s.directPrimitiveBytes==primitive&&s.metrics.retainedNativeBytes==native&&s.lambertianAttemptCount==attempts;};
        const auto changed=[&](auto& value,const auto& replacement){const auto saved=value;value=replacement;
            const bool refused=reject();value=saved;return refused;};
        for(unsigned k=0;k<8;++k){
            if(!changed(b.children[k],std::shared_ptr<const MetalLambertianArithmeticResult>{})||!changed(b.bands[k],std::uint32_t((k+1)%8))||!changed(b.encodings[k],b.encodings[k]^1u)
                ||!changed(b.children[k],b.children[(k+1)%8]))return false;
            if(!changed(b.wavelengths[k],b.wavelengths[k]^1u)||!changed(b.childSerials[k],b.childSerials[k]+1))return false;
            for(auto& mapping:b.mappings[k])if(!changed(mapping,mapping^1u))return false;
            for(unsigned word:{0u,2u,4u,5u,26u,86u,166u,226u,245u,246u,247u,248u,249u})
                if(!changed(b.certificates[k][word],b.certificates[k][word]^1u))return false;
            for(unsigned word:{0u,1u,2u,3u,4u,5u,9u,10u,21u})if(!changed(b.requests[k][word],b.requests[k][word]^1u))return false;
        }
