        std::swap(b.encodings[0],b.encodings[1]);std::swap(b.childSerials[0],b.childSerials[1]);
        const bool permutationRefused=reject();
        std::swap(b.children[0],b.children[1]);std::swap(b.certificates[0],b.certificates[1]);
        std::swap(b.encodings[0],b.encodings[1]);std::swap(b.childSerials[0],b.childSerials[1]);
        if(!permutationRefused||!changed(b.firstChildSlot,b.firstChildSlot+1)||!changed(b.metres,0u)||!changed(b.table,0u)||!changed(b.runtimeTime,b.runtimeTime^1u)
            ||!changed(b.cellX,1u)||!changed(b.width,2u)||!changed(b.childCount,7u)||!changed(b.completed,false)
            ||!changed(b.owner,std::shared_ptr<const MetalFixtureSceneFrame>{})
            ||!changed(b.base,std::shared_ptr<const MetalRestrictedCompleteBaseResult>{})
            ||!changed(b.receiver,std::shared_ptr<const MetalFiniteGratingReceiverResult>{})
            ||!changed(b.source,std::shared_ptr<const MetalFiniteGratingSourceResult>{})
            ||!changed(b.range,std::shared_ptr<const MetalCameraGeometricRangeResult>{})
            ||!changed(b.coverage,std::shared_ptr<const glasscaustics::NativeCameraCellCoverageResult>{})
            ||!changed(b.terminal,std::shared_ptr<const glasscaustics::NativeDirectGratingTerminalResult>{})
            ||!changed(b.binding,std::shared_ptr<const glasscaustics::GratingIncidentBinding>{})
            ||!changed(b.capture,std::shared_ptr<const MetalRasterCaptureManifest>{}))return false;
        for(auto& generation:b.generations)if(!changed(generation,generation+1))return false;
        for(auto& identity:b.inputIdentity)if(!changed(identity,identity^1u))return false;
        for(auto& key:b.support)if(!changed(key,key^1u))return false;
        for(auto& key:b.receiverKey)if(!changed(key,key^1u))return false;
        if(!changed(b.submission.completedFence,b.submission.completedFence+1)||!changed(b.reservation,b.reservation+1)
            ||!changed(b.hostAllocationBytes,0ull))return false;
        auto& record=const_cast<finiteradiance::Admission::Attempt&>(b.lease.ledger->record(b.lease.slot));
        for(auto& cost:record.construction)if(!changed(cost,cost+1))return false;
        if(!changed(record.serial,record.serial+1)||!changed(record.bytes,record.bytes+1)||!changed(record.published,false)
            ||!changed(record.live,false)||!changed(record.identityBytes,record.identityBytes+1)||!changed(record.identityBound,record.identityBound+1)||!changed(record.firstChildSlot,record.firstChildSlot+1))return false;
        for(auto& support:record.support)if(!changed(support,support^1u))return false;
        for(auto& cost:record.inspection){const auto saved=cost,count=record.inspections;cost+=1;
            const bool refused=!inspect()&&record.inspections==count;cost=saved;if(!refused)return false;}
        // Mutate actual registered numerical/native owners, rather than merely
        // changing a wrapper hash. Their own attempted inspectors remain charged.
        MetalCausticState::LambertianAttempt* numerical=nullptr;
        for(std::size_t i=0;i<s.lambertianAttemptCount;++i)if(s.lambertianAttempts[i].native&&s.lambertianAttempts[i].native->sealed==b.children[0])numerical=&s.lambertianAttempts[i];
        if(!numerical||!changed(numerical->committed,false))return false;
        const auto sealed=numerical->native->sealed;numerical->native->sealed.reset();
        const bool childUnregistered=reject();numerical->native->sealed=sealed;if(!childUnregistered)return false;
        for(std::size_t i=0;i<s.lambertianAttemptCount;++i){const auto& a=s.lambertianAttempts[i];
            if(a.committed&&a.native&&a.native->sealed&&a.native->sealed!=b.children[0]
                &&a.native->sealed->request!=b.requests[0]){if(!changed(b.children[0],a.native->sealed))return false;break;}}
        auto& resources=const_cast<MetalLambertianNativeResources&>(*b.children[0]->resources);
        if(!changed(resources.completed,false))return false;
        const auto command=resources.command;resources.command=nil;const bool commandRefused=reject();resources.command=command;
        const auto device=resources.device;resources.device=nil;const bool deviceRefused=reject();resources.device=device;
        if(!commandRefused||!deviceRefused)return false;
        resources.command=b.base->payload->command;const bool substitutedCommand=reject();resources.command=command;
        if(!substitutedCommand||!changed(resources.recipe,resources.recipe+1))return false;
        auto* receiverInput=completeBaseRegisteredReceiver(*f,b.receiver);if(!receiverInput||!receiverInput->cohort)return false;
        auto* directional=static_cast<std::uint32_t*>(receiverInput->cohort->sources[0]->batch->sourceInput.contents);
        for(unsigned word:{0u,1u,2u,3u})if(!changed(directional[word],directional[word]^1u))return false;
        if(!changed(receiverInput->inputs[286],receiverInput->inputs[286]^1u)
            ||!changed(receiverInput->inputs[287],receiverInput->inputs[287]^1u))return false;
        if(!changed(resources.source.bytes[resources.source.size],'x'))return false;
        if(!b.identity.empty()&&!changed(b.identity[0],char(b.identity[0]^1)))return false;
        {
            // The fixed 16-capacity string envelope includes this bounded test
            // copy, replacement and restored incumbent, including their NULs.
            auto large=b.identity;large.reserve(2*b.identityBound+1);
            if(large.capacity()>4*b.identityBound)return false;
            b.identity.swap(large);const bool capacityRefused=reject();b.identity.swap(large);if(!capacityRefused)return false;
        }
        auto* input=static_cast<std::uint32_t*>(resources.input.contents);
        for(unsigned word:{1u,2u,4u,5u})if(!changed(input[word],input[word]^1u))return false;
        auto* output=static_cast<std::uint32_t*>(resources.result.contents);
        for(unsigned word:{0u,2u,26u,86u,166u,226u,247u})if(!changed(output[word],output[word]^1u))return false;
        // Exact registry identity is required even when all generations match.
        const auto weak=s.finiteRadianceRegistry[b.lease.slot];s.finiteRadianceRegistry[b.lease.slot].reset();
        const bool unregistered=reject();s.finiteRadianceRegistry[b.lease.slot]=weak;if(!unregistered)return false;
        const auto raw=s.finiteRadiancePayloads[b.lease.slot];s.finiteRadiancePayloads[b.lease.slot]=nullptr;
        const bool rawRefused=reject();s.finiteRadiancePayloads[b.lease.slot]=raw;if(!rawRefused)return false;
        // A representability refusal never replaces M by a rounded float. These
        // are isolated derivation probes over copied dyadics, not optical grants.
        auto* receiver=completeBaseRegisteredReceiver(*f,b.receiver);if(!receiver)return false;
        const auto at=8+metalcaustic::finiteReceiverRequestWords(receiver->inputs[3])+100;
        lambertian::Request request{};std::array<std::uint32_t,10> saved{};std::copy_n(receiver->results.begin()+at,10,saved.begin());
        const auto restore=[&](){std::copy(saved.begin(),saved.end(),receiver->results.begin()+at);};
        for(unsigned word:{1u,6u,7u,8u,9u}){
            receiver->results[at+word]=word==1?2u:1u;
            const bool refused=!finiteRadianceRequest(*receiver,0,request);restore();if(!refused)return false;
        }
        receiver->results[at+1]=1;receiver->results[at+2]=2;
        const bool evenRefused=!finiteRadianceRequest(*receiver,0,request);restore();if(!evenRefused)return false;
        for(unsigned malformed=0;malformed<2;++malformed){
            std::fill_n(receiver->results.begin()+at,10,0);receiver->results[at+malformed]=1;
            const bool zeroRefused=!finiteRadianceRequest(*receiver,0,request);restore();if(!zeroRefused)return false;
        }
        for(int exponent:{-254,18}){receiver->results[at]=std::uint32_t(exponent);receiver->results[at+1]=1;receiver->results[at+2]=1;
            const bool refused=!finiteRadianceRequest(*receiver,0,request);restore();if(!refused)return false;}
        return inspect()&&s.bytes==bytes&&s.directPrimitiveBytes==primitive&&s.metrics.retainedNativeBytes==native;
    }catch(const std::exception& exception){error=exception.what();return false;}
}

bool readMetalFiniteGratingRadianceStorageForFixture(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    std::array<std::uint64_t,8>& storage,finiteradiance::Costs& work,std::string& error) {
    if(metalDirectQueryLease||metalTerminalEntryGuard)return false;
    const auto f=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);if(!f||!f->caustic||!f->staticResources)return false;
    std::lock_guard<std::mutex> guard(sokolMutex());MetalDirectQueryLease entry(f.get());const auto& s=*f->caustic;
    try {if(!finiteRadiancePublic(*f)||!validateMetalDirectAttemptLedgerUnlocked(*f,error))return false;std::uint64_t bytes=0;if(!metalFiniteRadianceRegistryImpl(*f,bytes,error))return false;
        std::uint64_t reservation=0;finiteradiance::Costs construction{};
        if(!finiteRadianceBudget(s.schedule.identity.size(),std::max<std::size_t>(15,s.schedule.identity.size()),reservation,construction))return false;
        const auto child=metalLrReservation(*f);
        storage={s.finiteRadianceFactories,s.finiteRadianceAdmission?s.finiteRadianceAdmission->attempts():0,bytes,
            finiteRadianceWholeParent(*f),0,s.lambertianAttemptCount,reservation,child};
        work=finiteradiance::add(s.finiteRadianceAdmission?s.finiteRadianceAdmission->work():finiteradiance::multiply(finiteradiance::factoryCost,s.finiteRadianceFactories),
            finiteradiance::add(s.finiteRadiancePublicCosts,s.finiteRadianceRegistryCosts));
        if(s.finiteRadianceAdmission)for(std::size_t i=0;i<s.finiteRadianceAdmission->attempts();++i)if(s.finiteRadianceAdmission->record(i).live)++storage[4];
        error.clear();return true;
    }catch(const std::exception& exception){error=exception.what();return false;}
}

// Fixed native spectral conversion. Existing shader recipes remain unchanged.
static constexpr char finiteRgbSource[]=R"METAL(#include <metal_stdlib>
using namespace metal;
kernel void finiteGratingRgb(const device uint* encodings [[buffer(0)]],
    const device float4* weights [[buffer(1)]],const device uint4* control [[buffer(2)]],
    device uint4* diagnostic [[buffer(3)]],device float4* output [[buffer(4)]],uint tid [[thread_position_in_grid]]) {
    if(tid!=0)return;
    if(any(control[0]!=uint4(1,8,1,0))){diagnostic[0]=uint4(1,1,1,8);return;}
    float3 xyz=float3(0.0);
    for(uint band=0;band<8;++band){float radiance=as_type<float>(encodings[band]);float4 w=weights[band];xyz+=radiance*w.w*w.xyz;}
    float3 rgb=float3(3.2406*xyz.x-1.5372*xyz.y-0.4986*xyz.z,
        -0.9689*xyz.x+1.8758*xyz.y+0.0415*xyz.z,
        0.0557*xyz.x-0.2040*xyz.y+1.0570*xyz.z);
    uint status=all(isfinite(rgb))&&all(abs(rgb)<=float3(65504.0))?0u:2u;
    output[0]=float4(rgb,1.0);diagnostic[0]=uint4(1,status,1,8);
}
)METAL";
