    MetalDirectQueryLease queryLease(frame.get());const auto& state=*frame->caustic;
    for(std::size_t i=0;i<state.receiverAttemptCount;++i) {
        const auto& a=state.receiverAttempts[i];
        if(!a.committed||!a.native||a.native->sealed!=output.nativeResult)continue;
        if(!validateMetalDirectCohortUnlocked(*frame,*a.cohort,a.cohort->seal,a.cohort->readbacks,error)
            ||!metalReceiverNative(*frame,a,error)
            ||!glasscaustics::sameDirectGratingTerminalReceiverReadback(output,a.native->readback,false))return false;
        error.clear();return true;
    }
    error="Metal receiver result is not registered in this actual frame";return false;
}

