bool inspectMetalDirectGratingCohortIncumbentRefusalForFixture(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const std::shared_ptr<const glasscaustics::DirectGratingIrradianceCohort>& prepared,
    glasscaustics::DirectGratingIrradianceCohortReadback& incumbent,std::string& error)
{
    using namespace glasscaustics;std::lock_guard<std::mutex> lock(sokolMutex());
    const auto frame=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);
