        ||state.directWork!=work||state.cohortDepositionWork!=deposition||state.bytes!=total
        ||state.metrics.retainedNativeBytes!=native||!state.directCohorts.empty()||state.cohortCandidate
        ||incumbent.cohort!=prior.cohort||!(incumbent.submission==prior.submission)
        ||incumbent.endpoints.size()!=prior.endpoints.size())return refuse("Metal distinct incumbent storage refusal dispatched or changed prior owners");
    for(std::size_t i=0;i<incumbent.endpoints.size();++i)
        if(incumbent.endpoints[i].surfaceIrradiance!=prior.endpoints[i].surfaceIrradiance
            ||!sameDirectGratingEndpointInput(incumbent.endpoints[i].input,prior.endpoints[i].input))
