bool inspectMetalDirectGratingAttemptBudgetForFixture(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    const std::vector<glasscaustics::NativeDirectGratingEndpointInput>& endpoints,std::uint64_t failedAttempts,std::string& error)
{
    using namespace glasscaustics;
    std::lock_guard<std::mutex> lock(sokolMutex());
    const auto frame=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);
    const auto* b=frame?frame->directBatch():nullptr;
    const auto refuse=[&](const char* message){error=message;return false;};
    if(!b||!b->binding||!b->reservedWork||endpoints.size()!=b->upload.inputs.size())
        return refuse("Metal dispatched-attempt fixture requires a completed real native batch");
    auto& state=*frame->caustic;std::uint64_t acceptedWork=0;
    for(const auto& accepted:state.directBatches)acceptedWork+=accepted->reservedWork;
    for(const auto& accepted:state.cameraTraceBatches)acceptedWork+=accepted->reservedWork;
    if(failedAttempts>kMaximumQueryWork/b->reservedWork
        ||state.directWork!=acceptedWork+failedAttempts*b->reservedWork)
        return refuse("Metal failed native endpoint, seam or query attempt discarded its whole-frame work charge");
    const auto remaining=kMaximumQueryWork-b->binding->bounds.combinedWork-state.adjunctWork;
    if(b->reservedWork>remaining||state.directWork>remaining-b->reservedWork)
        return refuse("Metal dispatched-attempt fixture lacks one bounded failure reservation");
    const auto bytes=state.bytes,primitiveBytes=state.directPrimitiveBytes,nativeBytes=state.metrics.retainedNativeBytes;
    const auto batches=state.directBatches.size();
    auto sentinel=b->readback;
    const auto unchanged=[&]() {
        if(frame->directBatch()!=b||state.directBatches.size()!=batches||state.bytes!=bytes
            ||state.directPrimitiveBytes!=primitiveBytes||state.metrics.retainedNativeBytes!=nativeBytes
            ||!sameDirectGratingContributionReadback(sentinel,b->readback))return false;
        return true;
    };
    // Charge a real failed dispatch before testing an unjournaled cap counter.
    const auto chargedBefore=state.directWork;
    if(produceMetalDirectGratingIrradianceReadbackUnlocked(owner,b->binding,endpoints,sentinel,error,true)
        ||error.empty()||state.directWork!=chargedBefore+b->reservedWork||!unchanged())
        return refuse("Metal real failed native attempt lost its charge or replaced accepted output/storage");
    struct RestoreWork {
        MetalCausticState& state;std::uint64_t prior;
        ~RestoreWork(){state.directWork=prior;}
    } restore{state,state.directWork};
    const auto attempts=state.directAttemptCount;
    state.directWork=remaining;
    if(produceMetalDirectGratingIrradianceReadbackUnlocked(owner,b->binding,endpoints,sentinel,error,true)
        ||error.empty()||state.directWork!=remaining||state.directAttemptCount!=attempts||!unchanged())
        return refuse("Metal unjournaled whole-frame counter admitted or charged another attempt");
    auto malformed=endpoints;malformed[0].control[0]=0;
    if(produceMetalDirectGratingIrradianceReadbackUnlocked(owner,b->binding,malformed,sentinel,error)
        ||error.empty()||state.directWork!=remaining||!unchanged())
        return refuse("Metal undispatched malformed input spent work or changed accepted output");
    state.directWork=restore.prior;
    MetalDirectQueryLease lease(frame.get());
    if(!validateDirectGratingContributionReadback(*b->binding,*frame,b->readback.submission,
        b->binding->evaluationTime,b->readback,error))return false;
    error.clear();return true;
}

