bool inspectMetalDirectGratingRefusalsForFixture(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,std::string& error)
{
    using namespace glasscaustics;
    std::lock_guard<std::mutex> lock(sokolMutex());
    const auto frame=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);
    auto* b=frame&&frame->caustic&&!frame->caustic->directBatches.empty()?frame->caustic->directBatches.back().get():nullptr;
    if(!b||!b->binding){error="Metal direct refusal fixtures need a completed real batch";return false;}
    MetalDirectQueryLease lease(frame.get());auto& state=*frame->caustic;
    const auto validate=[&](){return validateDirectGratingContributionReadback(*b->binding,*frame,b->readback.submission,
        b->binding->evaluationTime,b->readback,error);};
    if(!validate())return false;
    for(unsigned fault=0;fault<9;++fault) {
        const auto input=*static_cast<const NativeDirectGratingEndpointInput*>(b->input.contents);
        const auto source=*static_cast<const NativeDirectionalSourceInput*>(b->sourceInput.contents);
        const auto result=*static_cast<const metalcaustic::DirectGratingResult*>(b->result.contents);
        const auto query=b->query;const auto command=b->command;const auto device=gMetalDevice;
        const auto generation=frame->caustic->identity.queryGeneration;
        const auto bytes=state.directPrimitiveBytes,work=state.directWork;
        if(fault==0)static_cast<NativeDirectGratingEndpointInput*>(b->input.contents)->primitive[0]^=1;
        if(fault==1)static_cast<NativeDirectionalSourceInput*>(b->sourceInput.contents)->coefficients[0]+=.125f;
        if(fault==2)static_cast<metalcaustic::DirectGratingResult*>(b->result.contents)->irradiance[0]+=.125f;
        if(fault==3)b->query=nil;
        if(fault==4)b->command=nil;
        if(fault==5)++state.identity.queryGeneration;
        if(fault==6)gMetalDevice=nil;
        if(fault==7)state.directPrimitiveBytes=renderpassoutput::kMaximumTotalBytes;
        if(fault==8)state.directWork=kMaximumQueryWork;
        const bool accepted=validate();const bool missingError=error.empty();
        b->query=query;b->command=command;gMetalDevice=device;state.identity.queryGeneration=generation;
        state.directPrimitiveBytes=bytes;state.directWork=work;
        std::memcpy(b->input.contents,&input,sizeof(input));std::memcpy(b->sourceInput.contents,&source,sizeof(source));
        std::memcpy(b->result.contents,&result,sizeof(result));
        if(accepted||missingError){error="Metal actual direct query accepted a stale buffer, source, result, query, fence, generation, device or aggregate cap";return false;}
        if(!validate())return false;
    }
    DirectGratingContributionBounds bounds;
    const auto perBatch=b->bounds.queryWork+b->bounds.bandWork;
    if(state.directBatches.size()<2||state.directWork<2*perBatch
        ||calculateDirectGratingContributionBounds(*b->binding,b->upload.inputs.size(),b->upload.otherOwnedBytes,
            kMaximumQueryWork-b->binding->bounds.combinedWork-perBatch+1,bounds,error)
        ||calculateDirectGratingContributionBounds(*b->binding,b->upload.inputs.size(),
            renderpassoutput::kMaximumTotalBytes-b->binding->frame.bounds.transientBytes-b->binding->bounds.bytes
                -b->bounds.bytes+1,b->upload.otherWork,bounds,error)) {
        error="Metal direct batches lost cumulative original work or storage refusal";return false;
    }
    error.clear();return true;
}

