// Local fixture seam, deliberately absent from backend.h. It inspects real
// completed owning passes and never returns a caller-mintable proof snapshot.
bool inspectMetalRasterCaptureForFixture(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    bool privateStaging,std::string& error)
{
    std::lock_guard<std::mutex> lock(sokolMutex());
    const auto frame=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);
    const auto refuse=[&](const char* text){error=text;return false;};
    if(!frame||!frame->caustic||!frame->caustic->rasterCapture||frame->privateCameraAttachments!=privateStaging)
        return refuse("Metal raster fixture requires the real requested submission path");
    auto& state=*frame->caustic;const auto escaped=state.rasterCapture;
    auto& m=const_cast<MetalRasterCaptureManifest&>(*escaped);
    if(m.passes.empty()||m.passes[0]->draws.empty()||!inspectMetalRasterCaptureUnlocked(*frame,error))return false;
    const auto bytes=state.bytes,native=state.metrics.retainedNativeBytes,primitive=state.directPrimitiveBytes;
    const auto attempts=state.directAttemptCount,receivers=state.receiverAttemptCount,terminals=state.terminalAttemptCount;
    const auto unchanged=[&]() {
        return state.rasterCapture==escaped&&state.bytes==bytes&&state.metrics.retainedNativeBytes==native
            &&state.directPrimitiveBytes==primitive&&state.directAttemptCount==attempts
            &&state.receiverAttemptCount==receivers&&state.terminalAttemptCount==terminals;
    };
    auto& accounting=state.rasterCaptureAccounting;
    const auto reject=[&](bool charged) {
        const auto before=accounting;
        const bool accepted=inspectMetalRasterCaptureUnlocked(*frame,error);
        const auto count=before.invocations+(charged?1:0);
        return !accepted&&!error.empty()&&accounting.invocations==count
            &&accounting.recordVisits==count*before.visitsPerScan
            &&accounting.bytesCopied==count*before.copiesPerScan
            &&accounting.bytesCompared==count*before.comparesPerScan&&unchanged();
    };
    auto& p=*m.passes[0];auto& draw=p.draws[0];
    // A failed admitted scan keeps its full charge; restored real owners can
    // be inspected again without rewriting the prior attempted-work receipt.
    const auto matrix=draw.uniforms.objectMatrix[0];draw.uniforms.objectMatrix[0]=std::nextafter(matrix,INFINITY);
    bool refused=reject(true);draw.uniforms.objectMatrix[0]=matrix;
    if(!refused)return refuse("Metal raster uniform mutation was accepted or refunded its scan");
    const auto indexOffset=draw.indexOffset;draw.indexOffset+=4;
    refused=reject(true);draw.indexOffset=indexOffset;
    if(!refused)return refuse("Metal raster draw/index association mutation was accepted");
    const auto vertexHandle=draw.vertices[0];draw.vertices[0]+=1;
    refused=reject(true);draw.vertices[0]=vertexHandle;
    if(!refused)return refuse("Metal raster native vertex/identity association mutation was accepted");
    if(p.draws.size()>1) {
        std::swap(p.draws[0],p.draws[1]);refused=reject(true);std::swap(p.draws[0],p.draws[1]);
        if(!refused)return refuse("Metal raster actual draw sequence mutation was accepted");
    }
    const auto winding=draw.winding;draw.winding=(winding+1)%3;
    refused=reject(true);draw.winding=winding;
    if(!refused)return refuse("Metal raster winding mutation was accepted");
    const auto scissor=p.stamp.scissor;p.stamp.scissor[0]+=1;
    refused=reject(true);p.stamp.scissor=scissor;
    if(!refused)return refuse("Metal raster pass/scissor mutation was accepted");
    auto* archive=static_cast<unsigned char*>(p.archive.contents);const auto oldByte=archive[0];archive[0]^=1;
    refused=reject(true);archive[0]=oldByte;
    if(!refused)return refuse("Metal raster historical native uniform mutation was accepted");
    const auto geometryOffset=p.stamp.geometryOffsets[0];const auto oldGeometryByte=archive[geometryOffset];archive[geometryOffset]^=1;
    refused=reject(true);archive[geometryOffset]=oldGeometryByte;
    if(!refused)return refuse("Metal raster historical native geometry mutation was accepted");
    const auto historical=p.historical[0];p.historical[0]^=1;
    refused=reject(true);p.historical[0]=historical;
    if(!refused)return refuse("Metal raster historical host mutation was accepted");
    auto* source=static_cast<unsigned char*>(m.sourceArchive.contents);const auto sourceByte=source[0];source[0]^=1;
    refused=reject(true);source[0]=sourceByte;
    if(!refused)return refuse("Metal raster native shader source archive mutation was accepted");
    if(!m.sourceIdentity.empty()) {
        const auto identity=m.sourceIdentity[0];m.sourceIdentity[0]^=1;
        refused=reject(true);m.sourceIdentity[0]=identity;
        if(!refused)return refuse("Metal raster source identity mutation was accepted");
    }
    const auto pipeline=m.descriptions[0].face_winding;m.descriptions[0].face_winding=SG_FACEWINDING_CW;
    refused=reject(true);m.descriptions[0].face_winding=pipeline;
    if(!refused)return refuse("Metal raster pipeline association mutation was accepted");
    const auto generation=frame->rendererGeneration_;const_cast<MetalFixtureSceneFrame&>(*frame).rendererGeneration_+=1;
    refused=reject(false);const_cast<MetalFixtureSceneFrame&>(*frame).rendererGeneration_=generation;
    if(!refused)return refuse("Metal raster stale renderer generation was accepted");
    const auto time=m.evaluationTime;m.evaluationTime+=1;
    refused=reject(false);m.evaluationTime=time;
    if(!refused)return refuse("Metal raster stale evaluation time was accepted");
    const auto allocation=p.archiveAllocation;p.archiveAllocation-=1;
    refused=reject(false);p.archiveAllocation=allocation;
    if(!refused)return refuse("Metal raster historical native capacity mutation was accepted");
    const auto reservation=m.hostReservation;m.hostReservation-=1;
    refused=reject(false);m.hostReservation=reservation;
    if(!refused)return refuse("Metal raster retained host capacity omission was accepted");
    const auto geometry=p.nativeGeometry[0];p.nativeGeometry[0]=nil;
    refused=reject(false);p.nativeGeometry[0]=geometry;
    if(!refused)return refuse("Metal raster missing retained native geometry owner was accepted");
    const auto attachment=p.textures[0];p.textures[0]=nil;
    refused=reject(true);p.textures[0]=attachment;
    if(!refused)return refuse("Metal raster missing retained attachment owner was accepted");
    const auto shaderOwner=m.shaderOwners[0];m.shaderOwners[0]=nil;
    refused=reject(true);m.shaderOwners[0]=shaderOwner;
    if(!refused)return refuse("Metal raster missing retained native shader owner was accepted");
    const auto command=p.command;p.command=nil;
    refused=reject(false);p.command=command;
    if(!refused)return refuse("Metal raster missing owning command was accepted");
    const auto retainedAccounting=accounting;
    if(accounting.bytesCompared<accounting.comparesPerScan)return false;
    accounting.bytesCompared-=accounting.comparesPerScan;
    const bool acceptedOmission=inspectMetalRasterCaptureUnlocked(*frame,error);
    const bool omissionRetained=accounting.invocations==retainedAccounting.invocations;
    accounting=retainedAccounting;
    if(acceptedOmission||!omissionRetained||!unchanged())return refuse("Metal raster failed scan charge omission was accepted");
    // Escaped historical owners remain alive and charged when their current
    // registration is absent. Restoring registration preserves the same owner.
    const auto beforeMissing=accounting.invocations;state.rasterCapture.reset();
    const bool acceptedMissing=inspectMetalRasterCaptureUnlocked(*frame,error);
    const bool conserved=state.bytes==bytes&&state.metrics.retainedNativeBytes==native
        &&escaped->passes[0]->archive==p.archive&&accounting.invocations==beforeMissing;
    state.rasterCapture=escaped;
    if(acceptedMissing||!conserved||!unchanged())return refuse("Metal raster missing registration released or accepted an escaped owner");
    // Checked overflow refuses before another actual scan and leaves receipts.
    const auto beforeOverflow=accounting;accounting.invocations=UINT64_MAX;
    const bool acceptedOverflow=inspectMetalRasterCaptureUnlocked(*frame,error);
    const bool overflowRetained=accounting.invocations==UINT64_MAX;
    accounting=beforeOverflow;
    if(acceptedOverflow||!overflowRetained||!unchanged())return refuse("Metal raster inspection overflow spent or replaced its receipt");
    if(!inspectMetalRasterCaptureUnlocked(*frame,error)||!unchanged())return false;
    if(privateStaging) {
        std::uint64_t staged=0,stagedNative=0;
        if(!metalDirectCohortStageBytes(*frame,staged,stagedNative,error)
            ||staged!=state.metrics.admittedBytes)return refuse("Metal raster later stage reconstruction omitted retained capture storage");
    }
    error.clear();return true;
}

bool readMetalGlassCausticReceipt(const std::shared_ptr<const NativeFixtureSceneFrame>& owner,
    glasscaustics::Frame& schedule,glasscaustics::NativeReadback& receipt,
    glasscaustics::EnergyLedger& energy,std::string& error)
{
    std::lock_guard<std::mutex> lock(sokolMutex());
    const auto frame=std::dynamic_pointer_cast<const MetalFixtureSceneFrame>(owner);
    if(!frame || !frame->caustic || !frame->caustic->validated || !frame->caustic->submission
        || !frame->staticResources || frame->rendererGeneration_!=frame->staticResources->rendererGeneration
        || frame->caustic->prepared.glass.sourceScene!=frame->staticResources->snapshot
        || frame->caustic->prepared.glass.sourceMaterial!=frame->staticResources->materialProgram) {
        error="Metal caustic diagnostic requires its completed exact owning frame";return false;
    }
    if(!inspectMetalRasterCaptureUnlocked(*frame,error))return false;
    auto candidate=frame->caustic->energy;
    if(!glasscaustics::validateNativeReadback(frame->caustic->prepared,frame->caustic->schedule,
        frame->caustic->receipt,candidate,error,&frame->caustic->identity)) return false;
    schedule=frame->caustic->schedule;receipt=frame->caustic->receipt;energy=candidate;error.clear();return true;
}

