    }
    value = clamp((value - m.matteRefine.x)
                  / max(m.matteRefine.y - m.matteRefine.x, 1.0e-5f), 0.0f, 1.0f);
    value = clamp(value + m.matteChoke, 0.0f, 1.0f);
    return (m.matteFlags & 2) != 0 ? 1.0f - value : value;
